INSERT INTO entidade(id, nome, tipo, categoria_id, grupo, partido, campo, cargo, descricao, dossie, uf, nascimento, origem, origem_ref, ind_legado, criado_em, atualizado_em) VALUES('viviane-barci-de-moraes','Viviane Barci de Moraes','pessoa','jus','Outros',NULL,NULL,'Advogada; esposa do ministro Alexandre de Moraes','Seu escritório assinou contrato com o Master em 23/01/2024: R$ 129 mi em 3 anos (O Globo), R$ 131,3 mi (PF) ou R$ 108 mi (nota do escritório). Pago: R$ 80,2 mi segundo a Receita/IR do banco enviado à CPI, ou cerca de R$ 13,6 mi em 4 transferências localizadas pela PF. O escritório nega irregularidade e diz que houve um só contrato; a PGR arquivou pedido de investigação em 29/12/2025 por análise preliminar.',NULL,NULL,NULL,'teia','N[24]',24,'2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO entidade(id, nome, tipo, categoria_id, grupo, partido, campo, cargo, descricao, dossie, uf, nascimento, origem, origem_ref, ind_legado, criado_em, atualizado_em) VALUES('waldir-maranhao','Waldir Maranhão','pessoa',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'linha_do_tempo','Y.pol',NULL,'2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO entidade(id, nome, tipo, categoria_id, grupo, partido, campo, cargo, descricao, dossie, uf, nascimento, origem, origem_ref, ind_legado, criado_em, atualizado_em) VALUES('walfrido-warde','Walfrido Warde','pessoa','adv',NULL,NULL,NULL,'Advogado; defendeu Vorcaro até 21/01/2026','Mensagens de 16-17/11/2025 (''Estamos infernizando o cara'') levaram a PF a levantar se Vorcaro soube da prisão por meios ilícitos. O escritório diz que agiu dentro da lei e chama de caluniosa a acusação de obter dados sigilosos. Não consta como investigado formal.',NULL,NULL,NULL,'teia','N[151]',151,'2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO entidade(id, nome, tipo, categoria_id, grupo, partido, campo, cargo, descricao, dossie, uf, nascimento, origem, origem_ref, ind_legado, criado_em, atualizado_em) VALUES('warde-advogados','Warde Advogados','empresa','adv',NULL,NULL,NULL,'Escritórios ligados a Walfrido Warde','R$ 76,6 mi do Master (2022-2025, Receita). Sócios listados em dez/2025: Valdir Simão e Leandro Daiello; Roberta Rangel foi sócia desde 2021.',NULL,NULL,NULL,'teia','N[152]',152,'2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
