INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(1,'saul-dutra-sabba','daniel-vorcaro','societaria',NULL,'Contrato de venda do controle (15/09/2017)','O Comunicado BCB 31.344 registra que em 15/09/2017 foi assinado o Contrato de Compra e Venda e Outras Avenças entre Saul Dutra Sabbá (vendedor) e Daniel Bueno Vorcaro, com Alberto Maurício Caló e o Banco Máxima como intervenientes; a operação dependia de aprovação do BC. Segundo o Valor (via Jornal de Brasília e Brasil 247), o negócio previa 56,87% do capital por R$ 40 milhões, pagos em R$ 36 milhões em cotas do fundo Brazil Realty e R$ 4 milhões em dinheiro. O BC só aprovou a transferência de controle em 14/10/2019.','documentada',NULL,'2017',NULL,0,NULL,NULL,NULL,'Sabbá não respondeu aos pedidos de comentário do Valor (reportagem de jan/2026); a defesa de Vorcaro, procurada pelo Jornal de Brasília, não se manifestou.',1,'teia','E[0].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(2,'bcb','saul-dutra-sabba','juridica',NULL,'Inabilitação por 9 anos (2018)','Pela Decisão 946/2018 do Copat (processo 110550), assinada em 27/07/2018, aprovada por unanimidade na sessão de 19/07/2018 e resumida no Diário Eletrônico de 03/08/2018, o BC concluiu, segundo o texto, que o Banco Máxima foi conduzido em desacordo com a regulação e as boas práticas bancárias: teria simulado a valorização de investimento em empresa controlada para reduzir prejuízo contábil, assumido riscos incompatíveis com sua estrutura de capital e prestado informações incorretas ao BC, de forma intencional e sistemática, para dissimular grave insuficiência de capital. Aplicou multa de R$ 100 mil ao Banco Máxima, inabilitação de 9 anos a Saul Dutra Sabbá e de 8 anos a Alberto Maurício Caló. É decisão administrativa do BC; houve recurso ao CRSFN (evento de 17/11/2020).','documentada',NULL,'2018',NULL,0,NULL,NULL,NULL,'O banco atual disse em 2021 que as punições do BC se restringem aos antigos administradores; a decisão de 2018, porém, registra multa de R$ 100 mil ao Banco Máxima S.A. Os punidos recorreram ao CRSFN (evento de 17/11/2020), cujo resultado não consta das fontes. As fontes não trazem defesa individual de Sabbá e Caló.',1,'teia','E[1].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(3,'mpf','saul-dutra-sabba','investigacao',NULL,'Denúncia sobre a gestão do Máxima','Segundo Estadão/Seu Dinheiro e Diário do Grande ABC (24/07/2021), o juiz Nilson Martins Lopes Júnior, da 6ª Vara Criminal Federal de São Paulo, recebeu denúncia do MPF contra cinco pessoas, entre elas Saul Dutra, ex-diretor-presidente, Alberto Maurício Caló, ex-diretor jurídico, e Benjamim Botelho de Almeida, administrador dos fundos, apontado pelo MPF como articulador da triangulação; os outros dois denunciados não são nomeados. Os crimes imputados são gestão fraudulenta, informações falsas ao BC e dados inverídicos em demonstrativo financeiro, entre 2014 e 2016. O recebimento da denúncia (indícios mínimos de autoria e materialidade) não é condenação.','investigacao',NULL,'2021',NULL,0,NULL,NULL,NULL,'As reportagens não trazem manifestação dos acusados. O banco atual disse que não é parte da ação e que as punições do BC se restringem aos antigos administradores. Segundo o Jornal de Brasília (2026), a Justiça Federal absolveu depois outros ex-dirigentes, entre eles o ex-diretor jurídico e contábil, sem citar nomes.',1,'teia','E[2].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(4,'bcb','daniel-vorcaro','juridica',NULL,'Veto à compra do Máxima (fev/2019)','O voto BCB 20/2019, do diretor Sidnei Corrêa Marques, tornado público pelo BC (liberado após pedidos pela Lei de Acesso à Informação, com trechos tarjados), indeferiu a transferência de controle por falta de comprovação da origem dos recursos e da capacidade econômico-financeira dos adquirentes. Segundo o Let''s Money (reproduzindo o Valor) e o Brasil 247, o voto é de 13/02/2019; uma segunda matéria do Let''s Money traz 13/01/2019, e Jornal de Brasília e Times Brasil dizem apenas fevereiro. O voto aponta que parte relevante dos recursos teria vindo do próprio Máxima, em transferências entre banco, empresas de Vorcaro e fundos, e questiona laudos de imóveis. Marco da transição; a narrativa do banco antigo para aqui.','documentada',NULL,'2019',NULL,0,NULL,NULL,NULL,'Vorcaro declinou comentar ao Valor (via Let''s Money). Segundo o voto, inquirido, ele não apresentou elementos que esclarecessem a origem dos recursos de forma clara e inequívoca. O pedido foi reapresentado em 02/05/2019 com novo grupo de controle.',1,'teia','E[3].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(5,'bcb','daniel-vorcaro','juridica',NULL,'Aprovação da compra (14/10/2019)','O voto BCB 218/2019, do diretor João Manoel Pinho de Mello, de 14/10/2019, já na gestão de Roberto Campos Neto no BC, aprovou a operação, segundo Let''s Money, Times Brasil e Brasil 247. Segundo o Let''s Money, o voto diz que ''a origem dos recursos foi regularmente demonstrada por todos os novos acionistas''; segundo o Times Brasil, Pinho de Mello registrou que o veto não considerara projeções de fluxo de caixa nem laudos de valor de mercado. Houve aportes de R$ 100 milhões entre março e junho de 2019 (R$ 70 mi de Vorcaro e R$ 30 mi dos demais sócios, segundo o Jornal de Brasília). O Valor/Let''s Money estima o rombo potencial do FGC em R$ 3,224 bilhões em 2019. Marco: a entrada do grupo de Daniel Vorcaro encerra a história do banco antigo.','documentada',NULL,'2019',NULL,0,NULL,NULL,NULL,'Vorcaro declinou comentar ao Valor (via Let''s Money).',1,'teia','E[3].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(6,'henrique-vorcaro','grupo-multipar','societaria',NULL,'Fundador do grupo (c. 1991)','Poder360 e Band (14/05/2026), citando a página oficial do grupo, dizem que a Multipar foi fundada ''há cerca de 35 anos'' por Henrique Vorcaro (por volta de 1991, ano inferido pela data das reportagens), a partir da Vorcaro Imóveis e da Centro Sul Empreendimentos. O Hoje em Dia diz que o conglomerado nasceu em Belo Horizonte e depois expandiu a atuação para engenharia, energia, agronegócio, mineração e hotelaria. O Mais Goiás diz que Henrique se tornou corretor imobiliário e fundou a Multipar. Nenhuma fonte aberta traz o ano exato nem a lista de sócios.','reportada',NULL,'1991',NULL,0,NULL,NULL,NULL,'',1,'teia','E[4].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(7,'grupo-multipar','daniel-vorcaro','societaria',NULL,'Diretor-executivo; hotel em BH (2011)','O Estado de Minas noticiou em 20/10/2011 a retomada de um prédio inacabado de 27 andares no Bulevar Arrudas, no Centro de BH, para o hotel Royal Tulip, com 405 apartamentos e investimento de R$ 200 milhões, entrega prevista para dezembro de 2012. A construtora era a M.Roscoe, a operadora a Brazil Hospitality Group e os incorporadores RFM, Pacific Realty e Blackwood; o jornal chama Daniel de diretor-executivo da Multipar e idealizador do projeto, e Henrique de presidente da Multipar. O texto não detalha a participação societária de cada um.','reportada',NULL,'2011',NULL,0,NULL,NULL,NULL,'',1,'teia','E[5].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(8,'henrique-vorcaro','banco-maxima','societaria',NULL,'Minutas previam participação (negado)','O Fator (25/09/2026) diz ter confirmado, com fontes ligadas às investigações, minutas sem assinatura elaboradas entre nov/2016 e dez/2017, período em que se negociava a compra do Máxima. Uma minuta de nov/2017 diz que Henrique ''passaria a deter participação, direta ou indireta, de 50%'' no banco, percentual que a reportagem explica referir-se à metade das ações de Daniel; na versão de dezembro, Daniel aparece com 93% e Henrique com 46,5%. Henrique teria poder de veto sobre as principais decisões e os dividendos de Daniel seriam divididos meio a meio; os recursos viriam da Multipar, e uma minuta de dezembro de 2017 relata um contrato de julho de 2015 para compra de ações via Fundo Esmeralda. São versões de trabalho sem assinatura.','reportada',NULL,'2017',NULL,0,NULL,NULL,NULL,'A defesa de Henrique diz que as minutas ''não são documentos'' e registram conversas que ''nunca chegaram perto de se concretizar'', e que ele ''jamais foi acionista, conselheiro, e muitíssimo menos, gestor ou administrador'' do banco. Em carta ao ministro André Mendonça (STF), Henrique escreveu que o filho ''não tratava nada de banco'' com ele.',1,'teia','E[6].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(9,'cvm','henrique-vorcaro','juridica',NULL,'Multa no caso Brazil Realty (2026)','Em 8/9/2026, o colegiado da CVM, com relatoria do diretor João Accioly, condenou por unanimidade, segundo o Poder360, entre outros, Daniel (multa de R$ 20 milhões), Henrique (R$ 20 milhões), o Banco Master (R$ 12,5 milhões) e Felipe Vorcaro (R$ 5 milhões), por, segundo a CVM, incorporar ao fundo Brazil Realty ativos imobiliários por valores artificialmente elevados e simular liquidez das cotas no mercado secundário; a investigação começou em 2020. O Poder360 informa total de multas de R$ 201,5 milhões e cinco absolvidos; o Times Brasil fala em 19 acusados, 3 absolvidos, e não informa os valores das multas de Henrique e Felipe. É decisão administrativa da CVM, da qual os condenados podem recorrer ao CRSFN.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'A defesa de Daniel nega participação em fraude ou relação com os laudos considerados irregulares e contesta os cálculos da CVM; a advogada questionou a falta de provas individualizadas de dolo. Felipe nega participação nas negociações das cotas e diz que o processo não individualizou sua conduta. As defesas pediram prescrição.',1,'teia','E[7].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(10,'rede-super','igreja-batista-da-lagoinha','societaria',NULL,'Emissora da igreja desde 2000','Segundo a Wikipedia, a Rede de Televisão Comunitária, no ar desde 1997, foi vendida à Lagoinha em 2000 e passou a se chamar Rede Super; André Valadão é presidente da emissora desde 22/02/2010. A The Intercept Brasil descreve a Rede Super e a Rádio Super como propriedade da igreja, com transmissão em 13 estados. Em 2017 a emissora fez a campanha ''A Rede Super não pode parar'', para arrecadar R$ 3 milhões para digitalizar o sinal; a fonte não nomeia doadores.','documentada',NULL,'2000',NULL,0,NULL,NULL,NULL,'',1,'teia','E[8].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(11,'henrique-vorcaro','rede-super','financeira',NULL,'Teria financiado a emissora (2000)','A Gazeta do Povo (27/03/2026) escreve que, em 2000, Henrique Vorcaro, pai de Daniel, foi ''um dos principais financiadores da Rede Super'', emissora ligada à Lagoinha. A Agência Pública (02/12/2025), citando reportagem da revista piauí que não foi possível abrir, diz que a emissora só foi viabilizada por doações dele e que ele teria ajudado a quitar prestações de um BMW que Valadão comprara antes de liderar a Lagoinha Global; o Mais Goiás, reproduzindo a Folha (13/03/2026), diz que ele ''ajudou a quitar'' a dívida do carro. A CartaCapital diz apenas que a família Vorcaro apoiou financeiramente a Rede Super. Nenhuma fonte aberta traz valores, datas precisas ou documentos desses aportes. Doar a uma igreja ou ajudar um amigo é conduta lícita, e as fontes não apontam irregularidade nesses aportes.','reportada',NULL,'2000',NULL,0,NULL,NULL,NULL,'A assessoria da Lagoinha diz que Valadão se refere a ''um episódio pessoal ocorrido há cerca de 25 anos envolvendo a aquisição de uma BMW'', uma compra que ele fez na época, e que não houve ''qualquer tipo de presente ou benefício'' (nota reproduzida pelo Mais Goiás, que republica a Folha). A Lagoinha Global afirma não ter vínculo institucional com o Master e diz que Daniel Vorcaro e seus parentes ''participaram da vida da igreja em diferentes momentos''. Não localizei manifestação de Henrique Vorcaro sobre o financiamento da Rede Super.',1,'teia','E[9].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(12,'henrique-vorcaro','igreja-batista-da-lagoinha','financeira',NULL,'Teria financiado projetos da igreja','A Folha de S.Paulo, reproduzida pelo Mais Goiás (13/03/2026), descreve Henrique Vorcaro como o primeiro da família a se associar à Lagoinha, convertido ao meio evangélico, que financiou projetos da igreja. O Mais Goiás (14/05/2026) repete que ele ''teria financiado projetos religiosos'' e manteria proximidade com lideranças como André Valadão. A Bloomberg Linea diz que o avô de Daniel, imigrante italiano, tornou-se pastor (sem citar o nome; Serafim Vorcaro vem da Wikipedia, citando a piauí). As matérias não identificam quais projetos, nem valores ou datas, e a data do evento é uma aproximação. Financiar projetos de uma igreja é conduta lícita, e as fontes não apontam irregularidade nela.','reportada',NULL,'2000',NULL,0,NULL,NULL,NULL,'A Lagoinha diz que sua relação com Vorcaro é ''de natureza religiosa, não empresarial'' (CartaCapital, que não cita comunicado formal) e que as relações entre Valadão e a família são pessoais, entre famílias que convivem há décadas, sem vínculo institucional (nota de 10/03/2026, via Mais Goiás). Não localizei manifestação de Henrique Vorcaro sobre o financiamento de projetos da igreja; no contexto da prisão de maio de 2026, sua defesa nega irregularidades e a titularidade de conta de R$ 2,2 bilhões.',1,'teia','E[10].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(13,'daniel-vorcaro','rede-super','pessoal',NULL,'Apresentou programa gospel (c. 2008)','Daniel Vorcaro apresentou, por volta de 2008-2009, um programa de música gospel na Rede Super (a Wikipedia, que cita a piauí, fala em ''Supersônica''). A Agência Pública, a Gazeta do Povo e o Mais Goiás (Folha) confirmam que ele apresentou programa na emissora. Não há valor envolvido.','reportada',NULL,'2008',NULL,0,NULL,NULL,NULL,'',1,'teia','E[11].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(14,'andre-valadao','fabiano-zettel','pessoal',NULL,'Celebrou o casamento com Natália Vorcaro','Em 2018 o advogado e empresário Fabiano Zettel casou-se com Natália Vorcaro, irmã de Daniel. Segundo a Gazeta do Povo e O Globo (lido via Brasil 247, que traz o ano), a cerimônia foi celebrada por André Valadão, e Daniel acompanhou da primeira fila. A CartaCapital descreve Natália como pastora da Lagoinha; o Jornal de Brasília a aponta como responsável pelo templo do Belvedere em março de 2026. Casamento celebrado por pastor amigo da família é fato lícito; as fontes não o ligam a conduta investigada.','reportada',NULL,'2018',NULL,0,NULL,NULL,NULL,'A Lagoinha diz que relações pessoais entre famílias que convivem há décadas em Belo Horizonte ''não configuram, por si só, qualquer irregularidade'' (nota de 10/03/2026, via Mais Goiás).',1,'teia','E[12].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(15,'andre-valadao','igreja-batista-da-lagoinha','societaria',NULL,'Lidera a Lagoinha Global desde 2022','Em 11/12/2022, Márcio Valadão anunciou em culto que deixava o pastorado da igreja de Belo Horizonte, que o Correio Braziliense descreve com mais de 600 unidades; o pastor Flavinho Marques assumiu essa congregação. Após a crise interna de fim de 2022, a Lagoinha Global, que governa as filiais, passou à liderança de André Valadão (The Intercept Brasil; a Wikipedia cita o Pleno News para dezembro de 2022). A Gazeta do Povo registra que a banda Diante do Trono, de Ana Paula Valadão, saiu da Lagoinha anos antes.','documentada',NULL,'2022',NULL,0,NULL,NULL,NULL,'',1,'teia','E[13].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(16,'nikolas-ferreira','daniel-vorcaro','politica',NULL,'Voos em jato ligado a Vorcaro (2022)','O Globo (coluna de Malu Gaspar) reportou, e o Estadão repercutiu em 03/03/2026, que o deputado Nikolas Ferreira e o pastor Guilherme Batista, descrito pelas matérias como pastor da Lagoinha, usaram entre 20 e 28/10/2022 um Phenom 300 na caravana ''Juventude pelo Brasil'', de apoio a Bolsonaro no segundo turno. Segundo O Globo, no papel o avião era da Prime You, que em 2022 administrava o jatinho e outros bens de Daniel Vorcaro; a Revista Oeste acrescenta que Vorcaro era sócio da empresa. As matérias não dizem quem pagou os voos. O uso foi político: não há repasse à igreja e Valadão não aparece como passageiro.','reportada',NULL,'2022',NULL,0,NULL,NULL,NULL,'A defesa de Vorcaro disse ao Estadão que o avião não pertence ao banqueiro. Nikolas confirmou o uso, disse que foi a convite do pastor Guilherme Batista para a agenda de campanha e que não sabia quem era o dono nem quem financiou. O gabinete de Batista disse que ele estava em retiro e não comentou. A nota da Lagoinha (10/03/2026, via Mais Goiás) diz que nem o pastor citado na reportagem nem o deputado são membros da igreja, que a viagem foi feita ''por terceiros em aeronave pertencente ao empresário citado'', que não foi agenda da igreja nem envolveu representantes da denominação e que a alegação de relação com a instituição é falsa.',1,'teia','E[14].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(17,'banco-master','andre-valadao','financeira',NULL,'Coaf: R$ 3,9 mi a produtora (negado)','O SBT News e o ICL Notícias (13/03/2026) relatam relatório do Coaf, não divulgado na íntegra, que aponta repasses de R$ 3,897 milhões do Banco Master à Amando Vidas Produtora e Gravadora Ltda., registrada na Receita em nome de André Valadão e da esposa, entre março e abril de 2022. O SBT descreve a operação como imobiliária, ligada a um imóvel em Sete Lagoas (MG); o ICL a chama de movimentação atípica e ressalva que isso não indica automaticamente crime. Segundo o SBT, as relações financeiras entre Valadão e Daniel Vorcaro ''ainda não foram esclarecidas''. As matérias não estabelecem que o valor foi recebido nem que foi ilícito. O dinheiro partiu do banco, não de familiares, e a empresa é do casal, não a igreja.','reportada',NULL,'2022',NULL,0,NULL,3897000.0,NULL,'A defesa de Valadão disse desconhecer a operação e negou o recebimento dos valores. A Amando Vidas ''nega veementemente qualquer vínculo ou participação'', diz que seus extratos não registram entradas compatíveis com o valor e que tem apenas uma conta bancária (SBT News; ICL).',1,'teia','E[15].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(18,'andre-valadao','clava-forte-bank','societaria',NULL,'Fundador e presidente (2024)','A Agência Pública (02/12/2025) informa que o Clava Forte Bank foi fundado em março de 2024 e presidido por André Valadão e Cassiane Valadão; a divulgação pública ocorreu em abril de 2025 (Jornal Opção, que o descreve como banco digital lançado pela Igreja Batista da Lagoinha, e Brasil 247, que cita capital de cerca de R$ 100 mil e gestão pelo casal). O Banco Central diz que a empresa nunca esteve autorizada a funcionar como instituição financeira; ela operava com a infraestrutura da CDC SCD (Banco 470) e da Dock. Em outubro de 2025 Cassiane deixou a direção, o site saiu do ar a partir de 21/11/2025 e a Gazeta do Povo registra a suspensão do CNPJ em janeiro de 2026. As fontes não citam sócios da família Vorcaro; o deputado Rogério Correia levantou a hipótese de ligação com o Master, que a Pública chama de ''campo da suposição''.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'André Valadão disse que o vínculo do Clava com o Master é ''menos um, não é zero, não, nem existe'' e que foi ''simplesmente um sistema de pagamento'', encerrado pelo alto índice de hackeamento bancário (Mais Goiás, reproduzindo a Folha); em 21/01/2026 disse que era ferramenta interna de pagamentos da Lagoinha Global, encerrada por segurança digital, e que ''não há uma vírgula de vínculo'' com o Master (Portal de Prefeitura). O Clava Forte afirmou, em nota, operar como correspondente bancário no modelo BaaS, o que considera legal (Brasil 247), e chamou a queda do site de ''manutenção programada'' (Agência Pública).',1,'teia','E[16].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(19,'daniel-vorcaro','andre-valadao','politica',NULL,'Pedido de ajuda com Nikolas (27/04/2024)','Mensagens divulgadas pelo ICL e relatadas pelo Poder360 mostram que em 27/04/2024 Vorcaro escreveu a Valadão ''De novo pedir sua ajuda com Nikolas'', por causa de publicações do deputado Nikolas Ferreira sobre um fórum jurídico financiado pelo Master; Nikolas diz ter pedido esclarecimentos pela Lei de Acesso à Informação. Valadão confirmou em vídeo (03-04/09/2026) que sua participação ''se limitou a aproximar duas pessoas que eu conhecia''. Nikolas confirmou que o contato de Vorcaro lhe foi passado por Valadão e nega ter recebido dinheiro ou encontrado o banqueiro.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Valadão: participação limitada a aproximar duas pessoas; ''não houve qualquer relação da minha parte com negócios, interesses ou atividades do Banco Master''; desconhecia as irregularidades; está disposto a adotar medidas legais se lhe atribuírem condutas que não praticou. Nikolas: ''nunca recebi um tostão do Vorcaro''.',1,'teia','E[17].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(20,'andre-valadao','nikolas-ferreira','politica',NULL,'Diz ter apenas aproximado os dois','Mensagens divulgadas pelo ICL e relatadas pelo Poder360 mostram que em 27/04/2024 Vorcaro escreveu a Valadão ''De novo pedir sua ajuda com Nikolas'', por causa de publicações do deputado Nikolas Ferreira sobre um fórum jurídico financiado pelo Master; Nikolas diz ter pedido esclarecimentos pela Lei de Acesso à Informação. Valadão confirmou em vídeo (03-04/09/2026) que sua participação ''se limitou a aproximar duas pessoas que eu conhecia''. Nikolas confirmou que o contato de Vorcaro lhe foi passado por Valadão e nega ter recebido dinheiro ou encontrado o banqueiro.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Valadão: participação limitada a aproximar duas pessoas; ''não houve qualquer relação da minha parte com negócios, interesses ou atividades do Banco Master''; desconhecia as irregularidades; está disposto a adotar medidas legais se lhe atribuírem condutas que não praticou. Nikolas: ''nunca recebi um tostão do Vorcaro''.',1,'teia','E[18].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(21,'fabiano-zettel','lagoinha-belvedere','societaria',NULL,'Presidente da unidade (2024)','O CNPJ da Lagoinha Belvedere, em Belo Horizonte, foi aberto em setembro de 2024, com Fabiano Zettel como presidente (Jornal de Brasília). A Gazeta do Povo diz que a unidade foi inaugurada em setembro de 2024, com 14,4 mil m2 e capacidade para mais de 2 mil pessoas, voltada a público de alta renda, e que o aluguel mensal seria de cerca de R$ 420 mil. O Jornal de Brasília diz que o templo foi inaugurado ''com pompa'' em 2025, e O Globo (via Brasil 247) fala em cerca de 16 mil m2, numa antiga concessionária, com cerimônia de inauguração em abril de 2025. Zettel veio da Bola de Neve em 2024 (Folha, via Mais Goiás). Não identifiquei o proprietário do imóvel.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'A Lagoinha diz que Zettel passou a integrar a igreja como pastor voluntário há menos de dois anos, com atuação restrita à unidade do Belvedere, e que cada igreja local tem liderança própria, responsável pelas decisões administrativas e jurídicas do templo (Mais Goiás; Jornal de Brasília/Folhapress).',1,'teia','E[19].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(22,'fabiano-zettel','lagoinha-belvedere','financeira',NULL,'Coaf: R$ 19,2 mi enviados à conta','O RIF 140515 do Coaf, tornado público em 10-14/09/2026 após decisão do ministro André Mendonça, registra que entre 24/12/2024 e 08/12/2025 Fabiano Zettel fez 26 operações que somam R$ 19,205 milhões para a conta da Lagoinha Belvedere, mais de dois terços dos créditos analisados. O relatório não identifica a origem do dinheiro; o Coaf classificou a movimentação como atípica, o que não prova crime, e a reportagem observa que a suspeita de uso da conta como ''conta de passagem'' ainda não está comprovada. Antes disso, a Folha havia reportado 54 transferências, cerca de R$ 40,9-41 milhões, de Zettel ao templo entre outubro de 2024 e janeiro de 2026; o número difere do RIF e não foi reconciliado.','investigacao',NULL,'2024',NULL,0,NULL,19205000.0,NULL,'A Lagoinha Global disse ter sido informada de que os recursos seriam para reformas, ''e não doações, dízimos ou ofertas'', e que não conhecia os montantes (Itatiaia, ICL). Segundo a igreja, cada unidade tem autonomia e Zettel presidia a Belvedere. A defesa de Zettel disse que não comentará.',1,'teia','E[19].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(23,'henrique-vorcaro','lagoinha-belvedere','financeira',NULL,'Coaf: R$ 120 mil enviados à conta','O mesmo RIF do Coaf (24/12/2024 a 08/12/2025) lista Henrique Moura Vorcaro, pai de Daniel, com R$ 120 mil na conta da Lagoinha Belvedere: quatro operações segundo Itatiaia, ICL e Bahia Notícias, três segundo o Brasil 247 (15/09/2026). Equivale a menos de 1% dos R$ 28,5 milhões de créditos da conta. O Brasil 247 acrescenta que a HV Empreendimentos e Participações, ''administrada por Henrique Vorcaro'', enviou R$ 700 mil em três transações (ver item seguinte); o ICL cita a empresa sem dizer quem a administra. Doar a uma igreja é lícito, e o Coaf registra movimentação, sem concluir crime.','investigacao',NULL,'2024',NULL,0,NULL,120000.0,NULL,'Itatiaia e ICL não trazem manifestação de Henrique Vorcaro. A Lagoinha Global diz não ter participado da captação dos recursos nem conhecer os montantes. A defesa dele, em outro assunto (prisão de maio de 2026), nega irregularidades e a titularidade da conta de R$ 2,2 bilhões (Mais Goiás; Diário do Comércio).',1,'teia','E[20].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(24,'daniel-vorcaro','lagoinha-belvedere','financeira',NULL,'Mensagens: cobrança por recursos da obra','O Brasil 247 (15/09/2026), única fonte aberta deste item, com base em documentos enviados ao STF cujo sigilo foi retirado, relata que Zettel pediu a Daniel Vorcaro recursos para o templo. Em julho de 2025 teria escrito ''Igreja tem um mês que não faz. Odeio cobrar, mas obra vai parar''; em agosto teria enviado planilha de pagamentos pendentes com uma rubrica de R$ 2 milhões para a ''Lagoinha Belvedere''. A matéria não confirma que a rubrica foi paga nem esclarece de quem era o dinheiro cobrado. A PF apura se Zettel usou empresas (Super Empreendimentos, Moriah Asset) para disfarçar a origem de recursos; não há conclusão judicial.','reportada',NULL,'2025',NULL,0,NULL,NULL,NULL,'André Valadão afirmou que a gestão financeira era responsabilidade exclusiva de Zettel, que cada templo tem autonomia jurídica e administrativa e que sabia apenas de reformas, sem conhecer os valores; disse que a instituição ''não compactua com ilegalidade'' e não quer impedir o esclarecimento dos fatos. Não há resposta de Zettel nem de Daniel Vorcaro na fonte.',1,'teia','E[21].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(25,'andre-valadao','henrique-vorcaro','pessoal',NULL,'Amizade de décadas, dita em culto','Segundo O Globo (via Brasil 247, 30/03/2026), em culto de inauguração de templo da Lagoinha em Belo Horizonte, que a matéria data de abril de 2025 (a data diverge da abertura do Belvedere em setembro de 2024 relatada por outras fontes), André Valadão pediu que Henrique e Aline Vorcaro ficassem em pé, chamou-os de ''amigos da minha vida'' e disse que são amigos ''desde as minhas solteirices'', de décadas. Chamou Zettel de ''pastor dessa casa'' e falou em mais de 20 anos de relacionamento com ele. Em outro culto, em agosto de 2024, disse conhecer Natália e Daniel ''desde criancinha'' (Brasil 247). Amizade e pastorado são fatos lícitos; nenhuma autoridade aponta ato de favorecimento nessa convivência.','reportada',NULL,'2025',NULL,0,NULL,NULL,NULL,'Depois do avanço do caso, Valadão disse estar ''profundamente decepcionado'' e ter se afastado da família, e negou irregularidades. A Lagoinha diz, em nota, que hoje não há vínculo entre Valadão, a igreja e a família Vorcaro e que a relação sempre foi de amizade pessoal (Brasil 247).',1,'teia','E[22].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(26,'igreja-batista-da-lagoinha','fabiano-zettel','pessoal',NULL,'Igreja diz tê-lo afastado (nov/2025)','Segundo a Lagoinha, Zettel foi afastado do pastoreio em novembro de 2025, assim que surgiram as primeiras informações públicas, e desde então não tem função na igreja. Ele foi preso em 14/01/2026 no aeroporto de Guarulhos (Compliance Zero, 2a fase) e solto horas depois por decisão de Dias Toffoli (Poder360); em 15/01 a igreja negou ligação com a Compliance Zero e com a CPMI do INSS. Zettel foi preso de novo em 04/03/2026, e o CNPJ da Belvedere seguiu ativo com ele como presidente, segundo Jornal de Brasília e ICL Notícias.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'Nota da Lagoinha (via Portal Tela, 16/01/2026): ''não há indícios de uso da igreja em esquemas de fraude envolvendo INSS ou Banco Master''; a presença de fiéis em cultos não cria vínculo jurídico com a instituição. A defesa de Zettel disse que ele está à disposição das autoridades e que suas atividades são ''conhecidas e lícitas, sem relação alguma com a gestão do Banco Master'' (Metrópoles).',1,'teia','E[23].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(27,'cpmi-do-inss','andre-valadao','investigacao',NULL,'Requerimento de quebra de sigilo','Segundo a Agência Pública, o deputado Rogério Correia (PT-MG) pediu em 25/11/2025 à CPMI do INSS a quebra dos sigilos fiscal e bancário de André Valadão e suspeitou que o Clava Forte fosse ''canal de circulação dos valores desviados'' do INSS; no início de dezembro pediu o mesmo para a Moriah Asset de Zettel (Metrópoles). São requerimentos de parlamentar: não são prova nem decisão, e a Pública não registra deliberação da CPMI sobre eles nem sobre a Lagoinha como instituição. A Pública menciona ainda Felipe Macedo Gomes, ex-presidente da Amar Brasil e fiel da Lagoinha (proximidade com Valadão descrita como ''suposta''), que negou em depoimento à CPMI ter patrocinado a festa de fim de ano de 2024; ele não é da família Vorcaro.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'Valadão (22/01/2026): perseguição infundada e caluniosa, nome surgido de requerimento de Correia, contra quem diz tomar medidas judiciais. A Pública: Clava Forte não respondeu.',1,'teia','E[24].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(28,'lagoinha-belvedere','igreja-batista-da-lagoinha','societaria',NULL,'Unidade encerra atividades (15/03/2026)','A unidade do Belvedere encerrou os cultos em 15/03/2026, cerca de onze dias depois da nova prisão de Zettel (Gazeta do Povo; Jornal de Brasília). A assessoria da Lagoinha confirmou o fim das atividades sem explicar o motivo e remeteu perguntas a Natália Vorcaro, apontada como responsável pelo templo. Segundo o ICL, a unidade apagou as redes sociais nos dias seguintes.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'A Lagoinha não explicou o motivo do fechamento. Natália Vorcaro não respondeu ao Jornal de Brasília antes da publicação.',1,'teia','E[25].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(29,'fabiano-zettel','reag-investimentos','financeira',NULL,'Lucros do fundo Kairós, administrado pela Reag','Segundo dados de imposto de renda obtidos pelo g1 e reportados pelo CNBC/Times Brasil (24/03/2026), Zettel declarou R$ 190,2 milhões em lucros e dividendos do FIP Kairós em 2023-2024, e seu patrimônio declarado subiu de cerca de R$ 67,5 mi (2021) para R$ 204,3 mi (2024). O Kairós, administrado pela Reag, tinha como principal ativo até agosto de 2024 a Super Empreendimentos, da qual Zettel foi diretor de 2021 a 2024 e que a PF aponta como usada pelo grupo ''A Turma'' para crimes financeiros e lavagem e como fonte de pagamentos a um integrante do grupo. O Poder360 informa que a Super adquiriu imóveis, incluindo o tríplex onde Vorcaro morou. Nenhuma fonte liga esses valores à Lagoinha.','reportada',NULL,'2023',NULL,0,NULL,190200000.0,NULL,'A reportagem não traz resposta de Zettel, de advogados, da Reag ou do fundo. A defesa de Zettel afirmou em janeiro que suas atividades empresariais são conhecidas e lícitas, sem relação com a gestão do Master.',1,'teia','E[26].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(30,'operacao-compliance-zero','henrique-vorcaro','investigacao',NULL,'Preso na 6ª fase (14/05/2026)','Henrique Moura Vorcaro foi preso em 14/05/2026, na 6a fase da Compliance Zero, em decisão do ministro André Mendonça que o chama de ''demandante, beneficiário e operador financeiro'' do núcleo ''A Turma'', suspeito de intimidação, vigilância clandestina e invasão de dispositivos; a PF cita uma conta atribuída a ele, na CBSF DTVM (Reag), com saldo acima de R$ 2,2 bilhões. Ele é fundador e, segundo suas redes sociais, diretor-presidente do Grupo Multipar (imobiliário, com atuação também em construção civil). A Gazeta liga o nome dele à Lagoinha pela relação familiar com Zettel, e as fontes abertas não ligam essas apurações ao dinheiro enviado à igreja.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'O advogado Eugênio Pacelli diz que a decisão se baseia em fatos cuja comprovação de licitude e lastro de racionalidade econômica ainda não estão no processo, que a defesa provará a legalidade das transações e nega que ele seja titular da conta de R$ 2,2 bilhões. Em petição noticiada pelo Correio da Manhã (19/06/2026), a defesa, sem nomear advogados, afirma que os recursos investigados tinham origem em relações comerciais legítimas ligadas a um projeto habitacional (Projeto Campo Grande, RJ).',1,'teia','E[27].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(31,'banco-master','banco-maxima','societaria',NULL,'Sucessor do Máxima','O Master é o antigo Banco Máxima, que adotou o nome Master (relançamento em agosto de 2021).','documentada',NULL,'2019','2021',0,NULL,NULL,NULL,'',1,'teia','E[28].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(32,'banco-master','banco-letsbank','societaria',NULL,'Banco do conglomerado','O Letsbank integrava o conglomerado; o BC vetou a venda a Maurício Quadrado e liquidou o banco em 18/11/2025.','documentada',NULL,'2024','2025',0,NULL,NULL,NULL,'',1,'teia','E[29].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(33,'cvm','daniel-vorcaro','juridica',NULL,'Multa no caso Brazil Realty','Em 08/09/2026 a CVM multou Daniel Vorcaro, o pai Henrique, o primo Felipe e o Banco Master num total de R$ 201,5 milhões (R$ 20 milhões para Daniel e para Henrique) por fraude no fundo Brazil Realty; cabe recurso ao CRSFN.','documentada',NULL,'2026',NULL,0,NULL,201500000.0,NULL,'A defesa questionou a falta de provas individualizadas de dolo, pediu prescrição e propôs termos de compromisso, rejeitados.',1,'teia','E[30].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(34,'a-turma','daniel-vorcaro','investigacao',NULL,'Suposta milícia privada','A PF associa Vorcaro a grupo apelidado ''A Turma'', suspeito de intimidar desafetos e obter dados sigilosos; seu suposto coordenador morreu em 06/03/2026 após tentativa de suicídio sob custódia, circunstância que a defesa contesta.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'A defesa de Vorcaro afirma que ele sempre esteve à disposição das autoridades.',1,'teia','E[31].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(35,'fabiano-zettel','daniel-vorcaro','pessoal',NULL,'Cunhado, apontado como operador','A PF aponta Zettel, cunhado de Vorcaro, como operador financeiro e integrante de ''A Turma''; ele foi preso em 14/01 e 04/03/2026.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'',1,'teia','E[32].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(36,'flavio-bolsonaro','daniel-vorcaro','financeira',NULL,'Recursos para o filme ''Dark Horse''','Segundo o Intercept Brasil (reproduzido pelo Jornal Opção), Vorcaro teria se comprometido a repassar US$ 24 milhões (cerca de R$ 134 milhões) ao filme ''Dark Horse'' e ao menos US$ 10,6 milhões teriam sido pagos entre fevereiro e maio de 2025; Flávio cobraria a liberação dos recursos. Na delação de Freixo, homologada em 09/09/2026, segundo o BPMoney, pouco mais de US$ 12 milhões foram enviados a um fundo nos EUA por determinação de Vorcaro após pedidos de Flávio. Não há decisão judicial nem conclusão da PF.','reportada',NULL,'2024','2025',0,NULL,134000000.0,NULL,'Questionado pelo Intercept, Flávio Bolsonaro respondeu ''De onde você tirou essa informação? É mentira'' e negou irregularidades. Em nota citada em outra reportagem do Jornal Opção, ele admite ter pedido dinheiro ao banqueiro para o filme, nega irregularidades e diz ''zero de dinheiro público''. O BPMoney não traz resposta dele sobre a delação.',1,'teia','E[33].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(37,'flavio-bolsonaro','daniel-vorcaro','financeira',NULL,'Repasses ao filme Dark Horse','Em 23/07/2026 Mendonça autorizou inquérito da PF (com parecer favorável da PGR) sobre repasses de Vorcaro ao filme Dark Horse. Segundo o Intercept Brasil, Flávio negociou US$ 24 milhões e documentos indicam ao menos US$ 10,6 milhões (cerca de R$ 61 milhões) até mai/2025.','investigacao',NULL,'2025',NULL,0,NULL,61000000.0,NULL,'Flávio afirma que o pedido foi de patrocínio privado, sem contrapartida nem irregularidade. Segundo O Povo, ele prometeu em 19/05 divulgar em 30 dias uma planilha sobre o financiamento, o que não teria sido feito.',1,'teia','E[33].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(38,'banco-master','viviane-barci-de-moraes','contratual',NULL,'Contrato de cerca de R$ 131 milhões','O escritório de Viviane Barci de Moraes confirma contrato com o Master de fevereiro de 2024 a novembro de 2025; reportagens citam valor de R$ 131 milhões (R$ 3,6 milhões por mês durante 36 meses) e relatório da PF cita metadados segundo os quais a minuta teria sido alterada por usuário identificado como ''Ministro Alexandre de Moraes''.','documentada',NULL,'2024','2025',0,NULL,131000000.0,NULL,'O escritório diz que o compliance consultou Moraes, como marido da sócia, sobre possíveis impedimentos; que não havia previsão de atuação no STF nem impedimento; que ele ''jamais julgou qualquer causa envolvendo o Banco Master''; e que o contrato foi assinado e os serviços foram prestados. Moraes nega ter mantido diálogo com Vorcaro; as fontes consultadas não trazem resposta dele sobre a edição da minuta.',1,'teia','E[34].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(39,'viviane-barci-de-moraes','banco-master','contratual',NULL,'Contrato de R$ 129 mi em 3 anos','Contrato de assessoria jurídica com mensalidades de R$ 3,6 milhões desde 2024, encontrado no celular de Vorcaro; o Master declarou ter pago cerca de R$ 80,2 milhões até a liquidação. A PF menciona cifra de R$ 131 milhões em relatório. O contrato não especificava processos.','documentada',NULL,'2024','2025',0,NULL,80200000.0,NULL,'O escritório ''não quis se manifestar'' à Band. Em abril, Moraes afirmou em nota que ''jamais viajou em nenhum avião de Daniel Vorcaro''; o escritório diz que contratava táxi aéreo, que Vorcaro nunca esteve nos voos e nega contrato de serviços advocatícios com a Prime Aviation. Em proposta de delação, Vorcaro diz que o contrato era lícito e sem contrapartida.',1,'teia','E[34].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(40,'daniel-vorcaro','banco-master','societaria',NULL,'Controlador do banco','Vorcaro é o controlador do Master, antigo Banco Máxima: o BC vetou a compra em fev/2019 e a aprovou em out/2019 com grupo de controle menor. Foi preso em 17/11/2025 e de novo em 04/03/2026.','documentada',NULL,'2019',NULL,0,NULL,NULL,NULL,'A defesa de Vorcaro ''nega categoricamente'' as acusações e diz que ele sempre colaborou com as investigações (Forbes, 04/03/2026).',1,'teia','E[35].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(41,'daniel-vorcaro','banco-master','societaria',NULL,'Controlador com bens indisponíveis','O BC tornou indisponíveis em 18/11/2025 os bens da Master Holding Financeira, da 133 Investimentos e de Vorcaro, Armando Gallo Neto e Felipe Simonsen, além de antigos administradores.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'Em processo nos EUA, a defesa de Vorcaro argumentou que a decisão do BC era prematura e estaria sob contestação no TCU; o juiz rejeitou as objeções.',1,'teia','E[35].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(42,'daniel-vorcaro','banco-master','financeira',NULL,'Direitos creditórios (plano, R$ 8,5 bi)','O plano de 21/09/2025 ao BC previa aportar direitos creditórios do controlador de até R$ 8,5 bilhões; não há evidência nas fontes de que isso se tenha concretizado.','reportada',NULL,'2025','2025',0,NULL,8500000000.0,NULL,'',1,'teia','E[35].r[2]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(43,'bcb','banco-master','investigacao',NULL,'Supervisão de precatórios (R$ 8,7 bi)','O balanço de 2024 registra R$ 8,73 bilhões em precatórios e direitos creditórios (nota 9); segundo a Revista Oeste, o BC exigiu em março de 2024 (Ofício 5.582) prova de origem e existência dos precatórios, e as análises de auditorias e pareceres externos não identificaram irregularidades nos processos revisados, segundo pessoas com conhecimento do caso.','documentada',NULL,'2023','2025',0,NULL,8730000000.0,NULL,'A KPMG disse ter considerado adequada a mensuração dos ativos e que deixou de ser auditora do Master em 2025; o Galdino Advogados afirmou que seus pareceres se limitaram a riscos jurídicos e à expectativa de recebimento dos créditos.',1,'teia','E[36].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(44,'bcb','banco-master','juridica',NULL,'Rejeita compra e liquida (2025)','O BC reprovou a compra do Master pelo BRB (03/09/2025) e decretou a liquidação extrajudicial (18/11/2025). Segundo o BC, as duas decisões foram unânimes na diretoria; o voto pela liquidação foi do diretor de Fiscalização Ailton de Aquino Santos.','documentada',NULL,'2025','2025',0,NULL,NULL,NULL,'',1,'teia','E[36].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(45,'bcb','banco-master','investigacao',NULL,'Liquidação extrajudicial (18/11/2025)','Ao decretar a liquidação em 18/11/2025, o BC apontou grave crise de liquidez, comprometimento econômico-financeiro e graves violações normativas; em depoimento citado pelo InfoMoney, o diretor de Fiscalização do BC, Ailton Aquino, disse que o banco só tinha R$ 4 milhões em caixa antes da liquidação. A liquidação do Master Múltiplo em 17/03/2026 encerrou o conglomerado.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'A defesa de Vorcaro diz que a decisão foi prematura e, segundo o Conjur, contesta a liquidação no TCU.',1,'teia','E[36].r[2]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(46,'banco-master','brb','financeira',NULL,'Carteiras de crédito: R$ 12,2 bi','O BRB comprou em 2024-2025 carteiras de crédito do Master no valor de R$ 12,2 bilhões, sob investigação da PF por suspeita de falta de lastro. Um diretor do BC estimou rombo de ao menos R$ 5 bilhões, segundo a Agência Pública.','investigacao',NULL,'2024',NULL,0,NULL,12200000000.0,NULL,'O BRB diz que definirá o capital necessário após as revisões; Ibaneis afirma que qualquer cifra de perda é especulativa até as auditorias; o ex-presidente do BRB disse à PF que informava o governador periodicamente (Agência Pública).',1,'teia','E[37].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(47,'brb','banco-master','financeira',NULL,'Carteiras negociadas (R$ 12,76 bi)','Segundo nota do BRB de 21/11/2025, foram negociados R$ 12,76 bilhões em carteiras com o Master, dos quais mais de R$ 10 bilhões teriam sido liquidados ou substituídos. A PF fala em R$ 17 bilhões transferidos, incluindo compras mesmo após o TAC com o BC.','documentada',NULL,'2024','2025',0,NULL,12760000000.0,NULL,'O BRB diz ser vítima de atos criminosos e ter removido integralmente a diretoria da época (Bahia Notícias/Folha); na nota de 21/11/2025 afirmou atuar como credor na liquidação e que o restante dos R$ 12,76 bilhões não representa exposição direta ao Master.',1,'teia','E[37].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(48,'brb','banco-master','financeira',NULL,'Carteiras inexistentes? (R$ 12,2 bi)','A PF e o MPF investigam a venda ao BRB de cerca de R$ 12,2 bilhões em carteiras de consignado que não existiriam, com documentos que o Master teria entregue ao BC; as estimativas da PF variam de R$ 12 a 12,7 bilhões.','investigacao',NULL,'2024','2025',0,NULL,12200000000.0,NULL,'O Master não comentou; Augusto Lima nega ter elaborado carteiras ou negociado com o BRB; o BRB afirma ser vítima.',1,'teia','E[37].r[2]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(49,'banco-master','brb','financeira',NULL,'Ativos ligados ao Master (R$ 21,9 bi)','Segundo o presidente do BRB, Nelson de Souza (Senado, 09/06/2026), a carteira de créditos ligada ao Master no balanço soma R$ 21,9 bilhões de face (R$ 12,2 bilhões fraudulentos segundo as investigações); o banco afirma ter arrecadado cerca de R$ 5 bilhões com a venda de carteiras de crédito originais.','documentada',NULL,'2024',NULL,0,NULL,21900000000.0,NULL,'Na nota de 21/11/2025, sobre os R$ 12,76 bilhões negociados, o BRB afirmou que o restante não representa exposição direta ao Master e que atua como credor na liquidação.',1,'teia','E[37].r[3]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(50,'brb','banco-master','societaria',NULL,'Tentativa de compra do controle','O GDF enviou à CLDF projeto (PL 1882/2025) para o BRB comprar 49% das ações ordinárias e todas as preferenciais do Master; foi aprovado em cerca de uma semana e sancionado. O BC rejeitou a operação em 03/09/2025.','documentada',NULL,'2025','2025',0,NULL,NULL,NULL,'',1,'teia','E[37].r[4]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(51,'brb','banco-master','societaria',NULL,'Compra de 58% por R$ 2 bi (vetada)','Em março de 2025, Master e BRB fecharam acordo para o BRB adquirir 58% do capital total (49% do votante) do Master por cerca de R$ 2 bilhões; o Banco Central rejeitou a compra em setembro de 2025, citando ativos sem lastro.','documentada',NULL,'2025','2025',0,NULL,2000000000.0,NULL,'',1,'teia','E[37].r[5]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(52,'brb','banco-master','financeira',NULL,'Provisão estimada do BRB (R$ 5 a 13 bi)','Estimativas de ajuste/provisão: mais de R$ 5 bilhões (diretor de Fiscalização do BC, depoimento de dez/2025), R$ 8,8 bilhões (provisão necessária segundo o presidente do BRB, jun/2026) e R$ 13 bilhões (necessidade de provisão apontada por auditoria forense independente, segundo O Povo). Levantamento do portal Vero cita R$ 22,8 bilhões em perdas mapeadas, não confirmado pelo BRB.','reportada',NULL,'2025',NULL,0,NULL,8800000000.0,NULL,'O BRB não divulgou o balanço de 2025 e, segundo seu presidente, o provisionamento necessário é de R$ 8,8 bilhões.',1,'teia','E[37].r[6]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(53,'ibaneis-rocha','banco-master','politica',NULL,'Sancionou lei de compra pelo BRB','Ibaneis sancionou a lei (PL 1882/2025), aprovada pela CLDF em cerca de uma semana, que autorizou o BRB a comprar parte do Master (ago/2025). Segundo a Agência Pública, a defesa dele resume o episódio a ''excesso de confiança''; ele atribui a condução das negociações a Paulo Henrique Costa.','documentada',NULL,'2025','2025',0,NULL,NULL,NULL,'Ibaneis diz nunca ter tratado da operação nas quatro reuniões com Vorcaro e que não sabia de fraude até a liquidação.',1,'teia','E[38].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(54,'ibaneis-rocha','daniel-vorcaro','politica',NULL,'Encontros sobre o BRB (2024-2025)','Vorcaro disse à PF ter se reunido poucas vezes com Ibaneis, em encontros ''institucionais'', e que conversaram sobre a compra do Master pelo BRB. Ibaneis admite quatro encontros. A Agência Pública reporta que Antônio Rueda teria intermediado o contato inicial.','documentada',NULL,'2024','2025',0,NULL,NULL,NULL,'Ibaneis afirma que nunca tratou da transação com Vorcaro, que foi a um almoço a convite de amigo comum (''entrei mudo e saí calado'') e que tudo foi conduzido por Paulo Henrique Costa.',1,'teia','E[39].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(55,'ibaneis-rocha','paulo-henrique-costa','politica',NULL,'Indicação à presidência do BRB','Costa presidiu o BRB de 2019 a nov/2025 após indicação de Ibaneis, segundo o Poder360. Costa disse à PF que reportava ao governador, inclusive sobre a compra do Master; Ibaneis atribui a Costa a condução das negociações.','reportada',NULL,'2019','2025',0,NULL,NULL,NULL,'Ibaneis nega ter tratado da operação e responsabiliza Costa; a defesa de Costa afirma que a prisão foi desnecessária.',1,'teia','E[40].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(56,'paulo-henrique-costa','operacao-compliance-zero','investigacao',NULL,'Preso em 16/04/2026 (4ª fase)','Mendonça decretou, a pedido da PF, a prisão preventiva de Costa. Segundo a decisão, ele teria posto o BRB a serviço da liquidez do Master (''atuação bifronte'') e seria beneficiário direto de vantagem indevida, estimada em R$ 146,6 milhões e representada por seis imóveis de luxo. A reportagem cita separadamente R$ 74 milhões em seis imóveis ligados a ''repasses já iniciados'' no esquema atribuído a Vorcaro, sem explicar a relação entre as duas cifras. Costa foi afastado do BRB por decisão judicial em nov/2025.','investigacao',NULL,'2025',NULL,0,NULL,NULL,NULL,'O advogado Cleber Lopes disse que a prisão foi ''absolutamente desnecessária'' e que analisará recurso. O BRB não se manifestou na reportagem.',1,'teia','E[41].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(57,'ibaneis-rocha','operacao-compliance-zero','investigacao',NULL,'Tratado como investigado (abr/2026)','O STJ enviou à PGR pedido de investigação de Ibaneis (fev/2026). Em 02/04/2026 Mendonça entendeu que ele deve ser tratado como ''investigado'' e tornou facultativo seu comparecimento à CPI do Crime Organizado. Não há denúncia.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'Ibaneis afirma que não sabia de fraude nas negociações até a liquidação e responsabiliza o ex-presidente do BRB; a decisão de abril não traz manifestação dele.',1,'teia','E[42].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(58,'ibaneis-rocha','reag-investimentos','contratual',NULL,'Cessão de honorários (R$ 38,1 mi)','Segundo o blog de Malu Gaspar (O Globo, 10/03/2026), o escritório de Ibaneis cedeu em maio/2024 ao fundo Pedra Azul FIDC, ligado à Reag, cerca de R$ 38,12 milhões em honorários a receber de ação do Sindilegis. O PSB-DF protocolou notícia de fato no STF pedindo o afastamento do governador.','reportada',NULL,'2024',NULL,0,NULL,38120000.0,NULL,'Os advogados de Ibaneis (escritório de Kakay) dizem que ele está afastado do escritório desde 2018 e que nunca participou de negociações com Marcos Ferreira Costa, executivo ligado ao fundo e à Reag.',1,'teia','E[43].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(59,'ciro-nogueira','daniel-vorcaro','politica',NULL,'Mesada de R$ 300-500 mil (segundo a PF)','Na 5ª fase da Compliance Zero (07/05/2026) Mendonça autorizou busca e apreensão contra Ciro. Segundo a decisão, ele teria recebido mesada de R$ 300 mil de Vorcaro, que a PF diz ''teria evoluído para R$ 500 mil'', encoberta por parceria entre empresas, além de despesas pessoais custeadas por operadores do banqueiro. Investigadores também apontam a venda de participação na empresa Green, estimada em R$ 13 milhões, por R$ 1 milhão a empresa ligada à família do senador. Mendonça afirmou que os elementos indicam, ''em tese'', arranjo de benefícios mútuos. PSOL-Rede pediu a cassação dele ao Conselho de Ética em 17/06/2026. Não há condenação.','investigacao',NULL,'2024',NULL,0,NULL,NULL,NULL,'A defesa ''repudia qualquer ilação de ilicitude'', diz que o senador está à disposição e critica medidas baseadas em ''mera troca de mensagens''. Ciro disse ter ido de van, e não de helicóptero, a evento citado em e-mail.',1,'teia','E[44].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(60,'ciro-nogueira','banco-master','politica',NULL,'Emenda que elevaria o FGC a R$ 1 mi','Ciro apresentou em 2024 a emenda nº 11 à PEC da autonomia do BC, elevando a cobertura do FGC de R$ 250 mil para R$ 1 milhão. Segundo a PF, o texto foi redigido pela assessoria do Master e enviado em envelope; Vorcaro teria comemorado: ''saiu exatamente como mandei''. A emenda foi rejeitada no Senado.','investigacao',NULL,'2024','2024',0,NULL,NULL,NULL,'Os advogados de Ciro rejeitam qualquer ilicitude e dizem que as medidas foram precipitadas.',1,'teia','E[45].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(61,'jaques-wagner','augusto-ferreira-lima','investigacao',NULL,'Apartamento e pagamentos à família','Segundo a PF e a decisão de Mendonça, Wagner teria indicado a Lima um apartamento em Salvador (R$ 2,45 milhões, comprado via Epítome S.A.) e a BN Financeira, ligada à família do senador, teria recebido R$ 3,5 milhões de empresa que a PF associa ao grupo de Lima e ao Credcesta. A PF registra 74 ligações entre os dois (nov/2023 a mai/2025). Não há denúncia.','investigacao',NULL,'2023','2025',0,NULL,3500000.0,NULL,'Wagner nega ser réu, nega ter atuado a favor do Master, diz que o apartamento nunca foi seu e atribui os dólares apreendidos (cerca de US$ 49 mil) a diárias não usadas de missões oficiais. Diz ter encontrado Vorcaro duas vezes e nega relação ou negócios com ele.',1,'teia','E[46].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(62,'jaques-wagner','banco-master','politica',NULL,'Atuação parlamentar investigada','Segundo reportagens, a PF apura se Wagner atuou em temas de interesse do Master (ampliação do consignado, FGC, ''emenda Master'') e qual sua relação com o grupo de Augusto Lima, cujos consignados teriam inflado a carteira negociada com o BRB. Ele foi intimado a depor em agosto/2026 e o Novo pediu sua cassação ao Conselho de Ética (notícia de 31/07/2026). Dados da Receita citam R$ 12 milhões pagos pelo Master à empresa de Bonnie Bonilha, casada com enteado do senador. Não há condenação nem acusação formal.','investigacao',NULL,'2023',NULL,0,NULL,12000000.0,NULL,'Wagner nega atuar politicamente pelo Master e nega vantagens; declinou comentar a intimação por orientação de advogados. O presidente do PT, Edinho Silva, diz que ele é ''depositário de toda a nossa confiança''.',1,'teia','E[47].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(63,'jaques-wagner','ricardo-lewandowski','politica',NULL,'Indicou o escritório ao Master','Wagner confirmou ter sido consultado pela direção do Master sobre ''um bom jurista'' e ter indicado Lewandowski para a consultoria jurídica.','documentada',NULL,'2023','2023',0,NULL,NULL,NULL,'Wagner nega ter participado da contratação de Guido Mantega.',1,'teia','E[48].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(64,'hugo-motta','daniel-vorcaro','pessoal',NULL,'Mensagens de proximidade e pedidos','Mensagens extraídas do celular de Vorcaro, reveladas pelo SBT News, mostram pedidos de Motta (ajuda em empréstimo para empresa da cunhada, avião, helicóptero, camarote) e contato em 19/07/2025 antes de reunião no BC sobre a venda ao BRB. Segundo a reportagem do Times Brasil, as mensagens não mostram o conteúdo das ligações nem interferência na análise do BC.','reportada',NULL,'2024','2025',0,NULL,NULL,NULL,'Motta diz não haver ilícito, que o empréstimo foi anterior às investigações e que vai processar o senador Veneziano Vital do Rêgo por calúnia. Já admitiu que Vorcaro pagou viagem a Lisboa em jun/2024.',1,'teia','E[49].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(65,'daniel-vorcaro','hugo-motta','politica',NULL,'Pedido de empréstimo à cunhada (mar/2024)','Mensagens analisadas pela PF indicam que Motta pediu a Vorcaro a liberação do empréstimo (Jornal de Brasília, Metrópoles); a Folha diz que a conversa começa em 09/03/2024 e trata de possível sociedade no terreno. Motta também teve hospedagem em Lisboa paga por Vorcaro (junho/2024), que ele admite. Nenhuma fonte aponta ato do presidente da Câmara; o pedido foi anterior à presidência.','investigacao',NULL,'2024','2024',0,NULL,NULL,NULL,'Motta: ''nenhum ilícito retratado'', diálogo descontextualizado e com diversos setores.',1,'teia','E[49].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(66,'davi-alcolumbre','daniel-vorcaro','pessoal',NULL,'Mensagens de proximidade (2025)','Mensagens da PF divulgadas pela Veja e confirmadas pela CNN mostram tratamento de ''irmão'' entre os dois em 2025. Em 17/07/2025, quando o BC analisava a venda do Master ao BRB, Vorcaro diz ter procurado Alcolumbre sobre assunto do BC, que ''também não sabe''. A reportagem registra que as mensagens não ligam Alcolumbre à decisão do BC nem à negociação com o BRB. Em outra conversa, Vorcaro disse ter ido a reunião na residência oficial do Senado em ago/2025 sem que Alcolumbre soubesse.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'A assessoria da Presidência do Senado diz que as mensagens são ''supostas'' e de ''teor pessoal'', que não indicam ilegalidade, e anunciou medidas judiciais.',1,'teia','E[50].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(67,'davi-alcolumbre','jocildo-lemos','politica',NULL,'Indicação à Amprev; ex-tesoureiro','Segundo o Poder360, Lemos foi indicado por Alcolumbre à presidência da Amprev e antes atuou como seu tesoureiro. Foi alvo de busca da PF (Operação Zona Cinzenta) por aportes do instituto no Master e pediu exoneração em 11/02/2026.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Segundo a Gazeta do Povo, Alcolumbre nega ter feito a indicação de aliado alvo do caso; o Poder360 não traz manifestação do senador.',1,'teia','E[51].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(68,'amprev','banco-master','financeira',NULL,'Aportes de ~R$ 400 mi (jul/2024)','A PF (Operação Zona Cinzenta, fev/2026) apura aportes de cerca de R$ 400 milhões em letras financeiras, decididos em menos de 20 dias, com alertas internos desconsiderados. Lemos teve ''papel central'' nas reuniões de jul/2024.','investigacao',NULL,'2024',NULL,0,NULL,400000000.0,NULL,'Lemos diz que sua saída permite apuração independente, que sua gestão seguiu a legalidade e que o patrimônio cresceu 41% entre 2023 e 2025.',1,'teia','E[52].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(69,'amprev','banco-master','financeira',NULL,'Letras financeiras (R$ 400 mi)','A Amprev aplicou R$ 400 milhões em letras do Master (4,7% da carteira), com aprovações em julho de 2024 em menos de 20 dias, sem cobertura do FGC.','documentada',NULL,'2024',NULL,0,NULL,400000000.0,NULL,'Em nota, a Amprev disse que se sente lesada pelos malfeitos do Banco Master e não abre mão de ser ressarcida.',1,'teia','E[52].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(70,'rioprevidencia','banco-master','financeira',NULL,'~R$ 3 bi aplicados (2023-2024)','A PF investiga cerca de R$ 970 milhões em letras financeiras (out/2023 a jul/2024, Barco de Papel) e R$ 2,01 bilhões em fundos do banco; os recursos não são cobertos pelo FGC. O ex-presidente Deivis Antunes está preso desde fevereiro, segundo a Folha de Pernambuco.','investigacao',NULL,'2023',NULL,0,NULL,2980000000.0,NULL,'O governo do RJ diz ter aberto procedimento interno (CGE-RJ) em dezembro/2025; Antunes negou irregularidades na carta de renúncia.',1,'teia','E[53].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(71,'rioprevidencia','banco-master','financeira',NULL,'Letras financeiras (R$ 960-970 mi)','Aplicações entre outubro de 2023 e agosto de 2024, com vencimento em 2033 e 2034, sem cobertura do FGC: R$ 970 milhões pelo Ministério da Previdência e R$ 960 milhões segundo o próprio regime. O TCE-RJ calculou R$ 2,6 bilhões em letras e fundos do grupo, número que o regime contesta.','documentada',NULL,'2023',NULL,0,NULL,970000000.0,NULL,'O Rioprevidência diz que seguiu o plano anual de investimentos aprovado pelo conselho, que os benefícios estão garantidos e que negocia trocar as letras por precatórios federais.',1,'teia','E[53].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(72,'claudio-castro','rioprevidencia','politica',NULL,'Governador na época dos aportes','Os aportes ocorreram na gestão de Castro (PL), que exonerou o presidente do instituto em 23/01/2026. Castro foi alvo de operação distinta da PF (Sem Refino, 15/05/2026). Nas fontes abertas não há imputação a ele sobre os aportes no Master.','documentada',NULL,'2023','2026',0,NULL,NULL,NULL,'O governo do RJ informou investigação interna; a defesa de Castro nega irregularidades (em referência à operação de maio).',1,'teia','E[54].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(73,'amazonprev','banco-master','financeira',NULL,'~R$ 390 mi aplicados','A PF cumpriu sete mandados de busca em março/2026, que alcançaram três ex-diretores do instituto do Amazonas, por suspeita de aplicações irregulares de cerca de R$ 390 milhões no Master; servidores também foram afastados das funções, segundo a Folha de Pernambuco.','investigacao',NULL,'2024',NULL,0,NULL,390000000.0,NULL,'',1,'teia','E[55].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(74,'aparecidaprev','banco-master','financeira',NULL,'R$ 40 mi (jun/2024)','O MPGO apura aplicação de cerca de R$ 40 milhões feita em jun/2024, na gestão do ex-prefeito Vilmar Mariano. Segundo a prefeitura atual, o banco foi apresentado ao instituto pelo ex-secretário da Fazenda Einstein Paniago.','investigacao',NULL,'2024',NULL,0,NULL,40000000.0,NULL,'A prefeitura diz que o banco tinha nota inferior à permitida pela política do fundo, que comunicou os órgãos de controle em jan/2025 e que nenhum aposentado será prejudicado.',1,'teia','E[56].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(75,'ricardo-lewandowski','banco-master','contratual',NULL,'Consultoria jurídica: R$ 250 mil/mês','Contrato assinado em 28/08/2023, pago até set/2025 (cerca de R$ 6,5 milhões brutos, dos quais R$ 5,25 milhões após ele assumir o Ministério da Justiça, em jan/2024). A Receita registra R$ 6,1 milhões declarados pelo Master ao escritório de familiares.','documentada',NULL,'2023','2025',0,NULL,6100000.0,NULL,'Lewandowski diz que se desligou do escritório e suspendeu o registro na OAB ao assumir o ministério e deixou de atuar nos casos.',1,'teia','E[57].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(76,'guido-mantega','banco-master','contratual',NULL,'Consultoria: R$ 14 mi (Pollaris)','Dados da Receita enviados à CPI do Crime Organizado mostram R$ 14 milhões pagos pelo Master à Pollaris Consultoria, de Mantega. Reportagens citam remuneração de cerca de R$ 1 milhão por mês. Wagner nega ter indicado Mantega ao banco.','documentada',NULL,'2025','2025',0,NULL,14000000.0,NULL,'Mantega confirmou o contrato e disse não ter conhecimento de irregularidades; negou irregularidades e disse ter atuado tecnicamente e dentro da lei.',1,'teia','E[58].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(77,'guido-mantega','daniel-vorcaro','politica',NULL,'Articulação junto a Lula','Mantega intermediou a reunião de Vorcaro com Lula em 04/12/2024 (Lula diz que foi pedido de Mantega). Segundo o Times Brasil, mensagens de jul/2025 com o advogado Walfrido Warde mostram proposta de levar Mantega a um encontro com Lula, quando o BC levantava novos questionamentos sobre o Master e a venda ao BRB.','reportada',NULL,'2024','2025',0,NULL,NULL,NULL,'O Planalto diz que houve um único encontro com Lula e que não houve outro contato; a matéria do Times Brasil não traz manifestação de Mantega.',1,'teia','E[59].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(78,'luiz-inacio-lula-da-silva','daniel-vorcaro','politica',NULL,'Reunião fora da agenda (04/12/2024)','O Planalto confirma encontro de Lula com Vorcaro em 04/12/2024, fora da agenda, com Mantega, Rui Costa e Galípolo (este em parte do encontro). Segundo Lula, a reunião foi pedido de Mantega. Relatos da imprensa (Poder360/UOL, via Band) dizem que Lula desaconselhou a venda do Master ao BTG.','documentada',NULL,'2024','2024',0,NULL,NULL,NULL,'Segundo o governo, Lula só se reuniu uma vez com Vorcaro; Lula disse que denúncias deveriam ser analisadas tecnicamente pelo BC e que não haveria posição política pró ou contra o Master.',1,'teia','E[60].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(79,'henrique-meirelles','banco-master','contratual',NULL,'Consultoria (R$ 8 mi segundo a CNN)','Dados da Receita sobre declarações do Master mostram pagamentos a empresa de Meirelles por consultoria; a CNN Brasil informa R$ 8 milhões e o Jornal Opção, R$ 18,5 milhões. Meirelles diz que o contrato, de março de 2024 a julho de 2025, era de consultoria ''em caráter opinativo''.','documentada',NULL,'2023','2025',0,NULL,8000000.0,NULL,'Meirelles confirmou o contrato de consultoria ''em caráter opinativo'' sobre macroeconomia e mercado financeiro e disse não ter conhecimento de eventuais irregularidades.',1,'teia','E[61].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(80,'michel-temer','banco-master','contratual',NULL,'Escritório: mediação jurídica','Dados da Receita mostram R$ 10 milhões pagos pelo Master ao escritório de Temer (2023-2025).','documentada',NULL,'2023','2025',0,NULL,10000000.0,NULL,'Temer confirma a prestação de serviços de mediação jurídica, mas diz que recebeu R$ 7,5 milhões.',1,'teia','E[62].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(81,'antonio-rueda','banco-master','contratual',NULL,'Escritórios: R$ 6,4 mi','Dados da Receita mostram R$ 6,4 milhões pagos desde 2023 a escritórios associados a Rueda. A CPI ressalva que as transferências, isoladamente, não comprovam crime.','documentada',NULL,'2023',NULL,0,NULL,6400000.0,NULL,'Rueda reconhece ter advogado para o Master e diz que a atuação foi técnica; o União Brasil afirma que os serviços foram efetivos e documentados e criticou o vazamento de dados fiscais.',1,'teia','E[63].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(82,'acm-neto','banco-master','contratual',NULL,'A&M Consultoria: R$ 5,45 mi','Dados da Receita mostram R$ 5,45 milhões pagos pelo Master à A&M Consultoria, ligada a ACM Neto, entre 2023 e 2025.','documentada',NULL,'2023','2025',0,NULL,5450000.0,NULL,'O União Brasil diz que os serviços foram estritamente técnicos; a defesa de ACM Neto afirma que a relação comercial foi lícita e transparente.',1,'teia','E[64].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(83,'rui-costa','banco-master','politica',NULL,'Credcesta / Ebal (Bahia)','Segundo o BNews, decreto de Rui Costa (13/01/2022) vedou a portabilidade do Credcesta, programa de consignado ligado à privatização da Ebal (2018) e operado pelo universo Master/Augusto Lima. Não há imputação de crime a ele nas fontes abertas.','reportada',NULL,'2018','2022',0,NULL,NULL,NULL,'Rui Costa chamou de ''fantasia'' as ligações entre o PT baiano e o Master e disse que a venda da Ebal, falida, foi legal; não respondeu especificamente sobre o decreto.',1,'teia','E[65].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(84,'augusto-ferreira-lima','daniel-vorcaro','societaria',NULL,'Ex-sócio no Master','Lima foi sócio do Master, preso e solto na primeira fase da Compliance Zero e novamente alvo na 9ª fase (jun/2026); a PF o liga ao negócio do Credcesta e a Wagner.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'A defesa de Lima não foi localizada pelo Poder360.',1,'teia','E[66].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(85,'fabiano-zettel','jair-bolsonaro','financeira',NULL,'Doação de R$ 3 mi (campanha 2022)','Dados do TSE: Zettel, cunhado de Vorcaro, doou R$ 3 milhões à campanha de Bolsonaro em 2022 (2,38% do total arrecadado; ele está entre os cinco maiores doadores). Em proposta de delação rejeitada por PF e PGR por falta de corroboração, Vorcaro afirmou que as doações a Bolsonaro e a Tarcísio seriam contrapartida ilícita ligada ao Credcesta em SP (reportagem do UOL citada pelo Poder360).','documentada',NULL,'2022','2022',0,NULL,3000000.0,NULL,'Valdemar Costa Neto (PL) disse que ''todo mundo doa''; o PL não respondeu à CNN. A defesa de Zettel diz que suas atividades são lícitas e sem relação com a gestão do Master.',1,'teia','E[67].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(86,'fabiano-zettel','tarcisio-de-freitas','financeira',NULL,'Doação de R$ 2 mi (campanha 2022)','Dados do TSE: Zettel foi o maior doador pessoa física da campanha de Tarcísio em 2022 (R$ 2 milhões). Em proposta de delação rejeitada por PF e PGR por falta de corroboração, Vorcaro afirmou que as doações seriam contrapartida ilícita ligada ao Credcesta em SP, negociada com Gilberto Kassab; Kassab e Tarcísio negam.','documentada',NULL,'2022','2022',0,NULL,2000000.0,NULL,'A campanha diz ter respeitado a lei, ter tido mais de 600 doadores e contas aprovadas pela Justiça Eleitoral, e que Tarcísio não tem vínculo com o doador; Tarcísio nega qualquer contato ou relação com Vorcaro, e Kassab nega ter tratado de doações com Lima ou Vorcaro.',1,'teia','E[68].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(87,'henrique-vorcaro','partido-novo-diretorio-de-minas-gerais','financeira',NULL,'Doação de R$ 1 mi (2022)','O pai de Daniel Vorcaro doou R$ 1 milhão ao diretório estadual do Novo em MG para manutenção partidária, conforme prestação de contas anual de 2022 ao TSE; a reportagem não encontrou doação à campanha de Romeu Zema.','documentada',NULL,'2022','2022',0,NULL,1000000.0,NULL,'O Novo-MG diz que a doação é ''pública e devidamente registrada'' e que em 2022 as ilegalidades do Master eram desconhecidas.',1,'teia','E[69].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(88,'alexandre-de-moraes','daniel-vorcaro','investigacao',NULL,'52 mensagens em relatório da PF','Relatório da PF, cujo sigilo Mendonça levantou em 01/09/2026, aponta 52 mensagens de Vorcaro a número atribuído a Moraes (2023 a 17/11/2025), incluindo cópia do contrato de R$ 131 milhões com o escritório da esposa dele e busca por informação sobre operação iminente; as respostas não foram recuperadas. Em 15/09/2026 o plenário começou a analisar questão de ordem sobre julgar em conjunto ou separadamente os pedidos envolvendo Moraes e Mendonça (4 a 3 pela separação) e Dino pediu vista. A PGR pede a anulação do relatório. Não há decisão de mérito.','investigacao',NULL,'2023',NULL,0,NULL,NULL,NULL,'Moraes nega qualquer contato com Vorcaro, nega ter recebido mensagens de visualização única e acusa Mendonça de direcionar investigações contra desafetos; Mendonça nega (''Mentira'').',1,'teia','E[70].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(89,'dias-toffoli','maridt-participacoes','societaria',NULL,'Sócio de empresa familiar','Toffoli admitiu ser sócio da Maridt, que detinha participação no resort Tayayá (PR); vendeu em duas etapas (27/09/2021 ao fundo Arllen; 21/02/2025 à PHD Holding), tudo declarado à Receita segundo o gabinete.','documentada',NULL,'2021',NULL,0,NULL,NULL,NULL,'Toffoli diz que a Lei Orgânica da Magistratura permite ser sócio e receber dividendos, sem atos de gestão.',1,'teia','E[71].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(90,'dias-toffoli','daniel-vorcaro','investigacao',NULL,'Resort Tayayá; relatório da PF','Relatório de 200 páginas da PF entregue a Fachin em 09/02/2026 cita Toffoli em conversas de Vorcaro com o cunhado Zettel sobre o Tayayá. Mensagens citadas pelo Estadão somam cerca de R$ 35 milhões de aportes de Vorcaro no fundo do resort (valor não é pagamento a Toffoli). A PF arguiu suspeição.','investigacao',NULL,'2021','2025',0,NULL,NULL,NULL,'Toffoli nega amizade com Vorcaro e diz que ''jamais recebeu qualquer valor de Daniel Vorcaro ou de seu cunhado Fabiano Zettel''; o STF disse não haver suspeição ou impedimento.',1,'teia','E[72].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(91,'dias-toffoli','banco-master','juridica',NULL,'Relator do inquérito (dez/25 a fev/26)','Relatou o caso no STF a partir de dezembro/2025 (após menção a autoridade com foro), restringiu o acesso aos autos e a PGR arquivou, em jan/2026, três representações pedindo seu afastamento. Deixou a relatoria em 12/02/2026 alegando ''altos interesses institucionais''; os ministros emitiram nota de apoio e reconheceram a validade dos seus atos. Mendonça depois reforçou o papel técnico da PF, o que levou à saída do perito e do delegado que Toffoli havia designado.','documentada',NULL,'2025','2026',0,NULL,NULL,NULL,'Toffoli nega amizade com Vorcaro e ter recebido valores dele ou de Zettel; o gabinete confirma que ele é sócio da Maridt, que teve participação no resort Tayayá (vendida em 2021 e 2025).',1,'teia','E[73].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(92,'andre-mendonca','banco-master','juridica',NULL,'Relator desde 12/02/2026','Assumiu o caso por sorteio em 12/02/2026. Autorizou a prisão de Vorcaro (04/03), a prisão de Costa (16/04), a busca em Ciro (07/05), a 9ª fase contra Wagner (18/06) e inquérito sobre Dark Horse (23/07); levantou o sigilo de relatório da PF em 01/09 e, a pedido de Fachin, o sigilo do inquérito e de outros 14 processos (notícia de 11/09). As propostas de delação de Vorcaro apresentadas até agora foram rejeitadas por PF e PGR.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'Mendonça disse não ter tido acesso à proposta de delação; Moraes o acusa de direcionar investigações, o que Mendonça nega.',1,'teia','E[74].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(93,'gilmar-mendes','banco-master','juridica',NULL,'Relator de recurso; palestrante em fórum','Gilmar é relator no STF de recurso do Master contra a União sobre CSLL e participou de painel do fórum em Londres (abr/2024) com patrocínio não divulgado do banco. Em 22/06/2026 criticou Mendonça por participar de negociação de delação (''erro crasso''); em set/2026 seu gabinete recebeu da PF a íntegra do material do celular de Vorcaro e, em outubro, pediu a Fachin a identificação de todos os envolvidos nas conversas.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'O Master classificou o patrocínio oculto como ''estratégia de marca''; Gilmar não é apontado por irregularidade nas fontes abertas.',1,'teia','E[75].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(94,'banco-master','grupo-voto','contratual',NULL,'Patrocínio oculto de fórum em Londres','O Master custeou a palestra de Tony Blair (cerca de 120 mil libras, ~R$ 765 mil, segundo o Poder360) no 1º Fórum Jurídico Brasil de Ideias (Londres, abr/2024), sem constar como patrocinador. O banco tinha 27 ações no STJ e um recurso no STF; os ministros Gilmar Mendes e Raul Araújo, relatores de processos do banco, participaram de painéis do evento.','documentada',NULL,'2024','2024',0,NULL,765000.0,NULL,'O Master chamou o patrocínio oculto de ''estratégia de marca''; o Grupo Voto disse que patrocinadores são privados e que a comunicação foi decisão da organização.',1,'teia','E[76].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(95,'paulo-gonet','daniel-vorcaro','pessoal',NULL,'Encontro em Londres (abr/2024)','A PGR confirmou a autenticidade de foto de Gonet com Vorcaro em evento em Londres (abr/2024), achada pela PF no celular do banqueiro. Relatório da PF também cita viagem de filho de Gonet a Londres supostamente bancada por Vorcaro. O Conselho Superior do MPF rejeitou por 5 a 4, em 25/09/2026, abrir investigação por prevaricação.','documentada',NULL,'2024','2025',0,NULL,NULL,NULL,'Gonet diz ter encontrado Vorcaro uma vez, contato ''brevíssimo e banal'', sem interesse pessoal; pede a nulidade do relatório da PF que o cita.',1,'teia','E[77].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(96,'paulo-sergio-neves-de-souza','daniel-vorcaro','financeira',NULL,'Mesada / ''consultor informal'' (PF)','Segundo a PF, o ex-diretor de Fiscalização teria atuado como ''consultor informal'' de Vorcaro, com recebimento mensal de vantagens indevidas por meio de contratos de consultoria simulados, e alertado Vorcaro sobre movimentações monitoradas pelo BC. Foi afastado do cargo em jan/2026 pelo BC e, em 04/03/2026, passou a usar tornozeleira por decisão de Mendonça, que o descreveu como ''espécie de empregado/consultor de Vorcaro''.','investigacao',NULL,'2022','2026',0,NULL,NULL,NULL,'As reportagens (Estadão, Forbes) não trazem resposta da defesa; Mendonça tornou facultativo seu comparecimento à CPI do Crime Organizado (decisão de 18/03/2026).',1,'teia','E[78].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(97,'belline-santana','daniel-vorcaro','financeira',NULL,'Relação semelhante (segundo a PF)','Ex-chefe do Departamento de Supervisão Bancária do BC, afastada em jan/2026 pelo BC, alvo de tornozeleira e busca em 04/03/2026 por suspeitas semelhantes às de Souza; segundo a PF, mensagens de WhatsApp indicariam o mesmo tipo de relação com Vorcaro.','investigacao',NULL,'2022','2026',0,NULL,NULL,NULL,'A reportagem do Estadão não traz resposta da defesa.',1,'teia','E[79].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(98,'roberto-campos-neto','banco-master','politica',NULL,'Supervisão na sua gestão no BC','O Master foi aprovado e cresceu durante a presidência de Campos Neto (2019-2024); a inspeção do TCU analisou também esse período. Não há imputação a ele nas fontes abertas.','reportada',NULL,'2019','2024',0,NULL,NULL,NULL,'Campos Neto nega inércia e diz que o BC fez alertas ao Master (segundo reportagem).',1,'teia','E[80].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(99,'gabriel-galipolo','daniel-vorcaro','politica',NULL,'Reuniões com Vorcaro (2024-2025)','Galípolo participou de trecho do encontro Lula-Vorcaro (04/12/2024) e recebeu Vorcaro no BC em jul/2025 para tratar da documentação da venda ao BRB. Diz que o BC teve dúvidas sobre as carteiras desde jan/2025 e que a liquidação veio após trabalho com o FGC; Aquino deu à PF versão diferente sobre quando a fraude foi confirmada (jun/2025).','documentada',NULL,'2024','2025',0,NULL,NULL,NULL,'Galípolo afirmou publicamente que o BC ''faz notícias de fatos'' às autoridades; o BC também disse que não houve reunião Galípolo-Alcolumbre em 17/07/2025, como as mensagens sugeriam.',1,'teia','E[81].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(100,'tcu','bcb','juridica',NULL,'Inspeção sobre a liquidação do Master','Em dez/2025 o relator Jhonatan de Jesus determinou inspeção no BC; a decisão foi suspensa em 07/01/2026 a pedido do BC e a inspeção seguiu após entendimento entre o presidente do TCU e o BC. Auditores concluíram a inspeção documental em 06/02/2026. Segundo o presidente do TCU, Vital do Rêgo, reverter a liquidação não cabe à Corte.','documentada',NULL,'2025','2026',0,NULL,NULL,NULL,'O BC pediu a suspensão da inspeção e concordou em seguida; o presidente do TCU disse que o BC conduz a liquidação.',1,'teia','E[82].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(101,'cvm','banco-master','investigacao',NULL,'Denúncia do FGC arquivada; PF apura','A área técnica da CVM arquivou em 2022 denúncia do FGC sobre o Grupo Master. Em 24/09/2026 Dino determinou à PF inquérito sobre possíveis irregularidades na atuação da CVM, incluindo esse arquivamento, e citou indícios de influência de autoridades de alto escalão (relatório inicial em 60 dias). Em fev/2026 a CVM informou ter 6 inquéritos administrativos e 8 processos sancionadores em casos que incluem Master, Reag e entidades conexas.','investigacao',NULL,'2022',NULL,0,NULL,NULL,NULL,'O texto da decisão não traz manifestação pública da CVM.',1,'teia','E[83].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(102,'flavio-dino','cvm','juridica',NULL,'Manda PF investigar a CVM','Na ADI 7.791, Dino citou relatório de grupo de trabalho da própria CVM (314 processos analisados, 100 com deficiências de compliance) e indícios de que autoridades de alto escalão teriam influenciado decisões da autarquia; determinou inquérito à PF (relatório em 60 dias) e envio do processo pela CVM em 72 horas. Em decisão anterior (20/09), dera 90 dias à União para revisar as normas da CVM.','documentada',NULL,'2026','2026',0,NULL,NULL,NULL,'',1,'teia','E[84].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(103,'cpi-do-crime-organizado','banco-master','investigacao',NULL,'Dados da Receita e convocações','A CPI recebeu da Receita as declarações do Master sobre pagamentos a Temer, Meirelles, Mantega, Lewandowski, Rueda, ACM Neto e outros, aprovou convocações (Paulo Sérgio, Ibaneis, Castro) e trata de lavagem de dinheiro e de ligações entre ministros do STF e investigados.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'Mendonça tornou facultativo o comparecimento de Paulo Sérgio e de Ibaneis, como investigados.',1,'teia','E[85].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(104,'edson-fachin','pf','juridica',NULL,'Pede lista de ministros citados','Em 02/10/2026 Fachin enviou ofício à PF pedindo levantamento dos ministros do STF citados nas conversas de Vorcaro e marcou reunião com o diretor-geral, Andrei Rodrigues, para 13/10. Gilmar pediu, em ofício a Fachin, a identificação de todos os envolvidos. A reportagem cita os nomes de Nunes Marques, Toffoli, Fux e Mendonça, além de mensagem enviada a número atribuído a Moraes, e não informa se as menções implicam irregularidade.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'',1,'teia','E[86].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(105,'operacao-compliance-zero','daniel-vorcaro','investigacao',NULL,'Prisões de 17/11/2025 e 04/03/2026','Vorcaro foi preso na 1ª fase (17/11/2025), solto pelo TRF-1 com tornozeleira, e preso de novo em 04/03/2026 por mensagens sobre intimidação de adversários. Em 18/09 a defesa pediu a Fachin a revogação. Propostas de delação anteriores foram rejeitadas por PF e PGR e a negociação está parada.','investigacao',NULL,'2025',NULL,0,NULL,NULL,NULL,'A defesa nega categoricamente as acusações; negou tentativa de fuga em 2025 (viagem para assinar a venda do banco).',1,'teia','E[87].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(106,'xp-investimentos','banco-master','financeira',NULL,'CDBs distribuídos pela XP (~R$ 26 bi)','Segundo a Bloomberg Línea, a XP distribuiu cerca de R$ 26 bilhões em CDBs do Master, o maior volume entre as instituições; os CDBs do Master pagavam até 140% do DI. Referência: relatos de 2025.','reportada',NULL,'2024','2025',0,NULL,26000000000.0,NULL,'A XP disse que a remuneração média dos assessores em renda fixa é de 0,3% ao ano, em linha com o mercado.',1,'teia','E[88].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(107,'btg-pactual','banco-master','financeira',NULL,'CDBs distribuídos pelo BTG (~R$ 6,7 bi)','O BTG distribuiu cerca de R$ 6,7 bilhões em CDBs do Master (16% da captação com garantia do FGC, segundo o Times Brasil) e interrompeu as vendas em outubro ou dezembro de 2024, conforme a fonte.','reportada',NULL,'2024','2024',0,NULL,6700000000.0,NULL,'O diretor financeiro Renato Cohn reconheceu que ''houve um exagero''; o CEO Roberto Sallouti disse que ''o erro não está na distribuição, está no que o banco fez com o dinheiro captado''.',1,'teia','E[89].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(108,'easynvest','banco-master','financeira',NULL,'CDBs via Easynvest (~R$ 2,9 bi)','Segundo a Bloomberg, a Easynvest distribuiu cerca de R$ 2,9 bilhões em CDBs do Master, metade antes da compra pelo Nubank em 2020; o Nubank parou em julho de 2024.','reportada',NULL,'2020','2024',0,NULL,2900000000.0,NULL,'Nubank e BTG não comentaram à Bloomberg.',1,'teia','E[90].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(109,'instituto-abradecont','xp-investimentos','investigacao',NULL,'Ação civil pública (R$ 100 mi)','Ação no Rio de Janeiro acusa XP e BTG de publicidade enganosa e conflito de interesses na venda de CDBs do Master; pede caução de 65% à XP e dano moral coletivo de R$ 100 milhões a ser dividido entre as duas.','investigacao',NULL,'2026',NULL,0,NULL,100000000.0,NULL,'A reportagem não registra resposta da XP à ação.',1,'teia','E[91].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(110,'instituto-abradecont','btg-pactual','investigacao',NULL,'Ação civil pública (caução de 25%)','Na mesma ação, pede-se caução de 25% ao BTG, restituição dos prejuízos não cobertos pelo FGC e dano moral coletivo de R$ 100 milhões repartido entre as instituições.','investigacao',NULL,'2026',NULL,0,NULL,100000000.0,NULL,'O BTG não comentou a ação desde janeiro de 2026.',1,'teia','E[92].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(111,'fgc','banco-master','financeira',NULL,'Ressarcimento a credores (~R$ 40,6 bi)','O FGC projetou desembolsar R$ 40,6 bilhões (cerca de R$ 41 bilhões em outras reportagens) em garantias do conglomerado Master, com pagamentos iniciados em 17/01/2026; em maio de 2026 quase R$ 40 bilhões haviam sido pagos a mais de 915 mil credores, e cerca de R$ 2,2 bilhões seguiam disponíveis para retirada. As estimativas de credores variam: cerca de 800 mil atendidos (Poder360) a 1,6 milhão com valores a receber (Times Brasil).','documentada',NULL,'2025',NULL,0,NULL,40600000000.0,NULL,'O FGC tem reforçado que os credores precisam solicitar formalmente a garantia (limite de R$ 250 mil por CPF/CNPJ).',1,'teia','E[93].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(112,'fgc','banco-master','financeira',NULL,'Assistência de 2025 (R$ 4-4,3 bi)','Entre 05/05 e 01/10/2025 o FGC concedeu assistência financeira de cerca de R$ 4,3 bilhões (R$ 4 bilhões em maio, segundo a Folha) para quitar instrumentos cobertos pela garantia; o conglomerado captou só R$ 90,2 milhões no período, segundo a CNN. A linha foi estendida exclusivamente à Will Financeira até 30/11/2025. Segundo a Folha, o contrato previa suspensão da ajuda em caso de investigação da PF ou do MPF.','reportada',NULL,'2025','2025',0,NULL,4300000000.0,NULL,'O FGC disse que não comenta entidades associadas; em 23/09/2025 avisou ao Master que a extensão exigiria plano concreto de saída.',1,'teia','E[93].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(113,'fgc','will-financeira','financeira',NULL,'Garantias do Will (~R$ 6,3 bi)','Com a liquidação em janeiro de 2026, o FGC estimou em cerca de R$ 6,3 bilhões os pagamentos aos clientes do Will, com base em dados preliminares.','documentada',NULL,'2026',NULL,0,NULL,6300000000.0,NULL,'',1,'teia','E[94].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(114,'fgc','banco-pleno','financeira',NULL,'Garantias do Pleno (~R$ 4,9 bi)','Após a liquidação de 18/02/2026, o FGC confirmou que ressarciria cerca de R$ 4,9 bilhões a cerca de 160 mil credores do Banco Pleno, segundo o Estadão reproduzido pela Revista Oeste.','reportada',NULL,'2026',NULL,0,NULL,4900000000.0,NULL,'',1,'teia','E[95].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(115,'bancos-associados-ao-fgc','fgc','financeira',NULL,'Antecipação de contribuições (~R$ 42 bi)','Plano do conselho do FGC (aprovado em 10/02/2026 segundo o Mercado & Consumo; o Times Brasil registrou o aval em 09/02): antecipação de cinco anos de contribuições em 2026 (cerca de R$ 30 bilhões) e de 12 meses em 2027 e em 2028 (cerca de R$ 12 bilhões), mais alíquota extra de 0,06% (cerca de R$ 3 bilhões por ano), segundo o Valor. O valor de R$ 42 bilhões é a soma das duas antecipações, calculada, e não consta como total nas fontes. O custo total do caso foi estimado em R$ 55 bilhões (Valor) a R$ 58 bilhões (Estadão).','reportada',NULL,'2026','2028',0,NULL,42000000000.0,NULL,'Em nota, o FGC evitou comentar alternativas em avaliação, disse que as discussões sobre a recomposição da liquidez estão avançadas e reafirmou o compromisso de honrar as garantias.',1,'teia','E[96].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(116,'daniel-vorcaro','fgc','financeira',NULL,'Devolução de R$ 40 bi oferecida na delação (rejeitada)','Na base da delação entregue em 05/05/2026, a defesa de Vorcaro se comprometeu a devolver ao menos R$ 40 bilhões (a reportagem não especifica o beneficiário). Segundo a Exame (15/06), a PF formalizou a rejeição por falta de informações inéditas e a PGR tendia a seguir; a Gazeta do Povo (22/07) relatou que PF e PGR rejeitaram as propostas.','reportada',NULL,'2026','2026',0,NULL,40000000000.0,NULL,'As reportagens citadas não trazem manifestação pública da defesa sobre a proposta; não há registro de homologação de acordo.',1,'teia','E[97].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(117,'tirreno','banco-master','financeira',NULL,'Créditos Tirreno (provisão ~R$ 2,6 bi)','A PF descreve a Tirreno, criada em dezembro de 2024, como empresa de fachada que originou os consignados dos títulos vendidos ao BRB; auditoria do BC pedida pelo MPF indicou cerca de R$ 2,6 bilhões a provisionar sobre créditos da empresa.','investigacao',NULL,'2024','2025',0,NULL,2600000000.0,NULL,'A Cartos nega ter originado ou cedido qualquer crédito ligado ao caso e nega relação com a Tirreno; a Tirreno não se manifestou nas fontes.',1,'teia','E[98].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(118,'quadra-gestao-de-recursos','brb','contratual',NULL,'Memorando de venda (ref. R$ 15 bi)','Memorando de abril de 2026 previa fundo para receber ativos do Master com referência de R$ 15 bilhões (R$ 3 a 4 bilhões à vista); foi encerrado em 17/07/2026 sem conclusão das diligências. Um pagamento inicial de R$ 1 bilhão noticiado em maio não foi confirmado nas demais fontes.','documentada',NULL,'2026','2026',0,NULL,15000000000.0,NULL,'O BRB disse que as negociações foram encerradas de forma consensual e que fará a gestão e a recolocação dos ativos.',1,'teia','E[99].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(119,'fgc','brb','financeira',NULL,'Empréstimo pleiteado (até R$ 6,6 bi)','Acordo entre União e GDF, em conciliação conduzida por Fux no STF em 28/05/2026, viabiliza o pedido de empréstimo de até R$ 6,6 bilhões do FGC ao BRB, com FPE e FPM como contragarantia e sem aval da União; juros propostos de IPCA + 4,5% e carência de 18 meses. Os maiores bancos seriam fiadores, mas, segundo o Bem Paraná, ainda não havia concordância deles; as fontes não registram contrato assinado.','documentada',NULL,'2026',NULL,0,NULL,6600000000.0,NULL,'A Secretaria de Economia do DF diz que o governo está pronto para assinar e que não há prazo legal para concluir; PSOL, PSB e PT (com apoio de PDT e Rede) questionam a lei autorizadora no TJDFT.',1,'teia','E[100].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(120,'governo-do-distrito-federal','brb','financeira',NULL,'Securitização dívida ativa (R$ 1,17 bi)','Parte do rombo seria coberta pela securitização da dívida ativa do DF: a primeira operação rendeu R$ 1,17 bilhão e o presidente do BRB estimou cerca de R$ 3 bilhões com mais duas.','documentada',NULL,'2026',NULL,0,NULL,1170000000.0,NULL,'',1,'teia','E[101].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(121,'daniel-vorcaro','paulo-henrique-costa','financeira',NULL,'Imóveis atribuídos (R$ 74-146 mi)','Segundo a PF, Costa teria recebido pelo menos seis imóveis de Vorcaro em troca de facilitar negócios do BRB com o Master; os valores citados são R$ 74 milhões (transferências) e R$ 146 a 146,5 milhões (suposta propina total). Reportagens indicam uso de fundos da Reag para ocultar a origem.','investigacao',NULL,'2024','2026',0,NULL,146000000.0,NULL,'A defesa de Costa nega que ele tenha recebido valores indevidos e chama a prisão de absolutamente desnecessária.',1,'teia','E[102].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(122,'banco-master','augusto-ferreira-lima','financeira',NULL,'Pagamentos por serviços sob investigação','A PF atribui a Lima a elaboração das carteiras fraudulentas a partir de janeiro de 2025 e investiga pagamentos recebidos do Master; o valor não consta nas fontes.','investigacao',NULL,'2025','2025',0,NULL,NULL,NULL,'A defesa nega ter atuado em carteiras ou negociado com o BRB, diz que saiu do Master em 28/05/2024 e que os pagamentos decorreram de contrato regular de serviços.',1,'teia','E[103].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(123,'banco-master','banco-pleno','societaria',NULL,'Venda do Voiter/Pleno a Lima (2025)','O Master vendeu o então Voiter a Augusto Lima em setembro de 2025 (contrato de junho), com autorização do BC a partir de 11/08/2025 e mudança de nome para Pleno; o preço não consta nas fontes.','documentada',NULL,'2025','2025',0,NULL,NULL,NULL,'O Banco Pleno disse não ser alvo da operação nem ter relação societária com o Master.',1,'teia','E[104].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(124,'roberto-de-rezende-barbosa','banco-master','societaria',NULL,'Venda do Voiter e aporte (R$ 800 mi)','Em fevereiro de 2024 o Master anunciou a compra do Voiter, elevando seu PL em R$ 800 milhões (R$ 400 milhões do PL do Voiter e R$ 400 milhões aportados pelo vendedor).','documentada',NULL,'2024','2024',0,NULL,800000000.0,NULL,'',1,'teia','E[105].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(125,'banco-master','will-financeira','societaria',NULL,'Aquisição do Will em 30/08/2024','O conglomerado Master adquiriu a Will Financeira em 30/08/2024, segundo o FGC. Em 18/11/2025 o BC aplicou o regime especial (Raet) ao Master Múltiplo, controlador do Will, para tentar viabilizar a venda do Will; o BC liquidou a Will Financeira em 21/01/2026.','documentada',NULL,'2024','2026',0,NULL,NULL,NULL,'',1,'teia','E[106].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(126,'efb-regimes-especiais-de-empresas','daniel-vorcaro','investigacao',NULL,'Ação do liquidante (>= R$ 4,8 bi)','Na 3ª Vara de Falências de SP, o liquidante busca recuperar bens e fundos ligados a Vorcaro que teriam sido desviados antes da liquidação; o Metrópoles consolidou ao menos R$ 4,8 bilhões a partir de dados da ação (não é valor declarado pelo liquidante). Em 17/03/2026 o juiz deferiu protesto contra alienações de 19 imóveis, 13 empresas e 3 fundos, o que alerta terceiros de que a aquisição pode ser considerada ineficaz. A ação descreve ''mecanismo sistemático de desvio'' de fundo do grupo Master para o Astralo 95.','investigacao',NULL,'2026',NULL,0,NULL,4800000000.0,NULL,'A defesa de Vorcaro disse ao Metrópoles que não se manifestaria sobre o tema.',1,'teia','E[107].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(127,'efb-regimes-especiais-de-empresas','daniel-vorcaro','investigacao',NULL,'Desvio de US$ 1 bi (EUA e Bahamas)','Segundo apuração preliminar do liquidante apresentada à Justiça das Bahamas, ''é razoavelmente claro'' que Vorcaro e outros desviaram ao menos US$ 1 bilhão de ativos do Master; o liquidante apontou nove entidades ligadas ao banco no país. Em tribunal dos EUA, o liquidante descreveu ''fraude massiva'' e bens ''supostamente desviados'', sem quantificar. Ambos os tribunais reconheceram a liquidação.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'Nos EUA, a defesa de Vorcaro tentou impedir o reconhecimento, alegando que a decisão do BC era prematura; sobre a decisão das Bahamas, disse que não comentaria.',1,'teia','E[107].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(128,'banco-master','astralo-95','financeira',NULL,'Cotas Hans II vendidas por R$ 294 mi','Segundo a ação do liquidante, cotas do fundo Hans II, que Vorcaro teria comprado por R$ 2,5 milhões, foram vendidas por R$ 294 milhões a um fundo cujo único cotista é o Astralo 95 (retorno de 11.400% segundo a ação); o liquidante fala em ''mecanismo sistemático de desvio de recursos''.','investigacao',NULL,'2023',NULL,0,NULL,294000000.0,NULL,'A defesa de Vorcaro disse ao Metrópoles que não se manifestaria sobre o tema.',1,'teia','E[108].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(129,'stf','daniel-vorcaro','investigacao',NULL,'Bloqueio de bens no exterior (> R$ 2 bi)','Decisão de Mendonça de 24/07/2026, tornada pública em 13/09: 18 bens no exterior somando mais de R$ 1,9 bilhão (R$ 2 bilhões com itens sem avaliação) e ativos das instituições liquidadas e imóveis de R$ 21,4 bilhões; inclui obras de Basquiat, Picasso e R$ 280 milhões da venda de aeronave.','documentada',NULL,'2026',NULL,0,NULL,2000000000.0,NULL,'',1,'teia','E[109].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(130,'pf','daniel-vorcaro','investigacao',NULL,'Bloqueio de R$ 5,7 bi (2ª fase)','Em 14/01/2026, por decisão de Toffoli, a PF obteve bloqueio de cerca de R$ 5,7 bilhões dos alvos; investiga se recursos do Master foram desviados por fundos ao patrimônio de Vorcaro e ligados.','investigacao',NULL,'2026',NULL,0,NULL,5700000000.0,NULL,'Os advogados de Vorcaro disseram não ter acesso aos motivos da fase e não comentaram.',1,'teia','E[110].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(131,'daniel-vorcaro','reag-investimentos','financeira',NULL,'Conta do pai na Reag (> R$ 2,2 bi)','Segundo a decisão de prisão de março de 2026, Vorcaro e Zettel teriam movido mais de R$ 2,2 bilhões para conta do pai de Vorcaro na Reag, achado da PF em janeiro; as datas das transferências não constam.','investigacao',NULL,'2026',NULL,0,NULL,2200000000.0,NULL,'A defesa de Vorcaro nega categoricamente as condutas atribuídas.',1,'teia','E[111].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(132,'nelson-tanure','banco-master','financeira',NULL,'Aportes via fundos offshore (~R$ 2,5 bi)','Segundo O Globo, Tanure teria colocado cerca de R$ 2,5 bilhões no Master desde 2020 por fundos offshore; a PF apura se ele foi sócio oculto.','reportada',NULL,'2020','2025',0,NULL,2500000000.0,NULL,'Tanure afirma não ter sido controlador nem sócio do Master, nem minoritário, e que a relação foi estritamente comercial, como cliente.',1,'teia','E[112].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(133,'nelson-tanure','banco-master','financeira',NULL,'Debêntures Banvox via fundo (R$ 366 mi)','Segundo o Valor, um fundo ligado a Tanure detinha R$ 366 milhões em debêntures da Banvox Holding Financeira, apontada como veículo usado por Vorcaro e Maurício Quadrado.','reportada',NULL,'2024',NULL,0,NULL,366000000.0,NULL,'A defesa de Tanure afirma que ele não tem relação societária com o Banco Master e foi cliente do banco.',1,'teia','E[112].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(134,'cvm','nelson-tanure','investigacao',NULL,'Relatório da CVM: ações da Ambipar','Relatório técnico da CVM descreve atuação ''coordenada'' e ''interdependente'' entre Tanure e o Master numa iniciativa para supostamente inflar o preço das ações da Ambipar, hoje em recuperação judicial.','investigacao',NULL,'2025',NULL,0,NULL,NULL,NULL,'Tanure nega ter sido controlador ou sócio do Master e diz que as relações foram estritamente comerciais (a matéria não traz resposta específica sobre a Ambipar); a defesa de Vorcaro afirma que o Master não realizou operações destinadas a beneficiar terceiros.',1,'teia','E[113].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(135,'grupo-fictor','banco-master','societaria',NULL,'Proposta de compra com aporte de R$ 3 bi','Em 17/11/2025 a Fictor anunciou a compra do Master, com aporte imediato de R$ 3 bilhões, dependente de aprovação do BC e do Cade; o BC decretou a liquidação do Master no dia seguinte e não há registro nas fontes de aporte efetivado. A Fictor pediu recuperação judicial em 01/02/2026, com cerca de R$ 4 bilhões em compromissos.','documentada',NULL,'2025','2025',0,NULL,3000000000.0,NULL,'A Fictor atribui sua crise de liquidez ao anúncio da compra e à liquidação do Master e diz que pagará as dívidas sem desconto; segundo seu advogado, clientes pediram a retirada de cerca de 70% dos recursos.',1,'teia','E[114].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(136,'daniel-vorcaro','btg-pactual','financeira',NULL,'Venda de ativos ao BTG (R$ 1,5 bi)','Em 27/05/2025 o BTG concluiu a compra de ações da Light e da Méliuz, imóveis, créditos e direitos creditórios de Vorcaro por cerca de R$ 1,5 bilhão; Vorcaro se comprometeu a disponibilizar os recursos ao Master.','documentada',NULL,'2025','2025',0,NULL,1500000000.0,NULL,'',1,'teia','E[115].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(137,'pf','rioprevidencia','investigacao',NULL,'Barco de Papel (PF cita R$ 3,7 bi)','Em 23/01/2026 a PF cumpriu quatro mandados e apura gestão fraudulenta, desvio, corrupção passiva e outros crimes; relatório da PF cita R$ 3,7 bilhões em fundos e letras. O diretor interino de investimentos foi exonerado em dezembro de 2025.','investigacao',NULL,'2026',NULL,0,NULL,3700000000.0,NULL,'O Rioprevidência diz que as aplicações seguiram o Plano Anual de Investimentos aprovado pelo conselho e que o pagamento de aposentadorias e pensões está garantido; o governo do Rio informou ter revisto a estrutura de controles.',1,'teia','E[116].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(138,'pf','amprev','investigacao',NULL,'Operação Zona Cinzenta (R$ 400 mi)','Em 06/02/2026 a PF fez buscas contra o então diretor-presidente da Amprev e outros membros do comitê de investimentos (Operação Zona Cinzenta); a decisão judicial cita ''violação consciente de normas de governança'' e possível crime de gestão fraudulenta ou temerária. Segundo o Poder360, o ex-presidente foi indicado ao cargo pelo senador Davi Alcolumbre e atuou como tesoureiro de sua campanha.','investigacao',NULL,'2026',NULL,0,NULL,400000000.0,NULL,'O ex-presidente não respondeu e o gabinete de Alcolumbre não retornou à reportagem.',1,'teia','E[117].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(139,'iprev-maceio','banco-master','financeira',NULL,'Letras financeiras (R$ 97 mi)','O regime de Maceió aplicou cerca de R$ 97 milhões em letras financeiras do Master, sem cobertura do FGC, segundo dados do Ministério da Previdência.','documentada',NULL,'2023',NULL,0,NULL,97000000.0,NULL,'O Iprev diz que o valor representa menos de 10% do patrimônio total do instituto e que o Master estava habilitado no Banco Central e tinha grau de investimento à época.',1,'teia','E[118].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(140,'sao-roque-prev','banco-master','financeira',NULL,'Letras financeiras (R$ 93 mi)','O regime de São Roque (SP) aplicou cerca de R$ 93 milhões em letras do Master, sem cobertura do FGC.','documentada',NULL,'2023',NULL,0,NULL,93150000.0,NULL,'O regime diz ter seguido ritos legais e técnicos, com pareceres, aprovação do comitê de investimentos e homologação dos conselhos.',1,'teia','E[119].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(141,'demais-14-rpps','banco-master','financeira',NULL,'Letras de 14 regimes (R$ 307 mi)','Soma dos demais regimes da lista: Cajamar R$ 87 mi, Itaguaí R$ 59,6 mi, Amazonas R$ 50 mi, Aparecida de Goiânia R$ 40 mi, Araras R$ 29 mi e outros nove entre R$ 1,2 mi e R$ 14 mi. O total dos 18 regimes é R$ 1,867 bilhão.','documentada',NULL,'2023',NULL,0,NULL,307300000.0,NULL,'',1,'teia','E[120].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(142,'estados-e-municipios','ministerio-da-previdencia-social','financeira',NULL,'Cobertura final de rombo dos RPPS','Segundo o Ministério, estados e municípios são os garantidores finais: se os regimes faltarem recursos por perdas com o Master (ao menos R$ 1,8 bilhão em letras), o ente deve cobrir, conforme a Lei 9.717/1998. As letras contam como dívida na liquidação, com recuperação incerta.','documentada',NULL,'2025',NULL,0,NULL,1800000000.0,NULL,'O governo diz que não há aporte imediato necessário e que a União não pode intervir na gestão local; sua sanção principal é suspender o CRP.',1,'teia','E[121].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(143,'banco-master','reag-investimentos','contratual',NULL,'Master era cliente da Reag','Em 11/03/2026 Mansur confirmou à CPI do Crime Organizado que o Banco Master era cliente da Reag, como outras instituições. A CVM relaciona procedimentos envolvendo instituições dos grupos Master e Reag como investidoras, administradoras ou gestoras de fundos.','documentada',NULL,'2023',NULL,0,NULL,NULL,NULL,'Mansur disse que a relação era normal e que a Reag foi punida por ser grande e independente.',1,'teia','E[122].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(144,'banco-master','reag-trust-dtvm','financeira',NULL,'Operações Master com fundos da Reag','O Banco Central relatou ao TCU indícios de crimes de desvio de recursos e gestão fraudulenta em operações estruturadas do Master com fundos administrados pela Reag Trust entre jul/2023 e jul/2024 (citam-se Bravo 95 e D Mais, segundo a Folha) e comunicou o fato ao MPF em 17/11/2025. As fontes divergem sobre os R$ 11,5 bi: ora o total das operações estruturadas (das quais duas ligadas à Reag), ora o montante em fundos administrados pela Reag. As reportagens não dizem que o BC tenha relacionado a Reag ao PCC; a menção ao PCC vem da Carbono Oculto.','investigacao',NULL,'2023','2024',0,NULL,11500000000.0,NULL,'A Reag, em nota, negou vínculo com o PCC e disse não ter tido acesso ao relatório do BC, por isso não responde sobre a relação com o Master (Jornal de Brasília). Outras reportagens dizem que a Reag não se manifestou. As reportagens consultadas não trazem manifestação da defesa de Vorcaro. O BC diz que as operações justificam processos administrativos sancionadores, ainda em apuração.',1,'teia','E[123].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(145,'operacao-compliance-zero','reag-trust-dtvm','investigacao',NULL,'Fundos criariam falsa expansão do Master','Segundo a PF, citada pela imprensa, a Reag teria participado de movimentação de fundos que criava a falsa impressão de crescimento dos ativos do Master. Toffoli determinou sequestro de mais de R$ 5,7 bi na 2ª fase e a PF estima fraudes de até R$ 12 bi no conjunto.','investigacao',NULL,'2025',NULL,0,NULL,5700000000.0,NULL,'As fontes citadas não trazem manifestação da Reag sobre este ponto. Em outras reportagens (sobre a Carbono Oculto), a Reag disse colaborar com as autoridades e negou ligação com atividades ilícitas.',1,'teia','E[124].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(146,'operacao-compliance-zero','joao-carlos-mansur','investigacao',NULL,'Alvo de busca em 14/01/2026','Mansur foi alvo de mandado de busca na 2ª fase, ao lado de Vorcaro, do pai, de Zettel e de Nelson Tanure. A fase apura concessão de créditos fraudulentos pelo Master; as reportagens não detalham a base específica contra Mansur.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'As reportagens (InfoMoney, NeoFeed) não trazem manifestação de Mansur, de sua defesa ou da Reag sobre as buscas.',1,'teia','E[125].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(147,'bcb','reag-trust-dtvm','juridica',NULL,'Liquidação extrajudicial em 15/01/2026','O BC decretou a liquidação da CBSF DTVM, nova denominação da Reag Trust, por comprometimento econômico-financeiro e graves violações às normas, com indisponibilidade de bens de controladores e ex-administradores. A instituição representava menos de 0,001% do ativo do sistema.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'As reportagens não trazem manifestação da Reag sobre a liquidação; em outras ocasiões a empresa nega irregularidades.',1,'teia','E[126].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(148,'cvm','reag-trust-dtvm','juridica',NULL,'Acusação por ocultar cotistas e liquidez','Em acusação formal divulgada em 04/05/2026, a CVM processa a Reag Trust e um ex-diretor por ocultar cotistas com mais de 20% do patrimônio dos fundos, informar liquidez incorreta e não realizar testes de estresse. A reportagem cita o Hans 95 como cotista único do Reag Alpha e diz que Hans 95 e Reag Growth injetaram mais de R$ 1 bi no Master em out/2024. Sem julgamento (sem data marcada).','investigacao',NULL,'2026',NULL,0,NULL,1000000000.0,NULL,'A Reag disse ter identificado uma ''inconsistência operacional'': um pedido de resgate cancelado continuou refletido na carteira (conforme a reportagem; não fica claro que a manifestação foi feita à CVM).',1,'teia','E[127].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(149,'hans-95','banco-master','financeira',NULL,'Aportes de mais de R$ 1 bi em out/2024','A CVM afirma que o Hans 95 e o Reag Growth aportaram mais de R$ 1 bi no Master em outubro de 2024. O mesmo texto descreve o Hans 95 como multimercado investigado na Carbono Oculto, o que torna esse fundo um ponto de contato entre os dois casos, sem que a fonte diga que o Master tenha relação com o PCC.','investigacao',NULL,'2024','2024',0,NULL,1000000000.0,NULL,'A resposta da Reag à CVM, no processo, foi a descrita para outros pontos; não consta resposta específica sobre esses aportes.',1,'teia','E[128].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(150,'hans-95','operacao-carbono-oculto','investigacao',NULL,'Fundo descrito como investigado','O Let''s Money descreve o Hans 95 como multimercado ''investigado na Operação Carbono Oculto'' e o Metrópoles afirma que, segundo a investigação (MP-SP e Receita), os fundos Olaf 95 e Hans 95 ''teriam sido usados para lavar dinheiro do PCC''; as reportagens não detalham a base e nenhuma delas liga o Master ao PCC. O patrimônio do Hans 95 caiu de R$ 35,3 bi (04/04/2026) para cerca de R$ 27 bi cinco dias depois, segundo dados da CVM.','reportada',NULL,'2025',NULL,0,NULL,27000000000.0,NULL,'As fontes consultadas não trazem manifestação da Reag sobre o Hans 95.',1,'teia','E[129].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(151,'daniel-vorcaro','hans-ii','financeira',NULL,'Ganho declarado de R$ 441,9 mi em 2023','Pelo IR de 2024 de Vorcaro, enviado pela Receita à CPMI do INSS, duas operações com cotas do Hans II em maio-junho e dezembro de 2023 renderam cerca de R$ 150 mi e R$ 291,9 mi. A reportagem trata como indicativo de possíveis fraudes e lavagem; não há conclusão da PF.','reportada',NULL,'2023','2023',0,NULL,441900000.0,NULL,'A defesa de Vorcaro não quis se manifestar sobre os investimentos; a Reag nega todas as acusações.',1,'teia','E[130].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(152,'astralo-95','super-empreendimentos','financeira',NULL,'R$ 650 mi via FIP Termópilas','Decisão do STF que cita a Procuradoria em SP relata que o Astralo 95 resgatou cerca de R$ 800 mi em CDBs em maio de 2024 e transferiu R$ 650 mi ao FIP Termópilas, que repassou o mesmo valor à Super Empreendimentos, cujo sócio, segundo a investigação, é Fabiano Zettel.','investigacao',NULL,'2024','2024',0,NULL,650000000.0,NULL,'A defesa de Zettel afirma que ele ainda é sócio, embora não conste mais do quadro societário. A defesa de Mansur disse que não se manifestaria.',1,'teia','E[131].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(153,'joao-carlos-mansur','astralo-95','pessoal',NULL,'Familiares como beneficiários finais','Segundo a Procuradoria em SP, três pessoas com vínculo familiar com Mansur são os principais beneficiários finais declarados do Astralo 95 e do Reag Growth 95. Outro familiar comanda empresas que estão entre as 36 que tomaram empréstimos supostamente fictícios do Master, segundo o BC.','investigacao',NULL,'2024',NULL,0,NULL,NULL,NULL,'A defesa de Mansur disse que não se manifestaria.',1,'teia','E[132].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(154,'super-empreendimentos','fabiano-zettel','societaria',NULL,'Zettel como sócio','A investigação aponta Fabiano Zettel, cunhado de Vorcaro, como sócio da Super Empreendimentos, destino de repasses de fundos ligados à Reag.','investigacao',NULL,'2024',NULL,0,NULL,NULL,NULL,'A defesa de Zettel afirma que ele ainda é sócio, embora não conste mais no quadro societário.',1,'teia','E[133].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(155,'gold-style-fidc','reag-trust-dtvm','contratual',NULL,'Administradora do fundo','A Reag Trust administra o Gold Style, constituído em 01/04/2020 com R$ 480,1 mi e patrimônio de R$ 1,84 bi em maio de 2024, em funcionamento normal segundo o registro da CVM.','documentada',NULL,'2020',NULL,0,NULL,1840000000.0,NULL,'A Reag não quis comentar.',1,'teia','E[134].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(156,'gold-style-fidc','bk-bank','financeira',NULL,'Transações apontadas pelo Coaf','Relatórios do Coaf, segundo a Folha, registram lançamentos de R$ 133,6 mi da BK Bank para o Gold Style em 2023 e outras transações de R$ 12,9 mi entre o fundo e a BK em 2024-2025 (ao menos R$ 146,5 mi no total). A Folha identifica a BK como a fintech que PF, Receita e MP-SP dizem ter atuado como ''banco paralelo'' da facção na Carbono Oculto. O vínculo é de fluxo financeiro entre contrapartes; a fonte não afirma conduta ilícita do fundo nem da Reag.','reportada',NULL,'2023','2025',0,NULL,146500000.0,NULL,'A BK Bank não respondeu à Folha; em outra reportagem afirma atuar com total transparência e sob regulação do BC. A Reag não quis comentar.',1,'teia','E[135].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(157,'gold-style-fidc','aster-petroleo','financeira',NULL,'Cerca de R$ 311,7 mi movimentados','Segundo a Folha, o fundo movimentou cerca de R$ 311,7 mi com a Aster Petróleo, investigada por fraudes no setor de combustíveis. Na CPI do Crime Organizado, relatório aponta que o Gold Style recebeu cerca de R$ 1 bi de empresas citadas na investigação.','reportada',NULL,'2023','2025',0,NULL,311700000.0,NULL,'A Reag não quis comentar; Mansur negou na CPI qualquer vínculo da Reag com o PCC.',1,'teia','E[136].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(158,'gold-style-fidc','super-empreendimentos','financeira',NULL,'R$ 180 mi do fundo à empresa de Zettel','A Folha relata transações de ao menos R$ 180 mi entre o Gold Style e a Super Empreendimentos, e o Times Brasil (relatório da CPI do Crime Organizado) diz que o fundo transferiu R$ 180 mi à empresa, ligada a Vorcaro; a PF liga a Super à família de Vorcaro e a investigação aponta Fabiano Zettel como sócio. O mesmo fundo aparece, assim, com contrapartes citadas na Carbono Oculto (Aster, BK) e do universo Master (Super, Entre). As fontes não afirmam que o fundo, a Reag ou o Master pertençam ao PCC.','reportada',NULL,'2023','2025',0,NULL,180000000.0,NULL,'A Reag não quis comentar; a defesa de Vorcaro disse que não se manifestaria (Folha).',1,'teia','E[137].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(159,'gold-style-fidc','entre-investimentos-e-participacoes','financeira',NULL,'Ao menos R$ 20 mi para a Entre','Segundo a Folha (Coaf) e o Jornal Opção, o Gold Style repassou ao menos R$ 20 mi à Entre, empresa que, segundo as reportagens, teria sido usada por Vorcaro para repassar dinheiro ao filme Dark Horse. É fluxo financeiro noticiado, sem decisão judicial nem conclusão da PF.','reportada',NULL,'2025','2025',0,NULL,20000000.0,NULL,'A Entre disse em nota que as operações estão em conformidade com as normas e regulamentações do setor financeiro (Folha). A defesa de Vorcaro disse que não se manifestará.',1,'teia','E[138].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(160,'reag-investimentos','operacao-carbono-oculto','investigacao',NULL,'Gestora e fundos citados na operação','A Reag foi alvo de buscas em 28/08/2025 entre as administradoras de fundos suspeitos de ocultar patrimônio; a Receita investiga 40 fundos (patrimônio de R$ 30 bi), 11 deles da Reag segundo a Bloomberg Línea, e disse que os administradores dos fundos ''estavam cientes'' e ''contribuíram'', fala geral sem detalhar condutas atribuídas à gestora. Não há condenação nem acusação formal, nas fontes, de que a Reag pertença ao PCC.','investigacao',NULL,'2025',NULL,0,NULL,NULL,NULL,'A Reag nega ligação com atividades ilícitas, diz que parte dos fundos nunca esteve sob sua administração e que os demais foram liquidados ou tiveram gestão renunciada meses antes. Mansur disse à CPI que as 15 mil páginas do processo não mencionam associação com o PCC.',1,'teia','E[139].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(161,'mabruk-ii','mohamad-hussein-mourad','financeira',NULL,'Recursos de Mourad no fundo Mabruk II','Segundo o Gaeco/MP-SP (via Estadão, 14/10/2025), o fundo Mabruk II, administrado pela Reag, foi alimentado com recursos de Mohamad Hussein Mourad (Primo), apontado pelo MP como operador financeiro do PCC, e usado na compra da Usina Itajobi. Ainda segundo o Gaeco, executivos da Reag assinaram documentos que viabilizaram os fundos. A peça é descrita ora como relatório, ora como denúncia, sem esclarecer se há ação penal contra a Reag; são alegações da acusação, não condenação.','investigacao',NULL,'2024',NULL,0,NULL,NULL,NULL,'A Reag diz que seus diretores atuaram apenas como representantes legais dos fundos. A defesa de Mourad nega envolvimento ilícito e relação com o PCC; ele está foragido.',1,'teia','E[140].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(162,'operacao-carbono-oculto','pcc','investigacao',NULL,'Esquema no setor de combustíveis','Segundo MP-SP, Receita e PF, o PCC teria usado postos, importadoras, fintechs e fundos para sonegar e lavar dinheiro: R$ 52 bi movimentados por postos em 2020-2024, R$ 46 bi por uma fintech e 40 fundos de R$ 30 bi. Fraude fiscal estimada em R$ 7,6 bi a R$ 8,67 bi.','investigacao',NULL,'2025',NULL,0,NULL,52000000000.0,NULL,'Os denunciados Beto Louco e Primo negam relação com o PCC; as defesas dizem que a acusação se baseia em especulação.',1,'teia','E[141].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(163,'roberto-augusto-leme-da-silva','gaeco-mp-sp','juridica',NULL,'Denunciado por org. criminosa e lavagem','Em 18/08/2026 o Gaeco denunciou 16 pessoas, entre elas Beto Louco, por organização criminosa e lavagem; a denúncia não acusa formalmente os 16 de pertencer ao PCC. Em nova denúncia (set/2026), Beto Louco e Primo respondem por lavagem em usinas. Beto Louco está foragido.','investigacao',NULL,'2026',NULL,0,NULL,52000000000.0,NULL,'Na denúncia de 18/08/2026, a defesa de Beto Louco disse não ter tido acesso aos autos, que os fatos não têm relação com ele e chamou sua inclusão de ''infeliz tentativa de gerar repercussão midiática''. Na segunda denúncia (set/2026), seus advogados dizem que vão provar a improcedência; a defesa de Primo fala em ''estratégia da especulação sobre fatos não provados''. Ambos negam ligação com o PCC.',1,'teia','E[142].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(164,'operacao-quasar','pf','investigacao',NULL,'13 indiciados; relatório ao MPF','A PF indiciou 13 executivos de fundos, corretoras e fintechs por suspeita de lavagem de dinheiro de sonegação e crimes no setor de combustíveis (grupo Aster-Copape), em esquema que as reportagens vinculam ao PCC. O relatório final foi ao MPF, que decidirá entre denunciar, pedir diligências ou arquivar. As reportagens não citam Reag nem Banco Master. Segundo a defesa de Mourad e Leme, o próprio relatório diz que o vínculo com facção não é afirmado como fato provado.','investigacao',NULL,'2025',NULL,0,NULL,1200000000.0,NULL,'A defesa de Mourad e Leme nega ligação com facções e cita trecho do relatório da PF segundo o qual reportagens e dossiês não servem como prova do vínculo em si.',1,'teia','E[143].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(165,'daniel-vorcaro','operacao-carbono-oculto','juridica',NULL,'Pedido de remessa ao STF negado','Vorcaro pediu que partes da Carbono Oculto e da Quasar que o envolvessem fossem enviadas ao STF. Os pedidos foram negados em 19/12/2025: o juiz de Catanduva disse que, ao menos por ora, não havia notícia de conexão com Vorcaro e o Master; o de SP, que não se estendia a decisão de Toffoli. Os juízes seguiram o MP, para quem as investigações miram outros personagens.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'A defesa argumentou que, se houvesse ligação do banco ou de Vorcaro com essas investigações, o caso deveria ir ao STF; não admitiu ligação.',1,'teia','E[144].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(166,'banco-master','operacao-quasar','investigacao',NULL,'Diálogos de investigado citam o Master','Segundo o Portal Tela, a PF apontou, na Operação Quasar, diálogos de um investigado com menções ao Banco Master e a Vorcaro, tratados pela Justiça como encontro fortuito de provas entre investigações distintas. A 7ª Vara Federal informou que não há menção a autoridades com foro e, segundo a reportagem, os juízes registraram que não há vínculo entre Vorcaro ou o Master e os crimes apurados. Fonte única e secundária; não há acusação contra o Master.','reportada',NULL,'2025',NULL,0,NULL,NULL,NULL,'A defesa de Vorcaro não respondeu aos pedidos de comentário (Portal Tela); a reportagem não traz resposta do Master.',1,'teia','E[145].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(167,'daniel-vorcaro','antonio-carlos-freixo-junior','financeira',NULL,'Apontado pela PF como operador de Vorcaro','A PF aponta Freixo, dono da Entre, como operador financeiro de Vorcaro. Em delação homologada em 09/09/2026, ele relatou pagamentos feitos a pedido de Vorcaro, remessas ao fundo Havengate (Texas) e entregas em espécie, e disse não saber o destino final. Dados divulgados indicam que Vorcaro enviou ao menos US$ 12,3 mi à estrutura do filme.','investigacao',NULL,'2025',NULL,0,NULL,NULL,NULL,'Freixo não se manifestou, citando o sigilo da delação; a Entre diz cumprir as normas do setor.',1,'teia','E[146].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(168,'entre-investimentos-e-participacoes','operacao-credito-oculto','investigacao',NULL,'Dono da Entre é alvo de buscas','Em 24/09/2026, na 3ª fase da Carbono Oculto (Operação Crédito Oculto), o Gaeco e a Receita cumpriram buscas contra 13 pessoas físicas e 19 jurídicas em sete estados, entre elas Freixo, dono da Entre, e um executivo do Banco Genial (que o banco diz ter deixado a diretoria em maio/2026) e seus irmãos, por suposta ocultação dos reais donos de uma usina e da compra da distribuidora Tobras (Terrana). O comunicado da Receita não nomeia a Entre, o Master, Vorcaro, a Reag nem o PCC.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'Freixo não se pronunciou, citando o sigilo da delação; a Entre não se manifestou nas reportagens. O Genial disse que o executivo não integra a diretoria nem é sócio desde maio de 2026 e que forneceu informações ao Gaeco-SP.',1,'teia','E[147].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(169,'entre-investimentos-e-participacoes','pcc','politica',NULL,'Declaração do ministro da Fazenda','Em 24/09/2026, o ministro da Fazenda, Dario Durigan, disse que a Entre ''funcionou também como instrumento de ocultação e lavagem de dinheiro'' e, segundo a reportagem, que o dinheiro recebido por ela teria relação com o PCC e outras organizações criminosas; afirmou ainda que ''tudo indica'' que o recurso que dá liquidez a operações como o financiamento do Dark Horse vem de uma mesma entidade (sem nomear a Entre nessa frase). É declaração pública de autoridade, sem decisão judicial nem denúncia sobre a Entre; a instituição de pagamento do grupo (Entrepay) foi liquidada pelo BC em março de 2026.','reportada',NULL,'2026',NULL,0,NULL,NULL,NULL,'A Entre não se manifestou nas matérias; em outra reportagem disse que suas operações cumprem as normas do setor financeiro.',1,'teia','E[148].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(170,'joao-carlos-mansur','daniel-vorcaro','pessoal',NULL,'Círculo de amizades','O InfoMoney diz que, no círculo de amizades de Mansur, está o banqueiro Daniel Vorcaro, e que a Reag administra alguns fundos do Master.','reportada',NULL,'2023',NULL,0,NULL,NULL,NULL,'Não há manifestação de Mansur ou de Vorcaro sobre a amizade nas fontes consultadas.',1,'teia','E[149].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(171,'joao-carlos-mansur','daniel-vorcaro','juridica',NULL,'Delação de Mansur mira Vorcaro','Em acordo de colaboração com a PGR (fechado no início de set/2026), Mansur teria dito que fundos geridos pela Reag foram usados para ocultar pagamentos de propina atribuídos a Vorcaro a agentes públicos, com laranjas e empresas no exterior; a proposta tinha 17 anexos e multa de cerca de R$ 40 mi. O acordo aguardava homologação de Mendonça (sem decisão até 20/09/2026); a homologação não torna as declarações verdadeiras e o conteúdo não foi comprovado nem detalhado.','reportada',NULL,'2026',NULL,0,NULL,40000000.0,NULL,'A defesa de Vorcaro não se manifestou nas matérias; Vorcaro teve duas propostas de delação rejeitadas pela PGR e pela PF.',1,'teia','E[149].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(172,'reag-investimentos','arandu-partners-holding','societaria',NULL,'Venda de 87,38% a executivos','Em 07/09/2025 as controladoras Reag Asset Management e Reag Alpha FIA acordaram transferir 87,38% do capital à Arandu por cerca de R$ 100 mi (dívidas da Reag Asset) mais parcelas variáveis em 60 meses, com OPA aos minoritários. Mansur e Dario Tanure se abstiveram na votação por terem interesse direto.','documentada',NULL,'2025',NULL,0,NULL,100000000.0,NULL,'A Reag disse que a medida protege a integridade e a reputação da empresa diante de infundadas especulações.',1,'teia','E[150].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(173,'cvm','reag-investimentos','juridica',NULL,'Processos sancionadores e inquéritos','A CVM lista inquéritos sobre a administração de fundos pela Reag DTVM (2021-2023) e sobre a reorganização societária da GetNinjas e da Reag Trust, além de processos sancionadores por não entrega das demonstrações de 2024 e de informações trimestrais de 2025.','documentada',NULL,'2021',NULL,0,NULL,NULL,NULL,'Não há resposta da Reag no comunicado da CVM.',1,'teia','E[151].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(174,'banco-master','inss','contratual',NULL,'Acordo de cooperação do consignado','O Master operou crédito consignado a aposentados e pensionistas por acordo de cooperação técnica com o INSS de set/2020 a set/2025, não renovado. Em 10/10/2025 o INSS anunciou, como medida preventiva, que não renovaria o acordo, mantendo o banco impedido até a conclusão das apurações, por volume expressivo de reclamações e indícios de descumprimento das regras de autorização expressa e biometria.','documentada',NULL,'2020','2025',0,NULL,NULL,NULL,'A defesa de Vorcaro afirma que o banco sempre seguiu as normas do INSS sobre formalização, identificação e consentimento.',1,'teia','E[152].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(175,'inss','banco-master','financeira',NULL,'Repasses retidos: cerca de R$ 2 bi','O INSS reteve cerca de R$ 2 bi de repasses referentes a aproximadamente 254 mil contratos de consignado do Master por falhas documentais e aumento de reclamações; a 18ª Vara Federal do DF mandou depositar os valores retidos em conta judicial e negou liberação imediata ao banco.','documentada',NULL,'2026',NULL,0,NULL,2000000000.0,NULL,'O Master tentou negociar a liberação, que foi negada; a defesa de Vorcaro diz que o banco cumpriu as normas do INSS.',1,'teia','E[152].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(176,'banco-master','mpf','investigacao',NULL,'Indícios de fraude em consignados','O INSS apontou 251.718 de 338.608 contratos (74,3%) do Master sem comprovação idônea de assinatura; a CGU quantificou contratos sem biometria suficiente ou sem documentos; o MPF conduz inquérito civil e, em 03/02/2026, recomendou priorizar o ressarcimento dos lesados na liquidação. Também há o M Fácil Consignado, detectado em março de 2026.','investigacao',NULL,'2021',NULL,0,NULL,NULL,NULL,'A defesa de Vorcaro afirma que o banco sempre seguiu as normas do INSS; o Master não se manifestou sobre o relatório do INSS.',1,'teia','E[153].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(177,'banco-master','credcesta','contratual',NULL,'Credcesta operado pelo Master','Segundo a Folha, o cartão consignado de benefício Credcesta, criado em 2018 por Augusto Lima, foi operado pelo Master e apresentado ao INSS em 2022. O INSS diz que não trabalha com o Credcesta e não explicou diferenças de contagem; a reportagem cita 104,8 mil contratos em 2022 e 2,75 milhões em 2024, mas o INSS tinha 324.849 contratos ativos do Master ao fim de 2025.','reportada',NULL,'2020','2025',0,NULL,NULL,NULL,'A defesa de Vorcaro diz que o banco respeitou as normas do INSS; a Pleno diz que as questões cabem ao liquidante; o INSS não explicou a diferença nas quantidades.',1,'teia','E[154].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(178,'daniel-vorcaro','cpmi-do-inss','politica',NULL,'Convocação e quebra de sigilo','Em 04/12/2025 a CPMI aprovou a convocação e a quebra de sigilos bancário e telemático de Vorcaro; o foco declarado era a oferta de consignado a aposentados e as reclamações recebidas pela Senacon. Vorcaro não depôs: Mendonça tornou o comparecimento facultativo e ele desistiu em 20/02/2026.','documentada',NULL,'2025','2026',0,NULL,NULL,NULL,'Segundo o presidente da CPMI, Carlos Viana (relato de início de fev/2026), a defesa pediu adiamento e disse que Vorcaro estava disposto a comparecer e levar documentos, sem recorrer a habeas corpus; depois ele desistiu após a decisão de Mendonça.',1,'teia','E[155].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(179,'daniel-vorcaro','cpmi-do-inss','politica',NULL,'Pedido de indiciamento no relatório','O parecer de Alfredo Gaspar e o texto alternativo da base do governo (que não chegou a ser votado) pediam o indiciamento de Vorcaro, mas as fontes não explicam os crimes atribuídos a ele. O parecer foi rejeitado por 19 a 12 em 27/03/2026 e a CPMI terminou sem relatório final, sem indiciar ninguém; cópias seguem a outras instituições (MPF, STF).','documentada',NULL,'2026','2026',0,NULL,NULL,NULL,'As matérias não trazem manifestação de Vorcaro sobre o pedido.',1,'teia','E[155].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(180,'cpmi-do-inss','hans-ii','politica',NULL,'IR de Vorcaro revelou ganhos no Hans II','A declaração de IR de 2024 de Vorcaro, enviada pela Receita à CPMI do INSS, foi a origem dos dados divulgados (Folha, confirmados pela Gazeta do Povo) sobre os ganhos em operações com cotas do Hans II, fundo que a reportagem relaciona a fundos ligados ao Master, alguns administrados pela Reag. Nas fontes consultadas é o único ponto de contato entre a Reag e o caso INSS, e decorre da quebra de sigilo, não de investigação sobre descontos.','reportada',NULL,'2025','2026',0,NULL,441900000.0,NULL,'A defesa de Vorcaro não quis se manifestar sobre os investimentos.',1,'teia','E[156].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(181,'operacao-sem-desconto','inss','investigacao',NULL,'Descontos associativos: R$ 6,3 bi','Segundo PF e CGU, entidades descontavam mensalidades sem autorização de aposentados e pensionistas via acordos de cooperação com o INSS; prejuízo estimado de R$ 6,3 bi entre 2019 e 2024. Seis pessoas foram afastadas, 11 entidades enquadradas e os acordos suspensos; a CGU auditou 29 entidades e a maioria dos 1.300 entrevistados não autorizou os descontos.','investigacao',NULL,'2019','2024',0,NULL,6300000000.0,NULL,'O INSS não respondeu ao Poder360 na data; Camisotti e outros investigados contestam as acusações (a defesa de Camisotti nega motivo para a prisão).',1,'teia','E[157].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(182,'inss','operacao-sem-desconto','financeira',NULL,'Ressarcimento a aposentados','O governo já havia ressarcido cerca de R$ 2,3 bi até out/2025; até jun/2026 mais de R$ 3,2 bi a cerca de 4,7 milhões de segurados, e a MP 1.378 (20/07/2026) liberou mais R$ 547 mi. Os descontos associativos foram proibidos de forma definitiva.','documentada',NULL,'2025',NULL,0,NULL,3200000000.0,NULL,'Quem adere ao acordo administrativo mantém o direito de acionar a Justiça contra a União e o INSS se o pagamento não ocorrer.',1,'teia','E[157].r[1]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(183,'alessandro-stefanutto','conafer','financeira',NULL,'Propina mensal segundo a PF','No primeiro relatório final (14/07/2026), a PF indicia Stefanutto por organização criminosa, lavagem e corrupção passiva, afirmando que ele teria recebido até R$ 250 mil por mês para não fiscalizar entidades, parte paga pela Conafer. A PGR decidirá se denuncia; não há condenação.','investigacao',NULL,'2023','2025',0,NULL,250000.0,NULL,'O Metrópoles não obteve resposta da defesa de Stefanutto.',1,'teia','E[158].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(184,'antonio-carlos-camilo-antunes','mauricio-camisotti','financeira',NULL,'Repasses de R$ 25,5 mi ao lobista','Segundo a PF, empresas ligadas a Camisotti repassaram ao menos R$ 25,5 mi ao Careca do INSS, que teria recebido cerca de R$ 30 mi de associações; Ambec e Cebap teriam repassado R$ 11,9 mi e R$ 12,6 mi. Ambos foram presos em setembro de 2025 e tiveram preventivas mantidas por maioria na 2ª Turma do STF.','investigacao',NULL,'2025',NULL,0,NULL,25500000.0,NULL,'Os advogados de Camisotti afirmam que não há motivo para a prisão e alegam arbitrariedade.',1,'teia','E[159].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(185,'cpmi-do-inss','operacao-sem-desconto','politica',NULL,'CPMI encerrada sem relatório final','A CPMI funcionou por cerca de sete meses e terminou em 28/03/2026 sem relatório aprovado, após rejeitar o parecer de Alfredo Gaspar por 19 a 12; o parecer pedia o indiciamento de 216 pessoas e o texto alternativo, 130.','documentada',NULL,'2025','2026',0,NULL,NULL,NULL,'O presidente da CPMI, Carlos Viana, disse que cópias do parecer rejeitado seguirão a instituições como MPF e STF e que ''esta investigação poderia ter ido além, mas não permitiram avançar como deveríamos''.',1,'teia','E[160].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(186,'viviane-barci-de-moraes','alexandre-de-moraes','pessoal',NULL,'Esposa do ministro','Viviane é esposa do ministro Alexandre de Moraes. Moraes disse ao STF que ''minha mulher e meus dois filhos são advogados'' e que o contrato é ''legalmente existente''.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Moraes (defesa de 44 páginas ao STF): nunca julgou processo do Master ou de Vorcaro e ''inexistiu segundo contrato''. O escritório diz que o compliance consultou o ministro sobre impedimento antes do contrato.',1,'teia','E[161].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(187,'daniel-vorcaro','viviane-barci-de-moraes','contratual',NULL,'Contrato assinado em 23/01/2024; pagamentos divergentes','Contrato assinado em 23/01/2024 por Vorcaro e Ângelo Antônio Ribeiro da Silva (relatório da PF, via Correio da Manhã). Valor do contrato: R$ 129 mi em 3 anos segundo O Globo; R$ 131,3 mi segundo a PF; R$ 108 mi segundo a nota do escritório. Pago: R$ 80,2 mi em 22 parcelas segundo documento da Receita/IR do banco enviado à CPI do Crime Organizado; a PF localizou apenas 4 transferências de R$ 3,42 mi (cerca de R$ 13,6 mi).','documentada',NULL,'2024','2025',0,NULL,80200000.0,NULL,'O escritório diz que as informações são ''incorretas e vazadas ilicitamente'', que houve só um contrato e que os repasses compensavam honorários; nega ter assinado o segundo contrato proposto (até R$ 50 mi, em cotas de aeronaves via Vikings Participações).',1,'teia','E[162].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(188,'viviane-barci-de-moraes','alessandro-vieira','investigacao',NULL,'Suspeita de lavagem (alegação)','O senador Alessandro Vieira, relator da CPI do Crime Organizado, afirma haver ''fundadas suspeitas'' de que o contrato sirva à lavagem e que o valor é incompatível com os serviços; requerimentos de quebra de sigilo foram protocolados em 02/02/2026 e a aprovação não foi confirmada. O relatório da PF não conclui irregularidade e a PGR arquivou em 29/12/2025 pedido de investigação por falta de ilicitude aparente.','alegacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'O escritório diz ter entregue 36 pareceres, 94 reuniões e 22 manuais e nega irregularidade; Moraes chamou as alegações de ''absolutamente falsas''.',1,'teia','E[163].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(189,'alexandre-de-moraes','prime-aviation','financeira',NULL,'Voos (mai a out/2025)','A CPI do Crime Organizado (relatório final de Alessandro Vieira, via Poder360) aponta ao menos 7 voos de Moraes em aeronaves da Prime Aviation entre maio e outubro de 2025; custo estimado acima de R$ 1 mi (levantamento citado pela imprensa, sem metodologia detalhada).','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'O escritório de Viviane confirma que contratou voos da Prime Aviation e diz que os custos foram compensados com honorários; o gabinete de Moraes nega ter voado em avião de Vorcaro ou em sua companhia.',1,'teia','E[164].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(190,'alexandre-de-moraes','fsw-spe','financeira',NULL,'Um voo em Falcon 2000','Segundo o relatório final da CPI (via Poder360), 1 dos 8 voos foi em Falcon 2000 da FSW SPE, ligada a Fabiano Zettel.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Moraes e o escritório de Viviane negam voos de cortesia; o escritório diz que contrata táxi aéreo.',1,'teia','E[165].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(191,'prime-aviation','daniel-vorcaro','societaria',NULL,'Sócio via fundo até set/2025','A Prime Aviation diz que Vorcaro foi sócio por fundo até setembro de 2025 (Folha, via Jornal Opção).','reportada',NULL,NULL,'2025',0,NULL,NULL,NULL,'Vorcaro diz que não é dono da Prime Aviation.',1,'teia','E[166].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(192,'fsw-spe','fabiano-zettel','societaria',NULL,'Empresa ligada a Zettel','A CPI e o Poder360 descrevem a FSW SPE como empresa ligada a Fabiano Zettel.','reportada',NULL,NULL,NULL,0,NULL,NULL,NULL,'A defesa de Zettel diz que ele tem atividades lícitas conhecidas.',1,'teia','E[167].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(193,'fabio-faria','alexandre-de-moraes','politica',NULL,'Apresentou Vorcaro (dez/2023); ''o careca não pode atrasar''','Segundo mensagens do relatório da PF (Itatiaia, Correio da Manhã), Faria apresentou Vorcaro a Moraes entre 21 e 27/12/2023, perguntou em 15/01/2024 se Vorcaro respondera a ''Vivi'' sobre o contrato e escreveu em 15/03/2024 que ''o careca não pode atrasar'', seguido de pagamento de R$ 3,4 mi. A reportagem do Itatiaia ressalva que as mensagens documentam contatos, não crime.','investigacao',NULL,'2023','2024',0,NULL,NULL,NULL,'Faria disse que não conhecia Andrei Rodrigues na época e foi apenas consultado sobre convite; não respondeu aos demais pontos. Sem resposta de Moraes nesse trecho.',1,'teia','E[168].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(194,'fabio-faria','daniel-vorcaro','politica',NULL,'Interlocutor e ponte','Mensagens da PF mostram Faria organizando jantar com ''o Careca'' (02/02/2024) e encaminhando em abril/2024 convite ao diretor-geral da PF; em fevereiro/2026 a coluna de Andreza Matais (Metrópoles) o descrevia como ponte entre Vorcaro e Toffoli. Mensagens após o voto da Alcídia (''matou a gente'') são citadas pela Nova Cana.','investigacao',NULL,'2023','2026',0,NULL,NULL,NULL,'Não respondeu sobre os demais pontos (Itatiaia).',1,'teia','E[169].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(195,'fabio-faria','dias-toffoli','politica',NULL,'Ponte segundo coluna','A coluna de Andreza Matais (Metrópoles), citada pelo BPMoney, descreve Faria como ponte entre Vorcaro e Toffoli; é leitura da coluna, sem resposta do ministro no trecho.','alegacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'Toffoli chama os fatos da PF de ''ilações'' e nega receber valores de Vorcaro.',1,'teia','E[170].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(196,'kevin-de-carvalho-marques','kassio-nunes-marques','pessoal',NULL,'Filho do ministro','Kevin é filho do ministro Kassio Nunes Marques e tem escritório próprio.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Nunes Marques diz não ter ''relação de proximidade'' com Vorcaro, nunca ter votado a favor do Master e que o filho não recebeu de Vorcaro; declarou-se impedido em 15/09/2026 por presidir o TSE.',1,'teia','E[171].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(197,'consult-inteligencia-tributaria','kevin-de-carvalho-marques','financeira',NULL,'R$ 281.630 em 11 pagamentos','Segundo o Estadão (via Bahia Notícias), a Consult pagou R$ 281.630 em 11 parcelas a Kevin em 2024-2025; o Metrópoles fala em 10 parcelas.','reportada',NULL,'2024','2025',0,NULL,281630.0,NULL,'Kevin e o escritório dizem que foram serviços tributários, sem relação com o STF, e que ele nunca defendeu caso no STF. A Consult diz ser remuneração por serviços técnicos, atuando desde 2004 com outro CNPJ.',1,'teia','E[172].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(198,'banco-master','consult-inteligencia-tributaria','financeira',NULL,'R$ 6,6 mi do Master (e R$ 11,3 mi da JBS)','Relatório do Coaf obtido pelo Estadão: a Consult recebeu R$ 6,6 mi do Master e R$ 11,3 mi da JBS entre ago/2024 e jul/2025 (cerca de R$ 18 mi) e declarou faturamento de R$ 25,5 mil; o Coaf chama os valores de ''incompatíveis'' com a capacidade da empresa.','documentada',NULL,'2024','2025',0,NULL,6600000.0,NULL,'A Consult diz que a remuneração é por serviços técnicos. O Correio da Manhã ressalva que não há prova de que o dinheiro repassado a Kevin veio do Master.',1,'teia','E[173].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(199,'luiz-renno-netto','daniel-vorcaro','investigacao',NULL,'Mensagens sobre Kevin (''500 mil mês'')','Segundo o Correio da Manhã e a Tribuna do Sertão, o diretor jurídico do Master enviou a Vorcaro arquivo com nome e telefone de Kevin e perguntou sobre ''500 mil mês'' (04/07/2025; a Gazeta do Povo situa planilha em out/2024). O Correio da Manhã ressalva que as mensagens não provam pagamento nem origem do dinheiro.','reportada',NULL,'2024','2025',0,NULL,NULL,NULL,'Kevin e o escritório negam ter recebido dinheiro de Vorcaro; não há resposta de Rennó nas fontes lidas.',1,'teia','E[174].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(200,'newton-ramos','kassio-nunes-marques','pessoal',NULL,'Viagem a Maceió (nov/2025)','O Estadão (via Revista Oeste) afirma que Newton Ramos viajou a Maceió com Nunes Marques e família em nov/2025; o gabinete do ministro disse que convite e custo foram da advogada Camilla Ramos (Correio da Manhã). Mensagens de aliados de Vorcaro chamam o casal Ramos de ''Turma do KN''.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Nunes Marques nega mensagens com Vorcaro, nega pedir benefícios ou autorizar alguém a falar em seu nome.',1,'teia','E[175].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(201,'newton-ramos','kevin-de-carvalho-marques','juridica',NULL,'Liminar em causa da Refit (18/12/2025)','Segundo o Estadão (via Revista Oeste), em 18/12/2025 Newton Ramos concedeu liminar em causa da Refit defendida por Kevin; não é caso de precatório.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Não há resposta de Newton sobre este ponto nas fontes lidas.',1,'teia','E[176].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(202,'rodrigo-fux','luiz-fux','pessoal',NULL,'Filho do ministro','Rodrigo é filho do ministro Luiz Fux.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Sem posicionamento de Luiz Fux nas fontes abertas; a Folha registra que Luiz e Rodrigo não se manifestaram até a publicação.',1,'teia','E[177].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(203,'rodrigo-fux','daniel-vorcaro','pessoal',NULL,'Mensagens frequentes (mai/2024 a ago/2025)','Mensagens extraídas pela PF (Folha, Times Brasil): Vorcaro o trata por ''irmão'' (17/05/2024), ''Tapete vermelho irmão'' (04/12/2024); em 12/03/2025 Rodrigo o orientou a enviar material com cópia à secretária do pai no STF; em 17/06/2025 parabenizou pela aprovação do Cade ao BRB. Nenhuma fonte liga as mensagens a ato de Fux.','reportada',NULL,'2024','2025',0,NULL,NULL,NULL,'O escritório de Rodrigo diz que nunca advogou para Vorcaro ou Master, não recebeu valores nem fechou contrato e que foi tentativa comercial não concretizada.',1,'teia','E[178].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(204,'chiquinho-feitosa','gilmar-mendes','pessoal',NULL,'Ex-cunhado','Segundo o gabinete do ministro (via Aos Fatos/Folha), Chiquinho é ex-cunhado de Gilmar; O Povo o descreve como irmão de Guiomar Mendes, ex-mulher do ministro, mas o texto é ambíguo quanto ao estado civil em 2024.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'O gabinete diz que Gilmar ''não responde por relações privadas ou profissionais de ex-parente'' e que Chiquinho não foi procurado por ele.',1,'teia','E[179].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(205,'chiquinho-feitosa','daniel-vorcaro','politica',NULL,'Ajudou a marcar reunião com Gilmar (11/04/2024)','Aos Fatos e a Folha: Chiquinho ajudou a marcar a reunião de Vorcaro com Gilmar em 11/04/2024, às 18h, no gabinete do STF, com advogados do Master; segundo a PF/O Povo, também organizou encontro de Vorcaro com Guiomar. Chiquinho fazia lobby para o Master na área de educação (Folha).','investigacao',NULL,'2024','2024',0,NULL,NULL,NULL,'Gilmar e o gabinete: reunião breve e institucional; o ministro diz que desconhecia as tratativas e votou contra o Master em todos os casos do setor. Aos Fatos classifica como enganosa a narrativa de encontro ''secreto''.',1,'teia','E[180].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(206,'chiquinho-feitosa','super-empreendimentos','financeira',NULL,'Serviços à Super (R$ 500 mil/mês, segundo uma fonte)','O blog de Fausto Macedo (Estadão), via Times Brasil, diz que mensagens indicam contrato de R$ 500 mil por mês de Chiquinho com a Super Empreendimentos; o valor não aparece no texto de O Povo e não há confirmação documental. Chiquinho primeiro negou trabalhar para o banco e depois admitiu serviços à Super ''por um curto período''.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Chiquinho considerava a Super ''idônea'' e nega ter trabalhado para o banco.',1,'teia','E[181].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(207,'daniel-vorcaro','gilmar-mendes','politica',NULL,'Reunião no gabinete do STF (11/04/2024)','Folha (17/09/2026), CNN e Aos Fatos: Gilmar recebeu Vorcaro e advogados do Master em 11/04/2024, ''às vésperas'' do julgamento do ARE 1.327.995 (Alcídia), segundo a CNN. A CNN e a Folha não detalham o pedido; Aos Fatos diz que Vorcaro pediu voto favorável.','reportada',NULL,'2024','2024',0,NULL,NULL,NULL,'Gilmar: ambiente institucional e prerrogativa dos advogados; votou contra o Master em Alcídia (vencido com Mendonça), Raízen, Jalles Machado e na STP 976.',1,'teia','E[182].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(208,'lewandowski-advocacia','ricardo-lewandowski','societaria',NULL,'Escritório que levava seu nome','Os filhos Enrique e Yara de Abreu Lewandowski dirigem o escritório (Metrópoles); a Band diz que atuam a esposa e o filho. Lewandowski saiu da sociedade em 17/01/2024.','reportada',NULL,'2023','2024',0,NULL,NULL,NULL,'Lewandowski: consultoria prestada após deixar o STF, com outros clientes; deixou o escritório e suspendeu a OAB ao assumir o ministério em janeiro de 2024.',1,'teia','E[183].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(209,'lewandowski-advocacia','banco-master','contratual',NULL,'Consultoria de R$ 250 mil/mês (ago/2023 a set/2025)','Contrato de 28/08/2023: cerca de R$ 6,5 mi brutos, dos quais cerca de R$ 5,25 mi após a posse no Ministério da Justiça (Metrópoles); a Receita aponta R$ 6,1 mi desde nov/2023 e a CNN, R$ 2,3 mi só em 2025. O Oeste não identificou atuação em processo do Master.','documentada',NULL,'2023','2025',0,NULL,6500000.0,NULL,'Lewandowski confirmou a consultoria em nota; o escritório diz que ele não representou o Master perante o Executivo. Wagner confirmou ter indicado Lewandowski ao Master.',1,'teia','E[184].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(210,'enrique-de-abreu-lewandowski','ricardo-lewandowski','pessoal',NULL,'Filho do ministro','Enrique é filho de Ricardo Lewandowski e passou a dirigir o escritório com Yara de Abreu Lewandowski.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Lewandowski diz ter deixado a atuação em todos os casos ao aceitar o convite de Lula.',1,'teia','E[185].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(211,'irmaos-de-toffoli','dias-toffoli','pessoal',NULL,'Irmãos do ministro','Segundo a Folhapress (via Bem Paraná), José Carlos e José Eugênio Dias Toffoli são irmãos do ministro e sócios da Maridt.','reportada',NULL,'2021',NULL,0,NULL,NULL,NULL,'Toffoli admite a sociedade familiar na Maridt (dividendos, sem gestão) e nega ter recebido valor de Vorcaro ou Zettel.',1,'teia','E[186].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(212,'irmaos-de-toffoli','fabiano-zettel','societaria',NULL,'Sócios no resort Tayayá (2021-2025)','Folha e Estadão: os irmãos dividiram o controle do Tayayá (Ribeirão Claro, PR) com o fundo Arleen/Arllen, em que Zettel era cotista pelo fundo Leal; cotas vendidas ao Arllen (27/09/2021) e à PHD Holding (21/02/2025), parte vendida em 2025 estimada em R$ 3,5 mi. A coluna de Mario Sabino (opinião) fala em fundo ligado ao Master investindo R$ 20 mi.','reportada',NULL,'2021','2025',0,NULL,3500000.0,NULL,'Toffoli diz que a venda ao Arleen em 2021 não chegou a R$ 35 mi e chama os fatos da PF de ilações; Vorcaro diz nunca ter sido cotista dos fundos.',1,'teia','E[187].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(213,'mario-umberto-degani','dias-toffoli','pessoal',NULL,'Primo','A Folhapress (via Bem Paraná) cita Degani como primo de Toffoli e sócio no Tayayá.','reportada',NULL,'2021','2025',0,NULL,NULL,NULL,'Sem resposta específica de Degani.',1,'teia','E[188].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(214,'roberta-rangel','dias-toffoli','pessoal',NULL,'Esposa do ministro','Roberta é esposa de Toffoli e foi sócia do Warde Advogados a partir de 2021 (Revista Oeste).','reportada',NULL,'2021',NULL,0,NULL,NULL,NULL,'O escritório de Warde nega que a Maridt seja cliente.',1,'teia','E[189].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(215,'roberta-rangel','warde-advogados','societaria',NULL,'Ex-sócia (desde 2021)','A Revista Oeste informa que Roberta foi sócia do escritório de Warde desde 2021 e já não consta do site; o sócio Guilherme Lippi assinou ata de empresa dos irmãos Toffoli (Maridt/Tayayá) em 2023.','reportada',NULL,'2021',NULL,0,NULL,NULL,NULL,'Warde nega que a Maridt seja cliente.',1,'teia','E[190].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(216,'pedro-gonet-branco','paulo-gonet','pessoal',NULL,'Filho do procurador-geral','Pedro é filho do PGR Paulo Gonet.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'Gonet diz que o filho nunca teve contato com Vorcaro nem viajou.',1,'teia','E[191].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(217,'pedro-gonet-branco','daniel-vorcaro','pessoal',NULL,'Convite a fórum em Londres (2025)','Ciro Soares perguntou a Vorcaro, em 29/03/2025, se o filho de Gonet poderia ir ao II Fórum Jurídico Londres; Vorcaro respondeu ''Pedro e ciro ok'' (11/04/2025) e confirmou em 19/06/2025, ''autorizando'' o custeio segundo a PF. O evento de 2025 foi cancelado; não há valor nem confirmação de pagamento. O SBT diz que a PF não achou o contato de Gonet no celular de Vorcaro.','investigacao',NULL,'2025','2025',0,NULL,NULL,NULL,'Gonet: nunca pediu para convidar ou pagar a viagem; só encontrou Vorcaro uma vez em Londres (abril/2024) e teve uma ligação breve em março/2025. A reportagem aponta contradição entre ''sem ligações'' e a ligação descrita.',1,'teia','E[192].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(218,'paulo-gonet','ciro-soares','investigacao',NULL,'Intermediação de contato (PF)','Segundo a PF, Ciro Soares intermediou contatos de Vorcaro com Gonet. A PF relata ainda atuação de Gonet em abril/2024 em favor de Jarbas Soares Júnior, irmão de Ciro, na eleição do CNPG, com base em mensagens/áudio de Ciro (A Crítica). O Conselho Superior do MPF arquivou por 5 a 4 o pedido de investigação criminal contra Gonet (25/09/2026).','investigacao',NULL,'2024','2026',0,NULL,NULL,NULL,'Gonet: único encontro em Londres e uma ligação breve passada por Ciro.',1,'teia','E[193].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(219,'bianca-medeiros','hugo-motta','pessoal',NULL,'Cunhada (irmã da esposa)','Bianca é irmã de Luana Motta, esposa do presidente da Câmara.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'A assessoria da cunhada diz que a empresa não tem vínculo societário ou de gestão com Motta.',1,'teia','E[194].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
