INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(221,'banco-master','etc-participacoes','financeira',NULL,'Empréstimo de pelo menos R$ 22 mi (15/03/2024)','Empréstimo assinado em 15/03/2024, com as cotas da ETC em garantia, para comprar terreno de antiga fábrica de cimento em João Pessoa; o MP junto ao TCU pediu apuração (InfoMoney, via Jornal de Brasília).','documentada',NULL,'2024',NULL,0,NULL,22000000.0,NULL,'Assessoria da cunhada: condições usuais de mercado. Motta: o empréstimo foi contratado antes de a investigação vir a público.',1,'teia','E[196].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(222,'leo-serrano-giunchetti','hugo-motta','pessoal',NULL,'Reserva de quartos em Lisboa (18/06/2024)','Segundo a PF (CNN, Itatiaia), o agente de viagens reservou quartos em Lisboa para Hugo Motta e Ciro Nogueira em 18/06/2024.','investigacao',NULL,'2024','2024',0,NULL,NULL,NULL,'Motta admite a viagem e a hospedagem paga por Vorcaro.',1,'teia','E[197].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
