INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(228,'eduardo-sodre-martins','augusto-ferreira-lima','financeira',NULL,'Cobrança de boletos de apartamento (set/2025)','A PF diz que Sodré cobrou de Lima boletos de apartamento de cerca de R$ 2,45 mi em Salvador (comprado pela Epítome S.A. com recursos de fundos do grupo) em 01 e 04/09/2025 (CNN); a PF afirma que seria vantagem a Wagner.','investigacao',NULL,'2025','2025',0,NULL,2450000.0,NULL,'Wagner: o apartamento fazia parte de negociação para ajudar a filha, com Lima comprando e compromisso de recompra. Defesa de Lima: fatos ''rigorosamente lícitos''. Sodré não respondeu.',1,'teia','E[203].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
