INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(231,'cnlf-empreendimentos-imobiliarios','daniel-vorcaro','financeira',NULL,'Repasses de R$ 300 mil/mês à ''parceria BRGD/CNLF''','Segundo a PF/Mendonça (decisão de 07/05/2026) e o Coaf, mensagens entre Felipe e Daniel Vorcaro citam R$ 300 mil/mês, que a PF suspeita ser propina: ao menos R$ 6 mi em cerca de 20 meses, com mesada que teria subido a R$ 500 mil. Em abril/2024 a CNLF comprou 30% da Green Investimentos por R$ 1 mi (fatia estimada pela PF em R$ 13 mi). O advogado Kakay disse, ao deixar a defesa, que a família recebeu cerca de R$ 300 mil/mês de empresa do grupo Master por cerca de dois anos.','investigacao',NULL,'2024','2026',0,NULL,6000000.0,NULL,'Ciro diz que o imóvel foi pago ''100% por minha empresa'' e que é ''perseguição política''; a defesa afirma que ''mera troca de mensagens'' não basta.',1,'teia','E[206].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
