INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(233,'felipe-cancado-vorcaro','daniel-vorcaro','pessoal',NULL,'Primo; mensagens sobre repasses','Felipe é primo de Daniel; mensagens entre os dois citam a ''parceria BRGD/CNLF'' (PF).','investigacao',NULL,'2024','2026',0,NULL,NULL,NULL,'Defesa de Daniel e de Felipe não responderam no trecho.',1,'teia','E[208].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(234,'caio-carvalho-barros','ibaneis-rocha','pessoal',NULL,'Filho do governador (segundo Estadão/Brasil 247)','O Estadão e o Brasil 247 dizem que Caio é filho de Ibaneis; Metrópoles e BNews falam do escritório ''de Ibaneis'' sem citar o filho. Parentesco não confirmado em outras páginas abertas.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Ibaneis diz estar desligado da sociedade desde o fim de 2018 e que nunca negociou com Paulo Henrique Costa ou com a Reag.',1,'teia','E[209].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(235,'ibaneis-advocacia','ibaneis-rocha','societaria',NULL,'Escritório ligado à família','A imprensa descreve o escritório como ''de Ibaneis'' ou ligado à família do governador.','reportada',NULL,NULL,NULL,0,NULL,NULL,NULL,'Ibaneis: desligado da sociedade desde o fim de 2018.',1,'teia','E[210].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(236,'caio-carvalho-barros','ibaneis-advocacia','societaria',NULL,'Escritório do filho (segundo a imprensa)','Estadão/Brasil 247 identificam o escritório de Caio Barros como o ligado à família de Ibaneis.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'A nota do escritório trata a operação como regular.',1,'teia','E[211].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(237,'ibaneis-advocacia','laguz-i-e-reag-legal-claims','financeira',NULL,'Venda de direitos de honorários (R$ 38,1 mi; ao menos R$ 81 mi vendidos)','Estadão (documento da operação): fundo ligado à Reag comprou direitos de honorários de Caio Barros e de Engels Muniz por R$ 38,1 mi (10% de condenação de R$ 381,3 mi da União, caso Sindlegis), contrato de 29/05/2024; pago R$ 10,3 mi em 12/06/2024 (R$ 4 mi ao escritório ligado à família do governador, R$ 6,3 mi a Muniz, números da nota do escritório). Coaf (via CPMI do INSS, Metrópoles 21/03/2026): R$ 43 mi vendidos ao Laguz I (R$ 15 mi recebidos) e R$ 38 mi ao Reag Legal Claims (R$ 4 mi recebidos). Metrópoles lista 13 contratos do escritório (R$ 73,8 mi).','documentada',NULL,'2024','2024',0,NULL,38100000.0,NULL,'O escritório: negócio ''regular, lícito e reiteradamente praticado''. Engels Muniz nega relação com o Master e diz que o escritório de Ibaneis ficou com a maior parte, o que contradiz a divisão da nota. O BRB começou a negociar com o Master em junho/2024.',1,'teia','E[212].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(238,'laguz-i-e-reag-legal-claims','reag-investimentos','societaria',NULL,'Fundos ligados à Reag','Estadão e Coaf descrevem os fundos como ligados à Reag; o diretor do fundo comprador, Marcos Ferreira Costa, também responde pelo fundo Borneo, acionista do BRB.','reportada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Não há resposta do fundo nas fontes lidas.',1,'teia','E[213].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(239,'davi-alcolumbre','amprev','politica',NULL,'Conselheiro fiscal (irmão Alberto Alcolumbre)','Alberto Alcolumbre, irmão de Davi, é conselheiro fiscal da Amprev, que aplicou R$ 400 mi em letras financeiras do Master sem cobertura do FGC. Ata de julho/2024: conselheiros alertaram ''alto risco'' e ''problemas políticos'' do banco e a aplicação foi aprovada (Gazeta do Povo). Alberto não foi alvo da operação de 06/02/2026; a Gazeta e a Folhapress citam o vínculo, sem imputação a ele. A apreensão de R$ 500 mil com Alberto em 2022 não tem relação com o Master na reportagem.','documentada',NULL,'2024',NULL,0,NULL,400000000.0,NULL,'A assessoria de Davi nega envolvimento nas decisões do fundo; Alberto e Jocildo não se manifestaram; a Amprev diz que os aportes seguiram as normas.',1,'teia','E[214].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(240,'eduardo-bolsonaro','jair-bolsonaro','pessoal',NULL,'Filho','Eduardo é filho de Jair Bolsonaro e irmão do senador Flávio.','documentada',NULL,'2025',NULL,0,NULL,NULL,NULL,'Eduardo nega ter recebido recursos do fundo e diz que apenas cedeu direitos de imagem e investiu R$ 350 mil, depois reembolsados.',1,'teia','E[215].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(241,'eduardo-bolsonaro','flavio-bolsonaro','investigacao',NULL,'Irmão; investigados no mesmo inquérito','Eduardo e Flávio são investigados por lavagem, evasão de divisas, corrupção ativa e passiva e organização criminosa, em inquérito autorizado por Mendonça (BBC/O Povo). O Congresso em Foco diz que o texto sobre o inquérito de 23/07/2026 (PET 16.292) não afirma que Flávio seja formalmente investigado.','investigacao',NULL,'2026',NULL,0,NULL,NULL,NULL,'Flávio nega que o dinheiro tenha ido a Eduardo e diz que foi usado no filme.',1,'teia','E[216].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(242,'eduardo-bolsonaro','havengate','investigacao',NULL,'Orientou a gestão dos recursos do filme (PF)','A PF diz que Eduardo orientou como os recursos de Dark Horse seriam geridos nos EUA (captura de tela enviada por Thiago Miranda a Vorcaro em 21/03/2025).','investigacao',NULL,'2025',NULL,0,NULL,NULL,NULL,'Eduardo nega ter recebido recursos do fundo; não foi localizado pelo Estadão.',1,'teia','E[217].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
