INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(244,'entre-investimentos-e-participacoes','havengate','financeira',NULL,'US$ 12,3 mi enviados (fev. a set/2025)','O Estadão (via O Liberal) informa que a Entre, de Antônio Carlos Freixo Júnior, enviou US$ 12.333.335 ao Havengate; Vorcaro pretendia investir US$ 24 mi. Fundo ''dormente'' desde 2021 e reativado em 2025.','investigacao',NULL,'2025','2025',0,NULL,NULL,NULL,'Flávio diz que o dinheiro foi usado no filme.',1,'teia','E[219].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(245,'havengate','go-up-entertainment','financeira',NULL,'Caminho do dinheiro do filme','Caminho citado pela PF (preliminar): Entre -> fundo no Texas -> Go Up. Valores incompatíveis entre fontes: contrato de R$ 134 mi com R$ 61 mi pagos (Intercept), mais de 90% do orçamento de US$ 13 mi (Karina), pouco mais de US$ 12 mi (Flávio admitiu), R$ 2,3 mi do Master a empresa que financiou o filme (Poder360).','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Karina Ferreira da Gama diz que a Go Up nunca recebeu direto de Vorcaro.',1,'teia','E[220].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(246,'mario-frias','daniel-vorcaro','financeira',NULL,'Áudio agradecendo a Vorcaro (dez/2024)','O Intercept mostra áudio em que Frias agradece a Vorcaro e o chama de ''irmão''; Frias negou ''um centavo'' do Master e depois falou em ''diferença de interpretação sobre a origem formal''.','reportada',NULL,'2024','2024',0,NULL,NULL,NULL,'Frias nega verba do Master.',1,'teia','E[221].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(247,'andre-mendonca','eduardo-bolsonaro','investigacao',NULL,'Inquérito autorizado (23/07/2026)','Mendonça autorizou inquérito da PF (PET 16.292) após parecer favorável de Gonet, sobre origem e destino do dinheiro do filme e possíveis despesas de Eduardo nos EUA (Congresso em Foco).','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'Eduardo e Flávio negam ter recebido recursos do fundo.',1,'teia','E[222].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
