INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(250,'fabiano-zettel','belline-santana','financeira',NULL,'Pagamentos de R$ 760 mil','Mensagem de Zettel de 02/10/2024 cita R$ 760 mil a Belline (pontual, segundo a mensagem; o Itatiaia fala em R$ 760 mil por mês); Leonardo Palhares é citado como destinatário de dinheiro parcialmente destinado a Belline. A PF cita ainda viagem da esposa de Belline a Paris que Vorcaro teria ajudado a pagar.','investigacao',NULL,'2024','2024',0,NULL,760000.0,NULL,'Resposta não obtida (Itatiaia: ''espaço aberto'').',1,'teia','E[225].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(251,'cezinha-de-madureira','valeria-rodrigues-linhares','pessoal',NULL,'Esposa (ou ex-namorada)','As fontes divergem: ''ex-namorada'' (Itatiaia, perfil) ou ''mulher/esposa'' (Itatiaia, reportagem posterior; Bahia Notícias; Gazeta).','reportada',NULL,'2026',NULL,0,NULL,NULL,NULL,'A defesa de Valéria diz que o dinheiro foi declarado no IR.',1,'teia','E[226].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(252,'cezinha-de-madureira','andre-mendonca','politica',NULL,'Articulou o encontro com Vorcaro (14/03/2025)','Segundo a Itatiaia, mensagens do celular de Vorcaro indicam que Cezinha e Ciro Soares articularam o encontro de Vorcaro com Mendonça em 14/03/2025.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Mendonça confirmou um único encontro, em que só ouviu, e disse que depois decidiu contra interesses do banco. Cezinha: sem manifestação nas páginas abertas.',1,'teia','E[227].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(253,'cezinha-de-madureira','flavio-dino','investigacao',NULL,'Alvo da Operação Transparência (14/09/2026)','Na 3ª fase, autorizada por Dino, a PF cumpriu 4 mandados por tráfico de influência, exploração de prestígio, corrupção passiva e lavagem; Dino e a PF dizem não haver indício de que magistrados tenham pedido ou recebido vantagens. A operação não está ligada, nas fontes, a pagamento do Master.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'A defesa de Cezinha fala em conduta ''ilibada'' e motivação política.',1,'teia','E[228].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(254,'ciro-soares','daniel-vorcaro','politica',NULL,'Intermediário de contatos com Gonet, Mendonça e Otto Alencar','A PF diz que Ciro intermediou contatos de Vorcaro com Gonet, com Mendonça (14/03/2025, também por Cezinha) e com Otto Alencar; convidou-se ao fórum de Londres e pediu inclusão do filho de Gonet.','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Ciro: a quebra do sigilo advogado-cliente é ilegal, marcar encontros com magistrados é comum e Vorcaro não era investigado em março/2025.',1,'teia','E[229].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(255,'ciro-soares','andre-mendonca','politica',NULL,'Encontro com Vorcaro (14/03/2025)','Mendonça confirmou um único encontro com Vorcaro, em que só ouviu, e reunião com Ciro sobre a STP 976.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Mendonça: encontro institucional; decidiu depois contra interesses do banco.',1,'teia','E[230].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(256,'ciro-soares','otto-alencar','politica',NULL,'Contatos sobre o FGC','Mensagens mostram Vorcaro chamando Otto de ''conselheiro'' e ''comandante'' (2024-2025).','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Otto negou contatos e depois admitiu falar ''duas ou três vezes por telefone'', pelo aparelho de Ciro, sobre o FGC (R$ 250 mil para R$ 1 mi), dizendo que se opôs à proposta.',1,'teia','E[231].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(257,'daniel-vorcaro','otto-alencar','politica',NULL,'''Conselheiro'' e ''comandante''','Mensagens de 2024-2025 mostram Vorcaro tratando o senador como ''conselheiro'' e ''comandante'' (Times Brasil).','investigacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Otto: negou e depois admitiu ligações breves sobre o FGC; diz que se opôs à proposta.',1,'teia','E[232].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(258,'walfrido-warde','daniel-vorcaro','juridica',NULL,'Advogado de defesa; ''Estamos infernizando o cara'' (17/11/2025)','A PF diz que Warde tentou contato com o juiz Ricardo Leite (10ª Vara Federal) horas antes da prisão e escreveu a Vorcaro ''Estamos infernizando o cara''; diz ainda que Vorcaro soube da operação por ''meios ilícitos'', por servidores do BC ou por contato de Warde. Warde deixou a defesa em 21/01/2026 (motivo não esclarecido).','investigacao',NULL,'2025','2026',0,NULL,NULL,NULL,'O escritório diz que agiu ''absolutamente dentro da lei'', que quatro escritórios prepararam petição conjunta e que a acusação de obter dados sigilosos é ''caluniosa''.',1,'teia','E[233].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
