INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(276,'dalide-barbosa-alves-correa','gilmar-mendes','pessoal',NULL,'Ex-diretora-geral do IDP; ''canal direto com o STF''','Dalide foi diretora-geral do IDP, fundado por Gilmar, entre 2010 e 2017; mensagens de diretores do Master (Ângelo Ribeiro a Alberto Félix) a chamam de ''canal direto com o STF'' sem explicar.','reportada',NULL,'2010','2017',0,NULL,NULL,NULL,'Gilmar não se manifestou; interlocutores dizem que não há proximidade. Assessoria de Dalide nega ter atuado no STF.',1,'teia','E[251].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(277,'banco-master','marcus-vinicius-furtado-coelho','contratual',NULL,'R$ 27,5 mi em 2025','Receita (via CNN/BPMoney): R$ 27,5 mi em 2025; segundo maior de 2025 na CNN, ou Warde com cerca de R$ 27 mi segundo O Globo/Oeste.','documentada',NULL,'2025','2025',0,NULL,27500000.0,NULL,'Procurado pela CNN, não comentou.',1,'teia','E[252].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(278,'banco-master','fabio-wajngarten','contratual',NULL,'R$ 3,8 mi em 2025','Receita (via CPI): R$ 3,8 mi à WF Comunicação; contratado no 1º semestre de 2025 para defesa e gestão da crise de imagem. A manchete do Brasil de Fato (''R$ 38 mi'') é erro evidente.','documentada',NULL,'2025','2025',0,NULL,3800000.0,NULL,'Seu advogado diz que foi convidado a integrar a defesa de Vorcaro e que o contrato tem confidencialidade.',1,'teia','E[253].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(279,'banco-master','ronaldo-bento','contratual',NULL,'R$ 11 mi (Meta Consultoria, pessoa física e Mettacard)','Intercept, com dados da Receita à CPI: total de R$ 11 mi (Meta Consultoria R$ 6,2 mi em 2025; pessoa física R$ 773,3 mil; Mettacard R$ 2,98 mi). O Banco Pleno foi liquidado em fev/2026 e seus bens ficaram indisponíveis.','documentada',NULL,'2025','2025',0,NULL,11000000.0,NULL,'Remuneração declarada ao fisco; não depôs. Natureza dos serviços não especificada.',1,'teia','E[254].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(280,'daniel-vorcaro','antonio-rueda','financeira',NULL,'Delação proposta: R$ 3 mi/mês e 10% (alegação)','A proposta de delação de Vorcaro, segundo a UOL (via Diário do Rio), diz que o escritório de Rueda recebia cerca de R$ 3 mi/mês e que Rueda abriu portas em institutos de previdência do Rio por 10%. A PF e a PGR não aceitaram a proposta; a Receita lista R$ 6,4 mi (CNN: R$ 1 mi em 2025; InfoMoney: R$ 2,1 mi).','alegacao',NULL,'2023','2025',0,NULL,NULL,NULL,'Rueda: não viu o documento; contratos lícitos; sem cargo público, a acusação de propina é ''absolutamente fora de propósito''.',1,'teia','E[255].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(281,'michel-temer','ibaneis-rocha','politica',NULL,'Reunião com Ibaneis, Paulo Henrique Costa e Vorcaro','Temer relata reunião em Brasília com Ibaneis e Paulo Henrique Costa, com Vorcaro chegando depois (Revista Oeste); BandB liga o contrato ao tema da venda ao BRB.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Temer: ''Não recebi dinheiro, recebi honorários''; o valor foi de R$ 7,5 mi (R$ 5 mi e R$ 2,5 mi), por mediação jurídica, e não os R$ 10 mi da Receita.',1,'teia','E[256].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(282,'queiroga-vieira-queiroz-e-ramos-advocacia','banco-master','contratual',NULL,'Contrato de êxito de 5% em 12 ações (teto de R$ 427 mi)','Contrato no celular de Vorcaro (mar/2024, segundo a PF) ou procurações de dez/2024 (Estadão): 12 ações de precatórios sucroalcooleiros (face de R$ 8,5 bi), êxito de 5% do efetivamente recebido, podendo receber direto da União e registrar precatórios em nome do escritório; teto de R$ 427 mi só se o banco ganhar tudo. A minuta cita a Usina Capricho.','documentada',NULL,'2024',NULL,0,NULL,427000000.0,NULL,'O escritório diz que há contrato formal só para casos específicos, nenhum pagamento recebido, êxito abaixo dos limites do CPC e do Estatuto da OAB, nenhum caso no STF, e condena o vazamento.',1,'teia','E[257].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(283,'camilla-ramos','queiroga-vieira-queiroz-e-ramos-advocacia','societaria',NULL,'Advogada do escritório','Camilla Rose Ewerton Ferro Ramos assina pelo escritório, junto com o filho Gabriel Ribeiro Gonçalves Ramos (procurações de 12/2024).','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Camilla não é alvo declarado nas fontes.',1,'teia','E[258].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(284,'camilla-ramos','newton-ramos','pessoal',NULL,'Esposa do desembargador','Camilla é esposa de Newton Pereira Ramos Neto, desembargador do TRF-1.','documentada',NULL,'2024',NULL,0,NULL,NULL,NULL,'Newton: relação pessoal com Vorcaro, nunca julgou causa de interesse do Master; o procedimento do CNJ é ''natural e regular''.',1,'teia','E[259].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(285,'camilla-ramos','kassio-nunes-marques','politica',NULL,'''Turma do KN''; comemorou voto (jun/2025)','Em jun/2025, Camilla comemorou em mensagem (''excelente'') o voto de Nunes Marques na 2ª Turma favorável às usinas; ele havia registrado impedimento (foi vice-presidente do TRF-1) e depois julgou. Pedido de hotel Fasano e camarotes de Carnaval atribuídos ao ministro nas mensagens (sem manifestação de Camilla). A manchete do Times Brasil liga o escritório a Nunes Marques, mas o corpo cita só Camilla e o desembargador.','reportada',NULL,'2025','2025',0,NULL,NULL,NULL,'Nunes Marques nega mensagens com Vorcaro e diz que o processo julgado tratava de tese ampla, sem relação direta com as ações defendidas por ela; alegou inexistência de impedimento técnico.',1,'teia','E[260].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(286,'newton-ramos','usina-cansancao-de-sinimbu','juridica',NULL,'Votou em jan e jun/2024','A 11ª Turma do TRF-1 acolheu em 22-26/01/2024 recurso da usina e rejeitou em 03-07/06/2024 recursos da União; Newton integrava a turma. O Estadão afirma que o contrato da esposa foi seis meses depois (datas do contrato divergem: mar/2024 ou dez/2024).','reportada',NULL,'2024','2024',0,NULL,NULL,NULL,'Newton: o relator era outro, o agravo foi julgado em bloco (cerca de 300 processos), o interesse do Master não constava dos autos e o impedimento foi anotado. O CNJ diz na sindicância que a relação entre o crédito julgado e o Master ainda não foi comprovada.',1,'teia','E[261].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(287,'banco-master','usina-cansancao-de-sinimbu','financeira',NULL,'Ingresso no processo (21/03/2023) e compra de parte dos precatórios','O Estadão diz que o Master ingressou no processo como interessado em 21/03/2023 e atuou junto com a usina, comprando parte dos precatórios por fundos ligados à Reag; a PF diz que o objetivo seria inflar liquidez.','reportada',NULL,'2023',NULL,0,NULL,NULL,NULL,'Newton diz que o ingresso do Master foi depois do julgamento.',1,'teia','E[262].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(288,'newton-ramos','cnj','investigacao',NULL,'Sindicância e correição (22 e 24/09/2026)','O corregedor Benedito Gonçalves determinou sindicância (prazo de 60 dias) a partir de reclamação do advogado Alex Ferreira Borralho e, em 24/09, o CNJ fez correição extraordinária no gabinete com apoio da PF; Newton não foi afastado.','documentada',NULL,'2026',NULL,0,NULL,NULL,NULL,'Newton chama a correição de ''regular''; o TRF-1 declarou ''integral colaboração''.',1,'teia','E[263].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
