INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(294,'agu','stf','juridica',NULL,'Pede suspensão nacional (Pet 127700/2026, 08/10/2026)','Na questão de ordem, a AGU pediu suspender execuções (98 processos amostrados) e bloquear pagamento de precatórios já expedidos; impacto de R$ 255,3 bi com juros (R$ 224,69 bi no TRF-1); amostra de R$ 12,37 bi já pagos.','documentada',NULL,'2026',NULL,0,NULL,255300000000.0,NULL,'As usinas dizem que o valor é ''artificialmente majorado'' (sem juros R$ 190 bi; cerca de R$ 63 bi seriam títulos transitados não pagos) e pedem remessa a Fachin.',1,'teia','E[269].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
