INSERT INTO relacao(id, de, para, tipo, subtipo, rotulo, descricao, natureza_id, confianca, periodo_inicio, periodo_fim, periodo_aprox, periodo_texto, valor_brl, valor_texto, resposta, direcional, origem, origem_ref, status, criado_em, atualizado_em) VALUES(301,'kassio-nunes-marques','destilaria-alcidia','investigacao',NULL,'Voto pelo pagamento; impedimento alegado e revertido','Nunes Marques votou pelo pagamento. A denúncia de Alessandro Vieira (24/09/2026) afirma que o sistema registrou impedimento em fev/2024, revertido em mar/2024 por ''equívoco da assessoria''; a data do julgamento (01/10/2024 ou 03/06/2025), o placar (empate 2x2 desempatado por ele ou 3x2) e o pedido de vista divergem entre fontes.','alegacao',NULL,'2024','2025',0,NULL,NULL,NULL,'Nunes Marques diz que nunca votou em favor de Vorcaro ou do Master e que o julgamento era sobre tese ampla.',1,'teia','E[276].r[0]','publicada','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
