INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-1990-extincao-do-iaa-que-fixava-precos-do','Extinção do IAA, que fixava preços do açúcar e do álcool','O Instituto do Açúcar e do Álcool, criado em 1933, foi extinto em 1990. As usinas alegam que o preço tabelado ficou abaixo do custo em períodos entre 1985 e 1999 (varia por caso); a base legal citada é a Lei 4.870/1965, com custos apurados pela FGV. Fonte: Gilberto Melo e Valor/Nova Cana.','1990',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
