INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2021-lei-complementar-179-da-autonomia-ao','Lei Complementar 179 dá autonomia ao Banco Central','Em 24/2/2021 é sancionada a Lei Complementar 179, que define a estabilidade de preços como objetivo fundamental do Banco Central, o torna autarquia especial com autonomia técnica, operacional, administrativa e financeira e regula a nomeação e a exoneração de seu presidente e diretores.','2021',0,NULL,NULL,3,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2021].pol.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2021-lira-e-pacheco-sao-eleitos-presidentes','Lira e Pacheco são eleitos presidentes das Casas','Em 1/2/2021 Arthur Lira (PP-AL) é eleito presidente da Câmara no 1º turno, com 302 votos contra 145 de Baleia Rossi (MDB-SP), e Rodrigo Pacheco (DEM-MG) presidente do Senado, com 57 votos contra 21 de Simone Tebet (MDB-MS).','2021',0,NULL,NULL,3,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2021].pol.eventos[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2021-pec-dos-precatorios-e-aprovada-e','PEC dos Precatórios é aprovada e promulgada','Aprovada na Câmara em 9/11/2021 por 323 a 172 e no Senado em 2/12 (64 a 13 e 61 a 10, relator Fernando Bezerra Coelho), a PEC que limita o pagamento de precatórios e abre espaço ao Auxílio Brasil é promulgada em parte como Emenda Constitucional 113 em 8/12 e em parte como EC 114 em 16/12.','2021',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2021].pol.eventos[5]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
