INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-ec-123-cria-estado-de-emergencia-e','EC 123 cria estado de emergência e amplia benefícios','A PEC 1/2022, aprovada no Senado em 30/6 (relator Fernando Bezerra Coelho) e na Câmara em 13/7 por 469 a 17 no 2º turno (relator Danilo Forte), é promulgada em 14/7 como Emenda Constitucional 123 e autoriza R$ 41,25 bilhões fora do teto em benefícios em ano eleitoral, como o Auxílio Brasil de R$ 600.','2022',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].pol.eventos[2]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-fed-sobe-os-juros-de-0-25-0-50-a-4-25-4','Fed sobe os juros de 0,25%–0,50% a 4,25%–4,50%','Entre 16 de março e 14 de dezembro de 2022 o Fed elevou a meta dos fed funds de 0,25%–0,50% para 4,25%–4,50% para conter a inflação elevada.','2022',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].intl.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-lei-complementar-194-limita-o-icms-sobre','Lei Complementar 194 limita o ICMS sobre combustíveis','Em 23/6/2022 é sancionada a Lei Complementar 194, que classifica combustíveis, energia elétrica, comunicações e transporte coletivo como bens essenciais e impede os estados de cobrar ICMS sobre eles acima da alíquota geral das operações.','2022',0,NULL,NULL,3,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].pol.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-lula-derrota-bolsonaro-na-eleicao','Lula derrota Bolsonaro na eleição presidencial','Lula (PT) e Jair Bolsonaro (PL) vão ao segundo turno em 2/10/2022 e, em 30/10, Lula vence com 50,9% dos votos, tornando-se o primeiro candidato a derrotar um presidente que disputava a reeleição.','2022',0,NULL,NULL,5,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].pol.eventos[3]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-pec-da-transicao-vira-a-emenda','PEC da Transição vira a Emenda Constitucional 126','Aprovada no Senado em 7/12/2022 (64 a 16 e 64 a 13, relator Alexandre Silveira) e na Câmara em 21/12 (331 a 163 no 2º turno, relator Elmar Nascimento), que reduziu a vigência de dois anos para um, a PEC é promulgada no mesmo dia e libera R$ 145 bilhões fora do teto de gastos em 2023.','2022',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].pol.eventos[5]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-russia-invade-a-ucrania','Rússia invade a Ucrânia','Em 24 de fevereiro de 2022 a Rússia iniciou a invasão em larga escala da Ucrânia, a maior guerra na Europa desde a Segunda Guerra Mundial, o que gerou sanções ocidentais e um choque nos preços de energia e alimentos.','2022',0,NULL,NULL,5,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].intl.eventos[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2022-stf-condena-o-deputado-daniel-silveira','STF condena o deputado Daniel Silveira; Bolsonaro o indulta','Em 20/4/2022 o STF condena o deputado federal Daniel Silveira (PTB-RJ) a 8 anos e 9 meses de prisão por incentivar atos antidemocráticos e, em 21/4, o presidente Jair Bolsonaro concede-lhe indulto.','2022',0,NULL,NULL,3,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2022].pol.eventos[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
