INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-fed-leva-os-juros-a-5-25-5-50','Fed leva os juros a 5,25%–5,50%','Em 26 de julho de 2023 o Fed elevou a meta dos fed funds para a faixa de 5,25% a 5,50%, por unanimidade dos onze votantes.','2023',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].intl.eventos[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-lei-complementar-200-cria-o-novo','Lei Complementar 200 cria o novo arcabouço fiscal','Em 30/8/2023 é sancionada a Lei Complementar 200, que substitui o teto de gastos por metas de resultado primário e limites de despesa que crescem a 70% (ou 50%, se a meta não for cumprida) da variação da receita; a Câmara aprovou o texto-base em 23/5 por 372 a 108, com relatoria de Claudio Cajado.','2023',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[3]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-milei-e-eleito-e-o-peso-argentino-e','Milei é eleito e o peso argentino é desvalorizado em 54%','Em 19 de novembro de 2023 Javier Milei venceu o segundo turno com 55,65% dos votos e em 12 de dezembro o câmbio oficial passou de 366,5 para 800 pesos por dólar, desvalorização de 54%.','2023',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].intl.eventos[2]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-quebra-do-svb-e-venda-do-credit-suisse','Quebra do SVB e venda do Credit Suisse ao UBS','Em 10 de março de 2023 o Silicon Valley Bank, com US$ 209 bilhões em ativos, quebrou e em 19 de março o UBS anunciou a compra do Credit Suisse por 3 bilhões de francos suíços, em operação articulada pelo governo suíço.','2023',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].intl.eventos[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-stf-e-congresso-divergem-sobre-o-marco','STF e Congresso divergem sobre o marco temporal','Em 21/9/2023 o STF decide por 9 votos a 2 que a tese do marco temporal é inconstitucional; em 27/9 o Senado aprova o PL 2.903, sancionado em 20/10 como Lei 14.701 com vetos, que o Congresso derruba em 14/12 (Câmara 321 a 137, Senado 53 a 19).','2023',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[4]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2023-tse-torna-bolsonaro-inelegivel-por-oito','TSE torna Bolsonaro inelegível por oito anos','Em 30/6/2023 o TSE decide por 5 votos a 2 declarar Jair Bolsonaro inelegível por oito anos a partir da eleição de 2022, por abuso de poder político e uso indevido dos meios de comunicação em reunião com embaixadores em 18/7/2022, em ação movida pelo PDT.','2023',0,NULL,NULL,4,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2023].pol.eventos[2]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-01-22-11a-turma-do-trf-1-acolhe-recurso-da','11ª Turma do TRF-1 acolhe recurso da Cansanção de Sinimbu','Sessão virtual unânime de 22-26/01/2024; Newton Ramos integrava a turma. Ele diz que o relator era outro e que o agravo foi julgado em bloco (cerca de 300 processos).','2024-01-22',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[13]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-03-oficio-do-bc-cobra-comprovacao-dos','Ofício do BC cobra comprovação dos precatórios; minuta de contrato com o escritório de Camilla Ramos','O ofício 5.582 do Desup exige comprovação de origem, existência e valor e histórico de cessões, e o BC pede auditoria externa. Na mesma época, segundo a PF, a minuta com o escritório QVQR prevê êxito de 5% em 12 ações (teto de R$ 427 mi); o Estadão fala em procurações só em dez/2024.','2024-03',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[14]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-04-11-gilmar-recebe-vorcaro-e-advogados-do','Gilmar recebe Vorcaro e advogados do Master no STF','Reunião às 18h, intermediada por Chiquinho Feitosa, ex-cunhado do ministro, ''às vésperas'' do julgamento da Alcídia (CNN). Gilmar diz que foi institucional e que votou contra o Master em todos os casos do setor. Revelada pela Folha em 17/09/2026.','2024-04-11',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[15]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-05-27-bc-aprova-a-compra-da-will-no-dia','BC aprova a compra da Will; no dia seguinte, exigência de capital','O BC aprovou a compra da Will em 27/05/2024; em 28/05 a supervisão exigiu correção de déficit de capital de R$ 885 milhões e de operações irregulares com o Fundo Bravo, gerido pela Reag. As três compras de 2024 somaram cerca de R$ 26 bilhões em ativos, segundo o TCU citado pela fonte.','2024-05-27',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[61]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
