INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-10-01-data-disputada-do-julgamento-da-alcidia','Data disputada do julgamento da Alcídia (ARE 1.327.995)','A denúncia de Alessandro Vieira e a piauí falam em 01/10/2024 (empate 2x2 desempatado por Nunes Marques, segundo a denúncia; vista de Nunes Marques, segundo a piauí). A nota de Gilmar fixa 03/06/2025. Mensagem do diretor jurídico do Master a Vorcaro: ''Ganhamos Alcídia''. Divergência não resolvida (falta o andamento do STF).','2024-10-01',0,NULL,'alegacao',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[18]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
