INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-12-04-lula-recebe-vorcaro-no-planalto-fora-da','Lula recebe Vorcaro no Planalto, fora da agenda','Encontro de cerca de uma hora e meia (segundo a Band, com base em Poder360/UOL), com Mantega, Galípolo em parte e Rui Costa presentes; confirmado pelo governo, que diz ter sido o único.','2024-12-04',0,NULL,'documentada',4,'teia','lado: contexto',NULL,NULL,'teia','teia:EV[66]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
