INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2024-presos-por-suposto-plano-de-golpe-pf','Presos por suposto plano de golpe; PF indicia Bolsonaro','Em 19/11/2024 cinco integrantes de forças de segurança são presos por suposto plano de matar Lula, Alckmin e Moraes e, em 21/11, a Polícia Federal indicia 37 pessoas, entre elas Jair Bolsonaro, por supostos crimes de golpe de Estado, abolição violenta do Estado Democrático de Direito e organização criminosa, em relatório enviado ao STF.','2024',0,NULL,NULL,5,'brasil',NULL,NULL,NULL,'linha_do_tempo','Y[2024].pol.eventos[4]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
