INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-11-18-1a-fase-da-compliance-zero-7-prisoes-e','1ª fase da Compliance Zero: 7 prisões e 25 buscas','A PF cumpriu 5 mandados de prisão preventiva, 2 temporárias e 25 de busca em cinco unidades da federação; o diretor-geral da PF falou em esquema de cerca de R$ 12 bilhões. O presidente do BRB, Paulo Henrique Costa, foi afastado por decisão judicial.','2025-11-18',0,NULL,'investigacao',5,'teia',NULL,NULL,NULL,'teia','teia:EV[92]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-11-18-bc-decreta-a-liquidacao-extrajudicial-do','BC decreta a liquidação extrajudicial do Master','Pelo Ato do Presidente nº 1.373, o BC liquidou Banco Master, Master de Investimento, Letsbank e a corretora Master e pôs o Master Múltiplo em RAET, por ''grave crise de liquidez'' e violações às normas do SFN. O conglomerado detinha 0,57% do ativo do sistema; o liquidante é a EFB.','2025-11-18',0,NULL,'documentada',5,'teia','lado: barra',NULL,NULL,'teia','teia:EV[91]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-11-relatorio-do-inss-aponta-251-718','Relatório do INSS aponta 251.718 consignados do Master sem prova','Análise técnica do INSS, revelada em jan/2026 pelo Estadão e confirmada pelo O Globo, aponta falhas graves em 251.718 de 338.608 contratos (74,3%) firmados entre out/2021 e set/2025. O Master não se manifestou.','2025-11',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[96]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-12-04-cpmi-do-inss-aprova-convocacao-e-quebra','CPMI do INSS aprova convocação e quebra de sigilo de Vorcaro','O requerimento do relator Alfredo Gaspar buscava ouvir Vorcaro sobre a oferta de consignado a aposentados e as reclamações recebidas pela Senacon. Foram convocados também executivos de Daycoval, Pan, Facta, BMG e Agibank.','2025-12-04',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[98]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
