INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2025-12-caso-chega-ao-stf-toffoli-e-relator-e','Caso chega ao STF; Toffoli é relator e impõe sigilo','O inquérito foi para o STF após menção a autoridade com foro; Toffoli assumiu a relatoria e restringiu o acesso aos autos. No mesmo mês, o relator do TCU determinou inspeção no BC.','2025-12',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[102]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
