INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-02-18-bc-liquida-o-banco-pleno-ex-voiter','BC liquida o Banco Pleno (ex-Voiter)','Liquidação por comprometimento da situação econômico-financeira, deterioração da liquidez e descumprimento de determinações do BC. O banco pertencia a Augusto Lima, a quem o Master o vendeu em setembro de 2025. O FGC terá de ressarcir cerca de R$ 4,9 bilhões a cerca de 160 mil credores, segundo o Estadão reproduzido pela Revista Oeste.','2026-02-18',0,NULL,'documentada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[121]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-02-24-cvm-lista-18-procedimentos-sobre-os','CVM lista 18 procedimentos sobre os grupos Master e Reag','São 6 inquéritos administrativos, 8 processos sancionadores com acusação e 4 encerrados por termo de compromisso. Inclui processo de 2021 contra o Banco Master e os Vorcaro e processos contra a Reag por demonstrações financeiras não entregues.','2026-02-24',0,NULL,'documentada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[122]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-03-04-3a-fase-vorcaro-e-preso-de-novo','3ª fase: Vorcaro é preso de novo','Por decisão de Mendonça, Vorcaro e Zettel foram presos; também foi preso o suposto coordenador operacional de ''A Turma'', e buscas atingiram o ex-diretor de Fiscalização do BC Paulo Sérgio Neves de Souza. Mendonça apontou risco à integridade física de pessoas e a PF encontrou mensagens sobre plano contra um jornalista. Em sessão virtual de 13 a 20/03, Mendonça, Fux e Nunes Marques votaram por manter a preventiva na Segunda Turma; Toffoli se declarou suspeito.','2026-03-04',0,NULL,NULL,5,'teia',NULL,NULL,NULL,'teia','teia:EV[123]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-03-11-mansur-na-cpi-master-era-cliente-da-reag','Mansur na CPI: Master era cliente da Reag e nega vínculo com PCC','Amparado por decisão do ministro Flávio Dino, ficou calado em boa parte da sessão. Disse que o Master era cliente como outras instituições e que as páginas da Carbono Oculto não mencionam associação com o PCC.','2026-03-11',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[127]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-03-17-master-multiplo-e-liquidado-liquidante','Master Múltiplo é liquidado; liquidante move ação em SP','O BC liquidou o Master Múltiplo, última instituição do conglomerado ainda não liquidada. Segundo o Metrópoles, a 3ª Vara de Falências de SP deferiu pedido do liquidante de protesto contra alienações de 19 imóveis, 13 empresas e 3 fundos ligados a Vorcaro, medida que alerta terceiros de que a aquisição pode ser considerada ineficaz.','2026-03-17',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[129]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-03-dino-vota-para-cancelar-precatorios-da','Dino vota para cancelar precatórios da Tabu; Nunes Marques pede vista','Na STP 976-ED, 5 ministros já votam por cancelar (Moraes pedira vista em 11/2024); a vista de Nunes Marques suspende o julgamento. A fonte não atribui motivação.','2026-03',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[26]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-04-08-receita-mostra-pagamentos-do-master-a-ex','Receita mostra pagamentos do Master a ex-ministros e políticos','Declarações do Master enviadas à CPI do Crime Organizado listam contratos com Temer, Meirelles, Mantega, Lewandowski, Rueda, ACM Neto e o escritório de Viviane Barci de Moraes.','2026-04-08',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[134]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-04-16-ex-presidente-do-brb-paulo-henrique','Ex-presidente do BRB, Paulo Henrique Costa, é preso','4ª fase da Compliance Zero. A decisão cita vantagem indevida ligada a seis imóveis de luxo.','2026-04-16',0,NULL,'investigacao',5,'teia','lado: barra',NULL,NULL,'teia','teia:EV[136]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-04-20-brb-e-quadra-fecham-memorando-para','BRB e Quadra fecham memorando para vender ativos do Master','Valor de referência de R$ 15 bilhões sobre carteira de R$ 21,9 bilhões de face: R$ 3 a 4 bilhões à vista e R$ 11 a 12 bilhões em cotas subordinadas de um fundo a criar.','2026-04-20',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[138]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-04-estadao-revela-o-contrato-de-r-427-mi','Estadão revela o contrato de R$ 427 mi com o escritório de Camilla Ramos','Contrato de êxito de 5% em 12 ações (face de R$ 8,5 bi). O escritório diz que nada recebeu.','2026-04',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[27]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-05-04-cvm-acusa-reag-trust-e-ex-diretor-por','CVM acusa Reag Trust e ex-diretor por ocultar cotistas e liquidez','A CVM afirma que a rotina incluía ocultar cotistas com mais de 20% do patrimônio e divulgar liquidez incorreta. A Reag disse ter identificado uma ''inconsistência operacional''. Julgamento sem data.','2026-05-04',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[139]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-05-05-defesa-de-vorcaro-oferece-delacao-e','Defesa de Vorcaro oferece delação e devolução de R$ 40 bi','Advogados entregaram a base da delação à PF e à PGR em 05/05/2026, com compromisso de devolver ao menos R$ 40 bilhões. Segundo a Exame (15/06), a PF formalizou a rejeição por falta de informações inéditas e a PGR tendia a seguir; a Gazeta do Povo (22/07) relatou que PF e PGR rejeitaram as duas propostas.','2026-05-05',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[140]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-05-07-pf-faz-buscas-contra-o-senador-ciro','PF faz buscas contra o senador Ciro Nogueira (5ª fase)','A decisão de Mendonça cita mesada de R$ 300-500 mil e a ''emenda Master''; a defesa nega ilicitude.','2026-05-07',0,NULL,'investigacao',5,'teia',NULL,NULL,NULL,'teia','teia:EV[142]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-05-26-justica-das-bahamas-reconhece-a','Justiça das Bahamas reconhece a liquidação do Master','O liquidante foi nomeado representante e identificou nove entidades ligadas ao Master nas Bahamas. Segundo sua apuração preliminar, Vorcaro e outros teriam desviado ao menos US$ 1 bilhão; tribunais dos EUA já haviam reconhecido a liquidação em janeiro.','2026-05-26',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[143]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-05-28-uniao-e-gdf-acordam-emprestimo-de-ate-r','União e GDF acordam empréstimo de até R$ 6,6 bi do FGC ao BRB','Em conciliação conduzida por Fux, ficou acertado que o BRB buscará até R$ 6,6 bilhões no FGC, com FPE e FPM do DF como garantia e sem aval da União. Termos propostos: IPCA + 4,5% e carência de 18 meses.','2026-05-28',0,NULL,'documentada',5,'teia','lado: contexto',NULL,NULL,'teia','teia:EV[144]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-06-09-presidente-do-brb-fala-em-corrida-de','Presidente do BRB fala em corrida de liquidez e provisão de R$ 8,8 bi','Nelson de Souza disse que a carteira ligada ao Master soma R$ 21,9 bilhões (R$ 12,2 bilhões fraudulentos segundo as investigações) e que o provisionamento necessário é de R$ 8,8 bilhões. O balanço de 2025 segue sem divulgação.','2026-06-09',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[145]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-06-11-camara-do-df-aprova-o-socorro-ao-brb-por','Câmara do DF aprova o socorro ao BRB por 11 a 9','O BRB precisa provisionar R$ 8,8 bi e segue sem balanço de 2025.','2026-06-11',0,NULL,'documentada',NULL,'brb','lado: contexto',NULL,NULL,'dossie','dossie.brb.eventos[28]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-06-11-folha-liga-o-gold-style-a-bk-bank-aster','Folha liga o Gold Style a BK Bank, Aster e Super Empreendimentos','Segundo a Folha, o FIDC administrado pela Reag Trust teve R$ 146,5 mi em transações com a BK Bank (Coaf), R$ 311,7 mi com a Aster e ao menos R$ 180 mi com a Super Empreendimentos. Reag não comentou; BK não respondeu; Entre diz cumprir as normas.','2026-06-11',0,NULL,'reportada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[146]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-06-18-9a-fase-jaques-wagner-e-augusto-lima-sao','9ª fase: Jaques Wagner e Augusto Lima são alvos','A PF cumpriu 18 mandados de busca na BA, SP e DF; Wagner é investigado por suposta atuação pró-Vorcaro no Congresso em troca de vantagens, segundo a PF. Segundo a Gazeta do Povo, ele atribui a ação a interesses político-eleitorais; o Poder360 diz que ele não havia respondido, e o presidente do PT, Edinho Silva, afirmou confiança nele.','2026-06-18',0,NULL,'investigacao',5,'teia',NULL,NULL,NULL,'teia','teia:EV[147]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-07-14-pf-indicia-48-pessoas-na-sem-desconto','PF indicia 48 pessoas na Sem Desconto, incluindo ex-presidente do INSS','O primeiro relatório final, sobre a Conafer, foi enviado ao STF. Segundo a PF, Stefanutto teria recebido até R$ 250 mil por mês para não fiscalizar entidades. A PGR decidirá se denuncia.','2026-07-14',0,NULL,'investigacao',4,'teia',NULL,NULL,NULL,'teia','teia:EV[149]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-07-17-brb-encerra-o-memorando-com-a-quadra','BRB encerra o memorando com a Quadra','Em fato relevante de 17/07, o BRB informou que não daria continuidade à venda de ativos do Master objeto do memorando com a Quadra, sem que as diligências necessárias fossem concluídas; o BRB disse que as tratativas foram encerradas de forma consensual, e a Folha relatou divergências em parâmetros econômicos e financeiros. A entrada de R$ 3 a 4 bilhões não se concretizou, e o BRB afirma que fará a gestão e a recolocação dos ativos.','2026-07-17',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[150]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-07-23-mendonca-autoriza-inquerito-sobre','Mendonça autoriza inquérito sobre repasses de Vorcaro ao Dark Horse','A PF e a PGR pediram a apuração; segundo o Intercept, os repasses somam ao menos US$ 10,6 milhões. Flávio Bolsonaro nega irregularidade.','2026-07-23',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[151]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-08-18-mp-sp-denuncia-16-pessoas-da-carbono','MP-SP denuncia 16 pessoas da Carbono Oculto','Segundo o Gaeco, o grupo desviava metanol para adulterar combustíveis entre 2017 e 2025 e lavou recursos; a denúncia não acusa formalmente os 16 de pertencerem ao PCC. A defesa de Beto Louco diz não ter tido acesso aos autos.','2026-08-18',0,NULL,'investigacao',4,'teia',NULL,NULL,NULL,'teia','teia:EV[152]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-08-26-mansur-entrega-a-pgr-proposta-de-delacao','Mansur entrega à PGR proposta de delação com 17 anexos','Segundo o UOL, a proposta foca em Vorcaro e prevê multa de cerca de R$ 40 mi. Citou o fundo Jaguar (Cayman, R$ 494 mi recebidos do Master) e o High Tower (carteiras do antigo Besc de R$ 850 mi registradas como R$ 10 bi). São relatos não homologados.','2026-08-26',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[153]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-01-mendonca-levanta-sigilo-de-relatorio-da','Mendonça levanta sigilo de relatório da PF com 52 mensagens a número atribuído a Moraes','O relatório aponta 52 mensagens de Vorcaro a número atribuído a Moraes (2023 a 17/11/2025); a PGR pediu a anulação do relatório e Moraes nega contato com Vorcaro e diz que Mendonça age contra desafetos.','2026-09-01',0,NULL,'documentada',5,'teia',NULL,NULL,NULL,'teia','teia:EV[155]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-02-pgr-fecha-acordo-de-delacao-com-mansur','PGR fecha acordo de delação com Mansur; homologação pendente','Primeiro acordo de colaboração fechado pela PGR na Compliance Zero (BPMoney, 02/09); audiência de voluntariedade em 03/09; em 20/09 o acordo seguia sem decisão de André Mendonça. As reportagens usam o condicional: Mansur teria dito que fundos da Reag foram usados para ocultar propinas atribuídas a Vorcaro; o conteúdo não está comprovado nem homologado.','2026-09-02',0,NULL,NULL,5,'teia',NULL,NULL,NULL,'teia','teia:EV[156]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-08-mendonca-afasta-o-diretor-geral-da-pf','Mendonça afasta o diretor-geral da PF; CVM multa Vorcaro','Mendonça afastou Andrei Rodrigues e o diretor de Inteligência por pedido do Novo, citando relatórios de inteligência divulgados por Moraes. No mesmo dia a CVM multou Vorcaro, o pai, o primo e o Master num total de R$ 201,5 milhões no caso Brazil Realty (cabe recurso).','2026-09-08',0,NULL,'documentada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[157]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-09-fachin-suspende-decisoes-de-mendonca-e','Fachin suspende decisões de Mendonça e Dino sobre a PF','Fachin suspendeu as liminares conflitantes e marcou sessão plenária para 15/09. No mesmo dia, segundo o BPMoney, Mendonça homologou a delação de Antônio Freixo Júnior, que cita US$ 12 milhões ao filme ''Dark Horse'' por pedido atribuído a Flávio Bolsonaro, que nega irregularidades em outra reportagem.','2026-09-09',0,NULL,'documentada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[158]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-11-piaui-publica-relatorio-da-pf-sobre-o','piauí publica relatório da PF sobre o voto de Toffoli na Alcídia','A PF suspeita que Vorcaro agiu para mudar a posição de Toffoli; o diretor jurídico teria se oferecido para tirar o caso de pauta. A PF diz que os elementos pedem aprofundamento; Toffoli nega.','2026-09-11',0,NULL,'investigacao',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[28]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-13-stf-torna-publica-decisao-que-bloqueou','STF torna pública decisão que bloqueou bens de Vorcaro','Mendonça decidiu em 24/07 e o sigilo caiu em 13/09/2026: bens no exterior acima de R$ 2 bilhões (imóveis nos EUA, iate, obras de Basquiat e Picasso) e ativos e imóveis das instituições liquidadas de R$ 21,4 bilhões.','2026-09-13',0,NULL,NULL,5,'teia',NULL,NULL,NULL,'teia','teia:EV[159]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-15-plenario-do-stf-comeca-a-analisar','Plenário do STF começa a analisar questão de ordem sobre pedido de investigar Moraes; Dino pede vista','Moraes e Mendonça trocaram acusações em plenário; placar de 4 a 3 pela análise separada dos pedidos envolvendo Moraes e Mendonça. Em manifestação ao STF, Gonet disse ter visto Vorcaro uma vez, em Londres.','2026-09-15',0,NULL,NULL,5,'teia',NULL,NULL,NULL,'teia','teia:EV[162]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-22-cnj-manda-cancelar-16-precatorios-r-4-74','CNJ manda cancelar 16 precatórios (R$ 4,74 bi) e abre sindicância contra Newton Ramos','Cautelar do corregedor Benedito Gonçalves, a pedido da AGU, contra Capricho, Una e Vale do Ceará Mirim (assinada em 22/09, divulgada em 23/09). No mesmo dia, sindicância contra Newton por reclamação de Alex Ferreira Borralho.','2026-09-22',0,NULL,'documentada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[29]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-23-tribunal-de-contas-do-df-bloqueia-bens','Tribunal de Contas do DF bloqueia bens de ex-dirigentes do BRB','R$ 2,7 bi, segundo o título da reportagem.','2026-09-23',0,NULL,'documentada',NULL,'brb','lado: barra',NULL,NULL,'dossie','dossie.brb.eventos[29]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-24-credito-oculto-3a-fase-da-carbono-oculto','Crédito Oculto: 3ª fase da Carbono Oculto mira Freixo, apontado pela PF como operador de Vorcaro','Receita e Gaeco cumpriram buscas contra 13 pessoas e 19 empresas (R$ 11,6 bi movimentados por uma empresa financeira entre 2021 e 2025). Entre os alvos, Freixo (Entre) e um ex-executivo do Genial. O comunicado da Receita não cita Master, Vorcaro, Reag nem PCC.','2026-09-24',0,NULL,NULL,5,'teia',NULL,NULL,NULL,'teia','teia:EV[164]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-24-dino-manda-a-pf-investigar-a-atuacao-da','Dino manda a PF investigar a atuação da CVM no caso Master','Na ADI 7.791, o ministro cita arquivamento de denúncia do FGC em 2022 e indícios de influência de autoridades de alto escalão.','2026-09-24',0,NULL,'documentada',4,'teia',NULL,NULL,NULL,'teia','teia:EV[163]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-24-gilmar-leva-o-caso-raizen-ao-plenario','Gilmar leva o caso Raízen ao plenário; CNJ faz correição em Newton Ramos; Vieira denuncia Nunes Marques','Questão de ordem sobre o Tema 826 (União x Raízen), citando R$ 103,4 bi do risco ''provável'' da LDO. Correição extraordinária no gabinete de Newton com apoio da PF. Denúncia de impeachment de Nunes Marques no Senado.','2026-09-24',0,NULL,'documentada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[30]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-28-segunda-cautelar-do-cnj-e-oficios-de','Segunda cautelar do CNJ e ofícios de Gilmar a Fachin e ao STJ','Mais 14 precatórios (R$ 1,88 bi nas datas-base, R$ 2,36 bi atualizados) de Santa Helena, Agrovale Vale do Curu e Borborema; total das duas cautelares cerca de R$ 7 bi (a Nova Cana fala em 30 precatórios e R$ 6,5 bi, que não bate). Gilmar pede correição nos TRFs e proibição de expedir antes do trânsito.','2026-09-28',0,NULL,'documentada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[31]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-09-29-fachin-responde-a-gilmar','Fachin responde a Gilmar','Encaminha à Corregedoria, manda tribunais informarem precatórios expedidos irregularmente e fala em ''apuração rigorosa''. Dino pede a identificação de todos os precatórios pagos irregularmente; o MPTCU pede fiscalização do TCU.','2026-09-29',0,NULL,'documentada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[32]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-10-01-pf-indicia-13-executivos-na-quasar-e','PF indicia 13 executivos na Quasar e envia relatório ao MPF','A PF indiciou 13 executivos de fundos, corretoras e fintechs por suspeita de lavagem de dinheiro de sonegação e crimes no setor de combustíveis (grupo Aster-Copape), em esquema que as reportagens vinculam ao PCC; a defesa cita trecho do relatório da PF segundo o qual o vínculo com facção não é afirmado como fato provado. O relatório foi ao MPF. As reportagens não citam Reag nem Banco Master entre os indiciados.','2026-10-01',0,NULL,'investigacao',4,'teia',NULL,NULL,NULL,'teia','teia:EV[165]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-10-02-fachin-pede-a-pf-lista-de-ministros','Fachin pede à PF lista de ministros citados nas conversas de Vorcaro','Reunião com o diretor-geral da PF marcada para 13/10/2026. A reportagem cita Nunes Marques, Toffoli, Fux e Mendonça, além de mensagem enviada a número atribuído a Moraes, sem informar se as menções implicam irregularidade.','2026-10-02',0,NULL,NULL,4,'teia',NULL,NULL,NULL,'teia','teia:EV[166]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-10-02-vista-de-fux-interrompe-o-referendo-na','Vista de Fux interrompe o referendo na 2ª Turma','Gilmar e Toffoli votaram pela remessa ao plenário; pendiam Mendonça, Nunes Marques e Fux (CNN, 01/10). A vista de Fux tem um único relato (O Brasilianista, 14/10).','2026-10-02',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[33]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-10-08-agu-pede-suspensao-nacional-de-execucoes','AGU pede suspensão nacional de execuções','Pet 127700/2026: suspender execuções (98 processos amostrados) e bloquear pagamentos; impacto de R$ 255,3 bi com juros. As usinas contestam em 09/10 (sem juros, R$ 190 bi) e pedem remessa a Fachin.','2026-10-08',0,NULL,'documentada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[34]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ev-2026-10-14-sem-decisao-sobre-a-suspensao','Sem decisão sobre a suspensão','Pendentes: referendo da 2ª Turma, plenário sobre o Tema 826 em títulos transitados, STP 976-ED (Tabu), liminares do CNJ, sindicância de Newton Ramos e denúncia de impeachment de Nunes Marques.','2026-10-14',0,NULL,'reportada',NULL,'precatorios',NULL,NULL,NULL,'prec','PREC[35]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam0','Nasce Daniel Bueno Vorcaro, em Belo Horizonte','Mais Goiás, Jornal Contábil e a Wikipedia (que cita G1 e piauí) registram o nascimento de Daniel em 6 de outubro de 1983, em BH. Segundo Mais Goiás, InfoMoney e BPMoney, estudou no Colégio Fundação Torino e cursou Economia no Ibmec-BH; a Wikipedia, citando G1 e piauí, fala em Administração com MBA no Ibmec concluído em 2007. As fontes divergem sobre o curso; o ano de conclusão só aparece na Wikipedia.','1983-10-06',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[3]|origens:EV[3]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam1','Henrique Vorcaro funda o Grupo Multipar, há cerca de 35 anos segundo o site do grupo (c. 1991)','Poder360 e Band (14/05/2026), citando a página oficial do grupo, dizem que a Multipar foi fundada ''há cerca de 35 anos'' por Henrique Vorcaro (por volta de 1991, ano inferido pela data das reportagens), a partir da Vorcaro Imóveis e da Centro Sul Empreendimentos. O Hoje em Dia diz que o conglomerado nasceu em Belo Horizonte e depois expandiu a atuação para engenharia, energia, agronegócio, mineração e hotelaria. O Mais Goiás diz que Henrique se tornou corretor imobiliário e fundou a Multipar. Nenhuma fonte aberta traz o ano exato nem a lista de sócios.','1991',1,'c. 1991','reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[5]|origens:EV[5]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam10','Bahia regulamenta por decreto, em abril de 2018, o consignado Credcesta, depois ligado ao Master','O Times Brasil (29/01/2026) informa que o Decreto estadual nº 18.353, de abril de 2018, instituiu o programa de consignação em folha para bens e serviços de servidores baianos associado ao Credcesta, na gestão do governador Rui Costa. A CNN Brasil (14/01/2026) diz que Augusto Ferreira Lima, empresário baiano, venceu uma licitação de venda da Ebal (Empresa Baiana de Alimentos) e criou o CredCesta, cartão consignado; a reportagem não informa o ano de criação. O Brazil Journal (2021) liga a Credcesta a uma rede baiana de supermercados.','2018-04',0,NULL,'reportada',3,'familia',NULL,'A assessoria do senador Jaques Wagner, citada pela CNN, diz que ele conheceu Augusto Lima em 2017, quando era secretário de Desenvolvimento Econômico da Bahia, e que uma das atribuições da pasta era conduzir a venda do Supermercado Cesta do Povo.',NULL,'origens','teia:EV[28]|origens:EV[29]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam11','Negócios de cotas do fundo CARE11 em 28 e 29/6/2018 viram caso na CVM','A CNN Brasil (18/03/2026) relata que a área técnica da CVM propôs responsabilizar o Banco Máxima e Angelo Antonio Ribeiro da Silva, descrito como responsável pela emissão das ordens em nome do banco, por suposta manipulação de preços em compras de cotas do fundo imobiliário DEA CARE (CARE11) nos pregões de 28 e 29/6/2018, com variações ''atípicas''. O caso foi encerrado em 2022 por termo de compromisso (R$ 2,208 milhões do banco e R$ 736 mil de Angelo). A Revista Oeste menciona o CARE11 e o BZLI11 em um termo global de R$ 2,9 milhões.','2018-06-28',0,NULL,'documentada',4,'familia',NULL,'Segundo a CNN Brasil, os termos de compromisso são mecanismos que encerram processos sem julgamento do mérito; a defesa de Angelo não foi localizada pela reportagem.',NULL,'origens','teia:EV[29]|origens:EV[30]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam13','Sete novos sócios aparecem no quadro do Máxima, entre eles Augusto Lima','Segundo o Jornal de Brasília, com base em documentos do BC, em 16/1/2019 constavam como novos sócios do Máxima Augusto Lima (10%), Bruno Guedes, Yan Tironi, Alexandre Seguim e Antonio Neto (3% cada), Felipe Simonsen e Armando Gallo (1,75% cada). A data conflita com a Bloomberg Línea e a CNN Brasil, que situam a chegada de Lima ao controle em 2019 e a sociedade no Master em 2020, respectivamente.','2019-01-16',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[33]|origens:EV[35]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam15','Fontes dizem que a má reputação da família em BH dominou a discussão no BC; o voto não a analisou','O Let''s Money, citando o Valor, escreve que o voto de fevereiro não analisou a reputação ilibada, pois outros dois requisitos já barravam a compra, mas que fontes disseram que a má fama de Daniel e da família em Belo Horizonte dominou a discussão. A Gazeta do Povo (14/04/2026) cita ex-servidores do BC dizendo que a má reputação de Daniel já era conhecida em 2019, mas que esses problemas não foram formalizados nos documentos oficiais e que prevaleceu uma análise técnica sobre os números. A Bloomberg (21/05/2026) diz que Henrique era conhecido na elite de BH como ''mau pagador'' e que recorreu ao filho quando percebeu que sua reputação poderia comprometer a busca. As avaliações vêm de fontes anônimas, sem decisão judicial.','2019',0,NULL,'reportada',3,'familia',NULL,'Daniel declinou comentar ao Valor (via Let''s Money). A Bloomberg registra que o advogado de Henrique negou algo na reportagem; o trecho está cortado no acesso aberto e o conteúdo da negativa não pôde ser verificado.',NULL,'origens','teia:EV[39]|origens:EV[32]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam16','Novo pedido ao BC, com Simonsen e Gallo, e aportes de R$ 100 mi até junho','Em 2/5/2019 Daniel protocolou novo pedido, com grupo de controle formado por ele, Felipe Wallace Simonsen e Armando Miguel Gallo Neto, segundo Let''s Money (via Valor). Entre março e junho de 2019, segundo o Jornal de Brasília e o Let''s Money, ele aportou R$ 70 milhões e os demais sócios R$ 30 milhões; o novo plano incluía recebíveis de LCA e um cartão consignado do Estado da Bahia. Os candidatos entregaram declarações retificadoras à Receita, recolheram impostos e apresentaram recursos líquidos em bancos do grupo S1.','2019-05-02',0,NULL,'reportada',3,'familia',NULL,'A reportagem não obteve resposta da defesa; grande parte do detalhamento no documento do BC está tarjada.',NULL,'origens','teia:EV[35]|origens:EV[37]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam19','Mandado de prisão preventiva de cinco dias expedido em Ji-Paraná (RO)','O Let''s Money, reproduzindo o Valor, diz que em 29/10/2019 a Justiça Federal de Ji-Paraná decretou prisão preventiva de cinco dias contra Daniel, mandado que nunca foi cumprido e foi posteriormente revogado. A reportagem não informa o motivo, e esta é a única fonte aberta do episódio.','2019-10-29',0,NULL,'reportada',3,'familia',NULL,'Daniel declinou comentar ao Valor (via Let''s Money); a reportagem não informa o motivo da prisão preventiva.',NULL,'origens','teia:EV[38]|origens:EV[39]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam2','Daniel, aos 19 ou 20 anos, atua em negócio de educação da família','O Brazil Journal (dez/2021) conta que, aos 19 ou 20 anos, Daniel prestava consultoria a um sistema de ensino usado por escolas de Minas e, após a morte do fundador, comprou o negócio dos herdeiros e depois o vendeu a um grupo do Sul. A Wikipedia em inglês diz que o primeiro negócio dele, aos 19 anos, foi à frente da PQS (curso em Nova Lima) e de uma editora de livros didáticos, adquiridos pelo pai e vendidos depois de relatos de conflitos de gestão; também situa a entrada dele no setor imobiliário a partir de 2004, via empresas familiares como Multipar e Mercatto. As versões diferem sobre quem comprou o negócio (Daniel ou o pai). A Revista Oeste (2026) lista a PQS entre empresas com débitos em dívida ativa em que Henrique é responsável. O ano 2003 é aproximado, deduzido da idade.','2003',1,'c. 2003','reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[9]|origens:EV[9]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam20','Delação de 2019 cita captação de R$ 100 mi de fundos de pensão para o hotel','A Crítica (28/02/2026) relata que uma delação firmada em 2019 por três operadores do mercado financeiro (Christian Rego, Felipe Fonseca e Bruno Moraes) descreve a captação de cerca de R$ 100 milhões junto a fundos de previdência de estatais e de servidores municipais (entre eles Serpros e Refer) para o Golden Tulip BH, mediante pagamento de propina a gestores e uso de notas frias, e que Daniel ''pressionava e chantageava'' colaboradores. São alegações dos delatores; a reportagem diz que eles ''apresentaram provas'', mas não informa se houve verificação independente nem se a delação foi homologada. Segundo uma coluna de opinião do Brasil 247, as obras pararam em 2014.','2019',0,NULL,'reportada',3,'familia',NULL,'A Crítica não traz manifestação de Daniel nem de Henrique. Segundo a coluna do Brasil 247, a defesa dos Vorcaro rebateu e alegou que 95% da obra foi entregue e que pai e filho ''não têm nada a ver'' com os desvios.',NULL,'origens','teia:EV[40]|origens:EV[33]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam21','Augusto Lima, dono do Credcesta, entra na sociedade do Master em 2020, segundo a CNN','O Brazil Journal (dez/2021) diz que Lima, dono da Credcesta, ligada a uma rede baiana de supermercados, tornou-se sócio e chefe do varejo do Master. A CNN Brasil (14/01/2026) diz que ele entrou na sociedade do Master em 2020, levando o CredCesta, e saiu em maio de 2024; o Jornal de Brasília e a Bloomberg Línea trazem Lima já no quadro de 2019. Em depoimento à PF, segundo o Times Brasil, Daniel afirmou que Lima tocava a área de consignado.','2020',0,NULL,'reportada',3,'familia',NULL,'Daniel disse à PF que, como presidente, não entrava nos detalhes da originação ou de questões operacionais do consignado. Segundo a CNN, interlocutores de Lima dizem que ele deixou a sociedade em maio de 2024, um ano antes da tentativa de compra do Master pelo BRB.',NULL,'origens','teia:EV[45]|origens:EV[40]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam22','Maurício Quadrado associa-se ao Master para tocar o banco de investimento','O Brazil Journal (23/12/2021) diz que Quadrado, ex-Bradesco e ex-sócio da Planner, associou-se ao Master ''no ano anterior'' (2020), comanda o banco de investimentos, aprovado pelo BC em novembro de 2021, e apresentou Daniel a Nelson Tanure. A Revista Oeste (10/09/2024) diz que ele se tornou sócio em 2021 e estava prestes a vender sua participação, estimada em 20% a 30%.','2020',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[46]|origens:EV[41]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam23','Hapvida compra o grupo Promed por R$ 1,5 bi; Máxima assessora','O Brazil Journal diz que em 8/9/2020 a Hapvida anunciou a compra do Promed e da rede Vera Cruz por R$ 1,5 bilhão, e descreve Henrique Vorcaro como vendedor do Promed, que teria comprado pouco antes. O Istoé Dinheiro registra a conclusão em 19/5/2021 e que o Máxima assessorou o Promed, sem identificar o vendedor. O Brazil Journal (dez/2021) estima lucro de R$ 1 bilhão para a família.','2020-09-08',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[41]|origens:EV[43]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam24','CVM: voto de 1º/12/2020 defende aceitar termo de compromisso de R$ 2,325 mi no caso das debêntures','Em voto de 1º/12/2020, o diretor Henrique Machado Moreira, após pedido de vista (o Colegiado havia rejeitado as propostas em 3/11/2020), votou por aceitar o termo de compromisso de R$ 2.325.000 no PAS 19957.009798/2019-01: Daniel Vorcaro e Luiz Bull propuseram pagar R$ 250 mil cada e a Máxima CCTVM R$ 1 milhão, entre outros proponentes. O voto se fundamenta na cessação das condutas, na indenização aos investidores e no fato de a inspeção do BC ter concluído pelo encerramento de pendências. A CNN Brasil diz que os acordos de 2020 resultaram em indenização superior a R$ 51 milhões a investidores e multas de cerca de R$ 2,3 milhões, sem julgamento do mérito; a Revista Oeste noticia que Vorcaro e Bull pagaram R$ 250 mil cada.','2020-12-01',0,NULL,'documentada',4,'familia',NULL,'Segundo a CNN Brasil, a defesa de Daniel afirma que esses instrumentos ''não constituem condenação, nem implicam juízo de mérito sobre as condutas analisadas''; a defesa de Luiz Bull diz que não houve julgamento desfavorável nem admissão de culpa.',NULL,'origens','teia:EV[44]|origens:EV[46]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam25','Máxima (futuro Master) adquire o banco de investimento Vipal (fim de 2020; ainda sob análise do BC em mai/2021)','A Bloomberg Línea situa no fim de 2020 a compra do banco de investimento Vipal, parte de um plano que incluía a gestora MAM e uma corretora; o Istoé Dinheiro (21/05/2021) diz que o Máxima adquiriu ''recentemente'' a Vipal e que a operação ainda estava sob análise do BC. O Brazil Journal registra que o banco de investimentos foi aprovado pelo BC em novembro de 2021.','2020',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[47]|origens:EV[42]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam27','Brazil Journal: Master vira ''banco de investimento e merchant bank''','Perfil de Geraldo Samor (23/12/2021) descreve Daniel como mineiro de 38 anos e informa patrimônio líquido de R$ 30 milhões antes da gestão dele, R$ 420 milhões em 2020 e projeção de R$ 700 milhões em 2021. Cita Credcesta, 50% do Jeitto, a seguradora Kovr (ex-Banco Rural), a compra do Fasano Itaim e a parceria com Nelson Tanure na Alliar e na Copel Telecom. As fontes divergem nos números históricos: o InfoMoney fala em patrimônio líquido que ''passou de R$ 219 milhões'' para mais de R$ 5 bilhões em cinco anos, sem indicar o ano de partida.','2021-12-23',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[51]|origens:EV[49]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam28','Pai e irmã constam como responsáveis por cerca de R$ 8 mi em dívida ativa da União, com exigibilidade suspensa (Oeste)','A Revista Oeste (19/1/2026) relata 13 inscrições em dívida ativa da União (contribuições sociais e tributos como IRPJ) que têm como responsáveis Henrique Moura Vorcaro e/ou Natália Vorcaro Zettel, somando pouco mais de R$ 8 milhões; a maior parte (cerca de R$ 5,8 milhões) é da Mercatto Corporações Imobiliárias, da qual Henrique é sócio e a Multipar acionista. Também aparecem a PQS Empreendimentos Educacionais, a Mercatto Consultoria Imobiliária, o Tropical Clube de Minas Gerais e a Eukaryota Participações (débito de R$ 7 mil em nome de Natália). Todos os 13 débitos estão com exigibilidade suspensa. A reportagem cita a PGFN, segundo a qual a inadimplência ''pode resultar em cobrança judicial e penhora de bens''.','2026-01-19',0,NULL,'documentada',NULL,'familia',NULL,'A reportagem não traz manifestação de Henrique, de Natália ou das empresas.',NULL,'origens','origens:EV[73]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam29','CVM aplica multas a Daniel, Henrique e Felipe Vorcaro e ao Master no caso do fundo Brazil Realty (decisão administrativa, 08/09/2026)','Em 8/9/2026, o colegiado da CVM, com relatoria do diretor João Accioly, condenou por unanimidade, segundo o Poder360, entre outros, Daniel (multa de R$ 20 milhões), Henrique (R$ 20 milhões), o Banco Master (R$ 12,5 milhões) e Felipe Vorcaro (R$ 5 milhões), por, segundo a CVM, incorporar ao fundo Brazil Realty ativos imobiliários por valores artificialmente elevados e simular liquidez das cotas no mercado secundário; a investigação começou em 2020. O Poder360 informa total de multas de R$ 201,5 milhões e cinco absolvidos; o Times Brasil fala em 19 acusados, 3 absolvidos, e não informa os valores das multas de Henrique e Felipe. É decisão administrativa da CVM, da qual os condenados podem recorrer ao CRSFN.','2026-09-08',0,NULL,'documentada',NULL,'familia',NULL,'A defesa de Daniel nega participação em fraude ou relação com os laudos considerados irregulares e contesta os cálculos da CVM; a advogada questionou a falta de provas individualizadas de dolo. Felipe nega participação nas negociações das cotas e diz que o processo não individualizou sua conduta. As defesas pediram prescrição.',NULL,'origens','origens:EV[87]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam3','Estado de Minas: obra de hotel de luxo no Bulevar Arrudas, com a Multipar','O Estado de Minas noticiou em 20/10/2011 a retomada de um prédio inacabado de 27 andares no Bulevar Arrudas, no Centro de BH, para o hotel Royal Tulip, com 405 apartamentos e investimento de R$ 200 milhões, entrega prevista para dezembro de 2012. A construtora era a M.Roscoe, a operadora a Brazil Hospitality Group e os incorporadores RFM, Pacific Realty e Blackwood; o jornal chama Daniel de diretor-executivo da Multipar e idealizador do projeto, e Henrique de presidente da Multipar. O texto não detalha a participação societária de cada um.','2011-10-20',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[13]|origens:EV[13]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam4','Daniel é negativado no Serasa por dívida com escritório de advocacia','O Alma Preta (15/06/2026) relata que o grupo de empresas da família contratou em 2010 o escritório Guimarães & Vieira de Mello Advogados (GVM) por R$ 800 mil; após dois acordos judiciais e uma renegociação em três parcelas, da qual Daniel pagou só a primeira (R$ 500 mil, em nov/2014), a dívida chegou a R$ 1,05 milhão e, segundo a reportagem, Daniel ficou em 2014 com o nome sujo no Serasa. A Justiça mineira reteve R$ 72 mil e, em primeira e segunda instâncias, não anulou o acordo pedido pela família. A reportagem associa o nome sujo à dificuldade de criar um fundo imobiliário para concluir a obra e informa que a Cesto Participações emitiu em março de 2013 seis CCIs, no total de R$ 103 milhões; a documentação consultada não informa o desfecho da disputa.','2014',0,NULL,'reportada',3,'familia',NULL,'A família alegou serviço mal executado, aproveitamento da fragilidade financeira das empresas e vício de coação, e afirma que os advogados agiram de má-fé. O GVM não respondeu à reportagem e a assessoria de Daniel não se manifestou; o desfecho não é informado.',NULL,'origens','teia:EV[17]|origens:EV[16]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam6','Daniel entra no Máxima com 20% como participação qualificada','Segundo reportagem do Let''s Money que reproduz apuração do Valor, uma tabela do documento do BC indica que em agosto de 2017 o diretor Sidnei Corrêa Marques decidiu monocraticamente sobre a entrada de Daniel no Máxima com 20% do capital, em participação qualificada. A informação consta da tabela da reportagem, não do texto corrido. A data difere do ''minoritário em 2016'' citado por outros veículos.','2017-08',0,NULL,'reportada',3,'familia',NULL,NULL,NULL,'origens','teia:EV[22]|origens:EV[23]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('fam8','Minutas de 2016-2017 previam sociedade de Henrique no Máxima, diz O Fator','O Fator (25/09/2026) diz ter confirmado, com fontes ligadas às investigações, minutas sem assinatura elaboradas entre nov/2016 e dez/2017, período em que se negociava a compra do Máxima. Uma minuta de nov/2017 diz que Henrique ''passaria a deter participação, direta ou indireta, de 50%'' no banco, percentual que a reportagem explica referir-se à metade das ações de Daniel; na versão de dezembro, Daniel aparece com 93% e Henrique com 46,5%. Henrique teria poder de veto sobre as principais decisões e os dividendos de Daniel seriam divididos meio a meio; os recursos viriam da Multipar, e uma minuta de dezembro de 2017 relata um contrato de julho de 2015 para compra de ações via Fundo Esmeralda. São versões de trabalho sem assinatura.','2017-11',0,NULL,'reportada',3,'familia',NULL,'A defesa de Henrique diz que as minutas ''não são documentos'' e registram conversas que ''nunca chegaram perto de se concretizar'', e que ele ''jamais foi acionista, conselheiro, e muitíssimo menos, gestor ou administrador'' do banco. Em carta ao ministro André Mendonça (STF), Henrique escreveu que o filho ''não tratava nada de banco'' com ele.',NULL,'origens','teia:EV[25]|origens:EV[25]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida0','Fundação da Igreja Batista da Lagoinha, em Belo Horizonte','A Lagoinha nasceu em 1957 como congregação batista tradicional no bairro de mesmo nome, em Belo Horizonte, fundada por José Rego, segundo a Wikipedia (que cita o portal Gospel Mais). Gazeta do Povo e The Intercept Brasil também situam a origem da igreja em 1957.','1957-12-20',0,NULL,'documentada',4,'ida',NULL,NULL,NULL,'origens','teia:EV[0]|origens:EV[0]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida1','Márcio Valadão assume a Lagoinha e muda o perfil da igreja','Márcio Valadão tornou-se pastor sênior em 1972 (a Wikipedia indica 31/07/1972, com cerca de 300 membros) e introduziu elementos carismáticos, com a música no centro dos cultos, segundo a Gazeta do Povo. Em dezembro de 2022 ele anunciou, em culto, que deixava a liderança após cinco décadas, conforme o Correio Braziliense.','1972-07-31',0,NULL,'documentada',4,'ida',NULL,NULL,NULL,'origens','teia:EV[2]|origens:EV[2]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida10','Clava Forte Bank, fintech de André e Cassiane Valadão','A Agência Pública (02/12/2025) informa que o Clava Forte Bank foi fundado em março de 2024 e presidido por André Valadão e Cassiane Valadão; a divulgação pública ocorreu em abril de 2025 (Jornal Opção, que o descreve como banco digital lançado pela Igreja Batista da Lagoinha, e Brasil 247, que cita capital de cerca de R$ 100 mil e gestão pelo casal). O Banco Central diz que a empresa nunca esteve autorizada a funcionar como instituição financeira; ela operava com a infraestrutura da CDC SCD (Banco 470) e da Dock. Em outubro de 2025 Cassiane deixou a direção, o site saiu do ar a partir de 21/11/2025 e a Gazeta do Povo registra a suspensão do CNPJ em janeiro de 2026. As fontes não citam sócios da família Vorcaro; o deputado Rogério Correia levantou a hipótese de ligação com o Master, que a Pública chama de ''campo da suposição''.','2024-03',0,NULL,'documentada',4,'ida',NULL,'André Valadão disse que o vínculo do Clava com o Master é ''menos um, não é zero, não, nem existe'' e que foi ''simplesmente um sistema de pagamento'', encerrado pelo alto índice de hackeamento bancário (Mais Goiás, reproduzindo a Folha); em 21/01/2026 disse que era ferramenta interna de pagamentos da Lagoinha Global, encerrada por segurança digital, e que ''não há uma vírgula de vínculo'' com o Master (Portal de Prefeitura). O Clava Forte afirmou, em nota, operar como correspondente bancário no modelo BaaS, o que considera legal (Brasil 247), e chamou a queda do site de ''manutenção programada'' (Agência Pública).',NULL,'origens','teia:EV[58]|origens:EV[54]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida11','Lagoinha Belvedere: CNPJ aberto em setembro de 2024 e templo de alto padrão presidido por Zettel','O CNPJ da Lagoinha Belvedere, em Belo Horizonte, foi aberto em setembro de 2024, com Fabiano Zettel como presidente (Jornal de Brasília). A Gazeta do Povo diz que a unidade foi inaugurada em setembro de 2024, com 14,4 mil m2 e capacidade para mais de 2 mil pessoas, voltada a público de alta renda, e que o aluguel mensal seria de cerca de R$ 420 mil. O Jornal de Brasília diz que o templo foi inaugurado ''com pompa'' em 2025, e O Globo (via Brasil 247) fala em cerca de 16 mil m2, numa antiga concessionária, com cerimônia de inauguração em abril de 2025. Zettel veio da Bola de Neve em 2024 (Folha, via Mais Goiás). Não identifiquei o proprietário do imóvel.','2024-09',0,NULL,'reportada',3,'ida',NULL,'A Lagoinha diz que Zettel passou a integrar a igreja como pastor voluntário há menos de dois anos, com atuação restrita à unidade do Belvedere, e que cada igreja local tem liderança própria, responsável pelas decisões administrativas e jurídicas do templo (Mais Goiás; Jornal de Brasília/Folhapress).',NULL,'origens','teia:EV[63]|origens:EV[57]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida12','Coaf: Zettel enviou R$ 19,2 mi à conta da Lagoinha Belvedere','O RIF 140515 do Coaf, tornado público em 10-14/09/2026 após decisão do ministro André Mendonça, registra que entre 24/12/2024 e 08/12/2025 Fabiano Zettel fez 26 operações que somam R$ 19,205 milhões para a conta da Lagoinha Belvedere, mais de dois terços dos créditos analisados. O relatório não identifica a origem do dinheiro; o Coaf classificou a movimentação como atípica, o que não prova crime, e a reportagem observa que a suspeita de uso da conta como ''conta de passagem'' ainda não está comprovada. Antes disso, a Folha havia reportado 54 transferências, cerca de R$ 40,9-41 milhões, de Zettel ao templo entre outubro de 2024 e janeiro de 2026; o número difere do RIF e não foi reconciliado.','2024-12-24',0,NULL,'investigacao',3,'ida',NULL,'A Lagoinha Global disse ter sido informada de que os recursos seriam para reformas, ''e não doações, dízimos ou ofertas'', e que não conhecia os montantes (Itatiaia, ICL). Segundo a igreja, cada unidade tem autonomia e Zettel presidia a Belvedere. A defesa de Zettel disse que não comentará.',19205000.0,'origens','teia:EV[67]|origens:EV[61]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida13','Coaf: Henrique Vorcaro fez R$ 120 mil em aportes à Lagoinha Belvedere','O mesmo RIF do Coaf (24/12/2024 a 08/12/2025) lista Henrique Moura Vorcaro, pai de Daniel, com R$ 120 mil na conta da Lagoinha Belvedere: quatro operações segundo Itatiaia, ICL e Bahia Notícias, três segundo o Brasil 247 (15/09/2026). Equivale a menos de 1% dos R$ 28,5 milhões de créditos da conta. O Brasil 247 acrescenta que a HV Empreendimentos e Participações, ''administrada por Henrique Vorcaro'', enviou R$ 700 mil em três transações (ver item seguinte); o ICL cita a empresa sem dizer quem a administra. Doar a uma igreja é lícito, e o Coaf registra movimentação, sem concluir crime.','2024-12-24',0,NULL,'investigacao',3,'ida',NULL,'Itatiaia e ICL não trazem manifestação de Henrique Vorcaro. A Lagoinha Global diz não ter participado da captação dos recursos nem conhecer os montantes. A defesa dele, em outro assunto (prisão de maio de 2026), nega irregularidades e a titularidade da conta de R$ 2,2 bilhões (Mais Goiás; Diário do Comércio).',120000.0,'origens','teia:EV[68]|origens:EV[62]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida14','Coaf: ex-mulher de Daniel e duas empresas também aparecem entre os remetentes da conta','Segundo o Brasil 247 e o Bahia Notícias, A ex-mulher de Daniel fez sete operações que somam cerca de R$ 101,6 mil. O ICL (25/09/2026, citando o Banco do Brasil/RIF) e o Brasil 247 (15/09/2026) listam ainda a HV Empreendimentos e Participações (R$ 700 mil) e a Lagoinha Participações Ltda. (R$ 1 milhão no Brasil 247, R$ 1,1 milhão no ICL). Só o Brasil 247 diz quem as administra: a HV seria ''administrada por Henrique Vorcaro'' e a Lagoinha Participações (hoje Ingleses Holding) é gerida pelo advogado Thiago Assumpção Henriques, descrito como representante de negócios da família; o ICL não identifica os donos, e nenhuma fonte liga a Lagoinha Participações à igreja (o nome é coincidente). O Brasil 247 fala em pelo menos R$ 2,02 milhões vindos de familiares, soma que não bate com os valores listados (cerca de R$ 1,92 milhão). O relatório não conclui crime.','2024-12-24',0,NULL,'investigacao',3,'ida',NULL,'Sem manifestação da ex-mulher de Daniel nem das empresas nas fontes abertas. A Lagoinha Global diz não ter conhecimento dos valores movimentados pelo ex-pastor e que cada unidade administra suas finanças (Diário do Comércio).',101600.0,'origens','teia:EV[69]|origens:EV[63]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida15','Coaf e Banco do Brasil apontam movimentação atípica de R$ 57,1 mi (créditos e débitos) na conta da Belvedere','O Banco do Brasil comunicou ao Coaf movimentação de R$ 57,1 milhões na conta da Lagoinha Belvedere (R$ 28,49 mi em créditos e R$ 28,62 mi em débitos) entre 24/12/2024 e 08/12/2025, contra faturamento anual presumido de R$ 950 mil, com Zettel como procurador da conta; o banco citou a ''relação financeira íntima'' do procurador com possíveis ilicitudes (ICL). O Coaf classificou a movimentação como atípica e diz que ela pode configurar ''artifício para burla da identificação da origem, do destino, dos responsáveis ou dos destinatários finais''. Segundo Itatiaia e Diário do Comércio (Folhapress), cerca de R$ 4,9 milhões foram para construtoras e incorporadoras; o ICL lista quatro destinatários (Jorlan, R$ 2,56 mi; Muzzi Misk, R$ 2,30 mi; AFEB, pouco mais de R$ 1 mi; FDS, R$ 780 mil), soma maior que não foi reconciliada, e diz que o relatório não afirma irregularidade dessas empresas. O Diário do Comércio diz que PF e Coaf suspeitam do uso da conta como ''conta de passagem'' por Zettel; o termo não aparece em outras matérias, o Itatiaia diz que a suspeita não está comprovada e o Coaf ressalva que a comunicação não significa, por si só, prática criminosa. O total soma créditos e débitos e não é dinheiro enviado pela família.','2025-12-08',0,NULL,'investigacao',3,'ida',NULL,'A Lagoinha Global diz que não participou da captação, administração ou movimentação, que não recebeu parte dos valores, que repudia práticas ilícitas e apoia a apuração. A defesa de Zettel não comentou.',57110313.0,'origens','teia:EV[99]|origens:EV[69]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida16','Mensagens reportadas: Zettel teria cobrado Vorcaro por recursos para a obra do Belvedere','O Brasil 247 (15/09/2026), única fonte aberta deste item, com base em documentos enviados ao STF cujo sigilo foi retirado, relata que Zettel pediu a Daniel Vorcaro recursos para o templo. Em julho de 2025 teria escrito ''Igreja tem um mês que não faz. Odeio cobrar, mas obra vai parar''; em agosto teria enviado planilha de pagamentos pendentes com uma rubrica de R$ 2 milhões para a ''Lagoinha Belvedere''. A matéria não confirma que a rubrica foi paga nem esclarece de quem era o dinheiro cobrado. A PF apura se Zettel usou empresas (Super Empreendimentos, Moriah Asset) para disfarçar a origem de recursos; não há conclusão judicial.','2025-07',0,NULL,'reportada',3,'ida',NULL,'André Valadão afirmou que a gestão financeira era responsabilidade exclusiva de Zettel, que cada templo tem autonomia jurídica e administrativa e que sabia apenas de reformas, sem conhecer os valores; disse que a instituição ''não compactua com ilegalidade'' e não quer impedir o esclarecimento dos fatos. Não há resposta de Zettel nem de Daniel Vorcaro na fonte.',NULL,'origens','teia:EV[78]|origens:EV[66]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida17','Valadão chama Henrique e Aline Vorcaro de ''amigos da minha vida''','Segundo O Globo (via Brasil 247, 30/03/2026), em culto de inauguração de templo da Lagoinha em Belo Horizonte, que a matéria data de abril de 2025 (a data diverge da abertura do Belvedere em setembro de 2024 relatada por outras fontes), André Valadão pediu que Henrique e Aline Vorcaro ficassem em pé, chamou-os de ''amigos da minha vida'' e disse que são amigos ''desde as minhas solteirices'', de décadas. Chamou Zettel de ''pastor dessa casa'' e falou em mais de 20 anos de relacionamento com ele. Em outro culto, em agosto de 2024, disse conhecer Natália e Daniel ''desde criancinha'' (Brasil 247). Amizade e pastorado são fatos lícitos; nenhuma autoridade aponta ato de favorecimento nessa convivência.','2025-04',0,NULL,'reportada',3,'ida',NULL,'Depois do avanço do caso, Valadão disse estar ''profundamente decepcionado'' e ter se afastado da família, e negou irregularidades. A Lagoinha diz, em nota, que hoje não há vínculo entre Valadão, a igreja e a família Vorcaro e que a relação sempre foi de amizade pessoal (Brasil 247).',NULL,'origens','teia:EV[74]|origens:EV[65]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida18','Lagoinha diz ter afastado Zettel do pastoreio; prisões e nota de janeiro','Segundo a Lagoinha, Zettel foi afastado do pastoreio em novembro de 2025, assim que surgiram as primeiras informações públicas, e desde então não tem função na igreja. Ele foi preso em 14/01/2026 no aeroporto de Guarulhos (Compliance Zero, 2a fase) e solto horas depois por decisão de Dias Toffoli (Poder360); em 15/01 a igreja negou ligação com a Compliance Zero e com a CPMI do INSS. Zettel foi preso de novo em 04/03/2026, e o CNPJ da Belvedere seguiu ativo com ele como presidente, segundo Jornal de Brasília e ICL Notícias.','2025-11',0,NULL,'documentada',4,'ida',NULL,'Nota da Lagoinha (via Portal Tela, 16/01/2026): ''não há indícios de uso da igreja em esquemas de fraude envolvendo INSS ou Banco Master''; a presença de fiéis em cultos não cria vínculo jurídico com a instituição. A defesa de Zettel disse que ele está à disposição das autoridades e que suas atividades são ''conhecidas e lícitas, sem relação alguma com a gestão do Banco Master'' (Metrópoles).',NULL,'origens','teia:EV[97]|origens:EV[67]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida19','Lagoinha Belvedere encerra atividades','A unidade do Belvedere encerrou os cultos em 15/03/2026, cerca de onze dias depois da nova prisão de Zettel (Gazeta do Povo; Jornal de Brasília). A assessoria da Lagoinha confirmou o fim das atividades sem explicar o motivo e remeteu perguntas a Natália Vorcaro, apontada como responsável pelo templo. Segundo o ICL, a unidade apagou as redes sociais nos dias seguintes.','2026-03-15',0,NULL,'documentada',4,'ida',NULL,'A Lagoinha não explicou o motivo do fechamento. Natália Vorcaro não respondeu ao Jornal de Brasília antes da publicação.',NULL,'origens','teia:EV[128]|origens:EV[79]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida2','Igreja assume a TV que vira Rede Super; Lagoinha tem rádio e TV próprias','Segundo a Wikipedia, a Rede de Televisão Comunitária, no ar desde 1997, foi vendida à Lagoinha em 2000 e passou a se chamar Rede Super; André Valadão é presidente da emissora desde 22/02/2010. A The Intercept Brasil descreve a Rede Super e a Rádio Super como propriedade da igreja, com transmissão em 13 estados. Em 2017 a emissora fez a campanha ''A Rede Super não pode parar'', para arrecadar R$ 3 milhões para digitalizar o sinal; a fonte não nomeia doadores.','2000',0,NULL,'documentada',4,'ida',NULL,NULL,NULL,'origens','teia:EV[6]|origens:EV[6]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida20','Valadão pede perdão por ter confiado em pessoas e nega vínculo','Em vídeo exibido nos templos em 22/03/2026 (Gazeta do Povo) e divulgado no Instagram, segundo o Portal de Prefeitura (matéria de 23/03), André Valadão disse que seu coração ''dói, e dói muito'', pediu perdão ''por ter confiado em pessoas'' e por ter ''aberto o coração para algumas pessoas'', e disse que ''não há vínculo meu, não há vínculo da igreja nesse escândalo''. Em 27/01/2026 já havia negado ter feito negócios com Vorcaro, dizendo conhecê-lo apenas no contexto da igreja, onde ele foi ''membro por muitos anos'' (Portal Tela). Em 03-04/09/2026 disse conhecer Vorcaro havia mais de 30 anos e negou envolvimento com o Master (Diário de Pernambuco; Bahia Notícias).','2026-03-22',0,NULL,'documentada',4,'ida',NULL,'É a própria versão de Valadão. O vídeo não cita Vorcaro nominalmente nos trechos reproduzidos. Segundo a Gazeta do Povo, ele afirmou haver um movimento organizado para ''destruir a imagem da liderança cristã'' neste ano eleitoral.',NULL,'origens','teia:EV[131]|origens:EV[81]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida21','PF prende Henrique Vorcaro na 6a fase da Compliance Zero','Henrique Moura Vorcaro foi preso em 14/05/2026, na 6a fase da Compliance Zero, em decisão do ministro André Mendonça que o chama de ''demandante, beneficiário e operador financeiro'' do núcleo ''A Turma'', suspeito de intimidação, vigilância clandestina e invasão de dispositivos; a PF cita uma conta atribuída a ele, na CBSF DTVM (Reag), com saldo acima de R$ 2,2 bilhões. Ele é fundador e, segundo suas redes sociais, diretor-presidente do Grupo Multipar (imobiliário, com atuação também em construção civil). A Gazeta liga o nome dele à Lagoinha pela relação familiar com Zettel, e as fontes abertas não ligam essas apurações ao dinheiro enviado à igreja.','2026-05-14',0,NULL,'investigacao',NULL,'ida',NULL,'O advogado Eugênio Pacelli diz que a decisão se baseia em fatos cuja comprovação de licitude e lastro de racionalidade econômica ainda não estão no processo, que a defesa provará a legalidade das transações e nega que ele seja titular da conta de R$ 2,2 bilhões. Em petição noticiada pelo Correio da Manhã (19/06/2026), a defesa, sem nomear advogados, afirma que os recursos investigados tinham origem em relações comerciais legítimas ligadas a um projeto habitacional (Projeto Campo Grande, RJ).',NULL,'origens','origens:EV[84]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida3','Henrique Vorcaro teria sido um dos principais financiadores da Rede Super','A Gazeta do Povo (27/03/2026) escreve que, em 2000, Henrique Vorcaro, pai de Daniel, foi ''um dos principais financiadores da Rede Super'', emissora ligada à Lagoinha. A Agência Pública (02/12/2025), citando reportagem da revista piauí que não foi possível abrir, diz que a emissora só foi viabilizada por doações dele e que ele teria ajudado a quitar prestações de um BMW que Valadão comprara antes de liderar a Lagoinha Global; o Mais Goiás, reproduzindo a Folha (13/03/2026), diz que ele ''ajudou a quitar'' a dívida do carro. A CartaCapital diz apenas que a família Vorcaro apoiou financeiramente a Rede Super. Nenhuma fonte aberta traz valores, datas precisas ou documentos desses aportes. Doar a uma igreja ou ajudar um amigo é conduta lícita, e as fontes não apontam irregularidade nesses aportes.','2000',0,NULL,'reportada',3,'ida',NULL,'A assessoria da Lagoinha diz que Valadão se refere a ''um episódio pessoal ocorrido há cerca de 25 anos envolvendo a aquisição de uma BMW'', uma compra que ele fez na época, e que não houve ''qualquer tipo de presente ou benefício'' (nota reproduzida pelo Mais Goiás, que republica a Folha). A Lagoinha Global afirma não ter vínculo institucional com o Master e diz que Daniel Vorcaro e seus parentes ''participaram da vida da igreja em diferentes momentos''. Não localizei manifestação de Henrique Vorcaro sobre o financiamento da Rede Super.',NULL,'origens','teia:EV[7]|origens:EV[7]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida4','Henrique Vorcaro é descrito como convertido que financiou projetos da igreja','A Folha de S.Paulo, reproduzida pelo Mais Goiás (13/03/2026), descreve Henrique Vorcaro como o primeiro da família a se associar à Lagoinha, convertido ao meio evangélico, que financiou projetos da igreja. O Mais Goiás (14/05/2026) repete que ele ''teria financiado projetos religiosos'' e manteria proximidade com lideranças como André Valadão. A Bloomberg Linea diz que o avô de Daniel, imigrante italiano, tornou-se pastor (sem citar o nome; Serafim Vorcaro vem da Wikipedia, citando a piauí). As matérias não identificam quais projetos, nem valores ou datas, e a data do evento é uma aproximação. Financiar projetos de uma igreja é conduta lícita, e as fontes não apontam irregularidade nela.','2000',0,NULL,'reportada',3,'ida',NULL,'A Lagoinha diz que sua relação com Vorcaro é ''de natureza religiosa, não empresarial'' (CartaCapital, que não cita comunicado formal) e que as relações entre Valadão e a família são pessoais, entre famílias que convivem há décadas, sem vínculo institucional (nota de 10/03/2026, via Mais Goiás). Não localizei manifestação de Henrique Vorcaro sobre o financiamento de projetos da igreja; no contexto da prisão de maio de 2026, sua defesa nega irregularidades e a titularidade de conta de R$ 2,2 bilhões.',NULL,'origens','teia:EV[8]|origens:EV[8]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida5','Daniel Vorcaro apresenta programa gospel na Rede Super','Daniel Vorcaro apresentou, por volta de 2008-2009, um programa de música gospel na Rede Super (a Wikipedia, que cita a piauí, fala em ''Supersônica''). A Agência Pública, a Gazeta do Povo e o Mais Goiás (Folha) confirmam que ele apresentou programa na emissora. Não há valor envolvido.','2008',0,NULL,'reportada',3,'ida',NULL,NULL,NULL,'origens','teia:EV[10]|origens:EV[10]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida6','André Valadão celebra casamento de Fabiano Zettel e Natália Vorcaro','Em 2018 o advogado e empresário Fabiano Zettel casou-se com Natália Vorcaro, irmã de Daniel. Segundo a Gazeta do Povo e O Globo (lido via Brasil 247, que traz o ano), a cerimônia foi celebrada por André Valadão, e Daniel acompanhou da primeira fila. A CartaCapital descreve Natália como pastora da Lagoinha; o Jornal de Brasília a aponta como responsável pelo templo do Belvedere em março de 2026. Casamento celebrado por pastor amigo da família é fato lícito; as fontes não o ligam a conduta investigada.','2018',0,NULL,'reportada',3,'ida',NULL,'A Lagoinha diz que relações pessoais entre famílias que convivem há décadas em Belo Horizonte ''não configuram, por si só, qualquer irregularidade'' (nota de 10/03/2026, via Mais Goiás).',NULL,'origens','teia:EV[31]|origens:EV[27]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida7','Nikolas Ferreira e o pastor Guilherme Batista voam em jato ligado a Vorcaro; Lagoinha diz que o pastor não é membro','O Globo (coluna de Malu Gaspar) reportou, e o Estadão repercutiu em 03/03/2026, que o deputado Nikolas Ferreira e o pastor Guilherme Batista, descrito pelas matérias como pastor da Lagoinha, usaram entre 20 e 28/10/2022 um Phenom 300 na caravana ''Juventude pelo Brasil'', de apoio a Bolsonaro no segundo turno. Segundo O Globo, no papel o avião era da Prime You, que em 2022 administrava o jatinho e outros bens de Daniel Vorcaro; a Revista Oeste acrescenta que Vorcaro era sócio da empresa. As matérias não dizem quem pagou os voos. O uso foi político: não há repasse à igreja e Valadão não aparece como passageiro.','2022-10-20',0,NULL,'reportada',3,'ida',NULL,'A defesa de Vorcaro disse ao Estadão que o avião não pertence ao banqueiro. Nikolas confirmou o uso, disse que foi a convite do pastor Guilherme Batista para a agenda de campanha e que não sabia quem era o dono nem quem financiou. O gabinete de Batista disse que ele estava em retiro e não comentou. A nota da Lagoinha (10/03/2026, via Mais Goiás) diz que nem o pastor citado na reportagem nem o deputado são membros da igreja, que a viagem foi feita ''por terceiros em aeronave pertencente ao empresário citado'', que não foi agenda da igreja nem envolveu representantes da denominação e que a alegação de relação com a instituição é falsa.',NULL,'origens','teia:EV[54]|origens:EV[52]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida8','Márcio deixa a liderança; André Valadão assume a Lagoinha Global','Em 11/12/2022, Márcio Valadão anunciou em culto que deixava o pastorado da igreja de Belo Horizonte, que o Correio Braziliense descreve com mais de 600 unidades; o pastor Flavinho Marques assumiu essa congregação. Após a crise interna de fim de 2022, a Lagoinha Global, que governa as filiais, passou à liderança de André Valadão (The Intercept Brasil; a Wikipedia cita o Pleno News para dezembro de 2022). A Gazeta do Povo registra que a banda Diante do Trono, de Ana Paula Valadão, saiu da Lagoinha anos antes.','2022-12-11',0,NULL,'documentada',4,'ida',NULL,NULL,NULL,'origens','teia:EV[55]|origens:EV[53]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('ida9','Coaf: R$ 3,9 mi do Banco Master a produtora de André Valadão (negado)','O SBT News e o ICL Notícias (13/03/2026) relatam relatório do Coaf, não divulgado na íntegra, que aponta repasses de R$ 3,897 milhões do Banco Master à Amando Vidas Produtora e Gravadora Ltda., registrada na Receita em nome de André Valadão e da esposa, entre março e abril de 2022. O SBT descreve a operação como imobiliária, ligada a um imóvel em Sete Lagoas (MG); o ICL a chama de movimentação atípica e ressalva que isso não indica automaticamente crime. Segundo o SBT, as relações financeiras entre Valadão e Daniel Vorcaro ''ainda não foram esclarecidas''. As matérias não estabelecem que o valor foi recebido nem que foi ilícito. O dinheiro partiu do banco, não de familiares, e a empresa é do casal, não a igreja.','2022-03',0,NULL,'reportada',3,'ida',NULL,'A defesa de Valadão disse desconhecer a operação e negou o recebimento dos valores. A Amando Vidas ''nega veementemente qualquer vínculo ou participação'', diz que seus extratos não registram entradas compatíveis com o valor e que tem apenas uma conta bancária (SBT News; ICL).',3897000.0,'origens','teia:EV[53]|origens:EV[51]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max0','Origem como corretora Máxima (anos 1970; 1974 em parte das fontes)','O InfoMoney diz que o banco foi criado como a corretora Máxima na década de 1970 e virou banco na década de 1990; o Guia do Investidor diz apenas que foi fundado na década de 1970; o BP Money (2021) e o Correio da Manhã (2026) citam 1974, este último como ano de fundação da Máxima Corretora de Títulos e Valores Mobiliários. A Wikipedia em inglês (fonte secundária) traz duas datas, 1974 para a corretora e 1970 para o ''Banco Máxima'', sem fonte primária. Nenhuma fonte aberta nomeia os fundadores nem nomes anteriores.','1970',1,'década de 1970','reportada',3,'banco',NULL,NULL,NULL,'origens','teia:EV[1]|origens:EV[1]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max1','A corretora se torna banco (anos 1990, sem ato datado)','InfoMoney e BP Money afirmam que a instituição virou banco na década de 1990. O Correio da Manhã (2026) diz que recebeu autorização do Banco Central para operar como banco múltiplo nessa década e que atuava em crédito imobiliário; a Wikipedia em inglês fala em 1990. Nenhuma fonte aberta traz a carta-patente, o ato do BC ou a data exata.','1990',1,'década de 1990','reportada',3,'banco',NULL,NULL,NULL,'origens','teia:EV[4]|origens:EV[4]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max10','Sabbá oferece a Vorcaro participação no controle do banco (2016)','Reportagens (Mais Goiás, BP Money) dizem que em 2016 Saul Sabbá, então à frente do Máxima, ofereceu a Daniel Vorcaro uma participação no controle administrativo e que ele entrou como sócio minoritário; os dois já atuavam juntos em fundos imobiliários. O Fator e o Valor (via Brasil 247) situam a negociação entre fim de 2016 e 2017. Registro apenas como marco de entrada do grupo seguinte.','2016',0,NULL,'reportada',3,'banco',NULL,NULL,NULL,'origens','teia:EV[21]|origens:EV[21]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max11','Contrato de compra e venda do controle entre Sabbá e Vorcaro (15/09/2017)','O Comunicado BCB 31.344 registra que em 15/09/2017 foi assinado o Contrato de Compra e Venda e Outras Avenças entre Saul Dutra Sabbá (vendedor) e Daniel Bueno Vorcaro, com Alberto Maurício Caló e o Banco Máxima como intervenientes; a operação dependia de aprovação do BC. Segundo o Valor (via Jornal de Brasília e Brasil 247), o negócio previa 56,87% do capital por R$ 40 milhões, pagos em R$ 36 milhões em cotas do fundo Brazil Realty e R$ 4 milhões em dinheiro. O BC só aprovou a transferência de controle em 14/10/2019.','2017-09-15',0,NULL,'documentada',4,'banco',NULL,'Sabbá não respondeu aos pedidos de comentário do Valor (reportagem de jan/2026); a defesa de Vorcaro, procurada pelo Jornal de Brasília, não se manifestou.',NULL,'origens','teia:EV[23]|origens:EV[24]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max12','BC publica declaração de propósito; sede do banco era em Copacabana (RJ)','O Comunicado BCB 31.344, de 01/11/2017 (DEORF, processo 1701632678), divulga a declaração de propósito de 06/10/2017 para adquirir o controle do Banco Máxima S/A, com sede na Av. Atlântica 1.130, Copacabana, Rio de Janeiro. Vorcaro declara pretender ficar com 91,87% da participação societária, número diferente do 56,87% do contrato relatado pelo Valor; a divergência não é explicada nas fontes abertas. Objeções podiam ser enviadas ao BC em 30 dias.','2017-11-01',0,NULL,'documentada',4,'banco',NULL,NULL,NULL,'origens','teia:EV[24]|origens:EV[26]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max13','Sabbá diz ter se desligado formalmente da gestão em 2017','Segundo o Valor (via Let''s Money), Saul Sabbá, que controlava o Máxima, disse ter se desligado formalmente da gestão em 2017. Registro apenas a versão relatada; não há ato societário aberto que a confirme.','2017',0,NULL,'reportada',3,'banco',NULL,'Versão do próprio Sabbá, relatada pelo Valor/Let''s Money.',NULL,'origens','teia:EV[26]|origens:EV[22]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max14','Nova diretoria assume em janeiro de 2018 (versão do banco)','A InvestNews (02/08/2021) diz que uma nova diretoria assumiu em janeiro de 2018 e que o crédito imobiliário foi o foco em 2016-2017. Em 2021 o banco afirmou que seus atuais acionistas assumiram a administração em 2018 ''após aprovação do Banco Central''. A aprovação do BC à transferência de controle, porém, é de 14/10/2019 segundo o Valor e o Brasil 247; a diferença de datas não é explicada.','2018-01',0,NULL,'reportada',3,'banco',NULL,'Versão do Banco Máxima/Master em 2021: acionistas atuais assumiram em 2018; ex-gestores sem vínculo.',NULL,'origens','teia:EV[27]|origens:EV[28]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max15','BC multa o banco e inabilita Sabbá (9 anos) e Caló (8 anos)','Pela Decisão 946/2018 do Copat (processo 110550), assinada em 27/07/2018, aprovada por unanimidade na sessão de 19/07/2018 e resumida no Diário Eletrônico de 03/08/2018, o BC concluiu, segundo o texto, que o Banco Máxima foi conduzido em desacordo com a regulação e as boas práticas bancárias: teria simulado a valorização de investimento em empresa controlada para reduzir prejuízo contábil, assumido riscos incompatíveis com sua estrutura de capital e prestado informações incorretas ao BC, de forma intencional e sistemática, para dissimular grave insuficiência de capital. Aplicou multa de R$ 100 mil ao Banco Máxima, inabilitação de 9 anos a Saul Dutra Sabbá e de 8 anos a Alberto Maurício Caló. É decisão administrativa do BC; houve recurso ao CRSFN (evento de 17/11/2020).','2018-07-27',0,NULL,'documentada',4,'banco',NULL,'O banco atual disse em 2021 que as punições do BC se restringem aos antigos administradores; a decisão de 2018, porém, registra multa de R$ 100 mil ao Banco Máxima S.A. Os punidos recorreram ao CRSFN (evento de 17/11/2020), cujo resultado não consta das fontes. As fontes não trazem defesa individual de Sabbá e Caló.',NULL,'origens','teia:EV[30]|origens:EV[31]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max16','BC rejeita a compra do controle por Vorcaro (voto 20/2019, 13/02/2019)','O voto BCB 20/2019, do diretor Sidnei Corrêa Marques, tornado público pelo BC (liberado após pedidos pela Lei de Acesso à Informação, com trechos tarjados), indeferiu a transferência de controle por falta de comprovação da origem dos recursos e da capacidade econômico-financeira dos adquirentes. Segundo o Let''s Money (reproduzindo o Valor) e o Brasil 247, o voto é de 13/02/2019; uma segunda matéria do Let''s Money traz 13/01/2019, e Jornal de Brasília e Times Brasil dizem apenas fevereiro. O voto aponta que parte relevante dos recursos teria vindo do próprio Máxima, em transferências entre banco, empresas de Vorcaro e fundos, e questiona laudos de imóveis. Marco da transição; a narrativa do banco antigo para aqui.','2019-02-13',0,NULL,'documentada',4,'banco','lado: barra','Vorcaro declinou comentar ao Valor (via Let''s Money). Segundo o voto, inquirido, ele não apresentou elementos que esclarecessem a origem dos recursos de forma clara e inequívoca. O pedido foi reapresentado em 02/05/2019 com novo grupo de controle.',NULL,'origens','teia:EV[34]|origens:EV[36]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max17','BC aprova a mudança de controle (voto 218/2019, 14/10/2019)','O voto BCB 218/2019, do diretor João Manoel Pinho de Mello, de 14/10/2019, já na gestão de Roberto Campos Neto no BC, aprovou a operação, segundo Let''s Money, Times Brasil e Brasil 247. Segundo o Let''s Money, o voto diz que ''a origem dos recursos foi regularmente demonstrada por todos os novos acionistas''; segundo o Times Brasil, Pinho de Mello registrou que o veto não considerara projeções de fluxo de caixa nem laudos de valor de mercado. Houve aportes de R$ 100 milhões entre março e junho de 2019 (R$ 70 mi de Vorcaro e R$ 30 mi dos demais sócios, segundo o Jornal de Brasília). O Valor/Let''s Money estima o rombo potencial do FGC em R$ 3,224 bilhões em 2019. Marco: a entrada do grupo de Daniel Vorcaro encerra a história do banco antigo.','2019-10-14',0,NULL,'documentada',4,'banco','lado: empurra','Vorcaro declinou comentar ao Valor (via Let''s Money).',NULL,'origens','teia:EV[37]|origens:EV[38]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max18','CVM: parecer de 21/10/2020 sobre debêntures da C.I.P. e da Simsan colocadas pela Máxima CCTVM (ofertas de 2019)','Parecer do Comitê de Termo de Compromisso da CVM (21/10/2020, PAS SEI 19957.009798/2019-01) trata de duas emissões de debêntures de R$ 35 milhões cada, da C.I.P. e da Simsan (ofertas iniciadas em 08/02/2019 e 28/03/2019), com a Máxima S.A. CCTVM como intermediária líder e gestora dos fundos compradores e a Índigo (controlada por Benjamim Botelho de Almeida) como agente fiduciário. Na acusação, a área técnica da CVM apontou conflito de interesses e operações estruturadas para transferir recursos a pessoas ligadas aos envolvidos (acusação, sem julgamento do mérito). O comitê recomendou rejeitar as propostas de termo de compromisso (R$ 1 milhão no total de Máxima, Daniel Vorcaro e Luiz Bull); o Colegiado as rejeitou em 03/11/2020 e, após pedido de vista, um diretor votou em 01/12/2020 por aceitar propostas que somavam R$ 2,325 milhões. A CNN Brasil reporta que os termos de compromisso resultaram em indenização superior a R$ 51 milhões a investidores e multas de cerca de R$ 2,3 milhões.','2019',0,'2019 a 2020','documentada',4,'banco',NULL,'Segundo a CNN Brasil, os termos de compromisso encerram processos sem julgamento do mérito; a defesa de Daniel Vorcaro diz que esses instrumentos ''não constituem condenação, nem implicam juízo de mérito sobre as condutas analisadas'', e a de Luiz Bull diz que não houve julgamento desfavorável nem admissão de culpa. A defesa de Benjamim Botelho de Almeida não foi localizada pela CNN.',NULL,'origens','teia:EV[32]|origens:EV[34]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max19','CRSFN pautado para julgar recurso do Banco Máxima, Sabbá e Caló','A pauta da 443ª sessão do CRSFN (17/11/2020) inclui o processo 10372.100378/2018-75 (BCB 110550, o da Decisão 946/2018), em que são recorrentes o Banco Máxima S.A., Alberto Maurício Caló e Saul Dutra Sabbá, relator Sérgio Cipriano dos Santos. A pauta não informa o resultado do julgamento.','2020-11-17',0,NULL,'documentada',4,'banco',NULL,NULL,NULL,'origens','teia:EV[42]|origens:EV[44]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max2','BC aprova diretor da Máxima S.A. CTVM; corretora e banco são CNPJs distintos','O Comunicado BCB 19.058, de 11/11/2009, informa que José Costa Gonçalves foi eleito para a diretoria da Máxima S.A. Corretora de Títulos e Valores Mobiliários (AGE de 1º/10/2009), com despacho de 10/11/2009. Em documentos posteriores do CRSFN a corretora aparece com CNPJ 33.886.862/0001-12, distinto do CNPJ do Banco Máxima (33.923.798/0001-00), e José Costa Gonçalves figura depois como recorrente ao lado de Saul Dutra Sabbá.','2009-11-11',0,NULL,'documentada',4,'banco',NULL,NULL,NULL,'origens','teia:EV[11]|origens:EV[11]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max20','CRSFN: pauta inclui segundo recurso, de Máxima CCTVM, Abdalla, Gonçalves e Sabbá','A mesma pauta lista o processo 10372.100309/2019-42 (matéria BCB 100673), com recorrentes Máxima S.A. Corretora de Câmbio, Títulos e Valores Mobiliários (CNPJ 33.886.862/0001-12), Cristiano Ferreira Abdalla, José Costa Gonçalves e Saul Dutra Sabbá, relator Álvaro Affonso Mendonça. A pauta não descreve a infração nem o resultado.','2020-11-17',0,NULL,'documentada',4,'banco',NULL,NULL,NULL,'origens','teia:EV[43]|origens:EV[45]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max21','Justiça Federal recebe denúncia do MPF e torna réus cinco acusados ligados ao Máxima (reportado em 24/07/2021)','Segundo Estadão/Seu Dinheiro e Diário do Grande ABC (24/07/2021), o juiz Nilson Martins Lopes Júnior, da 6ª Vara Criminal Federal de São Paulo, recebeu denúncia do MPF contra cinco pessoas, entre elas Saul Dutra, ex-diretor-presidente, Alberto Maurício Caló, ex-diretor jurídico, e Benjamim Botelho de Almeida, administrador dos fundos, apontado pelo MPF como articulador da triangulação; os outros dois denunciados não são nomeados. Os crimes imputados são gestão fraudulenta, informações falsas ao BC e dados inverídicos em demonstrativo financeiro, entre 2014 e 2016. O recebimento da denúncia (indícios mínimos de autoria e materialidade) não é condenação.','2021-07-24',0,NULL,'investigacao',3,'banco',NULL,'As reportagens não trazem manifestação dos acusados. O banco atual disse que não é parte da ação e que as punições do BC se restringem aos antigos administradores. Segundo o Jornal de Brasília (2026), a Justiça Federal absolveu depois outros ex-dirigentes, entre eles o ex-diretor jurídico e contábil, sem citar nomes.',NULL,'origens','teia:EV[48]|origens:EV[47]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max22','Máxima passa a se chamar Banco Master (reportagem de 02/08/2021)','A InvestNews (02/08/2021) relata a troca de marca para Banco Master, que Daniel Vorcaro descreveu como ''basicamente, mudança de razão social'': ''mesmo CNPJ, mesma equipe, mesmos processos''. Segundo o próprio Vorcaro, o banco tem ''quase 50 anos de história'' e a receita foi de cerca de R$ 180 milhões em 2018 e quase R$ 1 bilhão em 2020. Fim do recorte do banco antigo.','2021-08-02',0,NULL,'documentada',4,'banco',NULL,NULL,NULL,'origens','teia:EV[50]|origens:EV[48]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max23','CRSFN pauta recurso de Sabbá e das empresas Máxima em processo da CVM','A pauta da 486ª sessão do CRSFN (sessão em 10/09/2024; pauta publicada em 26/08/2024) traz o processo 10372.100068/2023-18 (recurso, com a CVM como recorrida), relatora Maria Cecilia Rossi, com recorrentes Máxima Patrimonial Ltda. (nova denominação de Máxima Asset Management Ltda.), Master S/A CCTVM (nova denominação de Máxima S.A. CCTVM), César Siqueira Trotte e Saul Dutra Sabbá. A pauta não descreve a infração nem o resultado.','2024-09-10',0,NULL,'documentada',NULL,'banco',NULL,NULL,NULL,'origens','origens:EV[58]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max24','STJ limita a ação penal à gestão fraudulenta (RHC 188.922)','A 5ª Turma do STJ, seguindo o ministro Reynaldo Soares da Fonseca, reconheceu excesso acusatório em recurso de um ex-diretor jurídico do Máxima e, por maioria, limitou a ação penal ao crime de gestão fraudulenta (art. 4º da Lei 7.492/86), o que abriu espaço para um eventual ANPP (Migalhas, 07/10/2024). O Jornal de Brasília situa a decisão em 2025.','2024-10-07',0,NULL,'documentada',NULL,'banco',NULL,NULL,NULL,'origens','origens:EV[60]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max25','Imprensa: Justiça Federal condena Sabbá por gestão fraudulenta (2025)','O Jornal de Brasília (06/02/2026) e o Brasil 247, com base no Valor (16/01/2026), informam que Sabbá foi condenado por gestão fraudulenta no Máxima no início de 2025. O Money Times (19/12/2025) informa pena de três anos de reclusão em regime inicial aberto, imposta pela Justiça Federal de São Paulo, mas dá duas datas (''início de 2025'' no lead e ''abril de 2025'' no corpo). Jornal de Brasília e Money Times dizem que a Justiça absolveu outros ex-dirigentes, entre eles o ex-diretor jurídico e contábil, sem citar nomes. É decisão de primeira instância; as fontes não informam sobre recurso ou trânsito em julgado nem explicam a relação com o acordo de não persecução penal posterior.','2025',0,NULL,'reportada',NULL,'banco',NULL,'A defesa de Sabbá não se manifestou ao Jornal de Brasília; ele não respondeu aos pedidos de comentário do Valor (via Brasil 247).',NULL,'origens','origens:EV[64]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max26','Justiça homologa ANPP de Sabbá com o MPF (05/02/2026)','O Jornal de Brasília (06/02/2026) informa que, na quinta-feira (05/02), a Justiça Federal de São Paulo homologou acordo de não persecução penal entre Sabbá e o MPF: segundo o jornal, ele reconhece ter cometido crime e evita a ação penal em troca de dois anos de serviços comunitários e pagamento de R$ 100 mil. O Money Times (19/12/2025) fala em pagamento equivalente a cerca de 70 salários mínimos, segundo a Folha de S.Paulo, e não menciona serviços comunitários. O MPF era contrário ao acordo e o fechou após a decisão do STJ e determinação da 2ª CCR do próprio MPF. O acordo, por si, não é uma condenação.','2026-02-05',0,NULL,'documentada',NULL,'banco',NULL,'A defesa de Sabbá não se manifestou.',NULL,'origens','origens:EV[75]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max3','Cristiano Abdalla declara propósito de ser diretor adjunto da Máxima CTVM','O Comunicado BCB 19.256, de 11/01/2010 (DEORF), divulga a declaração de propósito de Cristiano Ferreira Abdalla para o cargo de diretor adjunto da Máxima S.A. CTVM, publicada no Monitor Mercantil em 5 e 6/01/2010. Abdalla aparece depois, com Gonçalves e Sabbá, em processo do BC que chegou ao CRSFN.','2010-01-11',0,NULL,'documentada',4,'banco',NULL,NULL,NULL,'origens','teia:EV[12]|origens:EV[12]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max4','Moody''s rebaixa notas do Banco Máxima (ago/2013)','Reportagem do Valor Online de 26/09/2013, republicada pela CBIC, diz que a Moody''s rebaixou as notas de crédito do banco em agosto de 2013, citando possíveis descasamentos de prazo e de juros com a mudança para obras de longo prazo. A diretora comercial Claudia Martinez respondeu que a agência avaliou um período de transição.','2013-08',0,NULL,'reportada',3,'banco',NULL,'Claudia Martinez (diretora comercial): a avaliação da Moody''s se baseou em período de transição; o banco deixou de fazer operações de ''plano empresário'' e os prazos de captação passaram a ser compatíveis com as carteiras compradas.',NULL,'origens','teia:EV[14]|origens:EV[14]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max5','Máxima compra carteiras imobiliárias de incorporadoras; carteira de R$ 250 mi','Segundo o Valor Online (26/09/2013, via CBIC), o banco tinha carteira imobiliária de R$ 250 milhões (60% empresas, 40% pessoas físicas, incluindo carteiras compradas). A estratégia era comprar financiamentos do balanço de incorporadoras (contratos com 50% já pagos), dar capital de giro a construtoras com prazo médio de 1,5 ano e emitir CRIs. A matéria diz também que o banco já havia tentado financiar a construção (''plano empresário'') e que antes atuou em crédito consignado.','2013-09-26',0,NULL,'reportada',3,'banco',NULL,NULL,NULL,'origens','teia:EV[15]|origens:EV[15]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max6','Fundo Ravena e FC Max: operação que o MPF diz ter inflado o resultado do banco (nov/2014)','Segundo a denúncia do MPF, ações da FC Max (turismo, controlada pelo Máxima) foram transferidas ao FIP Ravena, criado pelo banco, e em novembro de 2014 recursos do próprio banco teriam sido usados para inflar o valor das cotas, por meio da simulação de um empréstimo de R$ 7 milhões que circulou pelos fundos Aquilla Renda e Aquilla Veyron. O MPF diz que o ajuste positivo de R$ 10,4 milhões reduziu o prejuízo do semestre para R$ 5,1 milhões, valor que, segundo a denúncia, ficou bem abaixo do verdadeiro rombo; em março de 2016 o banco teria recomprado as cotas e o valor pago voltou ao banco como amortização do empréstimo simulado. São alegações do MPF; a Justiça recebeu a denúncia em 2021 (evento de 24/07/2021).','2014-11',0,NULL,'investigacao',3,'banco',NULL,'O Banco Máxima (gestão atual) afirmou em 2021 que seus atuais acionistas assumiram a administração em 2018, que os integrantes da antiga gestão não têm mais relação com a instituição e que o banco e sua gestão atual não fazem parte do processo do MPF. As reportagens de 2021 não trazem manifestação individual dos acusados; o Jornal de Brasília (2026) informa que a defesa de Sabbá não se manifestou ao tratar do acordo penal.',NULL,'origens','teia:EV[16]|origens:EV[17]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max7','Acusação do MPF: informações incorretas ao BC para ocultar falta de capital (jan/2015 a mar/2016)','Segundo a denúncia do MPF, noticiada em 2021, entre janeiro de 2015 e março de 2016 o banco aplicou metodologias diferentes das estabelecidas pelo Banco Central e omitiu informações nas declarações enviadas ao BC para dissimular insuficiência de capital, o que, segundo o MPF, permitiu ao banco assumir legalmente novos riscos e evitou restrições à remuneração de diretores e acionistas. Segundo o Jornal de Brasília (2026), a denúncia se baseou em informações do Banco Central.','2015-01',0,'2015-01 a 2016-03','investigacao',3,'banco',NULL,'O banco atual diz não ser parte do processo; a reportagem de 2021 não traz defesa individual dos acusados. O Jornal de Brasília (2026) informa que a Justiça Federal absolveu outros ex-dirigentes na ação, entre eles o ex-diretor jurídico e contábil, sem citar nomes.',NULL,'origens','teia:EV[18]|origens:EV[18]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max8','Holding da família Vorcaro teria contrato para comprar ações do banco (jul/2015)','O Fator, citando minutas de 2016-2017 confirmadas por fontes da investigação, diz que a Multipar, holding da família Vorcaro, assinou em julho de 2015 contrato para comprar ações do banco por meio do Fundo Esmeralda, ainda em vigor numa minuta de dezembro de 2017. Os documentos são minutas sem assinatura.','2015-07',0,NULL,'reportada',3,'banco',NULL,'A defesa de Henrique Vorcaro diz que as minutas ''não são documentos'' e registram conversas que ''nunca chegaram perto de se concretizar'', e que ele ''jamais foi acionista, conselheiro, e muitíssimo menos, gestor ou administrador'' do banco.',NULL,'origens','teia:EV[19]|origens:EV[19]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('max9','Crise de inadimplência na carteira imobiliária e risco de liquidação, segundo reportagens (2016)','O Correio da Manhã (2026) diz que em 2016 a instituição esteve à beira da falência após uma crise de inadimplência na carteira, concentrada em crédito imobiliário; a Wikipedia em inglês diz que o banco ficou ''perto da insolvência''. Reportagem do Valor, via Let''s Money, diz que o rombo potencial para o FGC teria saltado de R$ 827 milhões em 2016 para R$ 3,224 bilhões em 2019. O Brasil 247 descreve o banco como ''à beira de liquidação pelo Banco Central'' e a entrada de Vorcaro como vista como solução de mercado; o Jornal Grande Bahia diz que o banco estava sob risco de liquidação no período analisado pelo BC (2017 a 2019).','2016',0,NULL,'reportada',3,'banco',NULL,NULL,NULL,'origens','teia:EV[20]|origens:EV[20]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol1','Zettel doa R$ 5 milhões a Bolsonaro e Tarcísio na campanha de 2022','Dados do TSE reportados pela CNN Brasil (14/01/2026) mostram doações de Fabiano Zettel de R$ 3 milhões à campanha de Jair Bolsonaro e R$ 2 milhões à de Tarcísio de Freitas em 2022, a maior doação de pessoa física registrada na campanha de Tarcísio. A Metrópoles acrescenta R$ 10 mil ao candidato do Novo Lucas Gonzales. A CartaCapital descreve as doações como ''legais e declaradas''; as reportagens não as ligam a conduta investigada nem à Lagoinha.','2022',0,NULL,'documentada',NULL,'volta',NULL,'Governo de São Paulo (nota à CNN): campanha conduzida com respeito às leis eleitorais, contas aprovadas pela Justiça Eleitoral e governador sem vínculo ou relação com o doador; a defesa de Tarcísio, em setembro, cita mais de 600 doadores (Bahia Notícias). Defesa de Zettel: atividades empresariais conhecidas e lícitas, sem relação com a gestão do Master. O PL não respondeu à CNN.',5000000.0,'origens','origens:EV[50]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol10','CPMI do INSS: Rogério Correia pede quebra de sigilo de Valadão','Segundo a Agência Pública, o deputado Rogério Correia (PT-MG) pediu em 25/11/2025 à CPMI do INSS a quebra dos sigilos fiscal e bancário de André Valadão e suspeitou que o Clava Forte fosse ''canal de circulação dos valores desviados'' do INSS; no início de dezembro pediu o mesmo para a Moriah Asset de Zettel (Metrópoles). São requerimentos de parlamentar: não são prova nem decisão, e a Pública não registra deliberação da CPMI sobre eles nem sobre a Lagoinha como instituição. A Pública menciona ainda Felipe Macedo Gomes, ex-presidente da Amar Brasil e fiel da Lagoinha (proximidade com Valadão descrita como ''suposta''), que negou em depoimento à CPMI ter patrocinado a festa de fim de ano de 2024; ele não é da família Vorcaro.','2025-11-25',0,NULL,'documentada',4,'volta',NULL,'Valadão (22/01/2026): perseguição infundada e caluniosa, nome surgido de requerimento de Correia, contra quem diz tomar medidas judiciais. A Pública: Clava Forte não respondeu.',NULL,'origens','teia:EV[95]|origens:EV[68]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol11','PF detém Zettel em Guarulhos na 2ª fase da Compliance Zero','Zettel foi detido no aeroporto de Guarulhos em 14/01/2026, ao embarcar, no cumprimento de busca e apreensão e prisão temporária (Poder360, Metrópoles); o destino foi Dubai, segundo Bloomberg Linea e Metrópoles, e Bahrein, segundo a defesa e o Poder360. Foi solto horas depois, com passaporte apreendido e proibição de deixar o país por decisão de Dias Toffoli (Poder360). A Gazeta do Povo diz que as apurações da PF o apontam como ''um elo entre a congregação e o círculo empresarial'' do banco. A fase investiga, segundo a PF, organização criminosa, gestão fraudulenta, manipulação de mercado e lavagem de capitais (Bloomberg Linea).','2026-01-14',0,NULL,'investigacao',NULL,'volta',NULL,'Defesa de Zettel: não teve acesso aos autos, está à disposição, atividades empresariais conhecidas e lícitas, sem relação com a gestão do Master, passagem de volta marcada para 06/02.',NULL,'origens','origens:EV[70]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol12','Lagoinha publica nota: não é parte de investigação e afastou Zettel','Em nota de 15/01/2026, a Igreja Batista da Lagoinha nega relação com a CPMI do INSS e a Compliance Zero, afirma não haver indícios de uso da igreja em fraudes e diz que a presença de fiéis em cultos não cria vínculo jurídico. A nota informa que Zettel foi afastado e que a igreja tomará medidas legais para proteger sua reputação.','2026-01-15',0,NULL,'documentada',4,'volta',NULL,'É a própria versão da igreja; a Gazeta do Povo registra que a reportagem não obteve resposta adicional da igreja nem da assessoria de Valadão.',NULL,'origens','teia:EV[107]|origens:EV[71]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol13','Damares divulga lista de requerimentos da CPMI; Valadão e Zettel aparecem','A lista de requerimentos da CPMI divulgada pela senadora Damares Alves (InfoMoney, 15/01/2026) traz André Valadão como convidado a comparecer e alvo de pedido de quebra de sigilo, e Zettel como convidado a comparecer. As quatro igrejas listadas como alvo de quebra de sigilo eram outras (Adoração Church, Ministério do Renovo, Deus é Fiel, Campo de Anatote); a Lagoinha como instituição não consta da lista. Damares disse que as informações constam de documentos oficiais e foram aprovadas pelos integrantes da comissão. Convite e pedido de quebra de sigilo não são acusação.','2026-01-15',0,NULL,'investigacao',3,'volta',NULL,'Valadão, em vídeo de 22/01/2026, chamou a citação de ''perseguição infundada e caluniosa'', disse que seu nome veio de requerimento de Rogério Correia e que já tomava providências judiciais contra o deputado (Metrópoles). Silas Malafaia cobrou que Damares citasse nomes e criticou a generalização envolvendo líderes religiosos.',NULL,'origens','teia:EV[108]|origens:EV[72]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol14','Valadão nega negócios com Vorcaro e diz que o conhece da igreja','Em vídeo divulgado em 27/01/2026 (Portal Tela), André Valadão afirmou não ter feito negócios com Daniel Vorcaro e conhecê-lo apenas no contexto da Lagoinha, com relacionamento ''restrito à esfera religiosa''; disse que Vorcaro foi ''membro da Lagoinha por muitos anos'' e que as acusações seriam infundadas. O Portal Tela acrescenta, sem atribuir a Valadão, que Vorcaro teria frequentado outra igreja e voltado recentemente. É a versão do pastor. Em 13/03/2026 o SBT News relatou que o Coaf apontou repasse do Master a produtora registrada em nome dele e da esposa (ver evento de 13/03/2026), que ele e a empresa negam; a matéria diz que as relações financeiras entre os dois ainda não foram esclarecidas.','2026-01-27',0,NULL,'documentada',4,'volta',NULL,'Declaração própria de Valadão; a fonte é portal agregador, com a data de 27/01/2026.',NULL,'origens','teia:EV[116]|origens:EV[74]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol15','Mendonça dispensa Zettel de comparecer à CPI do Crime Organizado','Em decisão de 27/02/2026, o ministro André Mendonça atendeu a pedido de Zettel e o desobrigou de comparecer à CPI do Crime Organizado, que aprovara sua convocação em 25/02, com base no direito à não autoincriminação, que abrange a faculdade de comparecer ou não; se comparecer, teria direito ao silêncio e a advogado. O exercício dessa garantia constitucional não implica culpa.','2026-02-27',0,NULL,'documentada',NULL,'volta',NULL,'Zettel invocou a não autoincriminação.',NULL,'origens','origens:EV[76]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol16','Fase 3: PF prende Zettel como suposto operador financeiro de Vorcaro','Em 04/03/2026 Zettel se apresentou à PF em São Paulo, na terceira fase da Compliance Zero, com prisão preventiva decretada por Mendonça. Segundo a PF e a decisão, ele operacionalizaria pagamentos ao grupo "A Turma" (monitoramento e intimidação de críticos, jornalistas e concorrentes) e a servidores do Banco Central por contrato simulado via Varajo Consultoria; a fase teve 15 mandados em SP e MG e bloqueio de até R$ 22 bilhões. As fontes abertas não registram busca em endereço da Lagoinha.','2026-03-04',0,NULL,'investigacao',NULL,'volta',NULL,'Defesa de Zettel: ainda sem acesso ao material, está à disposição das autoridades. Lagoinha: não é parte de investigação; Zettel era pastor voluntário.',NULL,'origens','origens:EV[77]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol17','Lagoinha responde ao O Globo: relações são pessoais entre famílias','A nota de 10/03/2026, em resposta a coluna do O Globo de 09/03, diz que a igreja não é parte de qualquer investigação relacionada ao caso, que o pastor e o deputado citados na reportagem (identificados por ela como Guilherme Batista e Nikolas Ferreira) não são membros, que a viagem aérea foi feita por terceiros e não foi agenda da igreja, que Zettel integrava a Lagoinha como pastor voluntário havia menos de dois anos e que as relações entre Valadão e a família Vorcaro são pessoais, entre famílias que convivem há décadas, e ''não configuram, por si só, qualquer irregularidade''. Diz que a alegação de relação com a instituição é falsa e já foi objeto de reportagem considerada caluniosa, e que medidas judiciais estão sendo adotadas. Rogério Correia disse em 09/03, no X, que as ligações vão ''muito além'' do contado e que ''quando quebrar o sigilo, não sobra um'', citando lavagem de dinheiro e blindagem na CPMI, sem apresentar documentos no texto.','2026-03-10',0,NULL,'documentada',4,'volta',NULL,'A nota é a versão da igreja. As falas de Correia são de parlamentar adversário e não foram acompanhadas de prova na fonte aberta.',NULL,'origens','teia:EV[126]|origens:EV[78]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol21','Dino cobra Viana sobre R$ 3,6 mi em emendas à Fundação Oásis, da Lagoinha','O ministro Flávio Dino deu cinco dias ao senador Carlos Viana, presidente da CPMI do INSS, para explicar emendas Pix de R$ 1,5 mi (2019), R$ 1,47 mi (2023) e R$ 650,9 mil (2025) ligadas à Fundação Oásis, braço social da Lagoinha, em ação dos deputados Pastor Henrique Vieira (PSOL) e Rogério Correia (PT), que alegam conflito de interesse por Viana presidir a CPMI; a decisão se apoia na transparência e rastreabilidade das emendas Pix, e a matéria não afirma que a fundação seja investigada. Em 03/04/2026, a Folhapress noticiou relatório da CGU segundo o qual Viana escolheu a Fundação Oásis de forma irregular em emenda indicada em 2020 (outras fontes falam em 2019), sem concorrência prévia e sem definição do objeto; segundo Viana, a emenda acabou remanejada para outra obra. Nenhuma fonte liga essas emendas ao Banco Master, e o item não mostra ajuda da igreja à família Vorcaro ou ao Master.','2026-03-19',0,NULL,'documentada',4,'volta',NULL,'Viana: repasses legais, enviados às prefeituras, que aprovam um plano de trabalho, e não à conta da fundação; disse ter ajudado ''dezenas de fundações'', negou relação com Zettel e afirmou ''Não vou blindar ninguém''; seus ofícios são apenas indicativos e a emenda foi remanejada para uma quadra poliesportiva. Fundação Oásis: não foi notificada nem conhece o teor do relatório da CGU e diz atuar na assistência social e na educação conforme a lei.',3600000.0,'origens','teia:EV[130]|origens:EV[80]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol23','Zettel declarou R$ 190,2 mi em lucros do fundo Kairós, ligado à Super Empreendimentos','Segundo dados de imposto de renda obtidos pelo g1 e reportados pelo CNBC/Times Brasil (24/03/2026), Zettel declarou R$ 190,2 milhões em lucros e dividendos do FIP Kairós em 2023-2024, e seu patrimônio declarado subiu de cerca de R$ 67,5 mi (2021) para R$ 204,3 mi (2024). O Kairós, administrado pela Reag, tinha como principal ativo até agosto de 2024 a Super Empreendimentos, da qual Zettel foi diretor de 2021 a 2024 e que a PF aponta como usada pelo grupo ''A Turma'' para crimes financeiros e lavagem e como fonte de pagamentos a um integrante do grupo. O Poder360 informa que a Super adquiriu imóveis, incluindo o tríplex onde Vorcaro morou. Nenhuma fonte liga esses valores à Lagoinha.','2026-03-24',0,NULL,'reportada',3,'volta',NULL,'A reportagem não traz resposta de Zettel, de advogados, da Reag ou do fundo. A defesa de Zettel afirmou em janeiro que suas atividades empresariais são conhecidas e lícitas, sem relação com a gestão do Master.',190200000.0,'origens','teia:EV[132]|origens:EV[82]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol24','CPMI do INSS termina sem relatório final; texto alternativo da base, não votado, cita ''conexões'' com a Lagoinha','A CPMI terminou em 28/03/2026 sem relatório final: o parecer de Alfredo Gaspar, que pedia o indiciamento de mais de 200 pessoas, incluindo Vorcaro, foi rejeitado por 19 a 12 (Istoé), e as matérias lidas sobre esse relatório não citam a Lagoinha. O relatório alternativo da base governista, que a presidência encerrou sem votar, diz ''Apontamos conexões do Master com a Igreja Batista da Lagoinha e Fabiano Zettel'' e cita também conexões com os governadores Ibaneis Rocha e Cláudio Castro, sem pedir o indiciamento da igreja nos trechos lidos. É a única menção à Lagoinha como instituição em texto de CPMI que identifiquei, e vem de documento de grupo político que não foi aprovado.','2026-03-28',0,NULL,'documentada',4,'volta',NULL,'A Lagoinha nega ser parte de investigação (nota de 10/03/2026). Não confirmei, nas fontes lidas, a declaração atribuída a Viana de que enviaria cópias do relatório rejeitado ao MPF e ao STF.',NULL,'origens','origens:EV[83]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol26','Zettel propõe delação; PF e PGR devem rejeitar','O Poder360 informou em 28/06/2026 que Zettel, com novo advogado (Celso Vilardi), apresentou proposta de colaboração premiada, que PF e PGR deveriam rejeitar, segundo a expectativa do veículo. O conteúdo não é detalhado. Não há, nas fontes abertas, delação homologada de Zettel que cite a igreja.','2026-06-28',0,NULL,'reportada',NULL,'volta',NULL,'Defesa não detalha a proposta nas fontes abertas.',NULL,'origens','origens:EV[85]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol27','Proposta de delação de Vorcaro liga doações de Zettel a Credcesta','O UOL, reproduzido pelo Bahia Notícias (03/09/2026), relata que Vorcaro, em proposta de delação rejeitada por PF e PGR, afirmou que os R$ 5 mi doados em 2022 às campanhas de Tarcísio (R$ 2 mi) e Bolsonaro (R$ 3 mi) fizeram parte de uma negociação de propina ligada à manutenção do Credcesta em São Paulo; o texto associa a Zettel a expressão ''contrapartidas financeiras'' e a um suposto ''ajuste indevido'' com o presidente do PSD, sem deixar claro se a fala é dele ou apenas a ele atribuída. É alegação de um investigado, sem comprovação pública; as doações constam como declaradas ao TSE. A igreja não aparece como parte da alegação.','2026-09-03',0,NULL,'reportada',NULL,'volta',NULL,'Tarcísio (por meio da defesa): negou vínculo com Vorcaro; campanha com mais de 600 doadores, contas aprovadas pela Justiça Eleitoral. Presidente do PSD, não nomeado no trecho: nunca tratou de doações com Vorcaro ou Augusto Lima e não tem relação com ele. Bolsonaro: sem manifestação no texto. Zettel: sem resposta no texto.',5000000.0,'origens','origens:EV[86]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol28','STF abre sigilo e Coaf sobre a Belvedere vem a público','Após Mendonça levantar o sigilo de dados financeiros do caso Master, os relatórios do Coaf sobre a conta da Belvedere tornaram-se públicos (14/09 segundo Itatiaia e Bahia Notícias; 10/09 segundo a Folhapress). O ICL de 25/09 acrescenta que o Banco do Brasil comunicou o caso por entender haver "relação financeira íntima" de Zettel com possíveis ilicitudes, que Lagoinha Participações (R$ 1,1 mi) e HV Empreendimentos (R$ 700 mil) figuram entre os remetentes, e que as saídas foram sobretudo a construtoras como Jorlan, Muzzi Misk, AFEB e FDS. O Coaf ressalva que o relatório não conclui lavagem nem afirma irregularidade nas construtoras.','2026-09-14',0,NULL,'documentada',4,'volta',NULL,'Lagoinha Global (nota de setembro): unidades têm autonomia; recursos informados como para obras; Zettel afastado em 11/2025; Belvedere encerrada; defende apuração. ICL: igreja não respondeu até a publicação de 25/09.',NULL,'origens','teia:EV[160]|origens:EV[88]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol3','Valadão e a esposa fundam o Clava Forte Bank, fintech cristã','A Agência Pública informa que o Clava Forte foi fundado em março de 2024 por André Valadão e Cassiane Valadão, atuava como correspondente bancário sobre a estrutura da CDC SCD (Banco 470) e da Dock, e que o Banco Central diz nunca tê-lo autorizado a funcionar como banco. O site e o app saíram do ar por volta de 21/11/2025. A Pública afirma que a suspeita de atuação conjunta com o Master não estava comprovada e dependia de relatórios de inteligência financeira.','2024-03',0,NULL,'documentada',4,'volta',NULL,'Valadão (21/01/2026): o sistema era de pagamentos internos da Lagoinha Global, encerrado por segurança digital; "não há uma vírgula de vínculo entre Clava Forte e Banco Master".',NULL,'origens','teia:EV[59]|origens:EV[55]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol4','Vorcaro pede a Valadão que fale com Nikolas sobre críticas ao Master','Mensagens divulgadas pelo ICL e relatadas pelo Poder360 mostram que em 27/04/2024 Vorcaro escreveu a Valadão ''De novo pedir sua ajuda com Nikolas'', por causa de publicações do deputado Nikolas Ferreira sobre um fórum jurídico financiado pelo Master; Nikolas diz ter pedido esclarecimentos pela Lei de Acesso à Informação. Valadão confirmou em vídeo (03-04/09/2026) que sua participação ''se limitou a aproximar duas pessoas que eu conhecia''. Nikolas confirmou que o contato de Vorcaro lhe foi passado por Valadão e nega ter recebido dinheiro ou encontrado o banqueiro.','2024-04-27',0,NULL,'documentada',4,'volta',NULL,'Valadão: participação limitada a aproximar duas pessoas; ''não houve qualquer relação da minha parte com negócios, interesses ou atividades do Banco Master''; desconhecia as irregularidades; está disposto a adotar medidas legais se lhe atribuírem condutas que não praticou. Nikolas: ''nunca recebi um tostão do Vorcaro''.',NULL,'origens','teia:EV[60]|origens:EV[56]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento(id, titulo, descricao, data, data_aprox, data_texto, natureza_id, peso, canal, contexto, resposta, valor_brl, origem, origem_ref, criado_em, atualizado_em) VALUES('vol7','Folha: Zettel fez 54 repasses de R$ 40,9 milhões à unidade Belvedere','A Folha de S.Paulo, citada pela Folhapress (matéria sobre a CGU) e pela Gazeta do Povo, contabilizou 54 transferências de Zettel somando R$ 40,9 milhões à Lagoinha Belvedere entre outubro de 2024 e janeiro de 2026. O número difere do dado do Coaf (R$ 19,2 mi em 26 operações numa conta do Banco do Brasil, dez/2024 a dez/2025); as fontes abertas não explicam a diferença, possivelmente contas ou períodos distintos.','2024-10',0,NULL,'reportada',3,'volta',NULL,'A Lagoinha reitera que cada templo tem autonomia administrativa e financeira. A defesa de Zettel não se manifestou nos textos abertos.',40900000.0,'origens','teia:EV[65]|origens:EV[59]','2026-10-16T00:00:00Z','2026-10-16T00:00:00Z');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2019-02-13-bc-nega-a-compra-do-maxima-por-vorcaro','max16','13/02/2019: o Banco Central rejeita a compra do controle do Máxima por Vorcaro (voto 20/2019). Mesmo ato, escrito por origens e pelo dossiê BRB.','brb','dossie.brb.eventos[0]','{"canal": "brb", "contexto": "lado: barra", "data": "2019-02-13", "data_aprox": 0, "data_texto": null, "descricao": "Origem dos recursos não comprovada.", "entidades": [], "fontes": [["Let''s Money", "https://www.letsmoney.com.br/noticias/bc-veto-aval-compra-banco-maxima-vorcaro", "sustenta", 0]], "id": "ev-2019-02-13-bc-nega-a-compra-do-maxima-por-vorcaro", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[0]", "peso": null, "resposta": null, "titulo": "BC nega a compra do Máxima por Vorcaro", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2019-10-14-bc-aprova-a-compra-ja-com-nova-diretoria','max17','14/10/2019: o BC aprova a mudança de controle do Máxima (voto 218/2019). Mesmo ato em origens, dossiê BRB e teia.','brb','dossie.brb.eventos[1]','{"canal": "brb", "contexto": "lado: empurra", "data": "2019-10-14", "data_aprox": 0, "data_texto": null, "descricao": "Presidente Campos Neto; relator Pinho de Mello.", "entidades": [], "fontes": [["Let''s Money", "https://www.letsmoney.com.br/noticias/bc-veto-aval-compra-banco-maxima-vorcaro", "sustenta", 0]], "id": "ev-2019-10-14-bc-aprova-a-compra-ja-com-nova-diretoria", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[1]", "peso": null, "resposta": null, "titulo": "BC aprova a compra, já com nova diretoria", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2019-10-14-bc-aprova-controle-do-maxima-por-vorcaro','max17','14/10/2019: o BC aprova a mudança de controle do Máxima (voto 218/2019). Mesmo ato em origens, dossiê BRB e teia.','teia','teia:EV[36]','{"canal": "teia", "contexto": null, "data": "2019-10-14", "data_aprox": 0, "data_texto": null, "descricao": "No voto 218/2019 (out/2019), o BC aprovou a aquisição do Máxima por Vorcaro após documentação revisada, depois de um veto em fev/2019 por falta de comprovação da origem dos recursos e da capacidade econômica. O Valor, citado pelo Let''s Money, registra o relator inclinado a rejeitar e o rombo potencial do FGC, que crescera de R$ 827 mi (2016) para R$ 3,224 bi.", "entidades": [["daniel-vorcaro", null, 0], ["bcb", null, 1], ["fgc", null, 2], ["banco-maxima", null, 3]], "fontes": [["letsmoney.com.br", "https://www.letsmoney.com.br/noticias/bc-veto-aval-compra-banco-maxima-vorcaro", "sustenta", 0], ["jornalgrandebahia.com.br", "https://jornalgrandebahia.com.br/2026/04/banco-central-rejeitou-e-depois-aprovou-controle-do-banco-master-por-daniel-vorcaro-apos-revisao-de-capacidade-economica", "sustenta", 1]], "id": "ev-2019-10-14-bc-aprova-controle-do-maxima-por-vorcaro", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[36]", "peso": 4, "resposta": null, "titulo": "BC aprova controle do Máxima por Vorcaro", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2021-08-02-maxima-relanca-se-como-banco-master','max22','02/08/2021: reportagem da InvestNews sobre a troca de marca do Máxima para Banco Master.','teia','teia:EV[49]','{"canal": "teia", "contexto": null, "data": "2021-08-02", "data_aprox": 0, "data_texto": null, "descricao": "A InvestNews reportou a adoção do nome Master após quase 50 anos, com posicionamento de banco digital, índice de Basileia perto de 14% e meta de R$ 1 bilhão de patrimônio até o fim de 2022.", "entidades": [["banco-master", null, 0], ["banco-maxima", null, 1]], "fontes": [["investnews.com.br", "https://investnews.com.br/negocios/banco-maxima-muda-nome-para-master-e-busca-pulverizar-servicos-financeiros/amp", "sustenta", 0], ["dieese.org.br", "https://www.dieese.org.br/notatecnica/2026/notaTec291BancoMaster.pdf", "sustenta", 1]], "id": "ev-2021-08-02-maxima-relanca-se-como-banco-master", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[49]", "peso": 4, "resposta": null, "titulo": "Máxima relança-se como Banco Master digital", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2024-07-brb-comeca-a-comprar-carteiras-do-master','ev-2024-07-brb-comeca-a-comprar-carteiras-de','Jul/2024 (data só com mês nas duas): o BRB começa a comprar carteiras de crédito do Master. Títulos quase idênticos (teia e dossiê BRB).','brb','dossie.brb.eventos[5]','{"canal": "brb", "contexto": "lado: empurra", "data": "2024-07", "data_aprox": 0, "data_texto": null, "descricao": "No mesmo mês, a previdência do Amapá aplica R$ 400 mi em 18 dias.", "entidades": [], "fontes": [["Times Brasil", "https://timesbrasil.com.br/brasil/operacoes-da-pf/mensagens-vorcaro-brb-bancou-master-2024", "sustenta", 0]], "id": "ev-2024-07-brb-comeca-a-comprar-carteiras-do-master", "natureza_id": "reportada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[5]", "peso": null, "resposta": null, "titulo": "BRB começa a comprar carteiras do Master", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2024-12-04-lula-recebe-vorcaro-no-planalto-fora-da-2','ev-2024-12-04-lula-recebe-vorcaro-no-planalto-fora-da','04/12/2024: título idêntico na teia e no dossiê BRB.','brb','dossie.brb.eventos[8]','{"canal": "brb", "contexto": "lado: contexto", "data": "2024-12-04", "data_aprox": 0, "data_texto": null, "descricao": "Com Mantega e Galípolo. Segundo Poder360 e UOL, Lula teria dito para não vender ao BTG por R$ 1; isso é só reportagem.", "entidades": [], "fontes": [["Gazeta do Povo", "https://www.gazetadopovo.com.br/republica/lula-aconselhou-vorcaro-a-recusar-venda-do-master-para-o-btg", "sustenta", 0]], "id": "ev-2024-12-04-lula-recebe-vorcaro-no-planalto-fora-da-2", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[8]", "peso": null, "resposta": null, "titulo": "Lula recebe Vorcaro no Planalto, fora da agenda", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-03-28-conselho-do-brb-aprova-comprar-58-do','ev-2025-03-28-brb-anuncia-compra-de-58-do-master','28/03/2025: o conselho do BRB aprova e o banco anuncia a compra de 58% do Master por cerca de R$ 2 bi (teia e dossiê BRB descrevem o mesmo ato).','brb','dossie.brb.eventos[10]','{"canal": "brb", "contexto": "lado: empurra", "data": "2025-03-28", "data_aprox": 0, "data_texto": null, "descricao": "Dias antes, o presidente do BRB escreve a Vorcaro que o governador pediu material para defender a operação.", "entidades": [], "fontes": [["Metrópoles", "https://www.metropoles.com/colunas/grande-angular/o-que-se-sabe-sobre-a-compra-do-master-pelo-brb", "sustenta", 0]], "id": "ev-2025-03-28-conselho-do-brb-aprova-comprar-58-do", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[10]", "peso": null, "resposta": null, "titulo": "Conselho do BRB aprova comprar 58% do Master por cerca de R$ 2 bi", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-05-27-btg-compra-r-1-5-bi-em-ativos-de-vorcaro-2','ev-2025-05-27-btg-compra-r-1-5-bi-em-ativos-de-vorcaro','27/05/2025: título idêntico na teia e no dossiê BRB.','brb','dossie.brb.eventos[12]','{"canal": "brb", "contexto": "lado: contexto", "data": "2025-05-27", "data_aprox": 0, "data_texto": null, "descricao": "A J&F havia desistido dias antes.", "entidades": [], "fontes": [["Brazil Journal", "https://braziljournal.com/exclusivo-btg-compra-r-15-bi-em-ativos-de-vorcaro-que-vai-capitalizar-o-master", "sustenta", 0]], "id": "ev-2025-05-27-btg-compra-r-1-5-bi-em-ativos-de-vorcaro-2", "natureza_id": "reportada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[12]", "peso": null, "resposta": null, "titulo": "BTG compra R$ 1,5 bi em ativos de Vorcaro", "valor_brl": null}');
