INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-09-03-banco-central-rejeita-a-compra-do-master','ev-2025-09-03-bc-veta-a-compra-do-master-pelo-brb','03/09/2025: o BC veta por unanimidade a compra do Master pelo BRB. Três redações (duas na teia, uma no dossiê BRB).','teia','teia:EV[83]','{"canal": "teia", "contexto": null, "data": "2025-09-03", "data_aprox": 0, "data_texto": null, "descricao": "Segundo o BC, a decisão foi unânime e o parecer contrário veio da área de organização do sistema financeiro, por falta de solidez da operação.", "entidades": [["banco-master", null, 0], ["bcb", null, 1], ["brb", null, 2]], "fontes": [["sbtnews.sbt.com.br", "https://sbtnews.sbt.com.br/noticia/economia/decisoes-de-liquidacao-do-master-e-reprovacao-da-compra-pelo-brb-foram-unanimes-no-bc", "sustenta", 0], ["timesbrasil.com.br", "https://timesbrasil.com.br/brasil/hugo-motta-pediu-para-falar-com-vorcaro-antes-de-reuniao-sobre-venda-do-master-ao-brb", "sustenta", 1]], "id": "ev-2025-09-03-banco-central-rejeita-a-compra-do-master", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[83]", "peso": 5, "resposta": null, "titulo": "Banco Central rejeita a compra do Master pelo BRB", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-09-03-banco-central-veta-a-compra-por','ev-2025-09-03-bc-veta-a-compra-do-master-pelo-brb','03/09/2025: o BC veta por unanimidade a compra do Master pelo BRB. Três redações (duas na teia, uma no dossiê BRB).','brb','dossie.brb.eventos[21]','{"canal": "brb", "contexto": "lado: barra; crítico", "data": "2025-09-03", "data_aprox": 0, "data_texto": null, "descricao": "Parecer do diretor Renato Gomes. Depois do veto, o Master contrata o escritório de Michel Temer.", "entidades": [], "fontes": [["Poder360", "https://www.poder360.com.br/poder-economia/bc-nega-compra-do-banco-master-pelo-brb", "sustenta", 0]], "id": "ev-2025-09-03-banco-central-veta-a-compra-por", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[21]", "peso": null, "resposta": null, "titulo": "Banco Central veta a compra por unanimidade", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-11-17-fictor-e-investidores-dos-emirados','ev-2025-11-17-fictor-anuncia-compra-do-master-vorcaro','17/11/2025: a Fictor e investidores dos Emirados anunciam a compra do Master. O título da teia acrescenta a prisão de Vorcaro, que também existe como evento próprio (PF prende Daniel Vorcaro).','brb','dossie.brb.eventos[23]','{"canal": "brb", "contexto": "lado: contexto", "data": "2025-11-17", "data_aprox": 0, "data_texto": null, "descricao": "", "entidades": [], "fontes": [["Bloomberg Línea", "https://www.bloomberglinea.com.br/negocios/banco-master-de-daniel-vorcaro-e-vendido-para-consorcio-com-fictor-e-grupo-arabe", "sustenta", 0]], "id": "ev-2025-11-17-fictor-e-investidores-dos-emirados", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[23]", "peso": null, "resposta": null, "titulo": "Fictor e investidores dos Emirados anunciam a compra do Master", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-11-18-banco-central-liquida-o-master','ev-2025-11-18-bc-decreta-a-liquidacao-extrajudicial-do','18/11/2025: o BC decreta a liquidação extrajudicial do Master. Cinco redações (PREC, dossiê BRB e três da teia); nos títulos compostos o segundo trecho (busca no BRB/afastamento de Paulo Henrique Costa; Compliance Zero) já existe como evento próprio ''ev-2025-11-18-1a-fase-da-compliance-zero-7-prisoes-e''.','precatorios','PREC[24]','{"canal": "precatorios", "contexto": null, "data": "2025-11-18", "data_aprox": 0, "data_texto": null, "descricao": "A PF apreende o celular de Vorcaro na mesma data.", "entidades": [], "fontes": [["timesbrasil.com.br", "https://timesbrasil.com.br/brasil/master-repassou-r-14-bilhao-em-precatorios-a-entre-investimentos-empresa-de-mineiro-um-mes-antes-do-banco-ser-liquidado", "sustenta", 0]], "id": "ev-2025-11-18-banco-central-liquida-o-master", "natureza_id": "documentada", "origem": "prec", "origem_ref": "PREC[24]", "peso": null, "resposta": null, "titulo": "Banco Central liquida o Master", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-11-18-bc-liquida-o-banco-master-pf-faz-buscas','ev-2025-11-18-bc-decreta-a-liquidacao-extrajudicial-do','18/11/2025: o BC decreta a liquidação extrajudicial do Master. Cinco redações (PREC, dossiê BRB e três da teia); nos títulos compostos o segundo trecho (busca no BRB/afastamento de Paulo Henrique Costa; Compliance Zero) já existe como evento próprio ''ev-2025-11-18-1a-fase-da-compliance-zero-7-prisoes-e''.','teia','teia:EV[93]','{"canal": "teia", "contexto": null, "data": "2025-11-18", "data_aprox": 0, "data_texto": null, "descricao": "O BC decretou a liquidação extrajudicial; a PF cumpriu mandados na sede do BRB e a Justiça afastou Paulo Henrique Costa.", "entidades": [["banco-master", null, 0], ["bcb", null, 1], ["pf", null, 2], ["brb", null, 3], ["paulo-henrique-costa", null, 4]], "fontes": [["infomoney.com.br", "https://www.infomoney.com.br/politica/justica-afasta-presidente-brb-investigacao-prendeu-dono-banco-master/amp", "sustenta", 0], ["sbtnews.sbt.com.br", "https://sbtnews.sbt.com.br/noticia/economia/decisoes-de-liquidacao-do-master-e-reprovacao-da-compra-pelo-brb-foram-unanimes-no-bc", "sustenta", 1]], "id": "ev-2025-11-18-bc-liquida-o-banco-master-pf-faz-buscas", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[93]", "peso": 5, "resposta": null, "titulo": "BC liquida o Banco Master; PF faz buscas no BRB e Justiça afasta o presidente", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-11-18-bc-liquida-o-master-pf-deflagra-a','ev-2025-11-18-bc-decreta-a-liquidacao-extrajudicial-do','18/11/2025: o BC decreta a liquidação extrajudicial do Master. Cinco redações (PREC, dossiê BRB e três da teia); nos títulos compostos o segundo trecho (busca no BRB/afastamento de Paulo Henrique Costa; Compliance Zero) já existe como evento próprio ''ev-2025-11-18-1a-fase-da-compliance-zero-7-prisoes-e''.','teia','teia:EV[94]','{"canal": "teia", "contexto": null, "data": "2025-11-18", "data_aprox": 0, "data_texto": null, "descricao": "O BC decretou liquidação de Master, Master de Investimento, Letsbank e Master Corretora, com indisponibilidade de bens dos controladores; o Master Múltiplo ficou em regime especial. Segundo o BC, havia grave crise de liquidez e violações normativas.", "entidades": [["banco-master", null, 0], ["bcb", null, 1], ["pf", null, 2], ["operacao-compliance-zero", null, 3]], "fontes": [["infomoney.com.br", "https://www.infomoney.com.br/?p=3107708", "sustenta", 0], ["borainvestir.b3.com.br", "https://borainvestir.b3.com.br/noticias/o-que-disse-o-bc-ao-decretar-a-liquidacao-do-banco-master-grave-crise-de-liquidez", "sustenta", 1], ["revistaoeste.com", "https://revistaoeste.com/economia/bc-liquida-banco-master-e-bloqueia-bens-de-controladores", "sustenta", 2]], "id": "ev-2025-11-18-bc-liquida-o-master-pf-deflagra-a", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[94]", "peso": 5, "resposta": null, "titulo": "BC liquida o Master; PF deflagra a Compliance Zero", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2025-11-18-bc-liquida-o-master-vorcaro-e-preso','ev-2025-11-18-bc-decreta-a-liquidacao-extrajudicial-do','18/11/2025: o BC decreta a liquidação extrajudicial do Master. Cinco redações (PREC, dossiê BRB e três da teia); nos títulos compostos o segundo trecho (busca no BRB/afastamento de Paulo Henrique Costa; Compliance Zero) já existe como evento próprio ''ev-2025-11-18-1a-fase-da-compliance-zero-7-prisoes-e''.','brb','dossie.brb.eventos[24]','{"canal": "brb", "contexto": "lado: barra", "data": "2025-11-18", "data_aprox": 0, "data_texto": null, "descricao": "", "entidades": [], "fontes": [["Poder360", "https://www.poder360.com.br/poder-economia/fictor-suspende-compra-do-banco-master-apos-liquidacao-pelo-bc", "sustenta", 0]], "id": "ev-2025-11-18-bc-liquida-o-master-vorcaro-e-preso", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[24]", "peso": null, "resposta": null, "titulo": "BC liquida o Master; Vorcaro é preso", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-01-14-2a-fase-buscas-bloqueio-de-r-5-7-bi-e','ev-2026-01-14-2a-fase-da-compliance-zero-bloqueia-r-5','14/01/2026: 2ª fase da Compliance Zero, 42 mandados de busca e bloqueio de mais de R$ 5,7 bi determinado por Toffoli.','teia','teia:EV[103]','{"canal": "teia", "contexto": null, "data": "2026-01-14", "data_aprox": 0, "data_texto": null, "descricao": "A PF cumpriu 42 mandados de busca em cinco estados, com bloqueio de mais de R$ 5,7 bilhões determinado por Toffoli; foram alvos Fabiano Zettel (preso), Nelson Tanure e João Carlos Mansur, entre outros. Tanure nega relação societária com o Master.", "entidades": [["banco-master", null, 0], ["dias-toffoli", null, 1], ["pf", null, 2], ["joao-carlos-mansur", null, 3], ["nelson-tanure", null, 4], ["fabiano-zettel", null, 5]], "fontes": [["agenciagov.ebc.com.br", "https://agenciagov.ebc.com.br/noticias/202601/policia-federal-deflagra-segunda-fase-da-operacao-compliance-zero", "sustenta", 0], ["neofeed.com.br", "https://neofeed.com.br/negocios/pf-amplia-cerco-contra-fraudes-bilionarias-no-banco-master-e-mira-nomes-de-peso-do-mercado/en", "sustenta", 1], ["gazetadopovo.com.br", "https://www.gazetadopovo.com.br/republica/compliance-zero-alvos-pf-envolvimento-banco-master", "sustenta", 2]], "id": "ev-2026-01-14-2a-fase-buscas-bloqueio-de-r-5-7-bi-e", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[103]", "peso": 4, "resposta": null, "titulo": "2ª fase: buscas, bloqueio de R$ 5,7 bi e prisão de Zettel", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-01-15-bc-liquida-a-reag-cbsf-dtvm','ev-2026-01-15-bc-decreta-liquidacao-da-reag-trust-cbsf','15/01/2026: o BC liquida a Reag Trust (CBSF DTVM).','teia','teia:EV[105]','{"canal": "teia", "contexto": null, "data": "2026-01-15", "data_aprox": 0, "data_texto": null, "descricao": "O BC decretou a liquidação da antiga Reag Investimentos (hoje CBSF DTVM), suspeita de administrar fundos ligados ao Master numa ''ciranda'' de depósitos e retiradas que ocultaria o beneficiário final; segundo as investigações, as fraudes podem superar R$ 11 bilhões.", "entidades": [["banco-master", null, 0], ["bcb", null, 1], ["reag-investimentos", null, 2], ["reag-trust-dtvm", null, 3]], "fontes": [["monitormercantil.com.br", "https://monitormercantil.com.br/bc-liquida-reag-ligada-as-suspeitas-de-fraude-no-banco-master", "sustenta", 0]], "id": "ev-2026-01-15-bc-liquida-a-reag-cbsf-dtvm", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[105]", "peso": 4, "resposta": null, "titulo": "BC liquida a Reag (CBSF DTVM)", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-01-17-fgc-comeca-a-pagar-garantia-a-credores','ev-2026-01-17-fgc-inicia-o-maior-ressarcimento-de-sua','17/01/2026: o FGC começa a pagar a garantia aos credores do Master (três redações na teia).','teia','teia:EV[111]','{"canal": "teia", "contexto": null, "data": "2026-01-17", "data_aprox": 0, "data_texto": null, "descricao": "Maior operação de pagamento da história do fundo, para cerca de 800 mil credores.", "entidades": [["banco-master", null, 0], ["fgc", null, 1]], "fontes": [["poder360.com.br", "https://www.poder360.com.br/poder-economia/fgc-inicia-pagamento-a-investidores-do-banco-master", "sustenta", 0]], "id": "ev-2026-01-17-fgc-comeca-a-pagar-garantia-a-credores", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[111]", "peso": 4, "resposta": null, "titulo": "FGC começa a pagar garantia a credores do Master (desembolso projetado de ~R$ 40,6 bi)", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-01-17-fgc-inicia-pagamento-a-cerca-de-800-mil','ev-2026-01-17-fgc-inicia-o-maior-ressarcimento-de-sua','17/01/2026: o FGC começa a pagar a garantia aos credores do Master (três redações na teia).','teia','teia:EV[110]','{"canal": "teia", "contexto": null, "data": "2026-01-17", "data_aprox": 0, "data_texto": null, "descricao": "O FGC começou a pagar a garantia de até R$ 250 mil por CPF/CNPJ, em projeção de R$ 40,6 bilhões; até 16/03/2026 haviam sido pagos cerca de R$ 38,9 bilhões a 686 mil clientes, segundo o DIEESE.", "entidades": [["fgc", null, 0]], "fontes": [["poder360.com.br", "https://www.poder360.com.br/poder-economia/fgc-inicia-pagamento-a-investidores-do-banco-master", "sustenta", 0], ["dieese.org.br", "https://www.dieese.org.br/notatecnica/2026/notaTec291BancoMaster.pdf", "sustenta", 1]], "id": "ev-2026-01-17-fgc-inicia-pagamento-a-cerca-de-800-mil", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[110]", "peso": 4, "resposta": null, "titulo": "FGC inicia pagamento a cerca de 800 mil credores", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-01-23-pf-faz-a-operacao-barco-de-papel-no','ev-2026-01-23-pf-deflagra-barco-de-papel-castro','23/01/2026: a PF deflagra a operação Barco de Papel no Rioprevidência.','teia','teia:EV[115]','{"canal": "teia", "contexto": null, "data": "2026-01-23", "data_aprox": 0, "data_texto": null, "descricao": "Quatro mandados de busca no Rio. A PF apura se as aplicações foram aprovadas de forma irregular; o Rioprevidência diz que seguiram o plano anual de investimentos e que as aposentadorias estão garantidas.", "entidades": [["pf", null, 0], ["rioprevidencia", null, 1]], "fontes": [["mercadoeconsumo.com.br", "https://mercadoeconsumo.com.br/23/01/2026/economia/rioprevidencia-alvo-da-pf-foi-o-fundo-de-pensao-que-mais-investiu-no-master/amp", "sustenta", 0]], "id": "ev-2026-01-23-pf-faz-a-operacao-barco-de-papel-no", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[115]", "peso": 4, "resposta": null, "titulo": "PF faz a operação Barco de Papel no Rioprevidência", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-03-04-vorcaro-e-preso-de-novo-pf-mira-ex','ev-2026-03-04-3a-fase-vorcaro-e-preso-de-novo','04/03/2026: 3ª fase da Compliance Zero, Vorcaro é preso de novo (três redações na teia).','teia','teia:EV[124]','{"canal": "teia", "contexto": null, "data": "2026-03-04", "data_aprox": 0, "data_texto": null, "descricao": "Terceira fase da Compliance Zero: prisão preventiva de Vorcaro, prisão de Zettel, tornozeleira para Paulo Sérgio Neves de Souza e Belline Santana, bloqueio de até R$ 22 bi.", "entidades": [["daniel-vorcaro", null, 0], ["bcb", null, 1], ["paulo-sergio-neves-de-souza", null, 2], ["belline-santana", null, 3], ["pf", null, 4], ["operacao-compliance-zero", null, 5], ["fabiano-zettel", null, 6]], "fontes": [["forbes.com.br", "https://forbes.com.br/geral/2026/03/vorcaro-volta-a-ser-preso-em-nova-fase-de-operacao-sobre-master-ex-diretor-do-bc-usara-tornozeleira", "sustenta", 0], ["jornaldebrasilia.com.br", "https://jornaldebrasilia.com.br/noticias/brasil/pf-aponta-que-ex-diretor-e-ex-servidor-do-bc-receberam-dinheiro-para-ajudar-vorcaro", "sustenta", 1]], "id": "ev-2026-03-04-vorcaro-e-preso-de-novo-pf-mira-ex", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[124]", "peso": 5, "resposta": null, "titulo": "Vorcaro é preso de novo; PF mira ex-diretores do BC", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-03-04-vorcaro-e-preso-decisao-cita-r-2-2-bi-na','ev-2026-03-04-3a-fase-vorcaro-e-preso-de-novo','04/03/2026: 3ª fase da Compliance Zero, Vorcaro é preso de novo (três redações na teia).','teia','teia:EV[125]','{"canal": "teia", "contexto": null, "data": "2026-03-04", "data_aprox": 0, "data_texto": null, "descricao": "Por ordem de Mendonça, a PF prendeu Vorcaro preventivamente. Segundo a PF, ele teria tentado ocultar mais de R$ 2 bilhões em patrimônio, e a decisão cita transferências de mais de R$ 2,2 bilhões por Vorcaro e Zettel a conta do pai de Vorcaro na Reag, achado da PF em janeiro; a decisão não indica as datas. A defesa nega categoricamente.", "entidades": [["daniel-vorcaro", null, 0], ["andre-mendonca", null, 1], ["pf", null, 2], ["reag-investimentos", null, 3], ["fabiano-zettel", null, 4]], "fontes": [["conjur.com.br", "https://www.conjur.com.br/2026-mar-04/daniel-vorcaro-dono-do-banco-master-e-preso-novamente-pela-pf", "sustenta", 0]], "id": "ev-2026-03-04-vorcaro-e-preso-decisao-cita-r-2-2-bi-na", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[125]", "peso": 5, "resposta": null, "titulo": "Vorcaro é preso; decisão cita R$ 2,2 bi na Reag", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-03-28-cpmi-do-inss-termina-sem-relatorio-final','vol24','28/03/2026: a CPMI do INSS termina sem relatório final. O evento de origens (vol24) mantém o id; só acrescenta a nota sobre o texto alternativo.','teia','teia:EV[133]','{"canal": "teia", "contexto": null, "data": "2026-03-28", "data_aprox": 0, "data_texto": null, "descricao": "O parecer do relator Alfredo Gaspar, com pedido de indiciamento de 216 pessoas (incluindo Vorcaro), foi rejeitado por 19 votos a 12. O texto alternativo da base do governo, que também pedia o indiciamento de Vorcaro e Zettel, não foi votado.", "entidades": [["daniel-vorcaro", null, 0], ["cpmi-do-inss", null, 1], ["fabiano-zettel", null, 2]], "fontes": [["www12.senado.leg.br", "https://www12.senado.leg.br/noticias/materias/2026/03/28/cpmi-do-inss-termina-sem-relatorio-final", "sustenta", 0], ["diariodepernambuco.com.br", "https://www.diariodepernambuco.com.br/politica/2026/03/11710930-cpmi-do-inss-relator-pede-indiciamento-de-lulinha-vorcaro-e-mais-214.html", "sustenta", 1]], "id": "ev-2026-03-28-cpmi-do-inss-termina-sem-relatorio-final", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[133]", "peso": 4, "resposta": null, "titulo": "CPMI do INSS termina sem relatório final", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-04-16-4a-fase-ex-presidente-do-brb-e-preso','ev-2026-04-16-ex-presidente-do-brb-paulo-henrique','16/04/2026: 4ª fase da Compliance Zero, o ex-presidente do BRB Paulo Henrique Costa é preso (quatro redações: três na teia e uma no dossiê BRB).','teia','teia:EV[135]','{"canal": "teia", "contexto": null, "data": "2026-04-16", "data_aprox": 0, "data_texto": null, "descricao": "Paulo Henrique Costa foi preso por ordem de Mendonça; segundo a PF, recebeu imóveis como propina ligada à venda do Master ao BRB. A defesa o considera desnecessário e o BRB afirma ter atuado em conformidade.", "entidades": [["banco-master", null, 0], ["andre-mendonca", null, 1], ["pf", null, 2], ["brb", null, 3], ["paulo-henrique-costa", null, 4]], "fontes": [["timesbrasil.com.br", "https://timesbrasil.com.br/brasil/operacoes-da-pf/pf-prende-paulo-henrique-costa-ex-presidente-do-brb-em-nova-fase-da-compliance-zero", "sustenta", 0], ["gazetadopovo.com.br", "https://www.gazetadopovo.com.br/republica/compliance-zero-alvos-pf-envolvimento-banco-master", "sustenta", 1]], "id": "ev-2026-04-16-4a-fase-ex-presidente-do-brb-e-preso", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[135]", "peso": 4, "resposta": null, "titulo": "4ª fase: ex-presidente do BRB é preso", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-04-16-ex-presidente-do-brb-e-preso','ev-2026-04-16-ex-presidente-do-brb-paulo-henrique','16/04/2026: 4ª fase da Compliance Zero, o ex-presidente do BRB Paulo Henrique Costa é preso (quatro redações: três na teia e uma no dossiê BRB).','brb','dossie.brb.eventos[26]','{"canal": "brb", "contexto": "lado: barra", "data": "2026-04-16", "data_aprox": 0, "data_texto": null, "descricao": "A PF fala em R$ 146 mi em imóveis prometidos, R$ 74,6 mi pagos. A defesa nega crime. A nova governadora afasta 12 diretores.", "entidades": [], "fontes": [["Gazeta do Povo", "https://www.gazetadopovo.com.br/republica/ex-presidente-do-brb-e-preso-em-nova-fase-da-compliance-zero", "sustenta", 0]], "id": "ev-2026-04-16-ex-presidente-do-brb-e-preso", "natureza_id": "investigacao", "origem": "dossie", "origem_ref": "dossie.brb.eventos[26]", "peso": null, "resposta": null, "titulo": "Ex-presidente do BRB é preso", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-04-16-ex-presidente-do-brb-e-preso-pf-cita','ev-2026-04-16-ex-presidente-do-brb-paulo-henrique','16/04/2026: 4ª fase da Compliance Zero, o ex-presidente do BRB Paulo Henrique Costa é preso (quatro redações: três na teia e uma no dossiê BRB).','teia','teia:EV[137]','{"canal": "teia", "contexto": null, "data": "2026-04-16", "data_aprox": 0, "data_texto": null, "descricao": "Paulo Henrique Costa foi preso preventivamente. Segundo a PF, teria recebido seis imóveis de Vorcaro em troca de facilitar negócios sem lastro; os valores citados variam de R$ 74 milhões a R$ 146,5 milhões. A defesa nega.", "entidades": [["daniel-vorcaro", null, 0], ["pf", null, 1], ["brb", null, 2], ["paulo-henrique-costa", null, 3]], "fontes": [["letsmoney.com.br", "https://www.letsmoney.com.br/noticias/pf-prende-ex-presidente-brb-esquema-master", "sustenta", 0], ["revistaoeste.com", "https://revistaoeste.com/economia/ex-presidente-do-brb-devia-r-2-mi-ao-banco-ao-receber-imoveis-do-master", "sustenta", 1], ["movimentoeconomico.com.br", "https://movimentoeconomico.com.br/economia/justica/2026/04/22/stf-decide-se-mantem-prisao-de-ex-presidente-do-brb-por-propina-milionaria", "sustenta", 2]], "id": "ev-2026-04-16-ex-presidente-do-brb-e-preso-pf-cita", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[137]", "peso": 5, "resposta": null, "titulo": "Ex-presidente do BRB é preso; PF cita imóveis de R$ 74 a 146 mi", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-05-07-5a-fase-senador-ciro-nogueira-e-alvo','ev-2026-05-07-pf-faz-buscas-contra-o-senador-ciro','07/05/2026: 5ª fase, busca da PF contra o senador Ciro Nogueira.','teia','teia:EV[141]','{"canal": "teia", "contexto": null, "data": "2026-05-07", "data_aprox": 0, "data_texto": null, "descricao": "A PF afirma que o senador atuou em favor de interesses de Vorcaro, incluindo a ''Emenda Master'' (sobre a cobertura do FGC), em troca de vantagens. Nogueira atribui as acusações a interesses político-eleitorais.", "entidades": [["banco-master", null, 0], ["daniel-vorcaro", null, 1], ["ciro-nogueira", null, 2], ["pf", null, 3], ["fgc", null, 4]], "fontes": [["gazetadopovo.com.br", "https://www.gazetadopovo.com.br/republica/compliance-zero-alvos-pf-envolvimento-banco-master", "sustenta", 0]], "id": "ev-2026-05-07-5a-fase-senador-ciro-nogueira-e-alvo", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[141]", "peso": 4, "resposta": null, "titulo": "5ª fase: senador Ciro Nogueira é alvo", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-05-28-acordo-no-stf-abre-caminho-para','ev-2026-05-28-uniao-e-gdf-acordam-emprestimo-de-ate-r','28/05/2026: acordo no STF entre União e GDF para empréstimo de até R$ 6,6 bi do FGC ao BRB.','brb','dossie.brb.eventos[27]','{"canal": "brb", "contexto": "lado: contexto", "data": "2026-05-28", "data_aprox": 0, "data_texto": null, "descricao": "Em 13/08 a audiência termina sem avanço: os bancos pedem garantia do Tesouro.", "entidades": [], "fontes": [["Correio da Manhã", "https://www.correiodamanha.com.br/nacional/centro-oeste/2026/05/289442-gdf-fecha-acordo-bilionario-com-a-uniao-para-salvar-brb.html", "sustenta", 0]], "id": "ev-2026-05-28-acordo-no-stf-abre-caminho-para", "natureza_id": "documentada", "origem": "dossie", "origem_ref": "dossie.brb.eventos[27]", "peso": null, "resposta": null, "titulo": "Acordo no STF abre caminho para empréstimo de até R$ 6,6 bi ao BRB", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-06-18-9a-fase-da-compliance-zero-tem-jaques','ev-2026-06-18-9a-fase-jaques-wagner-e-augusto-lima-sao','18/06/2026: 9ª fase da Compliance Zero, Jaques Wagner e Augusto Lima são alvos.','teia','teia:EV[148]','{"canal": "teia", "contexto": null, "data": "2026-06-18", "data_aprox": 0, "data_texto": null, "descricao": "18 mandados na BA, SP e DF; a PF apreendeu cerca de US$ 49 mil e 13 relógios e apura apartamento em Salvador e pagamentos à família. Wagner nega.", "entidades": [["jaques-wagner", null, 0], ["pf", null, 1], ["operacao-compliance-zero", null, 2]], "fontes": [["poder360.com.br", "https://www.poder360.com.br/poder-justica/pf-deflagra-9a-fase-da-operacao-compliance-zero", "sustenta", 0], ["correiodamanha.com.br", "https://www.correiodamanha.com.br/politica/2026/06/amp/295245-operacao-expoe-elo-de-jaques-wagner-com-banco-master.html", "sustenta", 1]], "id": "ev-2026-06-18-9a-fase-da-compliance-zero-tem-jaques", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[148]", "peso": 5, "resposta": null, "titulo": "9ª fase da Compliance Zero tem Jaques Wagner como alvo", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-09-01-mendonca-tira-sigilo-de-relatorio-da-pf','ev-2026-09-01-mendonca-levanta-sigilo-de-relatorio-da','01/09/2026: Mendonça levanta o sigilo do relatório da PF sobre as mensagens a número atribuído a Moraes.','teia','teia:EV[154]','{"canal": "teia", "contexto": null, "data": "2026-09-01", "data_aprox": 0, "data_texto": null, "descricao": "O relatório cita 52 mensagens que os investigadores atribuem a Vorcaro e dirigidas a Alexandre de Moraes entre 2023 e 17/11/2025; as respostas não foram recuperadas. Moraes nega ter mantido diálogo e diz ser falsa a leitura de que atuou a favor do banqueiro. A decisão de Mendonça não nomeia Moraes nem atribui crime a ele.", "entidades": [["daniel-vorcaro", null, 0], ["alexandre-de-moraes", null, 1], ["andre-mendonca", null, 2], ["pf", null, 3]], "fontes": [["congressoemfoco.com.br", "https://www.congressoemfoco.com.br/noticia/121852/mendonca-retira-sigilo-de-apuracao-sobre-mensagens-de-vorcaro-e-moraes", "sustenta", 0], ["movimentoeconomico.com.br", "https://movimentoeconomico.com.br/economia/justica/2026/09/17/fachin-desmarca-julgamento-do-stf-sobre-atuacao-de-mendonca-no-caso-master", "sustenta", 1], ["cartacapital.com.br", "https://www.cartacapital.com.br/?p=636191", "sustenta", 2]], "id": "ev-2026-09-01-mendonca-tira-sigilo-de-relatorio-da-pf", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[154]", "peso": 5, "resposta": null, "titulo": "Mendonça tira sigilo de relatório da PF sobre mensagens a Moraes", "valor_brl": null}');
INSERT INTO evento_alias(alias, evento_id, motivo, canal_original, origem_ref_original, original_json) VALUES('ev-2026-09-15-plenario-do-stf-discute-moraes-e','ev-2026-09-15-plenario-do-stf-comeca-a-analisar','15/09/2026: o plenário do STF começa a analisar o pedido de investigar Moraes e Dino pede vista.','teia','teia:EV[161]','{"canal": "teia", "contexto": null, "data": "2026-09-15", "data_aprox": 0, "data_texto": null, "descricao": "Por 4 a 3, o plenário rejeitava a união dos casos quando Flávio Dino pediu vista; o julgamento pode voltar em até 90 dias. Não houve decisão de mérito sobre abrir investigação contra Moraes. Em 10/09, a pedido de Fachin, Mendonça havia levantado o sigilo de 15 procedimentos; em 17/09 Fachin retirou da pauta de 23/09 o julgamento sobre a atuação de Mendonça, sem nova data.", "entidades": [["stf", null, 0], ["alexandre-de-moraes", null, 1], ["andre-mendonca", null, 2], ["edson-fachin", null, 3], ["flavio-dino", null, 4]], "fontes": [["poder360.com.br", "https://www.poder360.com.br/poder-justica/supremo-salva-alexandre-de-moraes-por-ate-90-dias", "sustenta", 0], ["movimentoeconomico.com.br", "https://movimentoeconomico.com.br/economia/justica/2026/09/17/fachin-desmarca-julgamento-do-stf-sobre-atuacao-de-mendonca-no-caso-master", "sustenta", 1], ["poder360.com.br", "https://www.poder360.com.br/poder-justica/fachin-pede-e-mendonca-tira-sigilo-de-processos-do-master", "sustenta", 2]], "id": "ev-2026-09-15-plenario-do-stf-discute-moraes-e", "natureza_id": null, "origem": "teia", "origem_ref": "teia:EV[161]", "peso": 4, "resposta": null, "titulo": "Plenário do STF discute Moraes e Mendonça; Dino pede vista", "valor_brl": null}');
