INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(344,76,'sustenta','tinha um contrato com o Banco Master que previa o pagamento de R$ 129 milhões em três anos',0,'Veículo fora da lista nominal; trecho é parcial (sujeito da frase é o escritório de Viviane Barci de Moraes, esposa do ministro).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(345,288,'sustenta','filho do ministro Kassio Nunes Marques, do Supremo Tribunal Federal (STF)',0,'Republicação de reportagem do Estadão; defesa nega irregularidade.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(346,1310,'sustenta','manteve contato frequente por mais de um ano com o advogado Rodrigo Fux, filho do ministro Luiz Fux',0,'A reportagem ressalva que as mensagens não mostram Luiz Fux envolvido.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(347,300,'sustenta','o escritório passou a ser representado pelo advogado Enrique de Abreu Lewandowski, filho do ministro',0,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(348,1311,'sustenta','A empresa em questão é a Maridt, que hoje está no nome de um dos seus irmãos, o engenheiro eletricista José Eugênio',0,'Os dois nomes aparecem em frases separadas; José Carlos é descrito como ''padre'' e ex-sócio na época das aquisições.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(349,1312,'sustenta','Mario Umberto Degani, primo do ministro, e pelo advogado Euclides Gava Junior.',0,'Fonte descreve como primo; o grafo diz apenas ''familiar ou próximo'' (compatível). Republicação de matéria da Folha.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(350,1313,'sustenta','sua ex-esposa, a advogada Roberta Maria Rangel, viu o número de processos em que atuava no STF e no STJ saltar 140%',0,'Fonte descreve como ex-esposa, não vínculo atual.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(351,1314,'sustenta','o filho do procurador-geral da República, Paulo Gonet',0,'A matéria cita apenas ''Pedro Gonet'', sem o sobrenome ''Branco''. Veículo regional, fora da lista nominal.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(352,1315,'sustenta','cunhada de Hugo Motta (irmã de Luana Motta, esposa do parlamentar)',0,'Grafo diz ''familiar''; fonte: cunhada.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(353,1315,'sustenta','a ETC Participações, empresa controlada por Bianca Medeiros',0,'Vínculo é indireto (empresa da cunhada), não da família em sentido direto.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(354,313,'sustenta','a BK Financeira, empresa de Bonnie de Bonilha',0,'O trecho cita a empresa; o título e a matéria a descrevem como nora de Wagner. Segundo outra matéria, é casada com Eduardo Sodré, enteado de Wagner.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(355,1316,'sustenta','sócia da BN Financeira ao lado do advogado Moisés Dantas',0,'Metrópoles usa ''BN Financeira'' nesta matéria e ''BK Financeira'' na de 2026-03-18; nome pode variar. Vínculo com Wagner é indireto (via nora).','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(356,1316,'sustenta','Enteado do líder do governo no Senado, o secretário de Meio Ambiente da Bahia, Eduardo Sodré',0,'Fonte descreve como enteado, não ''familiar'' genérico.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(357,1317,'sustenta','O irmão do senador Ciro Nogueira (PP), Raimundo Neto e Silva Nogueira Lima, é um dos alvos da 5ª fase',0,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(358,1318,'sustenta','empresa que pertenceria ao senador Ciro Nogueira (PP-PI)',0,'Vínculo é de propriedade atribuída pela PF, não familiar; veículo fora da lista nominal.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(359,322,'sustenta','o escritório do advogado Caio Carvalho Barros, filho do governador do Distrito Federal, Ibaneis Rocha (MDB)',0,'Veículo fora da lista nominal.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(360,1319,'sustenta','para a produção sobre a vida do pai, o ex-presidente Jair Bolsonaro (PL)',0,'Parentesco é explícito só por ''pai''; a matéria não usa a palavra ''filho''. Eduardo nega ter recebido recursos.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(361,1320,'sustenta','um dos irmãos dele, o agricultor Luis Roberto',0,'Trecho parcial (irmão de Paulo Sérgio).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(362,1321,'sustenta','Valéria Rodrigues Lenhares, esposa do parlamentar Cezinha de Madureira (PL-SP)',0,'Grafia do sobrenome varia na fonte (Lenhares/Linhares). Veículo regional; contexto é a investigação de tráfico de influência em tribunais, ligada ao caso Master.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(363,362,'sustenta','de propriedade da advogada Camilla Ramos, esposa do desembargador Newton Ramos',0,'Grafo diz ''familiar''; fonte: esposa.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(364,362,'sustenta','de propriedade da advogada Camilla Ramos, esposa do desembargador Newton Ramos',0,'Fonte grafa ''Queiroga, Vieira, Queiroz & Ramos''; a sigla QVQR não aparece. Vínculo é via esposa, não do próprio desembargador.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(365,111,'sustenta','para a venda de honorários de precatórios a um fundo ligado à Reag',0,'Fonte usa ''escritório Ibaneis Rocha'', não ''Ibaneis Advocacia''. Defesa afirma afastamento desde 2018.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(366,300,'sustenta','o escritório passou a ser representado pelo advogado Enrique de Abreu Lewandowski, filho do ministro',0,'Nome ''Lewandowski Advocacia'' não conferido literalmente no trecho.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(367,298,'sustenta','o período em que ainda era cunhado do ministro Gilmar Mendes',0,'Fonte descreve como ex-cunhado.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(368,1300,'sustenta','Foi um dos fundadores do Partido da Social Democracia Brasileira (PSDB).',0,'Matéria sobre os presidentes (FHC 1995–2002) e o PSDB; não é o resultado do TSE (site do TSE inacessível no ambiente).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(369,1304,'sustenta','fundador do Partido dos Trabalhadores',0,'Posse em 1º/1/2003; vitória no 2º turno com 61,27%.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(370,1299,'sustenta','Dilma Vana Rousseff, do Partido dos Trabalhadores',0,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(370,1307,'sustenta','determinou o afastamento de Dilma Rousseff da Presidência da República pelo período de até 180 dias.',1,'Afastamento em 12/5/2016 (fim do exercício conforme descrição); saída definitiva em 31/8/2016.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(371,1308,'sustenta','manter, defender e cumprir a Constituição',0,'Posse definitiva em 31/8/2016; Temer assumiu como interino em 12/5/2016 (fonte Agência Brasil não aberta). Mandato até 31/12/2018. Página cita Temer no PMDB.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(371,1309,'sustenta','Michel Temer tem uma vida dedicada ao PMDB',1,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(372,1302,'sustenta','Jair Bolsonaro (PSL-RJ) foi eleito neste domingo (28) presidente do Brasil.',0,'Eleito pelo PSL; a fonte não trata da saída do partido em 2019 (Bolsonaro deixou o PSL em nov/2019, informação externa à fonte).','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(373,1305,'sustenta','Filiado ao PT, Lula sucede o presidente Jair Bolsonaro nos próximos quatro anos.',0,'Posse em 1º/1/2023; mandato vai até 2026 (descrição diz 2023 a 2025).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(374,1306,'sustenta','foi exercida por ele nos dois mandatos de Fernando Henrique Cardoso | indicado pelo PFL',0,'Período: a fonte indica vice-presidência de 1995 a 1º/1/2003 (descrição diz 1995 a 2002, aceitável como ano de término do mandato). Partido: PFL.','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(375,1304,'sustenta','como senador da República pelo Partido Liberal',0,'Confirma o PL na época da eleição (era senador pelo PL). Em 2011 a Agência Senado o diz no PRB. Término do mandato como vice não verificado nesta página.','fraca');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(376,1299,'sustenta','Michel Temer, do PMDB, foi empossado como vice-presidente.',1,'Trecho parafraseado a partir da leitura da página (PMDB ligado a Temer; posse em 1º/1/2011).','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(376,1309,'sustenta','para assumir como vice de Dilma Rousseff',0,'Vice de 2011 até 2016 (descrição diz 2011 a 2015). Partido PMDB confirmado na mesma página (''uma vida dedicada ao PMDB'').','boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(377,1302,'sustenta','O vice-presidente eleito é o general da reserva Hamilton Mourão (PRTB).',0,NULL,'boa');
INSERT INTO relacao_evidencia(relacao_id, evidencia_id, papel, trecho_citado, ordem, nota, qualidade) VALUES(378,1301,'sustenta','O vice-presidente eleito na chapa de Lula é Geraldo Alckmin (PSB).',0,'Alckmin migrou do PSDB para o PSB em março de 2022. Mandato vai até 2026 (descrição diz até 2025).','boa');
