INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1990-extincao-do-iaa-que-fixava-precos-do',494,'sustenta',1,'novacana.com',NULL,NULL,NULL);
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-criacao-da-organizacao-mundial-do',1222,'sustenta',0,'A brief history (WTO Annual Report 2023)','The WTO began life on 1 January 1995, succeeding the General Agreement on Tariffs and Trade (GATT) which had regulated world trade since 1948.','A fonte diz que o GATT ''regulated world trade since 1948'' (não ''em vigor''); essencialmente equivalente.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-criacao-do-proer',1223,'sustenta',0,'Resolução CMN nº 2.208, de 3/11/1995','Programa de Estímulo à Reestruturação e ao Fortalecimento do Sistema Financeiro Nacional (PROER) ... assegurar liquidez e solvência ao referido Sistema','Confirma a resolução do CMN de 3/11/1995.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-criacao-do-proer',1224,'sustenta',1,'Medida Provisória nº 1.179 de 03/11/1995','Dispõe sobre medidas de fortalecimento do Sistema Financeiro Nacional e dá outras providências.','Ementa não cita o Proer; o campo de indexação da página lista ''PROGRAMA DE ESTIMULO A REESTRUTURAÇÃO E AO FORTALECIMENTO AO SISTEMA FINANCEIRO NACIONAL (PROER)''. Confirma a MP de 3/11/1995.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-efeito-tequila-apos-a-crise-do-peso',1225,'sustenta',0,'Mexican peso crisis','coordinated a $50 billion bailout package in January 1995, to be administered by the IMF ... impact of Mexico''s crisis in Chile and Brazil became known as the ''Tequila effect''','Fonte wiki; fontes não-wiki abertas não sustentam US$ 50 bi em janeiro: Terceiro Mundo (fev/1995, rima.ufrrj.br) cita fundo de ~US$ 7 bi em 22/12/1994 dobrado para US$ 18 bi duas semanas depois; BBC Mundo (acento.com.do) fala em ~US$ 50 bi no total, ''a comienzos de 1995'', sem citar o Brasil.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-emendas-que-flexibilizam-monopolios',1226,'sustenta',0,'Emenda Constitucional nº 9, de 9 de novembro de 1995','A União poderá contratar com empresas estatais ou privadas a realização das atividades','EC 9 (petróleo, art. 177). Lida também a EC 8 (telecom, 15/8/1995, https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc08.htm) e a EC 5 (gás canalizado, 15/8/1995, art. 25 §2). EC 6 (15/8/1995) revoga o art. 171, mas a página não descreve a distinção empresa nacional/estrangeira.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-fed-passa-a-cortar-juros',772,'sustenta',0,'Open Market Operations Archive','1995: February 1 (increase 50, 6.00); July 6 (decrease 25, 5.75); December 19 (decrease 25, 5.50)','Citação é reconstrução das linhas da tabela (data, variação em pb, nível). Página não rotula explicitamente a coluna como meta de fed funds.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-greve-dos-petroleiros',1227,'sustenta',0,'Greve histórica dos petroleiros completa 15 anos','ocupou com tanques e metralhadoras as refinarias da Petrobrás ... impôs multas milionárias à FUP e aos sindicatos','Texto da imprensa da FUP publicado pela CUT (perspectiva sindical). Confirma início 3/5, 32 dias, suspensão proposta em 2/6, Exército nas refinarias em 24/5, multas do TST (26/5) e 73 demitidos. A multa é atribuída ao TST (descrição diz Justiça do Trabalho; compatível).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-mercosul-vira-uniao-aduaneira',1228,'sustenta',0,'Perguntas Mercosul (Comissão Parlamentar Conjunta do Mercosul)','O Mercosul, desde o dia 11 de janeiro de 1995, está num grau de integração comumente chamado União Aduaneira.','CONTRADIÇÃO: esta fonte dá 11 de janeiro de 1995, não 1º de janeiro; diz também que a TEC ''não está plenamente em vigor''. Outras fontes costumam dar 1/1/1995; não confirmado em fonte aberta por mim. Campo ''data'' da página não identificado.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-posse-de-fernando-henrique-cardoso',1229,'sustenta',0,'Currículo Fernando Henrique Cardoso (Fundação FHC)','Eleito Presidente da República, no primeiro turno ... com 34.337.198 votos (54,3%), 3 de outubro','Fonte institucional (não TSE). Confirma 1º turno e 54,3%; não confirma posse em 1/1/1995 (apenas ''Presidente 1995-2002''). A Wikipédia en (1994 Brazilian general election) traz 54.28%. Biblioteca digital do TSE cita 55,22% (provável base diferente, votos totais vs. válidos) e preparaenem.com cita 55% dos válidos.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-1995-posse-de-fernando-henrique-cardoso',1230,'sustenta',1,'Eleições de 1994','No dia 1º de janeiro de 1995 iniciou-se a ''Era FHC''.','Site educacional, usado só para a data da posse; informa 55% dos votos válidos, divergindo dos 54,28% da descrição.','fraca');
