INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-argentina-em-recessao',1231,'sustenta',0,'World Bank: GDP growth (annual %) - Argentina (NY.GDP.MKTP.KD.ZG)','2000: -0.78899893905691; 1999: -3.38545704063269','Confirma -0,79% em 2000 e queda também em 1999. NÃO verificado: Argentina como 2º destino das exportações brasileiras com 11,33% (nenhuma fonte aberta).','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-cassacao-do-senador-luiz-estevao',1232,'sustenta',0,'Por 56 votos a 19, Senado cassa Demóstenes Torres','pela primeira vez na sua história, cassou um senador ... em sessão fechada, houve 52 votos pela cassação do senador do Distrito Federal','Confirma ano 2000, 52 votos a favor, 18 contra, 10 abstenções e pioneirismo; não traz o dia 28/6. Congresso em Foco (outra matéria) cita ''junho de 2000'' via Correio Braziliense. Gazeta do Povo (conselho de ética) data erroneamente em 2001.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-eleicoes-municipais',1233,'sustenta',0,'Marta vence Maluf e é eleita prefeita de S.Paulo','A candidata do PT Marta Suplicy foi eleita prefeita de Sao Paulo, obtendo 3.248.115 votos (58,51%).','Confirma 2º turno em 29/10/2000 contra Maluf (PPB). Veículo regional (Diário do Grande ABC), não TSE.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-emenda-constitucional-29-saude',1234,'sustenta',0,'Emenda Constitucional nº 29, de 13 de setembro de 2000','recursos mínimos derivados da aplicação de percentuais calculados sobre','Confirma 13/9/2000; União, estados, DF e municípios aplicam percentuais mínimos de suas receitas em saúde.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-fed-leva-os-juros-a-6-50',772,'sustenta',0,'Open Market Operations Archive','2000: February 2 (increase 25, 5.75); March 21 (increase 25, 6.00); May 16 (increase 50, 6.50)','Citação é reconstrução das linhas da tabela. A última mudança listada em 2000 é 16/5 (6,50%), consistente com manutenção até o fim do ano. Altas: 25+25+50 pb (fev. 2, mar. 21, mai. 16).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-lei-de-responsabilidade-fiscal',1235,'sustenta',0,'Projeto de Lei da Câmara n° 4, de 2000 (Complementar)','Sancionada em 04/05/2000 ... CAE Parecer nº 298/2000, Relator: Senador Jefferson Péres','Confirma sanção em 4/5/2000 (LC 101), origem PLP 18/1999 da Câmara e Jefferson Péres (grafia com acento) como relator na CAE; na CCJ o relator foi Álvaro Dias. NÃO confirmado: Pedro Novais como relator na Câmara (nenhuma fonte aberta).','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-lei-de-responsabilidade-fiscal',1236,'sustenta',1,'Lei Complementar nº 101, de 4 de maio de 2000','LEI COMPLEMENTAR Nº 101, DE 4 DE MAIO DE 2000','Texto legal; não menciona relatores.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-petroleo-em-alta',1237,'sustenta',0,'Global price of Brent Crude (série FMI, anual)','1999: 18.108; 2000: 28.845 (US$/barril); 1996: 20.81; 1992: 19.36','Série do FMI (via FRED/Fed St. Louis). Confirma 18,11 em 1999 e 28,85 em 2000 e que 2000 é o maior valor entre 1992 e 2000.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2000-pico-e-inicio-do-estouro-da-bolha-da',1238,'sustenta',0,'Dot-com bubble','At its trough on October 9, 2002, the NASDAQ-100 had dropped to 1,114, down 78% from its peak.','A página dá pico do Composite de 5.048,62 em 10/3/2000; os 78% referem-se ao Nasdaq-100. International Banker (internationalbanker.com) confirma o pico 5.048,62 em 10/3/2000, mas diz queda ''more than 75 percent'' até out/2002.','fraca');
