INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-cassacoes-de-roberto-jefferson-e-jose',1239,'sustenta',0,'Dirceu é cassado por diferença de 37 votos','Logo após a meia-noite, o Plenário da Câmara cassou o deputado José Dirceu (PT-SP). ... No dia 14 de setembro, Jefferson perdeu o mandato','A matéria é de 1/12/2005 e diz que a cassação de Dirceu ocorreu logo após a meia-noite (sessão de 30/11 que virou 1/12); o dia 14/9 de Jefferson confere.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-china-encerra-a-paridade-fixa-com-o',1240,'sustenta',0,'A Look at China''s New Exchange Rate Regime','The revaluation puts the renminbi at 8.11 against the dollar, which amounts to an appreciation of 2.1%.','Trecho também menciona a cesta de moedas de referência; a página não foi checada para o dia 21/7 especificamente no trecho citado.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-denuncia-do-mensalao',1241,'sustenta',0,'20 anos de Mensalão: entenda como tudo começou','No dia 16 daquele mês, Dirceu pediu demissão da Casa Civil e retomou seu mandato de deputado.','Retrospectiva de 2025 (não da época). Confirma a entrevista de Jefferson à Folha em 6/6/2005 e a saída de Dirceu em 16/6.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-eleicao-e-renuncia-de-severino',1242,'sustenta',0,'Severino renuncia, mas promete voltar à Câmara','Severino Cavalcanti renunciou na tarde desta quarta-feira ao seu mandato de deputado federal.','A renúncia foi ao mandato de deputado (consequentemente à presidência), em 21/9/2005; a página não detalha a propina.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-eleicao-e-renuncia-de-severino',1243,'sustenta',1,'Aldo Rebelo — Portal da Câmara dos Deputados','Foi eleito presidente da Câmara dos Deputados no dia 28 de setembro de 2005, em segundo turno, por 258 votos a 243.','Confirma a eleição de Aldo em 28/9; a vitória de Severino sobre o candidato governista (fevereiro) consta em nsctotal.com.br/noticias/relembre-eleicoes-conturbadas-no-congresso (não incluída como entrada separada).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-fed-sobe-juros-em-todas-as-reunioes-do',1244,'sustenta',0,'FRB: Press Release--FOMC Statement--December 13, 2005','decided today to raise its target for the federal funds rate by 25 basis points to 4-1/4 percent.','Confirma 4,25% em 13/12; ''oito reuniões'' e início do ciclo em 30/6/2004 não verificados nesta página.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2005-katrina-e-petroleo-mais-caro',1245,'sustenta',0,'Surviving the Storm','Katrina damaged or destroyed 30 oil platforms and caused nine refineries to close','Confirma plataformas/refinarias. Preço do Brent: ver próxima entrada.','boa');
