INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-acordo-de-paris-na-cop21',1262,'sustenta',0,'The Paris Agreement','It was adopted by 195 Parties at the UN Climate Change Conference (COP21) in Paris, France, on 12 December 2015.','UNFCCC diz ''195 Parties'' (que já inclui a União Europeia como Parte); a descrição ''195 países e a UE'' pode somar a UE em duplicidade. Nenhuma das páginas abertas usa a palavra ''consenso''.','boa');
