INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-colapso-do-preco-das-commodities',1237,'sustenta',0,'Global price of Brent Crude (POILBREUSDA)','2014: 99.35; 2015: 53.02 (U.S. dollars per barrel, annual; fonte IMF)','Confirma os valores do Brent. Minério de ferro NÃO confirmado com os números do evento: o IMF Commodity Market Monthly de jan/2016 traz ferro 96.8 (2014) e 55.2 (2015), preliminar, vs. 97,39 e 56,14 do evento (https://www.imf.org/external/np/res/commod/pdf/monthly/011516.pdf). Diferença provavelmente de revisão da série.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-eduardo-cunha-assume-a-camara',1264,'sustenta',0,'Novo presidente da Câmara, Cunha quer independência sem prejuízo à governabilidade','eleito neste domingo (1º) presidente da Câmara dos Deputados para o biênio 2015-2017','Cunha 267 votos, Arlindo Chinaglia (PT-SP) 136 em segundo, primeiro turno. Chinaglia é PT-SP.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2015-fed-inicia-o-ciclo-de-alta-de-juros',1265,'sustenta',0,'Federal Reserve issues FOMC statement','the Committee decided to raise the target range for the federal funds rate to 1/4 to 1/2 percent','O comunicado não diz que é a primeira alta desde 2006 nem cita a faixa anterior; esse detalhe não foi verificado na página.','fraca');
