INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-adiamento-das-eleicoes-municipais',1272,'sustenta',0,'Emenda Constitucional nº 107, de 2 de julho de 2020','realizar-se-ão no dia 15 de novembro','Art. 1º: 15/11 e segundo turno em 29/11 (a leitura da página confirma 15/11 explicitamente; 29/11 vem do resumo do art. 1º).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-china-cresce-e-compra-um-terco-das',1273,'sustenta',0,'GDP growth (annual %) NY.GDP.MKTP.KD.ZG, 2020','CHN 2.3395; USA -2.0814; WLD -2.8862 (GDP growth, annual %, 2020)','PIB confere (China 2,34; EUA -2,08).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-china-cresce-e-compra-um-terco-das',1274,'sustenta',1,'China contribuiu com mais da metade do superávit comercial do Brasil','A participação do país saiu de 28,1% para 32,3% de 2019 para 2020.','CONTRADIÇÃO: fonte dá 32,3%, não 32,41%. O MDIC/Siscomex (gov.br) não publica o percentual: só US$ 70,08 bi para China+HK+Macau (~33%).','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-fed-zera-os-juros',1275,'sustenta',0,'Federal Reserve issues FOMC statement','the Committee decided to lower the target range for the federal funds rate to 0 to 1/4 percent.','Corte anterior em 3/3 para 1-1 1/4% (https://www.federalreserve.gov/newsevents/pressreleases/monetary20200303a.htm). Manutenção até o fim do ano: comunicado de 16/12/2020 mantém 0 a 1/4% (https://www.federalreserve.gov/newsevents/pressreleases/monetary20201216a.htm). O corte de 3/3 foi de 0,5 p.p., para 1 a 1 1/4%.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-guerra-de-precos-do-petroleo',1276,'sustenta',0,'How negative oil prices revealed the dangers of futures trading','a price war erupted between oil giants Saudi Arabia and Russia in early March','WTI a cerca de -US$ 37 em 20/4 confirmado. Data exata 8/3 não consta na página (''início de março''). Brent média 2020 = 43.33 confirmado em https://fred.stlouisfed.org/data/POILBREUSDA (série do FMI). Obs.: o -37 refere-se ao contrato de maio.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-novo-fundeb',1277,'sustenta',0,'Emenda Constitucional nº 108, de 26 de agosto de 2020','a União complementará os recursos dos fundos','Confirma promulgação 26/8/2020 e complementação (mín. 23%, progressiva a partir de 2021). A página não usa a palavra ''permanente'' (Fundeb passa ao art. 212-A) e não traz o placar 79x0 do Senado, não verificado.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-pandemia-de-covid-19',1278,'sustenta',0,'Decreto Legislativo nº 6, de 2020','Fica reconhecida, exclusivamente para os fins do art. 65 da Lei Complementar [...] a ocorrência do estado de calamidade pública','Efeitos até 31/12/2020.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-pandemia-de-covid-19',1279,'sustenta',1,'Lei nº 13.982, de 2 de abril de 2020','será concedido auxílio emergencial no valor de R$ 600,00 (seiscentos reais) mensais ao trabalhador',NULL,'boa');
