INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-pandemia-de-covid-19-2',1280,'sustenta',0,'WHO Director-General''s opening remarks at the media briefing on COVID-19 - 11 March 2020','We have therefore made the assessment that COVID-19 can be characterized as a pandemic.','Os dois eventos ''Pandemia de covid-19'' NÃO são o mesmo fato: -2 trata da declaração da OMS e do PIB mundial; o outro, das medidas do Congresso (DL 6, Lei 13.982).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-saida-de-sergio-moro-do-governo',1281,'sustenta',0,'Interferência na PF, fraude e demissão: veja dez frases de Moro','Falei ao presidente que seria uma intervenção política, e ele disse que seria mesmo.','A página não traz a contestação de Bolsonaro (parte da descrição não verificada nesta fonte).','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2020-trocas-no-ministerio-da-saude',1282,'sustenta',0,'Mandetta é demitido do Ministério da Saúde e Nelson Teich assume','O presidente Jair Bolsonaro demitiu nesta 5ª feira (16.abr.2020) o ministro Luiz Henrique Mandetta (Saúde).',NULL,'boa');
