INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-china-amplia-compras-e-eua-perdem-espaco',1284,'sustenta',0,'Mais China e menos EUA: veja ranking dos países que mais importaram produtos do Brasil em 2025','O valor total das exportações brasileiras para a China cresceu 5,99% em 2025; participação de 28,69%; EUA caíram para 10,82% e valor caiu 6,57%.','Reportagem que cita dados do MDIC (Comex Stat); página primária do MDIC/Comex Stat não aberta. Trecho condensado de várias frases da página (China 28,69% e +5,99%; EUA 10,82% ante 11,98% e -6,57%).','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-congresso-derruba-decreto-do-iof',1285,'sustenta',0,'Senado confirma derrubada do decreto do IOF e Congresso impõe derrota histórica ao governo','É a primeira vez desde 1992, 33 anos, que um decreto presidencial foi derrubado pelo Congresso.',NULL,'boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-congresso-derruba-decreto-do-iof',1286,'sustenta',1,'Câmara aprova projeto que suspende aumento do IOF','A Câmara dos Deputados aprovou proposta que suspende os efeitos de três decretos','Cobre só a votação na Câmara (25/6); a aprovação no Senado no mesmo dia consta da Exame.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-eleicao-das-mesas-da-camara-e-do-senado',1287,'sustenta',0,'Hugo Motta é o novo presidente da Câmara dos Deputados','O parlamentar foi eleito neste sábado (1º) em primeiro turno, com 444 votos. | Hugo Motta (Republicanos-PB) foi eleito presidente [...] para o biênio 2025-2026.',NULL,'boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-eleicao-das-mesas-da-camara-e-do-senado',1288,'sustenta',1,'Davi Alcolumbre é o novo presidente do Senado','Davi foi eleito durante votação em primeiro turno, com um total de 73 votos',NULL,'boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-eua-impoem-tarifa-de-50-a-produtos',1289,'sustenta',0,'Modifying the Scope of Tariffs on the Government of Brazil','an additional ad valorem duty rate of 40 percent on certain articles of Brazil','Página da Casa Branca é a ordem de 20/11/2025 (EO 14361), que cita a EO 14323 (30/7/2025) que impôs os 40%; a ordem original de 30/7 não abriu no fetch. Os 10% de abril não aparecem nesta página.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-eua-impoem-tarifa-de-50-a-produtos',1290,'sustenta',1,'Tarifaço sobre parte de exportações brasileiras entra em vigor hoje','foi imposta, em abril, a taxa mais baixa, de 10%. | elevou a tarifa para 50% contra o Brasil','A matéria não menciona explicitamente ''adicional de 40%'' nem a data de 30/7; trecho condensado de duas frases.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-eua-isentam-parte-dos-produtos-agricolas',1291,'sustenta',0,'Modifying the Scope of the Reciprocal Tariff with Respect to Certain Agricultural Products','certain agricultural products shall not be subject to the reciprocal tariff imposed under Executive [Order] 14257, as amended.','A página não nomeia café, carne, banana etc. (lista no anexo, não aberto). Esta ordem trata da tarifa ''recíproca''; a retirada dos 40% específicos do Brasil para esses itens é da ordem de 20/11/2025 (ver Agência Brasil).','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-eua-isentam-parte-dos-produtos-agricolas',1292,'sustenta',1,'Trump retira tarifa de 40% sobre produtos do Brasil como café e carne','café, chá, frutas tropicais e sucos de frutas, cacau e especiarias, banana, laranja, tomate e carne bovina','CONTRADIÇÃO DE DATA: a retirada dos 40% sobre itens brasileiros foi anunciada em 20/11/2025; 14/11/2025 é a data da ordem sobre a tarifa recíproca de produtos agrícolas.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-fed-corta-juros-tres-vezes',1293,'sustenta',0,'Federal Reserve issues FOMC statement','lower the target range for the federal funds rate by 1/4 percentage point to 3-1/2 to 3-3/4 percent','Só o comunicado de dezembro foi aberto; os cortes de setembro e outubro não foram confirmados em página própria.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-isencao-do-ir-ate-r-5-mil',1294,'sustenta',0,'Lula sanciona isenção do IR para quem ganha até R$ 5 mil; entenda o que muda','sancionou, nesta quarta-feira, 26, a isenção do Imposto de Renda (IR) para quem ganha até R$ 5 mil','A matéria não cita Arthur Lira.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-isencao-do-ir-ate-r-5-mil',1295,'sustenta',1,'Comissão da Câmara aprova projeto que isenta de Imposto de Renda quem ganha até R$ 5 mil mensais','O relatório do deputado Arthur Lira (PP-AL) também elevou de R$ 7 mil para R$ 7.350','Confirma Lira como relator na Câmara (comissão especial); não trata da sanção.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-stf-torna-bolsonaro-reu-e-o-condena',1296,'sustenta',0,'Primeira Turma do STF torna, por unanimidade, Bolsonaro e 7 aliados réus por tentativa de golpe de Estado','Agora, ele e mais sete aliados responderão a um processo judicial','Página do STF não localizada/aberta.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-stf-torna-bolsonaro-reu-e-o-condena',1297,'sustenta',1,'STF condena Bolsonaro a 27 anos e 3 meses de prisão em regime inicial fechado por tentativa de golpe de Estado e outros crimes','fixar a pena do ex-presidente Jair Bolsonaro a uma pena de 27 anos e 3 meses de prisão','Pena exata é 27 anos e 3 meses (descrição diz 27 anos). Página do STF não aberta.','fraca');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-tarifas-dos-eua-sobre-o-brasil',1289,'sustenta',0,'Modifying the Scope of Tariffs on the Government of Brazil','an additional ad valorem duty rate of 40 percent on certain articles of Brazil','Página da Casa Branca é a ordem de 20/11/2025 (EO 14361), que cita a EO 14323 (30/7/2025) que impôs os 40%; a ordem original de 30/7 não abriu no fetch. Os 10% de abril não aparecem nesta página.','boa');
INSERT INTO evento_evidencia(evento_id, evidencia_id, papel, ordem, rotulo, trecho_citado, nota, qualidade) VALUES('ev-2025-tarifas-dos-eua-sobre-o-brasil',1298,'sustenta',1,'Treasury Sanctions Alexandre de Moraes','Alexandre de Moraes has taken it upon himself to be judge and jury in an unlawful witch hunt.','Comunicado do Tesouro dos EUA (OFAC) confirma a sanção a Moraes em 30/7/2025.','boa');
