INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(60,'lacuna','teia',NULL,NULL,'Data de aquisição do Letsbank e do Banco Vipal: não encontrada.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(61,'lacuna','teia',NULL,NULL,'Denúncia formal da PGR contra Vorcaro ou ação penal recebida pelo STF: não encontrada.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(62,'lacuna','teia',NULL,NULL,'Delação premiada de Vorcaro homologada: não; PF e PGR rejeitaram três propostas (maio, junho e setembro de 2026).',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(63,'lacuna','teia',NULL,NULL,'Condenação criminal de Vorcaro: nenhuma encontrada; a única decisão sancionadora é a multa administrativa da CVM, com recurso possível.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(64,'lacuna','teia',NULL,NULL,'Instalação de CPI ou CPMI do Master: não confirmada em nenhuma fonte; em fevereiro/2026 estava parada.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(65,'lacuna','teia',NULL,NULL,'11ª fase da Compliance Zero: não encontrada até 09/10/2026.',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(66,'lacuna','teia',NULL,NULL,'Operação da PF contra Antônio Rueda ou ACM Neto: não confirmada; só há relato secundário (BPMoney, 10/09/2026) de que Vorcaro os citaria em proposta de delação, e eles negam.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(67,'lacuna','teia',NULL,NULL,'Balanço do Master de 2025 e números de 2018 a 2020 (ativos, patrimônio, captação, lucro): não encontrados.',9,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(68,'lacuna','teia',NULL,NULL,'Resultado final do TCU sobre a atuação do BC: não encontrado.',10,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(69,'lacuna','teia',NULL,NULL,'Eventos de 2020 em fonte oficial sobre a operação ''Fundo Fake'' (PF) ligada ao Máxima: não confirmado.',11,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(70,'aviso','teia','NUM.2022.fontes_adicionais',NULL,'https://economicnewsbrasil.com.br/2023/07/17/estrategicas-banqueiro-daniel-vorcaro-em-negociacao-bilionaria-para-aumentar-participacao-no-banco-master/',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(71,'aviso','teia','NUM.2023.fontes_adicionais',NULL,'https://monitormercantil.com.br/master-aumentou-intermediacao-financeira-em-2023/
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(72,'aviso','teia','NUM.2024.fontes_adicionais',NULL,'https://www.dieese.org.br/notatecnica/2026/notaTec291BancoMaster.pdf',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(73,'narrativa','origens','banco',NULL,'A história do Banco Máxima antes de 2017 é pouco documentada em fontes abertas. Algumas reportagens dizem que a instituição surgiu como a corretora Máxima na década de 1970 (parte das fontes fala em 1974) e que se tornou banco na década de 1990, sem apresentar o ato do Banco Central. Nenhuma fonte consultada nomeia os fundadores. Em 2009 e 2010, comunicados do BC registram a eleição de José Costa Gonçalves para a diretoria e a declaração de propósito de Cristiano Ferreira Abdalla para diretor adjunto da Máxima S.A. Corretora de Títulos e Valores Mobiliários, que tem CNPJ próprio. Em 2017 a sede do banco, segundo o BC, ficava na Avenida Atlântica, em Copacabana, no Rio de Janeiro.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(74,'narrativa','origens','banco',NULL,'Em 2013, o Valor mostrou um banco de nicho no crédito imobiliário: carteira de R$ 250 milhões, compra de financiamentos do balanço de incorporadoras, capital de giro a construtoras e emissão de CRIs. A diretora comercial Claudia Martinez disse que o banco tentara financiar a construção e achou a operação cara e competitiva; a matéria registra que o banco antes atuava no consignado. Em agosto de 2013 a Moody''s rebaixou as notas do banco, citando riscos de descasamento; a diretora respondeu que a agência avaliou uma fase de transição.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(75,'narrativa','origens','banco',NULL,'A partir de 2014 o Ministério Público Federal aponta irregularidades. Segundo o MPF, em novembro de 2014 recursos do próprio banco teriam inflado as cotas de um fundo, o Ravena, que recebera ações da FC Max, empresa de turismo controlada pelo Máxima, por meio de um empréstimo simulado de R$ 7 milhões que circulou por outros fundos. O MPF diz que o ajuste reduziu o prejuízo do semestre a R$ 5,1 milhões, e que entre janeiro de 2015 e março de 2016 o banco prestou informações incorretas ao BC para dissimular a insuficiência de capital. O banco atual respondeu que os ex-gestores não têm vínculo com ele e que não é parte do processo. A reportagem de 2021 não traz a defesa dos acusados.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(76,'narrativa','origens','banco',NULL,'Em 2016, segundo reportagens, a carteira imobiliária sofreu com a inadimplência e o banco esteve à beira da falência. O Valor calculou um rombo potencial para o FGC de R$ 827 milhões naquele ano. Nesse contexto, segundo reportagens, Saul Dutra Sabbá, controlador e ex-diretor-presidente, teria oferecido a Daniel Vorcaro uma participação no controle. Em 15 de setembro de 2017 os dois assinaram o contrato de compra e venda, que o Valor descreve como 56,87% do capital por R$ 40 milhões, e o BC publicou, em 1º de novembro, a declaração de propósito. Sabbá disse ter se desligado formalmente da gestão em 2017.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(77,'narrativa','origens','banco',NULL,'Em 27 de julho de 2018, o BC concluiu, na Decisão 946/2018 (decisão administrativa), que o banco fora conduzido contra normas e boa técnica bancária: teria inflado o valor de um investimento para reduzir perda contábil e informado dados incorretos para dissimular falta de capital. Aplicou multa de R$ 100 mil ao Máxima e inabilitou Sabbá por nove anos e Alberto Maurício Caló por oito. O caso chegou ao CRSFN, que o pautou em novembro de 2020; o resultado não consta das fontes. Outro processo do BC envolvendo a corretora, Abdalla, Gonçalves e Sabbá também chegou ao conselho.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(78,'narrativa','origens','banco',NULL,'A venda só se concluiu depois de idas e vindas: segundo os votos do BC divulgados em 2026, o BC rejeitou o pedido em fevereiro de 2019 (13 de fevereiro, segundo o Let''s Money), por falta de comprovação da origem dos recursos e da capacidade financeira dos compradores, e o aprovou em 14 de outubro de 2019, após novos aportes. Neste ponto a história do banco antigo termina e a do grupo de Daniel Vorcaro começa; em 2021 o Máxima passou a se chamar Master.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(79,'narrativa','origens','banco',NULL,'Para os antigos gestores, o desfecho veio depois. O MPF denunciou cinco pessoas e a Justiça Federal de São Paulo recebeu a denúncia em 2021. O STJ, em outubro de 2024 segundo o Migalhas, limitou a ação ao crime de gestão fraudulenta. Em 2025, segundo o Money Times, Sabbá foi condenado a três anos em regime aberto (o Jornal de Brasília diz que outros ex-dirigentes foram absolvidos), e em 5 de fevereiro de 2026 a Justiça homologou acordo de não persecução penal, com serviços comunitários e pagamento de R$ 100 mil, segundo o Jornal de Brasília. A defesa de Sabbá não se manifestou nas reportagens consultadas.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(80,'narrativa','origens','familia',NULL,'A trajetória empresarial da família Vorcaro começa, segundo o site do próprio Grupo Multipar citado por Poder360 e Band em 2026, em Belo Horizonte, há cerca de 35 anos (por volta de 1991), com Henrique Moura Vorcaro à frente da Vorcaro Imóveis e da Centro Sul Empreendimentos. O grupo teria se ampliado para engenharia, energia, agronegócio, mineração e hotelaria, segundo o Hoje em Dia; a lista de sócios não aparece nas reportagens abertas. Daniel Bueno Vorcaro nasceu em 6 de outubro de 1983 na capital mineira e estudou no Ibmec, em curso que as fontes ora chamam de Economia, ora de Administração com MBA. Aos 19 ou 20 anos, segundo o Brazil Journal, ele comprou uma empresa de sistema de ensino dos herdeiros do fundador e a revendeu a um grupo do Sul; a Wikipedia liga o início da vida empresarial dele à PQS Empreendimentos Educacionais, adquirida pelo pai.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(81,'narrativa','origens','familia',NULL,'Em outubro de 2011, o Estado de Minas noticiou a retomada das obras de um hotel de luxo no prédio inacabado do Bulevar Arrudas, no Centro de BH, com 405 apartamentos e R$ 200 milhões de investimento. O jornal chamou Daniel de diretor-executivo da Multipar e idealizador do projeto, e Henrique de presidente do grupo. Em 2014, segundo o Alma Preta, Daniel ficou com o nome sujo no Serasa por causa de uma dívida de mais de R$ 1 milhão com um escritório de advocacia contratado pelas empresas da família em 2010; a família alegou serviço mal executado, a Justiça não anulou o acordo e a reportagem não informa o desfecho. Reportagens de 2026 dizem que uma delação de 2019 acusa a captação de R$ 100 milhões em fundos de pensão para o hotel com propina, o que os delatores alegam e a reportagem não informa ter sido verificado; uma coluna do Brasil 247 diz que as obras pararam em 2014, e a defesa dos Vorcaro diz que 95% da obra foi entregue.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(82,'narrativa','origens','familia',NULL,'A chegada ao Banco Máxima aparece em 2016, quando Saul Sabbá, dono do banco, teria oferecido a Daniel uma participação, após ambos operarem fundos imobiliários. Segundo o Let''s Money, com apuração do Valor, o BC tratou em agosto de 2017 da entrada de Daniel com 20%; segundo o Jornal de Brasília, em 15 de setembro de 2017 ele negociou 56,87% do capital por R$ 40 milhões, pagos em grande parte com cotas do fundo Brazil Realty, e o BC suspeitou de uma circularização do dinheiro entre o banco, empresas de Daniel e fundos. Em janeiro de 2018, segundo a InvestNews, havia nova diretoria. O InfoMoney e outras fontes divergem sobre o ano em que ele assumiu o comando. O Fator publicou, em 2026, que minutas não assinadas de 2016 e 2017 previam a participação de Henrique, o que a defesa dele nega.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(83,'narrativa','origens','familia',NULL,'Em 13 de fevereiro de 2019 (outra reportagem fala em janeiro), o diretor Sidnei Corrêa Marques vetou o pedido por falta de comprovação clara da origem dos recursos e da capacidade econômica. Fontes ouvidas pelo Valor disseram que a má fama da família em BH dominou a discussão, embora o voto não a tenha analisado. Em 2 de maio, Daniel apresentou novo pedido com Felipe Wallace Simonsen e Armando Miguel Gallo Neto, e entre março e junho aportou R$ 70 milhões, com outros R$ 30 milhões dos demais sócios. Em 14 de outubro de 2019, o diretor João Manoel Pinho de Mello, já na gestão Roberto Campos Neto, aprovou a operação, sob o argumento de que o veto não considerara as projeções de caixa e os laudos de mercado. O Valor, em fonte única, afirma que uma prisão preventiva de cinco dias foi decretada em Ji-Paraná em 29 de outubro de 2019, nunca cumprida e depois revogada.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(84,'narrativa','origens','familia',NULL,'Em maio de 2019, a CVM enviou o Ofício 110/2019 sobre debêntures da C.I.P. e da Simsan colocadas pela Máxima CCTVM, que foram liquidadas; Daniel e Luiz Bull, diretores, propuseram um termo de compromisso e, segundo voto de dezembro de 2020, pagariam R$ 250 mil cada, sem julgamento do mérito, segundo a CNN Brasil. Em 2020, segundo a CNN Brasil, Augusto Lima entrou na sociedade do Master levando o Credcesta (outras fontes o põem em 2019), e Maurício Quadrado associou-se para tocar o banco de investimento. Em setembro de 2020, a Hapvida anunciou a compra do Promed por R$ 1,5 bilhão; o Brazil Journal aponta Henrique como vendedor. Em agosto de 2021, o Máxima virou Master, com receita de quase R$ 1 bilhão em 2020, segundo Daniel.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(85,'narrativa','origens','familia',NULL,'Desdobramentos posteriores: em 8 de setembro de 2026, a CVM multou Daniel, Henrique e Felipe Vorcaro no caso do fundo Brazil Realty, em decisão administrativa da qual cabe recurso, e a Revista Oeste noticiou, em janeiro de 2026, cerca de R$ 8 milhões em dívida ativa da União em que o pai e a irmã constam como responsáveis, com exigibilidade suspensa.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(86,'narrativa','origens','ida',NULL,'A Igreja Batista da Lagoinha nasceu em 1957 em Belo Horizonte, passou à liderança de Márcio Valadão em 1972 e se expandiu, com mais de 600 unidades segundo o Correio Braziliense, rádio e TV próprias (Rede Super, que a Wikipedia diz ter sido vendida à igreja em 2000) e, depois da transição de dezembro de 2022, a Lagoinha Global sob André Valadão. Em 2024-2025, André e a mulher, Cassiane, também lideraram o Clava Forte Bank, fintech que saiu do ar em novembro de 2025. As fontes abertas não mostram a família Vorcaro como sócia desse banco.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(87,'narrativa','origens','ida',NULL,'O vínculo da família com a igreja é antigo e, em termos pessoais, está bem relatado: Valadão diz conhecer Daniel há mais de 30 anos, chamou Henrique e Aline Vorcaro de ''amigos da minha vida'' num culto (segundo O Globo, via Brasil 247), teria celebrado em 2018 o casamento de Fabiano Zettel com Natália Vorcaro, e Daniel apresentou um programa na Rede Super por volta de 2008. Natália é descrita como pastora. Zettel veio da Bola de Neve em 2024 e presidiu a unidade do Belvedere, cujo CNPJ foi aberto em setembro de 2024 (as fontes divergem sobre a inauguração) e que fechou em 15/03/2026. A igreja diz que ele era pastor voluntário e foi afastado em novembro de 2025. Amizade, pastorado e casamento são fatos lícitos.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(88,'narrativa','origens','ida',NULL,'Sobre a hipótese de que o pai de Daniel ajudou a Lagoinha, há dois níveis. No primeiro, reportagens (Folha, piauí via Agência Pública, Gazeta do Povo) dizem que Henrique Vorcaro, convertido ao meio evangélico, financiou projetos da igreja, foi um dos principais financiadores da Rede Super e ajudou a quitar um BMW de André Valadão. Isso é reportado sem valores, datas precisas ou documentos; a assessoria da igreja diz que o carro foi compra pessoal de Valadão há cerca de 25 anos, e não há resposta de Henrique. No segundo nível há dados de um relatório do Coaf: R$ 120 mil enviados por Henrique à conta da Lagoinha Belvedere entre dezembro de 2024 e dezembro de 2025 (quatro operações, segundo Itatiaia, ICL e Bahia Notícias; três, segundo o Brasil 247). O Brasil 247, fonte única nesse ponto, diz ainda que a HV Empreendimentos, ''administrada por Henrique Vorcaro'', enviou R$ 700 mil. É lícito doar a uma igreja, e o valor é pequeno diante dos R$ 28,5 milhões de créditos da conta.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(89,'narrativa','origens','ida',NULL,'O grosso do dinheiro identificado veio de Zettel: R$ 19,2 milhões em 26 operações, segundo o Coaf, numa conta que movimentou R$ 57,1 milhões (créditos e débitos) contra faturamento presumido de R$ 950 mil. O Coaf classificou a movimentação como atípica, o que não prova crime, e a origem do dinheiro não é identificada; o Diário do Comércio (Folhapress) diz que PF e Coaf suspeitam de ''conta de passagem'', mas o Itatiaia afirma que isso não está comprovado. O Brasil 247, com base em documentos do STF, relata mensagens em que Zettel teria cobrado Daniel por recursos da obra, incluindo uma rubrica de R$ 2 milhões; o pagamento não foi confirmado. Aparecem também a ex-mulher de Daniel (R$ 101,6 mil) e a Lagoinha Participações (R$ 1 a 1,1 milhão), cujo nome coincide com o da igreja, sem relação demonstrada.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(90,'narrativa','origens','ida',NULL,'A Lagoinha Global diz que cada igreja tem autonomia, que foi informada de que o dinheiro era para reformas e não doações, que não conhecia os valores e que não tem vínculo institucional com o Master. André Valadão pediu perdão aos fiéis por ter confiado em pessoas e negou vínculo seu ou da igreja com o escândalo.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(91,'narrativa','origens','ida',NULL,'Não está sustentado: grandes doações do pai, construtoras da família erguendo templos, terrenos ou imóveis cedidos, empréstimos, patrocínio de eventos ou TV pela família, ou a ideia de que Henrique Vorcaro tenha sido o grande mantenedor da Lagoinha. O repasse de R$ 3,9 milhões do Master à Amando Vidas, do casal Valadão, é relatado pelo SBT News a partir de relatório do Coaf (2022), mas a empresa e Valadão o negam. Henrique foi preso em 14/05/2026 por outras acusações, que as fontes não ligam aos repasses à igreja. A leitura mais precisa: o pai foi apresentado como benfeitor próximo da igreja, com R$ 120 mil registrados pelo Coaf (R$ 820 mil se a atribuição da HV se confirmar) e relatos não quantificados; o dinheiro maior veio de Zettel, de origem não identificada.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(92,'narrativa','origens','volta',NULL,'A hipótese de que ''a Lagoinha ajudou o pessoal do Vorcaro'' não se sustenta no sentido institucional, mas há fatos relatados sobre pessoas e pontes. O ponto central é Fabiano Zettel, cunhado de Daniel Vorcaro, casado com Natália Vorcaro em cerimônia que teria sido celebrada por André Valadão em 2018, pastor voluntário segundo a igreja e presidente da unidade Lagoinha Belvedere. A PF e o ministro André Mendonça o descrevem como operador financeiro do grupo de Vorcaro: foi detido em 14/01/2026 e preso em 04/03/2026, sob suspeita de operacionalizar pagamentos ao grupo ''A Turma'' e a servidores do Banco Central por contratos simulados. A defesa diz que suas atividades são lícitas e alheias à gestão do Master. Reportagens com dados de imposto de renda dizem que ele declarou R$ 190,2 milhões em lucros do fundo Kairós.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(93,'narrativa','origens','volta',NULL,'Sobre dinheiro, o que está nos documentos vai da família para a igreja, não ao contrário. O Coaf, com alerta do Banco do Brasil, registrou R$ 57,1 milhões de movimentação (créditos e débitos) na conta da Belvedere entre dezembro de 2024 e dezembro de 2025, contra faturamento presumido de R$ 950 mil. Zettel enviou R$ 19,2 milhões, Henrique Vorcaro R$ 120 mil, a ex-mulher de Daniel R$ 101,6 mil e um investigado do grupo ''A Turma'', R$ 22 mil; ICL e Brasil 247 listam ainda duas empresas. As saídas foram em boa parte para construtoras, mas o destino da maior parte dos débitos não é detalhado. Investigadores levantam a hipótese de conta de passagem, mas o relatório não identifica a origem do dinheiro e o Coaf ressalva que não prova crime. A Folha contou ainda 54 repasses de R$ 40,9 milhões; a diferença para o Coaf não está explicada. A Lagoinha Global diz que cada unidade tem autonomia, que foi informada de que os recursos eram para obras e não doações, e que desconhecia o volume; a unidade fechou em 15/03/2026.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(94,'narrativa','origens','volta',NULL,'As fontes abertas consultadas não registram aplicações da igreja no Master, compra de papéis, empréstimos, pagamentos da igreja a empresas da família, imóveis da igreja ou a igreja entre credores da liquidação. Também não há prova de oferta de produtos do banco a fiéis. O Clava Forte Bank, fintech de Valadão e da esposa, saiu do ar em novembro de 2025 e teve o fim anunciado em janeiro de 2026; a Pública registrou que o elo com o Master não estava comprovado, e Valadão nega qualquer vínculo.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(95,'narrativa','origens','volta',NULL,'No campo político, o fato mais claro é uma ponte pessoal: em 27/04/2024 Vorcaro pediu a Valadão que falasse com o deputado Nikolas Ferreira, e Valadão admitiu ter apenas aproximado os dois. Zettel doou R$ 3 milhões a Bolsonaro e R$ 2 milhões a Tarcísio em 2022, declarados ao TSE; a alegação de que seriam propina vem de proposta de delação de Vorcaro rejeitada por PF e PGR, e Tarcísio e o presidente do PSD negam. Nikolas admitiu voos em jato ligado a Vorcaro em 2022, e a igreja diz que ele e o pastor Guilherme Batista não são membros. O senador Carlos Viana, que presidiu a CPMI do INSS, enviou R$ 3,6 milhões em emendas a uma fundação da Lagoinha; Dino pediu explicações e a CGU apontou irregularidade na escolha da fundação em emenda de 2019 ou 2020, mas nenhuma fonte liga as emendas ao Master, e Viana nega favorecimento.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(96,'narrativa','origens','volta',NULL,'Nas investigações, a Lagoinha como instituição aparece citada, não como alvo. Valadão e Zettel constaram em requerimentos da CPMI do INSS; o relatório alternativo da base governista, não votado, fala em ''conexões'' com a Lagoinha, mas a CPMI terminou sem relatório final. As fontes abertas não registram buscas em endereços da igreja nem inquérito da PF contra Valadão. Há ainda o relato do SBT News, a partir de relatório do Coaf, de que o Master repassou R$ 3,9 milhões em 2022 a uma produtora de Valadão e da esposa, que ele e a empresa negam.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(97,'narrativa','origens','volta',NULL,'A reação da igreja foi nota de 15/01/2026, o afastamento de Zettel em novembro de 2025 (segundo ela), nota de 10/03/2026 chamando de pessoais as relações entre famílias e pedido de perdão de Valadão em março. Não há declaração de Márcio Valadão nas fontes. O que está sustentado: vínculos pessoais, convivência pública, conta da unidade com fluxo atípico alimentado por Zettel e por familiares, e uma ponte política. O que não está: a igreja como ator que favoreceu Vorcaro.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(98,'sintese','origens','familia_para_igreja',NULL,'Está documentado o vínculo pessoal e religioso antigo (Valadão diz conhecer Daniel há mais de 30 anos; Natália Vorcaro Zettel é descrita como pastora; o cunhado Fabiano Zettel presidia a unidade Belvedere) e um relatório do Coaf, divulgado em setembro de 2026, que registra na conta da Belvedere R$ 19,2 mi enviados por Zettel e R$ 120 mil por Henrique Vorcaro (quatro operações, três segundo o Brasil 247) entre 24/12/2024 e 08/12/2025, movimentação classificada como atípica, sem origem identificada e sem conclusão de crime; a Lagoinha Global diz que foi informada de que eram recursos para reformas e que desconhecia os valores. É só relato de imprensa, sem valores, datas ou documentos, que Henrique foi um dos principais financiadores da Rede Super (2000), financiou projetos da igreja e ajudou a quitar um BMW de Valadão (a igreja diz que foi compra pessoal dele há cerca de 25 anos), e, em fonte única (Brasil 247), que a HV Empreendimentos, ''administrada por Henrique'', enviou R$ 700 mil. Não têm sustentação grandes doações do pai, construtoras da família erguendo templos, terrenos, empréstimos, patrocínios, nem Henrique ter ''comprado'' a Rede Super. Doar a uma igreja é conduta lícita, e nenhuma fonte liga as apurações contra Henrique (preso em 14/05/2026) aos repasses à igreja.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(99,'sintese','origens','igreja_para_familia',NULL,'Nenhuma fonte documenta ajuda financeira ou institucional da Lagoinha, como instituição, à família Vorcaro ou ao Master: os fluxos identificados no Coaf vão para a conta da unidade Belvedere, embora as fontes não detalhem o destino da maior parte dos R$ 28,6 mi em débitos (só R$ 4,9 mi a construtoras). Está documentado ou admitido o papel de Zettel (detido em 14/01/2026 e preso em 04/03/2026, apontado pela PF como operador financeiro de Vorcaro, o que a defesa nega) e o de André Valadão como ponte entre Vorcaro e o deputado Nikolas Ferreira em 2024 (admitido por ele, que nega envolvimento com o Master); a igreja diz não ser parte de investigação, e nenhuma fonte lida a nomeia como investigada. É só relato ou requerimento o repasse de R$ 3,9 mi do Master a produtora de Valadão e da esposa (relatório do Coaf lido via SBT, negado), os pedidos de quebra de sigilo na CPMI, a menção a ''conexões'' em relatório alternativo não votado e as emendas de Viana à Fundação Oásis (sem ligação com o Master nas fontes). Não têm sustentação a igreja como braço financeiro, aplicações no Master, inquérito da PF contra Valadão e as falas duras atribuídas a Lula (a CNN não as registra).',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(100,'nao_sustentado','origens','ida','O pai de Daniel Vorcaro ''bancou'' ou sustentou a Lagoinha ao longo dos anos, em larga escala.','Há duas bases concretas, ambas modestas ou vagas: (1) o Coaf lista R$ 120 mil de Henrique Vorcaro na conta da Belvedere entre dez/2024 e dez/2025; (2) reportagens (Folha, piauí via Agência Pública, Gazeta do Povo) dizem que ele financiou projetos da igreja, doou para viabilizar a Rede Super e ajudou com um BMW de Valadão, sem valores, datas exatas ou documentos. Não achei doação, dízimo, terreno ou obra de grande valor atribuído a ele com fonte primária.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(101,'nao_sustentado','origens','ida','Construtoras da família Vorcaro construíram ou reformaram templos da Lagoinha.','Nenhuma fonte aberta diz isso. O Coaf informa que a conta da Belvedere pagou R$ 4,9 milhões a construtoras (Jorlan, Muzzi Misk, AFEB, FDS) e O Globo cita um arquiteto amigo de Nikolas Ferreira; nenhuma é ligada à família Vorcaro ou à Multipar nas matérias abertas. O Grupo Multipar atua também em construção, mas sem vínculo com a igreja nas fontes.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(102,'nao_sustentado','origens','ida','A família doou terrenos ou imóveis, ou cedeu/alugou espaços à Lagoinha.','Não encontrei. O aluguel mensal do Belvedere (cerca de R$ 420 mil, Gazeta do Povo) é citado sem identificar o locador. Super Empreendimentos, de que Zettel foi diretor, tem imóveis em BH, SP e Brasília, mas nenhuma fonte os liga à igreja.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(103,'nao_sustentado','origens','ida','Banco Master ou a família patrocinou congressos, turnês, programas de TV, compra de horário ou equipamentos da Lagoinha.','Não localizei fonte. A única transferência do Master a entidade de Valadão é a de R$ 3,9 milhões à Amando Vidas (Coaf, 2022), negada pela empresa e descrita pelo SBT como operação imobiliária. A Agência Pública diz que um dirigente do Amar Brasil (Felipe Macedo Gomes, membro da Lagoinha) teria patrocinado a festa de fim de ano de 2024 no Allianz Parque; ele nega e não é da família Vorcaro.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(104,'nao_sustentado','origens','ida','A família Vorcaro emprestou dinheiro à Lagoinha ou a pastores, ou pagou salários a líderes.','Nenhuma fonte aberta. O único fluxo documentado para pastor é de Zettel (cunhado) à conta da unidade que ele presidia, e a Lagoinha Global afirma que os recursos eram para reformas.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(105,'nao_sustentado','origens','ida','A fintech Clava Forte Bank tinha a família Vorcaro ou o Banco Master como sócio ou parceiro.','As fontes citam como controladores só André e Cassiane Valadão. A Agência Pública diz que a ligação com o Master está ''no campo da suposição''; o deputado Rogério Correia pediu apuração, e Valadão nega.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(106,'nao_sustentado','origens','ida','As emendas Pix de R$ 3,6 milhões do senador Carlos Viana à Fundação Oásis (ligada à Lagoinha) têm relação com a família Vorcaro.','A decisão de Flávio Dino (19/03/2026) trata de emendas de 2019, 2023 e 2025 à fundação; a Jovem Pan e o Brasil de Fato não citam parentes de Vorcaro. Viana nega irregularidade.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(107,'nao_sustentado','origens','ida','André Valadão se casou com Natália Vorcaro.','Um resumo do texto do Mais Goiás (Folha) parecia dizer isso, mas Gazeta do Povo e Brasil 247 (O Globo) afirmam que Valadão celebrou o casamento de Zettel e Natália em 2018. Tratei como celebrante.',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(108,'nao_sustentado','origens','ida','Henrique Vorcaro ''comprou'' a Rede Super.','Um resumo da Wikipedia atribui à piauí que o pai adquiriu a emissora. Isso contradiz The Intercept e a própria Wikipedia (Rede Super), que dizem que a emissora pertence à igreja desde 2000; as demais fontes falam em financiamento ou doações. Não consegui abrir a piauí.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(109,'nao_sustentado','origens','vol','A Igreja Batista da Lagoinha, como instituição, ajudou a família Vorcaro ou o Master (igreja como braço financeiro)','Nenhuma fonte aberta documenta dinheiro, aval, papel ou contrato da Lagoinha Global ou da Matriz que beneficie Vorcaro ou o Master. Os fluxos do Coaf vão da família para a conta da unidade Belvedere, não da igreja para a família. A hipótese de "conta de passagem" é de investigadores sobre o uso da conta por Zettel e o Coaf não identifica a origem dos R$ 19,2 mi. A igreja diz não ser parte de nenhuma investigação e Viana disse que a estrutura investigada tinha CNPJ próprio. Nenhuma autoridade citada nas fontes nomeia a Lagoinha como investigada.',9,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(110,'nao_sustentado','origens','vol','A igreja ou entidades ligadas aplicaram dinheiro, compraram papéis ou emprestaram ao Master, ou estão entre os credores da liquidação','Não encontrei qualquer fonte sobre aplicações da Lagoinha no Master, nem lista de credores que cite a igreja. O único dado de aplicação em fundo é o de Zettel (Kairós), pessoa física. Lacuna, não prova de ausência.',10,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(111,'nao_sustentado','origens','vol','O Master ofereceu produtos (CDB, cartões, consignado) a fiéis em cultos ou por meio do Clava Forte','Não achei reportagem que documente oferta de produtos do Master a membros. O Clava Forte era correspondente bancário sobre a CDC SCD e a Dock; a Pública diz que a atuação conjunta com o Master não estava comprovada e dependia de RIFs. Valadão nega qualquer vínculo societário, operacional ou financeiro. O cartão consignado "Fé" (2019) é da marca de Valadão, a igreja se distanciou e nada o liga ao Master.',11,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(112,'nao_sustentado','origens','vol','O Clava Forte teve sócio ligado ao Master ou a Zettel','A Pública aponta como fundadores Valadão e Cassiane; não cita Zettel nem Master como sócios. A matéria de 22/01/2026 não informa a estrutura societária.',12,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(113,'nao_sustentado','origens','vol','Houve busca e apreensão em endereços da Lagoinha ou prisão de líderes da igreja além de Zettel','As fontes abertas não registram mandado contra templos, a Matriz ou Valadão. A fase 3 teve 15 mandados em SP e MG sem lista dos locais nas matérias abertas. Não consegui confirmar nem excluir.',13,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(114,'nao_sustentado','origens','vol','André Valadão é investigado pela PF ou pelo STF no caso Master','Só encontrei requerimentos da CPMI do INSS (convite, quebra de sigilo) e a citação em lista de Damares, que a própria fonte descreve sem acusação formal. Não localizei inquérito da PF contra ele.',14,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(115,'nao_sustentado','origens','vol','Lula chamou Valadão de "lavador de dinheiro" e "bandido contumaz" em 23/09/2026','A frase só aparece em resumo de um portal agregador. A CNN Brasil, que cobriu o evento, diz que Lula não citou Valadão nem a Lagoinha nas falas reportadas e apenas elogiou o vídeo de Porchat. Não sustentado.',15,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(116,'nao_sustentado','origens','vol','Valadão usou o jato de Vorcaro na campanha de 2022','A reportagem de Malu Gaspar reproduzida pela Oeste cita Nikolas e o pastor Guilherme Batista, não Valadão. Sem fonte aberta que coloque Valadão a bordo.',16,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(117,'nao_sustentado','origens','vol','Zettel doou também a Ibaneis Rocha e Cláudio Castro','Só consta no texto do relatório alternativo da CPMI (PT). CNN e Metrópoles, com dados do TSE, citam apenas Bolsonaro, Tarcísio e R$ 10 mil ao candidato do Novo Lucas Gonzales. Não verificado no TSE.',17,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(118,'nao_sustentado','origens','vol','Mensagens atribuídas a Valadão indicam que um senador o aconselhou a adiar o retorno ao Brasil para ser "protegido"','Só aparece em resumo do Brasil de Fato; não achei a reportagem original nem as mensagens. Valadão não comentou no texto. Não sustentado.',18,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(119,'nao_sustentado','origens','vol','Dinheiro da conta da igreja financiou o grupo A Turma ou os pagamentos a servidores do Banco Central','Um investigado do grupo fez 11 depósitos (R$ 22 mil) na conta da igreja, mas a PF descreve o pagamento a ele por empresas do grupo (Super Empreendimentos) e por Zettel via contrato com a Varajo. As saídas da conta da igreja foram sobretudo a construtoras e o Coaf diz que isso não conclui lavagem.',19,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(120,'nao_sustentado','origens','vol','Viana usou a presidência da CPMI para blindar a Lagoinha em troca de emendas','É tese da petição de Correia e Vieira, a que Dino pede esclarecimentos; Viana nega e diz que mandou emendas a outras entidades religiosas. A CGU apontou irregularidade na escolha da fundação em 2019, não crime nem contrapartida. Nenhuma fonte liga as emendas ao Master.',20,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(121,'nao_sustentado','origens','vol','Rogério Correia: ligações Lagoinha-Master incluem lavagem de dinheiro e "quando quebrar o sigilo, não sobra um"','Fala de parlamentar adversário em rede social, sem documento no texto da fonte. Não sustentada por fonte independente.',21,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(122,'lacuna','origens','banco',NULL,'Fundação: ano exato, fundadores, nomes anteriores e cidade de origem do Máxima não constam de nenhuma fonte aberta confiável; só há ''década de 1970'' / 1974 (reportado) e a Wikipedia em inglês aponta São Paulo, enquanto o BC registra sede no Rio em 2017.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(123,'lacuna','origens','banco',NULL,'Ato do BC que transformou a corretora em banco (década de 1990), tipo de carta-patente (banco múltiplo?) e mudanças de nome: não confirmados.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(124,'lacuna','origens','banco',NULL,'Controladores antes de Sabbá e data de entrada de Sabbá no controle: sem fonte.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(125,'lacuna','origens','banco',NULL,'Décadas de 1980 e 2000 (2000-2008): nenhuma fonte aberta descreve a atuação, ativos, patrimônio ou número de funcionários; só há os comunicados do BC de 2009-2010 sobre a corretora e a menção ao consignado sem data (Valor 2013).',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(126,'lacuna','origens','banco',NULL,'Ativos, patrimônio líquido e funcionários do banco em 2010-2017: não localizados (só carteira imobiliária de R$ 250 mi em 2013).',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(127,'lacuna','origens','banco',NULL,'Resultado do recurso ao CRSFN (processo 10372.100378/2018-75, pautado em 17/11/2020) e do processo 10372.100309/2019-42 (BCB 100673): sem acórdão aberto; infração do segundo processo não descrita.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(128,'lacuna','origens','banco',NULL,'Não localizei operação policial anterior a 2017 ligada ao Máxima nem investigação envolvendo fundos de previdência de servidores com o banco antes de 2017. O Correio Braziliense (19/11/2025) afirma que o banco foi alvo de operação da PF por desvios em fundos previdenciários municipais, mas sem nome nem data; não confirmei. O que existe é o PAS da CVM de 2019 (debêntures/Índigo) e matérias posteriores sobre previdência ligadas a ofertas de 2019.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(129,'lacuna','origens','banco',NULL,'Papel do FGC: o Valor (via Brasil 247) fala em empréstimo emergencial de R$ 20-30 milhões em 2019 e o Let''s Money cita aporte de R$ 15,447 milhões em dezembro de 2017; as fontes são ambíguas sobre destino e data e não foram conciliadas.',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(130,'lacuna','origens','banco',NULL,'Diferença entre 56,87% (contrato, segundo o Valor) e 91,87% (declaração de propósito no Comunicado BCB 31.344): não explicada.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(131,'lacuna','origens','banco',NULL,'Reportagem do PT (18/02/2015, fonte partidária) cita que Sabbá apareceria na lista HSBC e ligaria uma conta à Maximizer International Bank; vem do blog Megacidadania e do ICIJ, não foi confirmada em fonte independente e não afirmo nada a respeito.',9,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(132,'lacuna','origens','banco',NULL,'Possível parentesco de Saul Sabbá com a família Sabbá do S.B. Sabbá Crédito/Garantia ou da Amazônia: nenhuma fonte liga os nomes; não afirmado.',10,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(133,'lacuna','origens','banco',NULL,'Saul Sabbá: formação, trajetória empresarial e a sentença de 2025 (data exata, juiz, absolvidos nominalmente) não detalhadas; Money Times dá duas datas (início de 2025 e abril de 2025).',11,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(134,'lacuna','origens','familia',NULL,'Origem, formação e data de nascimento de Henrique Moura Vorcaro: só sabemos que tinha 64 anos em maio de 2026 (Bloomberg), o que indica nascimento por volta de 1961-62; naturalidade, estudos e a data exata de fundação da Multipar não constam nas fontes abertas. A piauí (Consuelo Dieguez, 18/11/2025), principal perfil, estava bloqueada para o acesso e só foi consultada via Wikipedia.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(135,'lacuna','origens','familia',NULL,'Mãe e outros irmãos de Daniel: nenhuma fonte aberta trata de papel empresarial deles antes de 2019. Apenas Natália Vorcaro Zettel aparece com atividade empresarial, e sem data anterior a 2019.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(136,'lacuna','origens','familia',NULL,'Fabiano Zettel e Felipe Cançado Vorcaro antes de 2019: não localizei atividades documentadas. Felipe aparece no julgamento da CVM sobre o Brazil Realty (fatos de 2017, decisão em 2026).',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(137,'lacuna','origens','familia',NULL,'Identidade de quem apresentou Daniel a Sabbá e do capital ''novo'' do Máxima em 2019: o voto do BC aprovado cita aportes de R$ 100 milhões (R$ 70 milhões de Daniel e R$ 30 milhões dos demais), mas as partes sobre a origem dos recursos estão tarjadas; Let''s Money menciona ''recursos líquidos em bancos do grupo S1'', sem detalhar a origem.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(138,'lacuna','origens','familia',NULL,'A Wikipedia, citando a piauí, diz que Daniel obteve a aprovação em 2019 ''em parceria com os irmãos Conte''; não achei confirmação em fonte aberta, e as fontes sobre a composição de 2019 listam Simonsen, Gallo e Augusto Lima.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(139,'lacuna','origens','familia',NULL,'Data exata do veto (13/1 ou 13/2/2019) e da aprovação (12 ou 14/10/2019): as fontes divergem.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(140,'lacuna','origens','familia',NULL,'O mandado de prisão preventiva de Ji-Paraná (29/10/2019) tem uma única fonte (Let''s Money, via Valor), sem motivo informado.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(141,'lacuna','origens','familia',NULL,'Entrada de Augusto Lima (janeiro de 2019, outubro de 2019 ou 2020) e de Maurício Quadrado (2020 ou 2021) varia conforme a fonte.',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(142,'lacuna','origens','familia',NULL,'Aporte de R$ 15,447 milhões do FGC em dezembro de 2017, citado por Let''s Money, é apresentado de forma confusa e não foi verificado; não o usei como evento.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(143,'lacuna','origens','familia',NULL,'A informação de que Daniel apresentou programa na Rede Super (2008-2009) e de que o pai comprou a emissora vem da Wikipedia e do Mais Goiás; a página da Rede Super na Wikipedia dá a Lagoinha como dona e não menciona os Vorcaro, então não registrei como fato. Relação com a Lagoinha cabe a outro agente.',9,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(144,'lacuna','origens','familia',NULL,'Início da atuação com precatórios: não encontrei, nas fontes abertas de 2019-2021, menção a precatórios; a entrevista de agosto de 2021 e o perfil do Brazil Journal de dezembro de 2021 não os citam.',10,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(145,'lacuna','origens','familia',NULL,'Fundo de cemitérios (encerrado com pagamento de R$ 2,2 milhões) e hotel inacabado: Revista Oeste (veículo opinativo) cita, sem outra confirmação, fracasso em educação, cemitérios e hotel; o site da Multipar fala em cemitérios, tratamento de resíduos e hotelaria.',11,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(146,'lacuna','origens','familia',NULL,'Processos no TJMG: o Diário de Pernambuco cita 159 processos ligados a Henrique e dezenas ligados a Daniel em consultas ao Jusbrasil/Escavador, sem descrever conteúdo; requerimento de convocação de Henrique na CPI do BNDES (como diretor da Multipar) é citado, sem data ou conteúdo verificados. Relações políticas de Henrique em Minas não foram documentadas antes de 2019.',12,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(147,'lacuna','origens','familia',NULL,'Patrimônio e estilo de vida em 2019-2021: as reportagens abertas tratam do tema só a partir de 2023 (Orlando, festa de 15 anos, jatos, Gulfstream); não registrei como pertinente à fase solicitada.',13,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(148,'lacuna','origens','familia',NULL,'Origem do dinheiro dos aportes de 2019 segundo a defesa: Daniel declinou comentar ao Valor; a versão dos Vorcaro sobre a origem não aparece em fonte aberta.',14,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(149,'lacuna','origens','ida',NULL,'Não consegui abrir os textos originais da piauí, da Folha e de O Globo (paywall ou bloqueio); as afirmações sobre Henrique Vorcaro, a Rede Super e o BMW vêm de reproduções (Mais Goiás, Agência Pública, Gazeta do Povo, Brasil 247).',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(150,'lacuna','origens','ida',NULL,'Faltam valores, datas e documentos dos supostos financiamentos de Henrique a projetos da igreja e à Rede Super, e a resposta dele a essas afirmações.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(151,'lacuna','origens','ida',NULL,'Ainda não se sabe quem são os donos da HV Empreendimentos e Participações e da Lagoinha Participações Ltda., nem a origem dos R$ 19,2 milhões enviados por Zettel; o RIF não a identifica.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(152,'lacuna','origens','ida',NULL,'Diferenças não reconciliadas: 4 versus 3 operações de Henrique; Folha (54 transferências, cerca de R$ 41 milhões) versus Coaf (26 operações, R$ 19,2 milhões); abertura do Belvedere em setembro de 2024 versus cerimônia de inauguração em abril de 2025; área de 14,4 mil versus 16 mil m2.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(153,'lacuna','origens','ida',NULL,'Não identifiquei o proprietário do imóvel alugado pelo Belvedere nem o contrato.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(154,'lacuna','origens','ida',NULL,'Parte das comunicações do RIF foi retida por possível envolvimento de pessoas com foro (ICL); a PF pediu acesso ao material omitido em 10/03/2026.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(155,'lacuna','origens','ida',NULL,'Não achei declaração de Márcio Valadão sobre os Vorcaro, nem resposta de Henrique, da ex-mulher de Daniel ou das empresas HV e Lagoinha Participações sobre os repasses à Belvedere.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(156,'lacuna','origens','ida',NULL,'Não há notícia, nas fontes abertas, de inquérito da PF, do MPF ou de CPI dirigido à Lagoinha como instituição por dinheiro dos Vorcaro; o que existe é o RIF do Coaf, a apuração da PF sobre Zettel e requerimentos na CPMI do INSS.',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(157,'lacuna','origens','volta',NULL,'Origem dos R$ 19,2 milhões enviados por Zettel à Belvedere: o relatório do Coaf não a identifica; o RIF com 823 nomes, que a PF pediu e que aguarda decisão de Mendonça segundo o ICL, pode esclarecer.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(158,'lacuna','origens','volta',NULL,'Reconciliação entre os R$ 40,9 mi em 54 repasses (Folha) e os R$ 19,2 mi em 26 operações (Coaf); não abri a matéria original da Folha, paywall.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(159,'lacuna','origens','volta',NULL,'Resposta da Lagoinha ao detalhamento do ICL de 25/09/2026 (Lagoinha Participações, HV Empreendimentos, construtoras): sem resposta até a publicação.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(160,'lacuna','origens','volta',NULL,'Quem são Lagoinha Participações e HV Empreendimentos e qual a relação com a igreja e a família: não encontrei.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(161,'lacuna','origens','volta',NULL,'Se há inquérito da PF sobre a Lagoinha ou sobre Valadão após o Coaf de setembro de 2026, e se o requerimento de quebra de sigilo de Valadão foi aprovado e executado na CPMI.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(162,'lacuna','origens','volta',NULL,'Credores da liquidação do Master: lista não pública nas fontes que consultei; não verifiquei se a igreja ou entidades ligadas estão nela.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(163,'lacuna','origens','volta',NULL,'Declarações de Márcio Valadão e de outros pastores: não encontrei; imprensa evangélica (Pleno.News, Gospel Prime, Guiame) não apareceu nos resultados e não foi aberta.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(164,'lacuna','origens','volta',NULL,'Conteúdo do vídeo de Porchat sobre a Lagoinha: não assisti e não o uso como fonte.',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(165,'lacuna','origens','volta',NULL,'Detalhes sobre Guilherme Batista e a relação dele com a Lagoinha e com Vorcaro além da nota da igreja.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(166,'lacuna','origens','volta',NULL,'Fonte primária do pagamento do Master à Amando Vidas: só tenho o SBT News, sem o relatório do Coaf.',9,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(167,'lacuna','origens','volta',NULL,'Desfecho do STF sobre as emendas à Fundação Oásis após as respostas de Viana a Dino.',10,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(168,'aviso','dossie','meta.aviso',NULL,'Tudo aqui vem de reportagens abertas por agentes de coleta e conferidas por uma segunda rodada. Nenhum documento original (decisões do STF, relatórios da PF, votos do Banco Central, painel da Câmara, TSE) foi lido. Ninguém citado foi condenado no caso; não há denúncia da PGR no caso Master nas fontes lidas. Citado não é investigado, e investigado não é culpado.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(169,'aviso','dossie','meta.status.doc',NULL,'Documentado: ato oficial, dado público ou admitido pelo citado',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(170,'aviso','dossie','meta.status.inv',NULL,'Alegado por autoridade em investigação, sem julgamento',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(171,'aviso','dossie','meta.status.rep',NULL,'Só reportagem, em geral sobre mensagens vazadas',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(172,'aviso','dossie','meta.status.ale',NULL,'Só delator ou adversário, sem corroboração',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(173,'aviso','dossie','meta.status.nc',NULL,'Não confirmado pela verificação',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(174,'tese','dossie','tese.pergunta',NULL,'A rede em torno do Banco Master funciona como um mercado, em que cada um vende o que controla, ou como uma máquina, em que grupos rivais agem juntos?',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(175,'tese','dossie','tese.resposta',NULL,'As fontes sustentam bem o mercado e trazem apenas indícios de máquina. O resultado foi dividido: a rede perdeu no Banco Central e ganhou no Congresso.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(176,'placar','dossie','tese.placar','Banco Central: perdeu','Vetou a venda ao BRB por unanimidade em 03/09/2025 e liquidou o banco em 18/11/2025. Antes, porém, preparou uma punição em maio de 2024 e não assinou, e dois ex-chefes da supervisão são investigados por receber de Vorcaro.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(177,'placar','dossie','tese.placar','Congresso: ganhou','Nenhuma CPI do Master foi instalada. A CPI do Crime Organizado e a CPMI do INSS terminaram sem relatório aprovado. A emenda que ampliaria o fundo garantidor, porém, foi rejeitada no dia seguinte.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(178,'placar','dossie','tese.placar','BRB e governo do DF: ganhou até o veto','O banco público comprou carteiras de julho de 2024 a outubro de 2025, contra pareceres internos, e a Câmara do DF aprovou a compra do controle em urgência.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(179,'placar','dossie','tese.placar','STF: misto','O relator atual autorizou as fases contra Ciro Nogueira, Jaques Wagner e o inquérito sobre Flávio Bolsonaro. Ao mesmo tempo, a ação que pede a CPI está parada com um ministro citado, e o julgamento sobre investigar Moraes está suspenso por pedido de vista.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(180,'placar','dossie','tese.placar','Fundos de previdência: ganhou','Dezoito regimes aplicaram R$ 1,867 bi em letras sem garantia entre out/2023 e dez/2024, vários contra alertas técnicos.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(181,'placar','dossie','tese.placar','PF e PGR: perdeu','Prisões, nove fases de operação e rejeição das delações de Vorcaro. Ainda sem denúncia.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(182,'narrativa','dossie','brb.hipotese',NULL,'A venda ao BRB era a única saída para o Master sobreviver, e por isso a rede política se mobilizou.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(183,'narrativa','dossie','brb.sustenta',NULL,'O BRB financia o Master desde julho de 2024, oito meses antes do anúncio da compra. Mensagens mostram Vorcaro cobrando repasses em agosto e setembro de 2024.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(184,'narrativa','dossie','brb.sustenta',NULL,'As compras de carteiras vão de R$ 12,2 bi (parte que a PF chama de falsa) a R$ 30,4 bi (planilhas obtidas pelo Metrópoles via Lei de Acesso), incluindo R$ 1,9 bi pagos depois do veto.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(185,'narrativa','dossie','brb.sustenta',NULL,'As outras saídas falharam: bancos privados recusaram, a J&F desistiu, o BTG só comprou ativos e a Fictor apareceu na véspera da liquidação.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(186,'narrativa','dossie','brb.sustenta',NULL,'O BRB comprou contra pareceres jurídicos internos de abril de 2025 e depois de assinar um termo de ajuste com o Banco Central.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(187,'narrativa','dossie','brb.nao_sustenta',NULL,'Nenhuma autoridade afirma que o BRB era a única saída.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(188,'narrativa','dossie','brb.nao_sustenta',NULL,'O único pagamento alegado a agente público na operação é ao ex-presidente do BRB. Contra o governador há mensagens; o relator teria negado duas buscas contra ele, segundo uma coluna.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(189,'narrativa','dossie','brb.nao_sustenta',NULL,'A operação fracassou: o Banco Central vetou por unanimidade, com parecer de um diretor indicado no governo Bolsonaro, que Vorcaro tentou afastar.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(190,'narrativa','dossie','brb.nao_sustenta',NULL,'Há uma alegação no sentido contrário: o diretor de Fiscalização do BC teria pedido ao BRB que comprasse carteiras. O BC nega.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(191,'narrativa','dossie','brb.valores','R$ 12,2 bi','R$ 12,2 bi | PF e BC: carteiras originadas pela Tirreno, que a PF chama de falsas',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(192,'narrativa','dossie','brb.valores','R$ 12,76 bi','R$ 12,76 bi | BRB: exposição bruta; diz que mais de R$ 10 bi foram liquidados ou substituídos',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(193,'narrativa','dossie','brb.valores','R$ 16,7 bi','R$ 16,7 bi | Vorcaro à PF, de jul/2024 a out/2025; diz que eram operações normais',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(194,'narrativa','dossie','brb.valores','R$ 17 bi','R$ 17 bi | Relatório da PF: total transferido',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(195,'narrativa','dossie','brb.valores','R$ 21,9 bi','R$ 21,9 bi | Presidente do BRB no Senado (jun/2026): créditos ligados ao Master no balanço',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(196,'narrativa','dossie','brb.valores','R$ 30,4 bi','R$ 30,4 bi | Metrópoles, planilhas via Lei de Acesso: total de compras, R$ 20,7 bi depois de mar/2025',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(197,'narrativa','dossie','brb.alternativas','Bancos privados','Bancos privados | O BC procurou em nov/2024; recusaram.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(198,'narrativa','dossie','brb.alternativas','BTG, por R$ 1','BTG, por R$ 1 | Discutida em dez/2024 e abr/2025; o BTG acabou comprando só ativos.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(199,'narrativa','dossie','brb.alternativas','J&F','J&F | Negociou ativos e desistiu em mai/2025.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(200,'narrativa','dossie','brb.alternativas','Fundo garantidor','Fundo garantidor | Emenda rejeitada em 2024; assistência de R$ 4 a 4,3 bi em 2025.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(201,'narrativa','dossie','brb.alternativas','Fictor e Emirados','Fictor e Emirados | Anunciada em 17/11/2025; o banco foi liquidado no dia seguinte.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(202,'narrativa','dossie','mercado.intro',NULL,'Cada linha separa três coisas: a alavanca que a pessoa controlava, o que recebeu ou teria recebido, e o ato. A última coluna diz se alguma autoridade liga o pagamento ao ato. Onde não liga, são dois fatos lado a lado e nada mais.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(203,'narrativa','dossie','maquina.intro',NULL,'Indício de máquina é quando grupos que brigam em público agem no mesmo sentido, na mesma hora. São poucos, e nenhum tem prova de combinação.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(204,'narrativa','dossie','previdencia.intro',NULL,'Dezoito regimes de previdência de servidores tinham R$ 1,867 bi em letras do Master, sem garantia do fundo. O que se repete entre eles é o intermediário, e não o partido.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(205,'narrativa','dossie','previdencia.intermediarios','Crédito e Mercado','Crédito e Mercado | Consultoria presente em pelo menos cinco institutos: Maceió, São Roque, Angélica, Campo Grande e Santo Antônio de Posse. Nega ter recomendado o Master.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(206,'narrativa','dossie','previdencia.intermediarios','Planner e Midias Promotora','Planner e Midias Promotora | Rioprevidência. Comissão de 0,6% sobre a captação, segundo a PF.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(207,'narrativa','dossie','previdencia.intermediarios','Alfa A Consultoria','Alfa A Consultoria | Amazonprev. Teria pago três dirigentes, segundo a PF.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(208,'narrativa','dossie','previdencia.contraprova',NULL,'O instituto do Pará foi procurado em 2024 e proibiu a aplicação por unanimidade.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(209,'narrativa','dossie','previdencia.contraprova',NULL,'No Paraná, só 1 de 177 regimes municipais aplicou.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(210,'narrativa','dossie','previdencia.contraprova',NULL,'Fundos de pensão de estatais não tinham exposição, segundo o órgão fiscalizador.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(211,'narrativa','dossie','previdencia.contraprova',NULL,'Dez dos dezoito entes ficaram sem partido identificado; nenhum dos identificados é de PT, PSB ou Novo.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(212,'narrativa','dossie','previdencia.fonte','Times Brasil, lista do Ministério da Previdência','Times Brasil, lista do Ministério da Previdência | https://timesbrasil.com.br/brasil/banco-master-18-fundos-de-previdencia-tinham-investimentos-no-banco-veja-lista/',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(213,'narrativa','dossie','previdencia.fonte','Relatório da PF sobre o Rioprevidência','Relatório da PF sobre o Rioprevidência | https://static.poder360.com.br/uploads/2026/09/relatorio-pf-castro-rioprevidencia-13set26.pdf',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(214,'narrativa','dossie','dinheiro.intro',NULL,'Doação eleitoral declarada é a menor parte. O dinheiro correu por contratos de advocacia e consultoria e por verba de mídia. Os valores vêm de dados da Receita enviados a uma CPI e variam entre veículos.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(215,'narrativa','dossie','dinheiro.notas',NULL,'A PF apura ao menos 46 perfis de influenciadores pagos para atacar o Banco Central.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(216,'narrativa','dossie','dinheiro.notas',NULL,'A PF e o relator afirmam que Vorcaro mandou agredir o jornalista Lauro Jardim.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(217,'narrativa','dossie','dinheiro.notas',NULL,'Em um fórum em Londres, em abril de 2024, o Master pagou uma degustação de uísque de cerca de US$ 640 mil. Estavam Moraes, Toffoli, o procurador-geral e o diretor-geral da PF.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(218,'narrativa','dossie','dinheiro.notas',NULL,'O portal do TSE não foi consultado diretamente; as doações vêm de reportagens.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(219,'narrativa','dossie','dinheiro.fonte','Jornal Opção','Jornal Opção | https://www.jornalopcao.com.br/ultimas-noticias/r-65-milhoes-em-repasses-lista-liga-banco-master-a-politicos-midia-e-ministros-813853/',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(220,'narrativa','dossie','dinheiro.fonte','Poder360','Poder360 | https://www.poder360.com.br/brasil/receita-mostra-pagamentos-do-banco-master-a-politicos-e-ex-ministros/',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(221,'narrativa','dossie','dinheiro.fonte','CNN Brasil, doações','CNN Brasil, doações | https://www.cnnbrasil.com.br/politica/alvo-da-pf-doou-r-5-mi-para-campanhas-de-bolsonaro-e-tarcisio-em-2022/',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(222,'narrativa','dossie','dinheiro.fonte','DGABC','DGABC | https://www.dgabc.com.br/Noticia/4293846/leo-dias-recebeu-r-9-9-milhoes-do-master-e-r-2-milhoes-de-empresa-que-teve-aportes-do-banco',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(223,'aviso','dossie','meta.paginas',NULL,'[["Teia do Caso Master", "./teia.html"], ["Origens do Caso Master", "./origens.html"], ["Brasil ano a ano", "./brasil-ano-a-ano.html"]]',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(224,'aviso','pares','notas.pib_idh',NULL,'Dados do Banco Mundial (versao disponivel em out/2026): 2025 ja tem valor para todos os paises e indicadores; nenhum null nos indicadores 1 a 4. Valores sujeitos a revisao e podem ser estimativas preliminares para 2024-2025.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(225,'aviso','pares','notas.pib_idh',NULL,'IDH: a serie anual completa nao foi obtida (CSV completo do HDR e grande demais para o WebFetch; o filtro do OWID devolveu so extremos). Foram obtidos apenas anos-ancora: 1995, 2000, 2010, 2015, 2020, 2021, 2022, 2023 (HDR 2025). Demais anos = null; nada foi interpolado. 1990 (BRA .641, etc.) existe nos dados mas fica fora do recorte 1995-2025.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(226,'aviso','pares','notas.pib_idh',NULL,'IDH: ultimo ano publicado = 2023; 2024 e 2025 = null.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(227,'aviso','pares','notas.pib_idh',NULL,'Coluna Russia no Banco Mundial para PIB per capita e crescimento 1995-2025 vem com precisao diferente (ex.: 4.49999999920672), reflete a fonte.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(228,'aviso','pares','notas.pib_idh',NULL,'IDH da Turquia 2022 e 2023 ambos 0.853 conforme tabela HDR25.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(229,'aviso','pares','notas.pib_idh',NULL,'PIB nominal de ARG 1995-2001 reflete paridade 1 peso = 1 US$ da conversao do Banco Mundial; salto de 2001 para 2002 e efeito da desvalorizacao.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(230,'aviso','pares','notas.educacao',NULL,'Nenhum valor foi preenchido de memoria; ausencia = ano sem dado na fonte (chave omitida) ou null.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(231,'aviso','pares','notas.educacao',NULL,'alfabetizacao: serie esparsa. RUS so 2002, 2010, 2021; CHN so 2000, 2010, 2020; ARG so 2001 e 2020. IND 2023 (81.7) e 2024 (78.2) nao sao monotonicas com 2022 (76.3): oscilacao entre pesquisas. ZAF oscila (95.0 em 2019, 90.0 em 2021, 91.2 em 2024) por mudanca de pesquisa.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(232,'aviso','pares','notas.educacao',NULL,'anos_estudo: fonte e HDR 2025 via OWID, nao a planilha do hdr.undp.org (CSV grande truncado). Serie anual 1995-2023 para BRA, CHN, ARG, COL; para IND, RUS, MEX, IDN, TUR e ZAF so 1995, 2000, 2005, 2010, 2015, 2020 e 2023 (consulta por ano filtrado). Valores de 2021-2023 sao iguais entre si em BRA, CHN, ARG, COL (repetidos pela fonte, provavelmente sem dado novo).',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(233,'aviso','pares','notas.educacao',NULL,'anos_estudo: um outro dataset OWID ''average-years-of-schooling'' (Barro-Lee/outra base) deu valores bem diferentes (ex.: BRA 2020 = 8.0; COL 1995 = 6.68) e nao foi usado.',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(234,'aviso','pares','notas.educacao',NULL,'gasto_educacao_pib: TUR 1998 vinha como 0 no Banco Mundial; descartado como dado invalido. TUR so tem 1995 e 2011-2022 (sem 1996-2010). IDN cai de 3.58 (2015) para 1.21 (2016) por quebra metodologica, nao queda real. CHN so 1995-1999 e 2023. Ultimo ano: ZAF 2024; ARG, CHN, IDN, RUS 2023; BRA, IND, MEX, TUR 2022; COL 2020.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(235,'aviso','pares','notas.educacao',NULL,'pisa: edicao 2025 nao incluida (resultados nao obtidos nas buscas; nao confirmado se ja saiu). Matematica 2000 e ciencias 2000/2003 nao constam na fonte OWID e ficaram null/ausentes. Russia: sem 2022 (nao participou/publicou). Turquia, Colombia e Indonesia: participacao a partir de 2003 (TUR), 2006 (COL); IDN desde 2000. Argentina: ausente em 2003; 2015 com ressalva de cobertura.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(236,'aviso','pares','notas.educacao',NULL,'pisa: Africa do Sul nunca participou do PISA (nao ha dados; mantido vazio). India so em 2009+ por dois estados, sem nota em leitura e ciencias.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(237,'aviso','pares','notas.educacao',NULL,'pisa: China nao tem dado nacional. Xangai 2012 (matematica 613, ciencias 580 e leitura 570) vem da Wikipedia, que tem inconsistencia de colunas; 2009 de Xangai nao foi obtido. 2022: B-S-J-Z participou mas resultados nao foram publicados (segundo Wikipedia).',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(238,'aviso','pares','notas.educacao',NULL,'Para comparacao informativa, Hong Kong e Macau (OWID) nao entram como ''China'' e foram omitidos.',8,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(239,'aviso','pares','notas.peso_economico',NULL,'Fonte: Banco Mundial, API v2 (NY.GDP.MKTP.CD, NE.EXP.GNFS.CD, NE.IMP.GNFS.CD, SP.POP.TOTL), consultada em 2026-10-09; lastupdated GDP 2026-07-13 (BRA/pais) e 2026-10-08 (CHN/WLD), populacao 2026-10-08.',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(240,'aviso','pares','notas.peso_economico',NULL,'Unidades: US$ correntes; populacao em habitantes. WLD = total mundial do Banco Mundial (indicador do agregado, usado como denominador). Exportacoes e importacoes de bens e servicos (contas nacionais), nao comercio de mercadorias.',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(241,'aviso','pares','notas.peso_economico',NULL,'Participacoes (%) = pais/WLD*100, 4 casas. Saldo = exportacoes - importacoes. Ranking 1 = maior PIB entre os 10 comparados.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(242,'aviso','pares','notas.peso_economico',NULL,'Importacoes de WLD nao foram coletadas (nao necessarias).',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(243,'aviso','pares','notas.peso_economico',NULL,'ranking_pib_brasil_mundo: null em todos os anos; nao foi coletada fonte confiavel do ranking mundial (nao estimado de memoria). Pode ser calculado com PIB de todos os paises da API (country/all) por ano.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(244,'aviso','pares','notas.peso_economico',NULL,'Valores de 2024/2025 podem ser preliminares/revistos pelo Banco Mundial. Dados ARG 2001 e anteriores sao a serie historica do WB (cambio oficial; quebra de serie em 2002 devido a desvalorizacao).',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(245,'aviso','pares','notas.peso_economico',NULL,'Valores transcritos da resposta da API via WebFetch (com resumidor); sem lacunas detectadas (31 anos x todos os paises).',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(246,'aviso','pares','notas.influencia_inovacao',NULL,'Series do Banco Mundial baixadas em 2026-10-08. Gasto militar cobre 1995-2025 completo; demais indicadores tem lacunas (null = sem dado na fonte; anos ausentes em gasto_pd_pib significam null).',0,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(247,'aviso','pares','notas.influencia_inovacao',NULL,'gasto_pd_pib: serie esparsa, so anos com valor. Brasil sem dado antes de 2000 e apos 2023; Colombia, Indonesia e India ate 2020; Indonesia tem so 2000, 2001, 2009, 2013 e 2016-2020; Africa do Sul tem lacunas (2002, 2000, 1998-1999 sem dado; 1997 e 2001 existem).',1,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(248,'aviso','pares','notas.influencia_inovacao',NULL,'patentes_residentes: 2025 null para todos; Indonesia 2012 null. Valores de outliers (ex.: ARG 2020/2016, COL 2022, IDN 2019) sao como publicados pela fonte, nao verificados.',2,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(249,'aviso','pares','notas.influencia_inovacao',NULL,'artigos_cientificos: 1995 e 2024-2025 null para todos (fonte so cobre 1996-2023).',3,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(250,'aviso','pares','notas.influencia_inovacao',NULL,'gasto_militar_pib e usd: um unico fetch cobre os dez paises, sem nulos; fonte primaria SIPRI via Banco Mundial (nao consultado SIPRI diretamente). Valores de 2024-2025 podem ser revisados.',4,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(251,'aviso','pares','notas.influencia_inovacao',NULL,'CSNU: mandatos de 2 anos, anos listados sao os anos de mandato. Extraido de pagina da Wikipedia (lista de membros do CSNU), nao do site un.org; o proprio extrator avisou que algumas tabelas eram dificeis de ler. Recomenda-se verificar em un.org/securitycouncil. Argentina: mandato 1994-1995, so 1995 entra na janela. Colombia tem mandato 2026-2027, fora da janela. China e Russia permanentes.',5,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(252,'aviso','pares','notas.influencia_inovacao',NULL,'Foruns G20, BRICS, OCDE e nuclear: consultados via Wikipedia (G20, BRICS, OECD, List of states with nuclear weapons), nao nos sites oficiais; nao validado em g20.org, brics ou oecd.org. G20: Colombia nao e membro. Russia no BRICS/G20 sem alteracao. Turquia: parceira BRICS, nao membro pleno.',6,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(253,'aviso','pares','notas.influencia_inovacao',NULL,'Nuclear: possuem China, India e Russia. Africa do Sul teve programa (6 armas, desmontado ~1989, aderiu ao TNP em 1991) mas nao possui hoje. Turquia nao possui, mas abriga armas dos EUA via compartilhamento nuclear da OTAN (estimativa ~20 em Incirlik, 2019).',7,NULL);
INSERT INTO nota(id, tipo, pagina, chave, titulo, texto, ordem, natureza_id) VALUES(254,'aviso','pares','notas.influencia_inovacao',NULL,'Brasil/OCDE: Key Partner e roteiro de acessao desde jun/2022; Argentina e Indonesia com roteiro desde mar/2024.',8,NULL);
