INSERT INTO indicio_maquina(id, ordem, titulo, texto, contra, forca) VALUES(1,0,'As sete semanas antes do veto do BC','Entre 17/07 e 02/09/2025: presidentes do Senado e da Câmara em contato com Vorcaro em torno de reuniões no BC, tentativa de levar o caso a Lula, lei aprovada em urgência no DF e pedido de seis partidos para votar o poder de afastar diretores do BC.','As mensagens não mostram o que foi dito. Nenhuma fonte liga o pedido de urgência ao Master. O BC vetou mesmo assim.',2);
INSERT INTO indicio_maquina(id, ordem, titulo, texto, contra, forca) VALUES(2,1,'Nenhuma CPI do Master','PL e PT assinaram pedidos, e ainda assim nada foi instalado. O presidente do Senado declarou que não leria o requerimento; a ação no STF está com um ministro citado no caso.','O bloqueio pode ser explicado só pelo interesse de quem controla a pauta, sem acordo entre partidos.',2);
INSERT INTO indicio_maquina(id, ordem, titulo, texto, contra, forca) VALUES(3,2,'CPI do Crime Organizado: relatório derrubado por 6 a 4','O texto pedia o indiciamento de três ministros do STF e do procurador-geral. Dois senadores favoráveis foram trocados horas antes. Votaram contra quatro petistas e dois aliados.','A troca foi formalizada pelo bloco MDB, PSDB, Podemos e União. A atribuição ao governo é de uma emissora e de um dos senadores trocados.',2);
INSERT INTO indicio_maquina(id, ordem, titulo, texto, contra, forca) VALUES(4,3,'PEC da Blindagem','Em 16/09/2025, PL (83 a 0), PP, União, Republicanos e MDB votaram por exigir aval do Congresso para processar parlamentares. Doze petistas também.','PT (51 contra), PSOL e Novo votaram contra. O Senado enterrou por 26 a 0.',1);
INSERT INTO indicio_maquina(id, ordem, titulo, texto, contra, forca) VALUES(5,4,'Dinheiro para os dois lados','O banco pagou ao mesmo tempo ex-ministros de Lula, aliados de Bolsonaro, dirigentes do Centrão e escritórios de familiares de ministros do STF.','Isso é o que um comprador de acesso faz. Não exige que os pagos se conheçam ou combinem.',1);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(1,'derrubado',0,'''Contrato de R$ 500 milhões'' ligado a Nunes Marques','Não existe em fonte aberta. Há mensagens sobre R$ 500 mil por mês e um contrato de terceiros com teto de R$ 427 mi.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(2,'derrubado',1,'''52 mensagens'' entre Vorcaro e Moraes','São 52 anotações enviadas a um contato salvo com o nome do ministro.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(3,'derrubado',2,'Foto de Flávio Bolsonaro com chefes do Comando Vermelho','Não encontrada. Existe foto com o chefe do grupo de intimidação de Vorcaro, sem sinal de adulteração.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(4,'derrubado',3,'Ex-cunhado de Gilmar Mendes com contrato de R$ 500 mil por mês','Não confirmado.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(5,'derrubado',4,'Mantega ''articulou'' a reunião com Lula','As fontes dizem que ele acompanhou Vorcaro.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(6,'derrubado',5,'Master ligado diretamente ao PCC','Nenhuma autoridade afirma. Há contato por intermediários financeiros.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(7,'aberto',0,NULL,'Voto por partido na derrubada do veto às saidinhas, na prisão de Chiquinho Brazão e na Câmara do DF: não conferidos em fonte oficial.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(8,'aberto',1,NULL,'Desfecho do projeto que permite afastar diretores do BC.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(9,'aberto',2,NULL,'Doações de outros sócios do Master e da Reag, direto no TSE.',NULL,NULL);
INSERT INTO limite(id, tipo, ordem, titulo, texto, data, data_texto) VALUES(10,'aberto',3,NULL,'Kassab e o Credcesta em São Paulo; outros nomes do Centrão ficaram sem cobertura.',NULL,NULL);
